    \centering
    \begin{subfigure}{0.49\textwidth}
       \includegraphics[trim={2.5cm 22.0cm 10.5cm 2.5cm},clip,width=1.0\textwidth]{expr-solvers_success.pdf}
    \end{subfigure}
    \begin{subfigure}{0.49\textwidth}
       \includegraphics[trim={2.5cm 22.0cm 10.5cm 2.5cm},clip,width=1.0\textwidth]{expr-solvers_runtime.pdf}
    \end{subfigure}
    \caption{Comparison of solving SEQ-PACK+S by the Gecode solver and the z3 solver on random cuboids. The right part shows cactus plots of runtimes (lower plot is better).}
