\title{Is magnitude `generically continuous' for finite metric spaces?}

\author{Hirokazu Katsumasa}
\address{Department of Mathematics, Osaka University, Japan}
\email{u895471k@ecs.osaka-u.ac.jp}

\author{Emily Roff}
\address{School of Mathematics, University of Edinburgh, Scotland}
\email{emily.roff@ed.ac.uk}

