The two parts of the next lemma are proved by Leinster as Corollary 2.3.3 and Proposition 2.1.13 in \cite{LeinsterMagnitude2013}.

\begin{lemma}
\label{lem:wedgesum_join}
Let $A$ and $B$ be metric spaces which both have magnitude.
\begin{enumerate}
    \item \label{lem:wedgesum}
    % (\cite[Cor.~2.3.3]{LeinsterMagnitude2013})
    For each \(a \in A\) and \(b \in B\), the wedge $A\vee_{a,b}B$ has magnitude
    \[|A\vee_{a,b}| = |A|+|B|-1.\]
    \item \label{lem:join}
    % (\cite[Prop.~2.3.13]{LeinsterMagnitude2013})
    For each $ \ell \geq \frac{1}{2}\diam (A), \frac{1}{2}\diam (B)$, the join \(A +_\ell B\) has magnitude
    \[
    |A+_\ell B|=\frac{|A|+|B|-2e^{-\ell}|A||B|}{1-e^{-2\ell}|A||B|}.
    \]
\end{enumerate}
\end{lemma}

Now, denote by $K_n$ the metric space determined by the complete graph on $n$ vertices---that is, the $n$-point metric space with $d(x,x')=1$ whenever \(x \neq x'\). Then
\begin{equation}
\label{eq:Kn_mag}
    |t K_n|=\frac{n}{1+(n-1)e^{-t}}
\end{equation}
by \cite[Ex.~2.1.6]{LeinsterMagnitude2013}.

\begin{example}
\label{ex:willerton}
A metric space \(X\) is said to have \demph{the one-point property} if 
\[\lim_{t \to 0} |tX| = 1.\]
Joins of complete graphs provide essentially all known examples of spaces lacking the one-point property. Two in particular will be useful to us below.
\begin{enumerate}
\item \cite[Example 2.3.8]{LeinsterMagnitude2013}
Let $X=K_3+_1 2K_3$. Then $\lim_{t\to 0}|tX|=\sfrac{6}{5}$. 
\item \cite[Example 3.4]{roff2023small}
Let $X=\frac{4}{3}K_2+_1 2K_3$. Then $\lim_{t\to 0}|tX|=\sfrac{7}{6}$. 
\end{enumerate}
\end{example}

We can use \Cref{lem:wedgesum_join}, along with \Cref{ex:willerton}, to prove that magnitude fails absolutely to be continuous at a generic point of Gromov--Hausdorff space. That is, it fails to be generically continuous in the sense of Formulation A.

\begin{theorem}
\label{thm:nowhere}
    The function \(X \mapsto |X|\) is nowhere continuous on $\FMetmag$. 
\end{theorem}

\begin{proof}
    Take any $X\in\FMetmag$. Let $Y$ be a space without 
    the one-point property---for concreteness, we may choose $Y=K_3+_1 2K_3$ as in Example \ref{ex:willerton} (1). 
    Pick any points $x\in X$ and $y\in Y$, take \(t > 0\) and consider the wedge $X \vee tY = X\vee_{x, y} tY$. 
    Observe that $X$ embeds isometrically into $X\vee tY$, and that 
    in the Hausdorff metric on subspaces of the wedge, we have $d(X, X \vee tY ) \leq \diam(tY)\to 0$ 
    as $t\to 0$. It follows that $X\vee tY\to X$ in $\FMet$. 
    Meanwhile, for sufficiently small $t > 0$ the space $tY$ has magnitude \cite[Rmk.~2.1]{roff2023small}, so, by 
    \Cref{lem:wedgesum_join} \eqref{lem:wedgesum}, for sufficiently small $t > 0$ the space $X\vee tY$ has magnitude given by 
    $|X\vee tY|=|X|+|tY|-1$. Hence, as $t \to 0$, we have
    \[
    |X\vee tY|\to |X|+\lim_{t\to 0}|tY| - 1=|X|+\frac{1}{5}\neq |X|,
    \]
    which tells us that magnitude is not continuous at $X$. 
\end{proof}

In \cite[Thm.~3.8]{roff2023small}, it was shown that magnitude's failure of continuity at the one-point space can be `arbitrarily bad', in the sense that for each real number \(\alpha \geq 1\) there exists a finite metric space \(X\) with \(\lim_{t \to 0} |tX| = \alpha\). So far as we know, no example has yet been found of a finite metric space \(X\) such that \(\lim_{t \to 0} |tX| < 1\) or \(\lim_{t \to 0} |tX| = +\infty\). However, if we consider more general paths in \(\mathrm{FMet}\) converging to the one-point space, the limiting magnitude can attain any value in the extended reals. A modification of Example \ref{ex:willerton} realizes such paths.

\begin{example}
\label{ex:perturb}
Fix $\alpha\in[0, \infty)$. For sufficiently small $t > 0$, both 
\[
\left(t+\alpha t^2\right)K_3+_t 2t K_3 \ \ \ \text{ and } \ \ \
\left(\frac{4}{3}t+\alpha t^2\right)K_2+_t 2tK_3
\]
become metric spaces, and, as $t\to 0$, both these families converge to the one-point space. Using \Cref{lem:wedgesum_join} \eqref{lem:join} along with the expression \eqref{eq:Kn_mag} for \(|tK_n|\), we find that
\[
\lim_{t\to 0}\left|\left(t+\alpha t^2\right)K_3+_t 2tK_3\right|=\frac{6\alpha-6}{6\alpha-5}
\]
and
\[
\lim_{t\to 0}\left|\left(\frac{4}{3}t+\alpha t^2\right)K_2+_t 2tK_3\right|=\frac{9\alpha-14}{9\alpha-12}.
\]
By varying \(\alpha\), both limits can achieve arbitrary values in $\mathbb{R}\cup\{\infty\}$, except for 1.
\end{example}

