\begin{example}
    There is a unique line from each \(Y \in \mathrm{FMet}\) to the one-point space: it is the family of scaled spaces \((tY)_{0 < t \leq 1}\) considered in the study of the one-point property (and throughout the study of magnitude).
\end{example}

\begin{example}
    The family of spaces \((X \vee_{x,y} tY)_{0 < t \leq 1}\) constructed in the proof of \Cref{thm:nowhere} is the line from \(X \vee_{x,y} Y\) to \(X\) along the function \(f\) specified by
    \[f(u) = \begin{cases}
        u & u \in X \\
        x \sim y & u \in Y.
    \end{cases}\]
    The paths to \(K_2\) described in the proof of \Cref{thm:2points_fnc} are also lines. The paths constructed in \Cref{ex:perturb} each converge to the one-point space, but they are not lines.
\end{example}

Since isometric spaces represent the same point in Gromov--Hausdorff space, two lines \((Y_{f,t})\) and \((W_{g,t})\) in \(\FMet\) are indistinguishable if there are isometries \(Y_{f,t} \simeq W_{g,t}\) for each \(t\). The next lemma, specifying when two surjective functions represent the same line, follows immediately from \Cref{def:GH_lines}.

\begin{lemma}
\label{lem:same_line}
    Let \(X\) and \(Y\) be finite metric spaces, and let \(f,g \colon Y \surj X\) be surjective functions. Suppose there exist isometries \(h \colon Y \xrightarrow{\sim} Y\) and \(k \colon X \xrightarrow{\sim} X\) such that \(k \circ f = g \circ h\). Then \(h\) gives an isometry \(Y_{f,t} \xrightarrow{\sim} Y_{g,t}\) for every \(t\). \qed
\end{lemma}

In light of the lemma, we make the following definition.

\begin{definition}
\label{def:set_of_lines}
    Let \(X\) be a finite metric space. The 
    \demph{set of lines to \(X\)} 
    is the set
    \[\lines{}{X} = \left\{(Y_{f,t})_{0 < t \leq 1} \mid f \colon Y \surj X \text{ is a surjective function}\right\} / \sim \]% 
    where \((Y_{f,t}) \sim (Y_{g,t})\)
    if there exist isometries \(h \colon Y \xrightarrow{\sim} Y\) and \(k \colon X \xrightarrow{\sim} X\) such that \(k \circ f = g \circ h\).
\end{definition}

In order to make a statement about the generic behaviour of magnitude with respect to lines, we need to equip the set of lines with a topology. We will topologise \(\lines{}{X}\) by relating it to a certain space of matrices.

Recall that every finite metric space \(X\), once we label its points as \(x_1,\ldots,x_m\), is determined by its \demph{distance matrix} 
\[D_X =  (d_X(x_i,x_j))_{i,j=1}^m.\]
Thus, ordered \(m\)-point metric spaces are parametrized by the set
\[
\label{eq:matrix}
\Met_m=
\left\{
(d_{ij})_{i, j=1, \dots, m}
\left|\ 
\begin{aligned}
    &d_{ii}=0\ (1\leq i\leq m)\\
&d_{ij}=d_{ji}>0\ (1\leq i<j\leq m)\\
&d_{ij}+d_{jk}\geq d_{ik}\ (1\leq i, j, k\leq m)
\end{aligned}
\right.
\right\},
\]
which is a $\binom{m}{2}$-dimensional convex cone in Euclidean space. The set of (unordered) \(m\)-point metric spaces is parametrized by \(\mathrm{Met}_m / \mathfrak{S}_m\), where the action of the group \(\mathfrak{S}_m\) permutes the rows and columns of each matrix in \(\mathrm{Met}_m\).

In \cite[\S 2]{roff2023small}, the small-scale limit of the magnitude function was studied via this identification of finite metric spaces with equivalence classes of matrices. To adapt the techniques of that paper to the present setting, we will identify lines in Gromov--Hausdorff space with certain equivalence classes of block matrices.

\begin{proposition}
\label{prop:space_of_lines}
    Let \(X\) be a finite metric space. Label its points as \(x_1,\ldots, x_m\), and let \(\mathrm{Iso}(X)\) denote the group of isometries of \(X\), regarded as a subgroup of the permutation group \(\mathfrak{S}_m\).
    There is a bijection
    \begin{equation}
    \label{eq:lines_biject}
        \lines{}{X} 
        \xrightarrow{\sim}
        \left(\bigsqcup_{\substack{(r_1,\ldots, r_m) \\ \sum r_i = n \\ n, r_1 \ldots, r_m \geq 1}} \mathrm{Met}_n/(\mathfrak{S}_{r_1} \times \cdots \times \mathfrak{S}_{r_m})\right) / \mathrm{Iso}(X).
    \end{equation}
    Here, each tuple \((r_1, \ldots, r_m)\) partitions the rows and columns of each matrix \(D \in \mathrm{Met}_n\). The action of \(\mathfrak{S}_{r_i}\) permutes the rows and columns within the \(i^\th\) section of the partition, and the action of \(\mathrm{Iso}(X)\) permutes the sections of the partition.
\end{proposition}

\begin{proof}
    First, let \(Y = (\{y_1,\ldots, y_n\}, d_Y)\), and consider a line from \(Y\) to \(X\) along some surjection \(f \colon \{y_1,\ldots, y_n\} \surj \{x_1,\ldots, x_m\}\). For each \(i \in \{1,\ldots, m\}\), let \(r_i = \# f^{-1}(x_i)\). Let the points of \(f^{-1}(x_i)\) inherit their order from \(Y\), but relabel them so that
    \(f^{-1}(x_i) = \{y_i^1,\ldots, y_i^{r_i}\}\).
    In this way, \(f\) is specified by the labelling
    \((y_1^1, \ldots y_1^{r_1}, \ldots, y_m^{1}, \ldots, y_m^{r_m})\)
    of the points of \(Y\), and hence by a block matrix  whose columns and rows are partitioned by the tuple \((r_1,\ldots, r_m)\).

    This defines a function 
    \begin{equation}
    \label{eq:space_of_lines0}
        \phi \colon \{f \colon (\{y_1,\ldots, y_n\} ,d_Y) \surj (\{x_1,\ldots, x_m\}, d_X)\} \to \bigsqcup_{\substack{(r_1,\ldots, r_m) \\ \sum r_i = n \\ n, r_1 \ldots, r_m \geq 1}} \mathrm{Met}_n
    \end{equation}
    which is obviously injective. To see that \(\phi\) is surjective, take any pair \((D, \mathbf{r})\) of a distance matrix \(D\) and \(\mathbf{r} = (r_1,\ldots, r_m)\), where \(r_i \geq 1\) satisfy \(\sum r_i = n\). Let 
    \[Y = (\{y_1^1,\ldots, y_1^{r_1}, \ldots, y_m^1, \ldots y_m^{r_m}\},d)\]
    be the metric space represented by \(D\) and specify \(f \colon Y \surj X\) by \(f(y_i^\alpha) = x_i\); then \(\phi(Y,f) = (D,\mathbf{r})\). This shows that \(\phi\) is a bijection; we need to see that it descends to a bijection after taking the appropriate quotient on each side of \eqref{eq:space_of_lines0}.

    By \Cref{def:set_of_lines}, surjections \(f, g \colon (\{y_1,\ldots, y_n\} ,d_Y) \surj (\{x_1,\ldots, x_m\}, d_X)\) represent the same line to \(X\) if and only if there exist \(\sigma \in \mathfrak{S}_n\) and \(\rho \in \mathfrak{S}_m\) such that the induced maps \(\sigma\colon Y \to Y\) and \(\rho \colon X \to X\) are both isometries---so, in particular,
    \begin{equation}
    \label{eq:space_of_lines1}
        d_Y(y_{\sigma(i)}, y_{\sigma(j)}) = d_Y(y_i,y_j)
    \end{equation}
    for all \(i,j \in \{1,\ldots, n\}\)---
    and we have 
    \begin{equation}
    \label{eq:space_of_lines2}
        \rho \circ f = g \circ \sigma.
    \end{equation}
    Condition \eqref{eq:space_of_lines1} says precisely that \(\sigma\) relates the matrix \(\phi(f)\) to \(\phi(g)\) by permuting its rows and columns.
    By \eqref{eq:space_of_lines2}, \(\sigma\) maps 
    \(\{y_i^1, \dots, y_i^{r_i}\}\) bijectively to 
    \(\{y_{\rho(i)}^1, \dots, y_{\rho(i)}^{r_{\rho(i)}}\}\). 
    Hence \(r_i=r_{\rho(i)}\), and there exists 
    \(\eta_i\in\mathfrak{S}_{r_i}\) such that 
    \(\sigma(y_i^\alpha)=y_{\rho(i)}^{\eta_i(\alpha)}\). 
    Therefore, \(f\) and \(g\) are related by 
    permutations \(\eta_i\in\mathfrak{S}_{r_i}\), 
    \(i=1, \dots, m\), and \(\rho\in\mathfrak{S}_m\). 
    This means that \(f\) and \(g\) are in the same 
    equivalence class of the right-hand side of 
    \eqref{eq:lines_biject}. The converse is obvious.
\end{proof}

We equip \(\mathrm{Met}_n\) with the Euclidean topology, and let this descend to the quotient on each component in the coproduct on the right of 
\eqref{eq:lines_biject}, then to the quotient by \(\mathrm{Iso}(X)\). The bijection in \eqref{eq:lines_biject} then makes \(\lines{}{X}\) into a topological space, which we will call \demph{the space of lines to \(X\)}.

\begin{remark}
Some readers may prefer to think of a line to \(X\) as representing a \demph{direction of approach} to \(X\): lines \((Y_t)\) and \((Y_t')\) approach `from the same direction' if \(Y_1' \simeq Y_t\) for some \(0<t\leq 1\), or vice versa. Our main result (\Cref{thm:main}) then says that for a generic finite metric space \(X\), and a linear sequence approaching \(X\) from a generic direction, magnitude behaves continuously. Thus, for continuity of magnitude, the bad directions are rare, and almost all directions are good.
\end{remark}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{Magnitude behaves continuously for generic limits along lines}
\label{sec:conti}

The goal in this section is to prove that for a generic line \((Y_{f,t})\) in Gromov--Hausdorff space, the limit as \(t \to 0\) is preserved by magnitude, meaning that
\[\lim_{t \to 0} |Y_{f,t}| = |\lim_{t \to 0} Y_{f,t}|.\]
Our main theorem runs as follows.

\begin{theorem}
\label{thm:main}
    For any finite metric space \(X\) such that \(Z_X\) is invertible, the space of lines to \(X\) contains a dense open subset whose elements satisfy \(\lim_{t \to 0} |Y_{f,t}| = |X|\).
\end{theorem}

The proof of \Cref{thm:main} depends on two propositions, whose proofs occupy most of the section. For ease of comprehension, we will first prove \Cref{thm:main} \emph{assuming} Propositions \ref{prop:poly_exists} and \ref{prop:poly_nonzero}, then proceed to the proofs of the propositions.

\begin{proof}[Proof of \Cref{thm:main}]
Let \(X\) be a metric space such that \(\det(Z_X) \neq 0\). Suppose \(\# X = m\). Propositions \ref{prop:poly_exists} and \ref{prop:poly_nonzero} tell us there exists, for each \(\mathbf{r} = (r_1, \ldots, r_m)\), a non-zero polynomial \(F_{X,\mathbf{r}}\) defined on \(\mathrm{Met}_n\) (where \(n=\sum r_i\)), whose non-vanishing at a matrix representing a line \((Y_{f,t})_{0 < t \leq 1}\) guarantees that \(\lim_{t \to 0} |Y_{f,t}| = |X|\). The complement of the zero set of \(F_{X,\mathbf{r}}\) is, therefore, a dense open subset of \(\mathrm{Met}_{n}\) on which this property holds. Since the quotient of \(\mathrm{Met}_n\) by the action of the group \(\mathfrak{S}_{r_1} \times \cdots \times \mathfrak{S}_{r_m}\) is an open map, the image of that subset is dense and open in the \(\mathbf{r}\)-component of the coproduct 
\[\bigsqcup_{\substack{(r_1,\ldots, r_m) \\ \sum r_i = n \\ n, r_1 \ldots, r_m \geq 1}} \mathrm{Met}_n/(\mathfrak{S}_{r_1} \times \cdots \times \mathfrak{S}_{r_m}).\]
And since the quotient of this space by the action of \(\mathrm{Iso}(X)\) is an open map, the union of the zero sets descends to a dense open subset of \(\lines{}{X}\).
\end{proof}

\begin{remark}
    If \(X\) is such that \(\det(Z_X) \neq 0\), then every line along a bijective function \(f \colon Y \xrightarrow{\sim} X\) satisfies \(\lim_{t \to 0} |Y_{f,t}| = |X|\). Indeed, in this case we have 
    \[Z_X = \lim_{t \to 0} Z_{Y_{f,t}}\]
    in \(\mathbb{R}^{m \times m}\), so the continuity of the determinant implies that \(Z_{Y_{f,t}}\) is invertible for sufficiently small \(t\), and that
    \(Z_X^{-1} = \lim_{t \to 0} Z_{Y_{f,t}}^{-1}\).
    Thus, we can use the expression \eqref{eq:mag_def} for magnitude to see immediately that \(|X| = \lim_{t \to 0} |Y_{f,t}|\).

    As we will see, the technicalities become much more delicate when we consider lines along surjections \(f \colon Y \surj X\) which are not injective---that is, linear limits in which distinct points become united.
\end{remark}

To establish the existence of the polynomial \(F_{X,\mathbf{r}}\), we will make use of a few familiar facts of linear algebra, which we gather here for convenience. Recall that an \demph{elementary column operation} on a matrix \(A\) is the operation of adding a multiple of one column to another. Two matrices $A$ and $B$ (of the same dimensions) are said to be \demph{column-equivalent} if $B$ can be obtained from $A$ by applying finitely many elementary column operations. In this case we write $A\sim B$. This notion is motivated by the following fundamental facts.

\begin{lemma}
\label{lem:elem1}
    Let $A$ be an $n\times n$ matrix. 
    \begin{enumerate}
        \item If \(B\) is an \(n \times n\) matrix such that \(A \sim B\), then \(\det(A) = \det(B)\). \label{lem:elem1_pt3}
        \item If $\det(A)\neq 0$, then $A$ is column-equivalent to a diagonal matrix with diagonal entries \(\alpha_1, \ldots, \alpha_n\), and $\det(A)=\prod_{i=1}^n\alpha_i$.  \label{lem:elem1_pt1}
        \item If $\det(A)=0$, $A$ is column-equivalent to a matrix with a zero column. \label{lem:elem1_pt2}
    \end{enumerate}
\end{lemma}

The next lemma is equally elementary, though slightly less standard.

\begin{lemma}
\label{lem:elem2}
    Let $A=(a_{ij})$ and $B=(b_{ij})$ be $m\times n$ matrices such that $A\sim B$. Let $\bm{1}_r=(1,1,\cdots, 1)^\top$ denote the $r$-dimensional column vector with all entries $1$. Given positive integers $r_1, \dots, r_m$, define $\left(\sum_{i=1}^m r_i\right)\times n$ matrices
        \[
        \widetilde{A} =
        \begin{pmatrix}
            a_{11}\bm{1}_{r_1}&a_{12}\bm{1}_{r_1}&\dots&a_{1n}\bm{1}_{r_1}\\
            a_{21}\bm{1}_{r_2}&a_{22}\bm{1}_{r_2}&\dots&a_{2n}\bm{1}_{r_2}\\
            \vdots&\vdots&\ddots&\vdots\\
            a_{m1}\bm{1}_{r_m}&a_{m2}\bm{1}_{r_m}&\dots&a_{mn}\bm{1}_{r_m}
        \end{pmatrix} \]
        and
        \[\widetilde{B} =
        \begin{pmatrix}
            b_{11}\bm{1}_{r_1}&b_{12}\bm{1}_{r_1}&\dots&b_{1n}\bm{1}_{r_1}\\
            b_{21}\bm{1}_{r_2}&b_{22}\bm{1}_{r_2}&\dots&b_{2n}\bm{1}_{r_2}\\
            \vdots&\vdots&\ddots&\vdots\\
            b_{m1}\bm{1}_{r_m}&b_{m2}\bm{1}_{r_m}&\dots&b_{mn}\bm{1}_{r_m}
        \end{pmatrix}.\]
        Then $\widetilde{A}\sim\widetilde{B}$.
\end{lemma}

From Lemmas \ref{lem:elem1} and \ref{lem:elem2} one can derive the following statement, which is the one that we will actually use.

\begin{lemma}
\label{lem:elem3}
    Let $n>0$ and $r_1, \dots, r_m>0$, $n=\sum_{i=1}^m r_i$ be 
    positive integers. Let $A=(a_{ij})$ be an $m\times m$ 
    matrix and $M$ be an $n\times n$ matrix of the form 
    \[
    M=
    \begin{pmatrix}
        a_{11}\bm{1}_{r_1}& a_{12}\bm{1}_{r_1}&\dots& a_{1n}\bm{1}_{r_1}&*&\dots&*\\
        a_{21}\bm{1}_{r_2}& a_{22}\bm{1}_{r_2}&\dots& a_{2n}\bm{1}_{r_2}&*&\dots&*\\
        \vdots & \vdots &\ddots& \vdots& \vdots&\ddots& \vdots\\
        a_{m1}\bm{1}_{r_m}& a_{m2}\bm{1}_{r_m}&\dots& a_{mm}\bm{1}_{r_m}&*&\dots&*
    \end{pmatrix}.
    \]
    Then 
\begin{equation}
\label{eq:detM}
    \det(M)=\det(A)\cdot\det
    \begin{pmatrix}
        \bm{1}_{r_1}& 0&\dots& 0&*&\dots&*\\
        0& \bm{1}_{r_2}&\dots& 0&*&\dots&*\\
        \vdots & \vdots &\ddots& \vdots& \vdots&\ddots& \vdots\\
        0& 0&\dots& \bm{1}_{r_m}&*&\dots&*
    \end{pmatrix}.
\end{equation}
\end{lemma}
\begin{proof}
    Suppose $\det(A)=0$. Then by Lemma \ref{lem:elem1} \eqref{lem:elem1_pt2} and 
    Lemma \ref{lem:elem2}, $M$ is column-equivalent to 
    a matrix with a zero column, so in this case, both sides of (\ref{eq:detM}) 
    are zero. If $\det(A)\neq 0$, then by Lemma \ref{lem:elem1} \eqref{lem:elem1_pt1} 
    and 
    Lemma \ref{lem:elem2}, $M$ is column-equivalent to 
    \[
        \begin{pmatrix}
        \alpha_1\bm{1}_{r_1}& 0&\dots& 0&*&\dots&*\\
        0& \alpha_2\bm{1}_{r_2}&\dots& 0&*&\dots&*\\
        \vdots & \vdots &\ddots& \vdots& \vdots&\ddots& \vdots\\
        0& 0&\dots& \alpha_n\bm{1}_{r_n}&*&\dots&*
    \end{pmatrix}, 
    \]
    with $\det(A)=\alpha_1\cdots\alpha_n$. Then Lemma 
    \ref{lem:elem1} \eqref{lem:elem1_pt3} yields (\ref{eq:detM}). 
\end{proof}

We can now proceed to the two propositions on which \Cref{thm:main} depends. Throughout what follows, we adopt the following notational conventions:
\begin{itemize}
    \item Given a matrix $A=(a_{ij})_{ij}$ (respectively, a vector $\bm{a}=(a_i)_i$), we denote the entry-wise $p$-th power by $A^{\langle p\rangle}=(a_{ij}^p)_{ij}$ (respectively, $\bm{a}^{\langle p\rangle}=(a_i^p)_i$). 
    \item Given a non-negative integral vector $\bm{p}=(p_1, \dots, p_n)$, we write $\bm{p}!=\prod_{i}p_i!$ and $|\bm{p}|=\sum_{i}p_i$. 
    \item The symbol $\runij$ will refer to an index running over $1, \dots, n$, while $\runab$ runs over $1, \dots, r_i$ (or $r_j$). 
    \item $\bm{1}_r=(1,1,\cdots, 1)^\top$ will denote the column vector of length \(r\) with all entries $1$, and $\bm{1}_{m, n}$ will denote the $m\times n$ matrix with all entries $1$. 
\end{itemize}

\begin{proposition}
\label{prop:poly_exists}
Let \(X\) be an \(m\)-point metric space such that \(\det(Z_X) \neq 0\). For each \(\mathbf{r} = (r_1,\ldots,r_m)\) there exists a polynomial
\[
F_{X,\mathbf{r}} \in \mathbb{R}[a_{ij}^{\alpha\beta}]
\]
(where $i,j= 1, \ldots, m$; $1\leq \alpha\leq r_i$; and $1\leq\beta\leq r_j$) with the following property.
If \(f \colon Y \surj X\), represented by the ordering \((y_1^1, \ldots y_1^{r_1}, \ldots, y_m^{1}, \ldots, y_m^{r_m})\) of \(Y\), satisfies
\[F_{X,\mathbf{r}} (d_Y(y_{i}^{\alpha}, y_j^\beta))\neq 0,\]
 then 
\[\lim_{t\to 0}|Y_{f,t}|=|X|.\]
\end{proposition}

\begin{proof}
Throughout this proof, let \(Z_{f,t}\) denote the similarity matrix of \(Y_{f,t}\), and, given an \(n \times n\) matrix \(M\), let \(\sumofentry(M) = \sum_{i,j=1}^n M(i,j)\).

Using the expression for magnitude in equation \eqref{eq:mag_def}, we have
\begin{equation}
\label{eq:magXt}
    |Y_{f,t}|=\frac{\sumofentry (\adj (Z_{f,t}))}{\det (Z_{f,t})}
\end{equation}
whenever \(\det(Z_{f,t}) \neq 0\). For each \(y,y' \in Y_{f,t}\), the \((y,y')\)-entry of \(Z_{f,t}\) is
\[e^{-d_X(f(y),f(y'))} \cdot e^{-t(d_Y(y,y') - d_X(f(y),f(y')))};\]
hence, \(\det(Z_{f,t})\) is a \emph{generalized polynomial} in \(e^{-t}\), in the sense of \cite[\S 2]{roff2023small} (but now with real coefficients). It follows that \(\det(Z_{f,t})\) vanishes for at most finitely many \(t\). In particular, for all sufficiently small \(t > 0\) we must have \(\det(Z_{f,t}) \neq 0\), so the expression \eqref{eq:magXt} is valid for \(0 < t \ll 1\). We will compute the denominator and the numerator of \eqref{eq:magXt} separately, beginning with the denominator.

First, we introduce some compressed notation. For \(i,j \in \{1, \ldots, m\}\) and \(\alpha \in \{1,\ldots, r_i\}\), \(\beta \in \{1, \ldots, r_j\}\), let \(d_{ij} = d_X(x_i,x_j)\) and let
\[c_{ij}^{\alpha\beta} =d_Y(y_{i}^{\alpha}, y_{j}^{\beta})-d_X(x_i,x_j).\]
Then 
\[
d_{Y_{f,t}}(y_{i}^{\alpha}, y_{j}^{\beta})=
d_X(x_i,x_j) +tc_{ij}^{\alpha\beta}. 
\]
Let us define for each \(i,j \in \{1, \ldots, m\}\)
an $r_i\times r_j$ matrix 
\[
\Gamma_{ij}{(t)}
=
(\exp(-t c_{ij}^{\alpha\beta}))_{
\substack{\alpha=1, \dots, r_i\\
\beta=1, \dots, r_j}}. 
\]
Using these matrices, one can write \(Z_{f,t}\) as the block matrix
\[
Z_{f,t}=
(e^{-d_{ij}} \cdot \Gamma_{ij}(t))_{
i, j=1, \dots, m}. 
\]
Expanding the entries of \(\Gamma_{ij}{(t)}\) as power series in \(t\), we see that the $(\alpha, \beta)$ 
entry of the $(i, j)$ block of \(Z_{f,t}\) is 
\begin{equation}
\label{eq:exponential}
e^{-d_{ij}}\cdot e^{-t c_{ij}^{\alpha\beta}} =
e^{-d_{ij}}\sum_{p\geq 0}\frac{(-tc_{ij}^{\alpha\beta})^p}{p!}. 
\end{equation}

We can now examine the denominator of \eqref{eq:magXt}. Using the multilinearity of the determinant for columns, we have the following expansion of $\det(Z_{f,t})$:
\[
\sum_{\bm{p}_{\runij}^{\runab}}
\frac{(-t)^{|\bm{p}_{\runij}^{\runab}|}}{\bm{p}_{\runij}^{\runab}!}
\det
\begin{pmatrix}
    e^{-d_{11}}(\bm{c}_{11}^{\runab 1})^{\langle p_1^1\rangle}&
    e^{-d_{11}}(\bm{c}_{11}^{\runab 2})^{\langle p_1^2\rangle}&
    \dots&
    e^{-d_{1m}}(\bm{c}_{1m}^{\runab r_m})^{\langle p_m^{r_m}\rangle}\\
    e^{-d_{21}}(\bm{c}_{21}^{\runab 1})^{\langle p_1^1\rangle}&
    e^{-d_{22}}(\bm{c}_{21}^{\runab 2})^{\langle p_1^2\rangle}&
    \dots&
    e^{-d_{2m}}(\bm{c}_{2m}^{\runab r_m})^{\langle p_m^{r_m}\rangle}\\
    \vdots&\vdots&\ddots&\vdots\\
    e^{-d_{m1}}(\bm{c}_{m1}^{\runab 1})^{\langle p_1^1\rangle}&
    e^{-d_{m2}}(\bm{c}_{m1}^{\runab 2})^{\langle p_1^2\rangle}&
    \dots&
    e^{-d_{nn}}(\bm{c}_{mm}^{\runab r_m})^{\langle p_m^{r_m}\rangle}
\end{pmatrix}, 
\]
where $\bm{p}_{\runij}^{\runab}=(p_i^\alpha)_{\substack{i=1, \dots, m\\ \alpha=1, \dots, r_i}}$ runs over vectors of length \(n = \sum r_i\) with entries in \(\mathbb{Z}_{\geq 0}\).

Let us call the block 
\[
\begin{pmatrix}
    e^{-d_{1j}}(\bm{c}_{1j}^{\runab 1})^{\langle p_j^1\rangle}&
    e^{-d_{1j}}(\bm{c}_{1j}^{\runab 2})^{\langle p_j^2\rangle}&
    \dots&
    e^{-d_{1j}}(\bm{c}_{1j}^{\runab r_j})^{\langle p_j^{r_j}\rangle}\\
    e^{-d_{2j}}(\bm{c}_{2j}^{\runab 1})^{\langle p_j^1\rangle}&
    e^{-d_{2j}}(\bm{c}_{2j}^{\runab 2})^{\langle p_j^2\rangle}&
    \dots&
    e^{-d_{2j}}(\bm{c}_{2j}^{\runab r_j})^{\langle p_j^{r_j}\rangle}\\
    \vdots&\vdots&\ddots&\vdots\\
    e^{-d_{nj}}(\bm{c}_{mj}^{\runab 1})^{\langle p_j^1\rangle}&
    e^{-d_{nj}}(\bm{c}_{mj}^{\runab 2})^{\langle p_j^2\rangle}&
    \dots&
    e^{-d_{nj}}(\bm{c}_{mj}^{\runab r_j})^{\langle p_j^{r_j}\rangle}
\end{pmatrix}
\]
%$(e^{-d_{\runij j}}c_{\runij j}^{\runab\runab})$ 
the $j$-th column block.  
If $p_j^\beta=0$, then the $\beta$-th column of the $j$-th 
column block is 
\[
\begin{pmatrix}
    e^{-d_{1j}}\bm{1}_{r_1}\\
    e^{-d_{2j}}\bm{1}_{r_2}\\
    \vdots\\
    e^{-d_{mj}}\bm{1}_{r_m}
\end{pmatrix}. 
\]
If two of $p_j^1, p_j^2, \dots, p_j^{r_j}$ are zero, the corresponding columns are identical, so it is enough to consider 
$p_{\runij}^{\runab}$ such that at most one of $p_j^1, \dots, p_j^{r_j}$ is zero for each $j=1, \dots, m$. 
Hence, the lowest degree term appearing with non-zero coefficient is 
\[
(-t)^{\sum_{i=1}^m (r_i -1)} = (-t)^{n - m}
\]
which is attained by 
the indices of the form $\bm{p}_j^{\runab}=(1, \dots, 1, 0, 1, \dots, 1)$.
The coefficient of $(-t)^{n-m}$ is 
\begin{equation}
\label{eq:coeff}
\sum_{\substack{\beta_1=1, \dots, r_1\\ \cdots\\ \beta_m=1, \dots, r_m}}
\det
\begin{pmatrix}
    \dots&
    e^{-d_{1j}}(\bm{c}_{1j}^{\runab 1})&
    \dots&
    \stackrel{\beta_j}{\widehat{e^{-d_{1j}}(\bm{1}_{r_1})}}&
    \dots&
    e^{-d_{1j}}(\bm{c}_{1j}^{\runab r_j})&
    \dots\\
    \dots&
    e^{-d_{2j}}(\bm{c}_{2j}^{\runab 1})&
    \dots&
    e^{-d_{2j}}(\bm{1}_{r_2})&
    \dots&
    e^{-d_{2j}}(\bm{c}_{2j}^{\runab r_j})&
    \dots\\
    &\vdots&\ddots&\vdots&\ddots&\vdots\\
    \dots&
    e^{-d_{nj}}(\bm{c}_{mj}^{\runab 1})&
    \dots&
    e^{-d_{nj}}(\bm{1}_{r_m})&
    \dots&
    e^{-d_{nj}}(\bm{c}_{mj}^{\runab r_j})&
    \dots
\end{pmatrix}. 
\end{equation}
Here, the sum is taken over matrices which have $e^{-d_{\runij j}}\bm{1}_{r_{\runij}}$ as the 
$\beta_j$-th column in the $j$-th column block,
% ($j=1, \dots, m$), 
with the other columns being of the form 
$e^{-d_{\runij j}}(\bm{c}_{\runij j}^{\runab\beta})$. 

Now we define the polynomial $F_{X,\mathbf{r}} \in \mathbb{R}[a_{ij}^{\alpha\beta}]$. For each \(i,j\), let \(\bm{d}_{ij} = d_{ij} \bm{1}_{r_i}\). Then \(F_{X,\mathbf{r}}({a}_{i,j}^{\alpha\beta})\) is defined to be
\[
\sum_{\substack{\beta_1=1, \dots, r_1\\ \cdots\\ \beta_m=1, \dots, r_m}}
\det
\begin{pmatrix}
    \dots&
    e^{-d_{1j}}(\bm{a}_{1j}^{\runab 1} - \bm{d}_{1j})&
    \dots&
    \stackrel{\beta_j}{\widehat{\delta_{1j}(\bm{1}_{r_1})}}&
    \dots&
    e^{-d_{1j}}(\bm{a}_{1j}^{\runab r_j} - \bm{d}_{1j})&
    \dots\\
    \dots&
    e^{-d_{2j}}(\bm{a}_{2j}^{\runab 1} - \bm{d}_{2j})&
    \dots&
    \delta_{2j}(\bm{1}_{r_2})&
    \dots&
    e^{-d_{2j}}(\bm{a}_{2j}^{\runab r_j} - \bm{d}_{2j})&
    \dots\\
    &\vdots&\ddots&\vdots&\ddots&\vdots\\
    \dots&
    e^{-d_{mj}}(\bm{a}_{mj}^{\runab 1} - \bm{d}_{mj})&
    \dots&
    \delta_{mj}(\bm{1}_{r_m})&
    \dots&
    e^{-d_{mj}}(\bm{a}_{mj}^{\runab r_j} - \bm{d}_{mj})&
    \dots
\end{pmatrix}
\]
where $\delta_{ij}$ is the Kronecker delta.

Rewriting the formula (\ref{eq:coeff}), but now picking out the $\beta_1$-st, $\cdots$, $\beta_n$-th 
columns, we see that the coefficient of \((-t)^{n-m}\)  in the denominator of \eqref{eq:magXt} is equal to
\[
\sum_{\substack{\beta_1=1, \dots, r_1\\ \cdots\\ \beta_m=1, \dots, r_m}}
\det
\begin{pmatrix}
    \dots&
    \stackrel{\mbox{\tiny $\beta_1$-th of $1$-st block}}{\widehat{e^{-d_{11}}(\bm{1}_{r_1})}}&
    \dots&
    \stackrel{\mbox{\tiny $\beta_j$-th of $j$-th block}}{\widehat{e^{-d_{1j}}(\bm{1}_{r_1})}}&
    \dots&
    \stackrel{\mbox{\tiny $\beta_m$-th of $m$-th block}}{\widehat{e^{-d_{1m}}(\bm{1}_{r_1})}}&
    \dots\\
    \dots&
    e^{-d_{21}}(\bm{1}_{r_2})&
    \dots&
    e^{-d_{2j}}(\bm{1}_{r_2})&
    \dots&
    e^{-d_{2m}}(\bm{1}_{r_2})&
    \dots\\
    &\vdots&\ddots&\vdots&\ddots&\vdots\\
    \dots&
    e^{-d_{m1}}(\bm{1}_{r_m})&
    \dots&
    e^{-d_{mj}}(\bm{1}_{r_m})&
    \dots&
    e^{-d_{mm}}(\bm{1}_{r_m})&
    \dots
\end{pmatrix},
\]
and, applying Lemma \ref{lem:elem3}, we see that this is equal to
\(
F_{X,\mathbf{r}}(d_{ij}^{\alpha\beta}) \cdot \det(e^{-d_{ij}})
\).
By assumption, $\det(e^{-d_{ij}}) \neq 0$. Thus, if \(F_{X,\mathbf{r}}(d_{ij}^{\alpha\beta}) \neq 0\), then the first non-zero term in the denominator of \eqref{eq:magXt} is
\[
F_{X,\mathbf{r}}(d_{ij}^{\alpha\beta}) \cdot \det(e^{-d_{ij}}) (-t)^{n-m}.
\]

Next, we consider the numerator of \eqref{eq:magXt}. 
Note that $\sumofentry (\adj (Z_{X_t}))$ is equal to 
\[
\sum_{\substack{j=1, \dots, m\\ \beta=1, \dots, r_j}}
\det
\begin{pmatrix}
    \dots&
    e^{-d_{1j}^{\runab 1}(t)}&
    \dots&
    \stackrel{\beta}{\widehat{\bm{1}_{r_1}}}&
    \dots&
    e^{-d_{1j}^{\runab r_j}(t)}&
    \dots\\
    \dots&
    e^{-d_{2j}^{\runab 1}(t)}&
    \dots&
    \bm{1}_{r_2}&
    \dots&
    e^{-d_{2j}^{\runab r_j}(t)}&
    \dots\\
    &\vdots&\ddots&\vdots&\ddots&\vdots\\
    \dots&
    e^{-d_{mj}^{\runab 1}(t)}&
    \dots&
    \bm{1}_{r_m}&
    \dots&
    e^{-d_{mj}^{\runab r_j}(t)}&
    \dots\\
\end{pmatrix}. 
\]
We have an expansion using (\ref{eq:exponential}), as in the case of the denominator. 
Unlike in that case, each determinant could be non-zero at degree 
$n-m-1$, where the coefficient is
\[
\sum_{\substack{j=1, \dots, n\\ \beta=1, \dots, r_j}}
\sum_{\substack{\beta_1=1, \dots, r_1\\ \cdots\\ \beta_n=1, \dots, r_n}}
\det
\begin{pmatrix}
    \dots&
    e^{-d_{1j}}(\bm{c}_{1j}^{\runab 1})&
    \dots&
    \stackrel{\beta_j}{\widehat{e^{-d_{1j}}(\bm{1}_{r_1})}}&
    \dots&\stackrel{\beta}{\widehat{\bm{1}_{r_1}}}&\dots&
    e^{-d_{1j}}(\bm{c}_{1j}^{\runab r_j})&
    \dots\\
    \dots&
    e^{-d_{2j}}(\bm{c}_{2j}^{\runab 1})&
    \dots&
    e^{-d_{2j}}(\bm{1}_{r_2})&
    \dots&\bm{1}_{r_2}&\dots&
    e^{-d_{2j}}(\bm{c}_{2j}^{\runab r_j})&
    \dots\\
    &\vdots&\ddots&\vdots&\ddots&\vdots&\ddots&\vdots\\
    \dots&
    e^{-d_{nj}}(\bm{c}_{nj}^{\runab 1})&
    \dots&
    e^{-d_{nj}}(\bm{1}_{r_n})&
    \dots&\bm{1}_{r_n}&\dots&
    e^{-d_{nj}}(\bm{c}_{nj}^{\runab r_j})&
    \dots
\end{pmatrix}. 
\]
However, by the alternating property of the determinant (using exchange between the 
$\beta_j$-th and $\beta$-th columns), this becomes zero. Thus, the lowest degree 
is again $n-m$, and that term has coefficient
\[
\sum_{j=1}^m
\sum_{\substack{\beta_1=1, \dots, r_1\\ \cdots\\ \beta_m=1, \dots, r_m}}
\det
\begin{pmatrix}
    \dots&
    \stackrel{\mbox{\tiny $\beta_1$-th of $1$-st block}}{\widehat{e^{-d_{11}}(\bm{1}_{r_1})}}&
    \dots&
    \stackrel{\mbox{\tiny $\beta_j$-th of $j$-th block}}{\widehat{\bm{1}_{r_1}}}&
    \dots&
    \stackrel{\mbox{\tiny $\beta_m$-th of $m$-th block}}{\widehat{e^{-d_{1m}}(\bm{1}_{r_1})}}&
    \dots\\
    \dots&
    e^{-d_{21}}(\bm{1}_{r_2})&
    \dots&
    \bm{1}_{r_2}&
    \dots&
    e^{-d_{2m}}(\bm{1}_{r_2})&
    \dots\\
    &\vdots&\ddots&\vdots&\ddots&\vdots\\
    \dots&
    e^{-d_{m1}}(\bm{1}_{r_m})&
    \dots&
    \bm{1}_{r_m}&
    \dots&
    e^{-d_{mm}}(\bm{1}_{r_m})&
    \dots
\end{pmatrix}. 
\]
Again applying \Cref{lem:elem3}, this turns to be equal to 
\[
F_{X,\mathbf{r}}(d_{ij}^{\alpha\beta}) \cdot
\sum_{j=1}^m\det
\begin{pmatrix}
    e^{-d_{11}} & \dots & \stackrel{\text{$j$-th column}}{\widehat{1}} & \dots & e^{-d_{1m}}\\
    e^{-d_{21}} & \dots & 1 & \dots & e^{-d_{1m}}\\
    \vdots & \ddots & \vdots & \ddots & \vdots\\
    e^{-d_{m1}} & \dots & 1 & \dots & e^{-d_{mm}}
\end{pmatrix}, 
\]
which is precisely 
$F_{X,\mathbf{r}}(d_{ij}^{\alpha\beta}) \cdot\sumofentry(\adj(Z_X))$. 

We have shown that, for \(0 < t \ll 1\), the magnitude of \(Y_{f,t}\) can be expressed as 
\[
|Y_{f,t}|=\frac{F_{X,\mathbf{r}}(d_{ij}^{\alpha\beta}) \cdot\sumofentry(\adj(Z_X))\cdot (-t)^{n-m}+O(t^{n-m+1})}{F_{X,\mathbf{r}}(d_{ij}^{\alpha\beta}) \cdot\det(Z_X)\cdot (-t)^{n-m}+O(t^{n-m+1})}.
\]
It follows that if $F_{X,\mathbf{r}}(d_{ij}^{\alpha\beta}) \neq 0$, then \(\lim_{t\to 0}|Y_{f,t}|=|X|\).
\end{proof}

It only remains to prove that the polynomial \(F_{X,\mathbf{r}}\) is not constantly zero.

\begin{proposition}
\label{prop:poly_nonzero}
Let \(X\) be any \(m\)-point metric space. For each \(n \geq m\) and \(\mathbf{r} = (r_1,\ldots,r_m)\) such that \(\sum r_i = n\), there exists $f:Y\surj X$ with $\# f^{-1}(x_i)=r_i$, such that $F_{X,\mathbf{r}}(d_Y(y_i^\alpha, y_j^\beta)) \neq 0$.
\end{proposition}

\begin{proof}
Let \(Y\) be the metric space with underlying set \(\bigsqcup_{i=1}^m \{y_i^1, \ldots, y_i^{r_i}\}\) and
\[
d_Y(y_i^\alpha, y_j^\beta)=
\begin{cases}
d_X(x_i, x_j) & i\neq j\\
1 & i=j \text{ and }\alpha\neq\beta\\
0 & i=j \text{ and }\alpha=\beta.
\end{cases}
\]
Let \(f\colon Y \surj X\) be given by \(f(y_i^\alpha) = x_i\).

Using the fact that $c_{ij}^{\alpha\beta}=0$ for $i\neq j$, and $c_{ii}^{\alpha\beta}=1-\delta_{\alpha\beta}$, 
we have 
\[
\begin{split}
F_{X,\mathbf{r}}(d_{ij}^{\alpha\beta})
&=
\sum_{\substack{\beta_1=1, \dots, r_1\\ \cdots\\ \beta_m=1, \dots, r_m}}
\prod_{k=1}^m\det
\begin{pmatrix}
c_{kk}^{11} & c_{kk}^{12} & \dots & \stackrel{\beta_k}{\widehat{1}}&\dots&c_{kk}^{1 r_k}\\
c_{kk}^{21} & c_{kk}^{22} & \dots & 1 &\dots&c_{kk}^{2 r_k}\\
\vdots & \vdots & \ddots & \vdots&\ddots&\vdots\\
c_{kk}^{r_k 1} & c_{kk}^{r_k 2} & \dots & 1 &\dots&c_{kk}^{r_k r_k}
\end{pmatrix}\\
&=
\sum_{\substack{\beta_1=1, \dots, r_1\\ \cdots\\ \beta_m=1, \dots, r_m}}
\prod_{k=1}^n\det
\begin{pmatrix}
0 & 1 & \dots & \stackrel{\beta_k}{\widehat{1}}&\dots & 1 \\
1 & 0 & \dots & 1 &\dots& 1 \\
\vdots & \vdots & \ddots & \vdots&\ddots&\vdots\\
1 & 1 & \dots & 1 &\dots&0
\end{pmatrix}\\
&=(-1)^{n-m} r_1r_2\cdots r_m.
\end{split}
\]
Since \(f\) is a surjection, we have \(r_i \neq 0\) for all \(i\), so this product is non-zero.
\end{proof}

