\begin{algorithm}
\caption{Finding Phase Shifts}
\label{algorithm:phaseshiftoperation}
\small
\hspace*{\algorithmicindent} \textbf{Input} The $n\times n$ matrix $T$ for an $n$-cell maximal length CA\\ 
\hspace{4.2em} pivot cell $p$\\
\hspace*{\algorithmicindent} \textbf{Output} phaseshift[n] /* stores shift of cell positions with respect to pivot cell */

\begin{algorithmic}[1]

\STATE $M$ $\leftarrow$ $T$, mark$_{1\times n}$ $\leftarrow$0; mark[p]$\leftarrow$1; power$\leftarrow$1; phaseshift[p]$\leftarrow$ $2^n-1$;
\STATE while (all mark $\neq$ 1) do step 3 to step 6.
\STATE count the number of 1's in the $p^{th}$ row of $M$.\\
if $p^{th}$ row contains single 1, then $j$ $\leftarrow$ column position with 1; otherwise $j$ $\leftarrow$ (-1). \\ 
\STATE if ($j$ $\neq$ 1), then \\
mark[j] $\leftarrow$ 1 \\
phaseshift[j] $\leftarrow$ (($2^n-1$) - power);\\
goto step 6.
\STATE for $i=0$ to $n-1$, do\\
if (mark[i]$\neq$1 and $M[i,p]=1$ and $i\neq p$), then \\
count number of 1's in the $i^{th}$ row of $M$ \\
if $i^{th}$ row contains single 1, then $j$ $\leftarrow$ column position with 1; otherwise $j$ $\leftarrow$ (-1). \\ 
if ($j$ $\neq$ 1), then \\
mark[i] $\leftarrow$ 1 \\
phaseshift[i] $\leftarrow$  power;\\
\STATE $M$ $\leftarrow$ $T\times M$\\
power $\leftarrow$ power+1

\end{algorithmic}
\end{algorithm}




