A \emph{track object} in $\cC$ (a \emph{$\cC$-track object}) is a
simple $\cC$-automaton isomorphic to the track object of some path in
$\cC$.


Let $\tro\cC\subseteq\saut\cC$ denote the full subcategory of track
objects. Morphisms of $\tro\cC$ are called
\emph{subsumptions}.  A track object $\Delta$ \emph{subsumes}
$\Gamma$, written $\Gamma\subsu\Delta$, if there exists a subsumption
$\Gamma\to \Delta$.

\begin{df}
\label{d:TrOConcat}
The \emph{concatenation} of simple $\cC$-automata $X,Y$
with $\tgt(X)=\src(Y)=U\in\cC$ is the simple $\cC$-automaton
\begin{equation*}
  X*Y=
  \big(
  \widehat{\src(X)}
  \longrightarrow
  \colim
  \big(
    X
    \longleftarrow
    \widehat{U}
    \longrightarrow
    Y
  \big)
  \longleftarrow
  \widehat{\tgt(Y)}
  \big)
  .
\end{equation*}
\end{df}

\begin{lem}
\label{l:SAutAssociativity}
	Concatenation of simple automata is associative, 
	\[
		(X*Y)*Z\cong X*(Y*Z),
	\]
	whenever $X,Y,Z\in\saut\cC$ and $\tgt(X)=\src(Y)$, $\tgt(Y)=\src(X)$.
\end{lem}
\begin{proof}
  This follows from the universal property of pushouts \cite[Example 2.1.22]{Johnson-Yau_2Categories}.
\end{proof}

\begin{lem}
\label{l:PathComposition}
For paths $\omega, \eta$ in $\cC$
with $\tgt(\omega)=\src(\eta)$,
there is a natural isomorphism
\[
	\widehat{\omega*\eta}
	\cong
	\widehat\omega*\widehat\eta.
\]
\end{lem}
\begin{proof}
	This follows from the universal property of colimits.
\end{proof}

The following consequence is immediate.
\begin{cor}
	Concatenations of track objects are track objects.
      \end{cor}

      Such concatenations are therefore associative up to natural
      isomorphism.

