\begin{df}
\label{d:ConcatSubsu}
Let $U,V,W\in\Ob(\cC)$, $\Gamma,\Gamma'\in\ilo{U}{\tro\cC}{V}$ and
$\Delta,\Delta'\in\ilo{V}{\tro\cC}{W}$.  The \emph{concatenation} of
subsumptions $f:\Gamma\to\Gamma'$ and $g:\Delta\to\Delta'$ is the
subsumption
	\[
		f*g:\Gamma*\Delta\to \Gamma'*\Delta'
	\]
	defined by the diagram
	\[
	\begin{tikzcd}[row sep=tiny]
			 & &
			 \Gamma*\Delta
				\arrow[bend left=40]{dddd}[right]{f*g}
			 & &
			 \\
			 &
			 \Gamma
 					\arrow{ur}
 					\arrow{dd}[left]{f}
			 & &
			 \Delta
 					\arrow{ul}
 					\arrow{dd}[right]{g}
			 &
			 \\
			\widehat{U}
				\arrow{ur}
				\arrow{dr}&  &
			\widehat{V}
				\arrow{ul}
				\arrow{dl}
				\arrow{ur}
				\arrow{dr}
			& &
			\widehat{W}\arrow{ul} \arrow{dl}
			\\
			 &
			\Gamma'
 				\arrow{dr}
			 & &
			 \Delta'
 				\arrow{dl}
			 &
			\\
			 & & \Gamma'*\Delta' & 	&
	\end{tikzcd}
	\]
      \end{df}

\begin{cor}
\label{c:ConcatSubsu}
	If $\Gamma\subsu\Gamma'$ and $\Delta\subsu\Delta'$,
	then $\Gamma*\Delta\subsu\Gamma'*\Delta'$.
	The subsumption relation is thus a precongruence.
	\qed
\end{cor}

A track object is \emph{elementary} if it is isomorphic to a track
object of a step.  Elementary track objects have the form
\begin{equation*}
\uptrack{\varphi}
=
  (\widehat{V}\overset{\widehat\phi}\longrightarrow\widehat{U}
  \overset{\id}\longleftarrow \widehat{U})
  \qquad
  \text{or}
  \qquad
\downtrack{\psi}
=
( \widehat{U}\overset{\id}\longrightarrow\widehat{U}
  \overset{\widehat{\psi}}\longleftarrow \widehat{V})
\end{equation*}
for $\phi\in\forM\cC(V,U)$ or $\psi\in\bckM\cC(V,U)$.
By Lemma \ref{l:PathComposition}, every track
object is isomorphic to a concatenation of elementary track objects.
The concatenation may be empty: the track object associated with the
constant path $(U)$, $U\in\Ob(\cC)$, is the \emph{identity track object}
$\idtrack{U}=(\widehat{U}\xrightarrow\id \widehat{U}\xleftarrow\id \widehat{U})$.

\begin{lem}
\label{l:TrackObjectGens}
A simple $\cC$-automaton is a track object if and only if it is
isomorphic to a concatenation of elementary track objects.
\end{lem}
\begin{proof}
	This follows from Lemmas \ref{l:PathConcatSteps} and \ref{l:PathComposition}.
\end{proof}

\begin{prp}
  \label{p:TrOPathEq}
  	Track objects of equivalent paths in $\cC$ are isomorphic.  
\end{prp}

\begin{proof}
  We need to check that the relations from Lemma \ref{l:ClRefin} preserve track objects.
  For $\varphi\in\forM\cC(U,V)$, $\psi\in\forM\cC(V,W)$,
  \begin{align*}
    \widehat{(W\arrO\psi V)}*\widehat{(V\arrO\varphi U)}
    &=
    (\widehat{W}\xrightarrow{\psi}\widehat{V}\xleftarrow\id \widehat{V})
    *
    (\widehat{V}\xrightarrow{\varphi}\widehat{U}\xleftarrow\id \widehat{U})		
    \\
    &\cong
    (\widehat{W}\xrightarrow{\psi\circ \varphi}\widehat{U}\xleftarrow\id \widehat{U})	\\	
    &\cong
    \widehat{(W\arrO{\varphi\circ \psi}U)},
  \end{align*}
  shows (1).  Track objects are presented here as cospans as in (\ref{e:SimpleAutSpan}).
  Verification of the remaining relations is similar.
\end{proof}

We are now ready to show that track objects provide
an alternative categorical notion of execution of presheaf
automata.

\begin{df}
  \label{d:Track}
  A \emph{track} in a $\cC$-presheaf $X$ is a presheaf map
  $\boldsymbol\alpha: \Gamma\to X$ from a track object~$\Gamma$.  The
  \emph{source} of a track $\boldsymbol\alpha:\Gamma\to X$ is the cell
  $\src(\boldsymbol\alpha)=\boldsymbol\alpha(\bot_\Gamma)$, its
  \emph{target} is
  $\tgt(\boldsymbol\alpha)=\boldsymbol\alpha(\top_\Gamma)$.  A track
  $\boldsymbol\alpha:\Gamma\to X$ in a $\cC$-automaton $X$ is
  \emph{accepting} if $\boldsymbol\alpha$ is a morphism of
  $\cC$-automata, that is, $\boldsymbol\alpha(\bot_\Gamma)\in \bot_X$
  and $\boldsymbol\alpha(\top_\Gamma)\in \top_X$.
\end{df}

\begin{df}
The \emph{concatenation} of tracks $\boldsymbol\alpha:\Gamma\to X$
and $\boldsymbol\beta:\Delta\to X$
such that $\tgt(\boldsymbol\alpha)=\src(\boldsymbol\beta)\in X[U]$
is the track
\[
  \boldsymbol\alpha*\boldsymbol\beta:
  \Gamma*\Delta
  =
  \colim(\Gamma \xleftarrow{\top_\Gamma} \widehat{U} \xrightarrow{\bot_\Delta} \Delta)
  \xrightarrow{\boldsymbol\alpha\cup \boldsymbol\beta}
  X.
\]
\end{df}
The concatenation of tracks is associative up to natural isomorphism:
\[
  (\boldsymbol\alpha*\boldsymbol\beta)*\boldsymbol\gamma\cong
  \boldsymbol\alpha*(\boldsymbol\beta*\boldsymbol\gamma).
  \]

\begin{rem}
  The above results can be extended to show that
  track objects in $\cC$ (or simple $\cC$-automata more generally)
  form a bicategory with objects of $\cC$ as $0$-cells, track objects
  as $1$-cells and subsumptions as 2-cells.  Composition of $1$-cells
  as well as horizontal composition of $2$-cells (Def.\@
  \ref{d:ConcatSubsu}) is concatenation (Def.\@ \ref{d:TrOConcat}),
  while vertical composition of $2$-cells is the composition of
  subsumptions. This forms a sub-bicategory of the cospan bicategory
  of $\psh\cC$.
\end{rem}


\section{Languages of presheaf automata}

In this section we define languages of presheaf automata and show how
they can be computed from the paths accepted by these automata.

\begin{df}
  The \emph{language} of a $\cC$-automaton $X$ is the set of all track objects of accepting tracks:
  \[
    \Lang(X)=\{\Gamma\in \tro\cC\mid \aut\cC(\Gamma,X)\neq \emptyset\}.
  \]
\end{df}

\begin{lem}
\label{l:LangFun}
	If $f:Y\to X$ is a map of\/ $\cC$-automata,
	then $\Lang(Y)\subseteq \Lang(X)$.
\end{lem}

\begin{proof}
	If $\Gamma\in \Lang(Y)$, then there exists a map $\boldsymbol\alpha:\Gamma\to Y$.
	Thus $f \circ \boldsymbol\alpha$ is a map $\Gamma\to X$ and hence $\Gamma\in \Lang(X)$.
\end{proof}

\begin{exa}
