      For a $\cC$-presheaf $X$ let
      $\Path(X):=\Path(\Cell{X})$ denote the category of paths in $X$.  For a path $\omega:\cI\to \cC$, the set of all paths with ``shape'' $\omega$ on $X$ is defined as
\begin{align}
  \Path(X;\omega) \label{e:PathShape}
  	&=\{\alpha\in\dCat(\cI,\Cell X)\mid \pi_x\circ \alpha=\omega\}\\
  	&\cong \{\alpha\in\Cat(\cI,\Cell X)\mid \pi_x\circ \alpha=\omega\}\notag \\
  	&\cong (\Cat{\downarrow}\cC)((\cI,\omega), (\Cell X,\pi_X)).\notag
\end{align}
The middle equation holds because the d-structure on $\Cell X$ is induced by the projection on $\cC$.

\begin{lem}
  \label{l:PathTrackCorrespondence}
  For a path $\omega\in\dCat(\cI,\cC)$ and $X\in\psh\cC$ the maps
 \begin{align*}
 	\Path(X;\omega)
 	\ni
 	\alpha
 	&\mapsto
 	(\widehat{\pi_X\circ \alpha}
	\xrightarrow{\alpha_*}
	\widehat\pi_X
	\xrightarrow\cong
	X)
	\in\psh\cC(\widehat\omega,X),
 \\
    \psh\cC(\widehat\omega,X)
    \ni
    \boldsymbol\alpha
    &\mapsto
    \Cell(\boldsymbol\alpha)\circ \kappa_\omega
    \in
    \Path(X;\omega)
  \end{align*}
  are inverses.
\end{lem}

\begin{proof}
This is an immediate consequence of the adjunction (\ref{e:CellGenAdj}).
\end{proof}

We can now show that languages of $\cC$-automata can be computed from
their accepting paths.

\begin{cor}
  For every $X\in\aut\cC$,
  \[
    \Lang(X)=\{\widehat{\pi_X\circ\alpha}\mid\text{$\alpha$ accepting path in $X$} \}.
  \]
\end{cor}

\begin{rem}
  Lemma \ref{l:PathTrackCorrespondence} exhibits a bijection between
  $\omega$-shaped paths on $X$ and tracks $\widehat\omega\to X$.  Yet
  there is no equivalence between all paths and all tracks on $X$: a
  track object $\Gamma\in\TrO(\cC)$ can be generated by different
  paths in $\cC$ ($\Gamma\simeq\widehat\omega\simeq\widehat\eta$ for
  $\omega\not\simeq\eta$) and then a track
  $\boldsymbol\alpha:\Gamma\to X$ corresponds to different paths
  (namely,
  $\Cell(\boldsymbol\alpha)\circ\kappa_\omega\neq
  \Cell(\boldsymbol\alpha)\circ\kappa_\eta$).  Example
  \ref{x:hdapaths2}, for instance, provides three different paths
  ($\alpha$, $\beta$, $\gamma$) with isomorphic tracks.
\end{rem}

\section{Languages over d-categories}
\label{se:lang}

In this section we introduce a notion of language parametrised by a
d-category $\cC$.  For $\cC=\cG(\Sigma)$ from Section \ref{s:StdAut},
we recover the classical notion.

\begin{df}
A \emph{$\cC$-language} is a subclass $A\subseteq\Ob(\tro\cC)$
that is down-closed with respect to subsumption:
\[
  \forall\;\Gamma,\Delta\in \Ob(\tro\cC):\; \Gamma\in A\;\land\;\Delta\subsu\Gamma
  \implies 
  \Delta\in A.
\]
The class of all $\cC$-languages is denoted by $\Langs(\cC)$.
\end{df}
\begin{rem}
  Though $\tro\cC$ is not a small category, it is essentially small:
  the isomorphism classes of $\cC$-track objects form a set, since
  it is a quotient of the set of isomorphism classes of paths in
  $\cC$.  Thus $\Langs(\cC)$ is contained in the powerset,
  because isomorphic track objects subsume each
  other.
\end{rem}

The following lemmas show that $\cC$-automata recognise exactly
the $\cC$-languages.

\begin{lem}
	If $X$ is a $\cC$-automaton, then $\Lang(X)$ is a $\cC$-language.
\end{lem}

\begin{proof}
  We need to check that $\Lang(X)$ is down-closed.  If
  $\Gamma\in\Lang(X)$ and $\Delta\subsu \Gamma$, then there
  are maps of $\cC$-automata $f:\Gamma\to X$ and
  $g:\Delta\to\Gamma$.  So $g\circ f\in\aut\cC(\Delta,X)\neq\emptyset$
  and thus $\Delta\in\Lang(X)$.
\end{proof}

\begin{lem}
	For every language $L\in\Langs(\cC)$ there exists a $\cC$-automaton $X$ such that $\Lang(X)=L$.
\end{lem}

\begin{proof}
  Let $A\subseteq L$ be a subset containing a representative of every
  isomorphism class; clearly $A\dcl=L$.  Let
  $X=\coprod_{\Gamma\in A}\Gamma$.  Then
  \begin{align*}
    \Delta\in\Lang(X)
    &\iff
    \aut\cC(\Delta,X)\neq \emptyset \\
    &\iff
    \exists\; \Gamma\in A:\; \aut\cC(\Delta,\Gamma)\neq \emptyset \\
    &\iff
    \Delta\in A\dcl=L. \qedhere
  \end{align*}
\end{proof}

\begin{lem}
   $(\Langs(\cC),\cup,\cap)$ is a distributive lattice.
\end{lem}
\begin{proof}
  Unions and intersections of $\cC$-languages are again
  $\cC$-languages.  Thus, $\Langs(\cC)$ is a sublattice of the
  powerset lattice of the set of isomorphism classes of track objects.
\end{proof}

\begin{rem}

  $\cC$-Languages are not necessarily closed under complementation:
  complements of down-closed sets are generally up-closed.  For
  $\cG$-automata, where down-closure is trivial and coincides with
  up-closure, this closure condition \emph{does} hold, but not for
  higher-dimensional automata.
\end{rem}

The \emph{down-closure} of $A\subseteq \Ob(\tro\cC)$ 
is the $\cC$-language
\[
  A{\downarrow} = \{\Gamma\in \Ob(\tro\cC)\mid \exists\;\Delta\in A:\; \Gamma\subsu\Delta\}.
\]
Let $\idlang{\cC}=\{\idtrack{U}\mid U\in\Ob(\cC)\}\dcl$.
We introduce the following operations on~$\Langs(\cC)$:
\begin{itemize}
\item  the union $L+M=L\cup M$,
\item   the concatenation $L* M =
  \{\Gamma*\Delta\mid \Gamma\in L,\; \Delta\in M,\; \tgt(\Gamma)=\src(\Delta)\}\dcl$,
\item the Kleene plus $L^+ = \bigcup_{n\geq 1} L^i$, for $L^0=\idlang{\cC}$
  and $L^{k+1}=L*L^k$,
\item the Kleene star $L^*=\idlang\cC+L^+$.
\end{itemize}
The down-closure of concatenations is necessary: see
\cite{FJSZ_Kleene-Conf} for an example.

\begin{lem}
  \label{l:KleeneUnit}
  $L*\idlang{\cC}=L=\idlang{\cC}*L$ for every $L\in\Langs(\cC)$.
\end{lem}

\begin{proof}
  If $\Gamma\in L$, then
  $\Gamma=\Gamma*\idtrack{\tgt(\Gamma)}\in L*\idlang{\cC}$.  If
  $\Gamma\in L*\idlang{\cC}$, then there are $\Delta\in L$ and
  $\Theta\subsu\idtrack{\tgt(\Gamma)}$ such that
  $\Gamma\subsu \Delta*\Theta$. Thus, by Corollary
  \ref{c:ConcatSubsu},
	\[
		\Gamma
		\subsu		
		\Delta*\Theta
		\subsu		
		\Delta*\idtrack{\tgt(\Gamma)}
		=
		\Delta*\idtrack{\tgt(\Delta)}
		=
		\Delta
		\in
		L.\qedhere
	\]

      \end{proof}

      Recall that a quantale $(Q,\le,\cdot,1)$ is a complete lattice
      $(Q,\le)$ equipped with a monoid structure $(Q,\cdot,1)$ whose
      multiplication preserves all suprema in both arguments. A
      quantale is distributive if the underlying lattice is. A Kleene
      star can be defined in any quantale $Q$ as
      $x^* = \bigvee_{i\ge 0} x^i$ for any $x\in Q$, where $x^0=1$ and
      $x^{i+1} = x\cdot x^i$, and where $\bigvee$ indicates a
      supremum.

\begin{prp}
  The class $(\Langs(\cC),\subseteq,*,\idlang\cC)$ forms a distributive
  quantale.
\end{prp}

\begin{proof}
  This follows from Lemmas \ref{l:SAutAssociativity} and \ref{l:KleeneUnit}.
\end{proof}
The Kleene stars in $\Langs(\cC)$ are thus
  represented using the star in this quantale.


\section{Rational languages over d-categories}
\label{se:ratlang}

We now define rational and then regular languages.  The unit
language $\idlang{\cC}$ tuns out to be non-regular in general,
for reasons explained below, hence we need \emph{non-unital}
algebras to capture their structures.

Recall that a Kleene algebra is an additively idempotent semiring
$(K,+,0,\cdot,1)$ equipped with a Kleene star $K\to K$ axiomatised as
a fixpoint, as arbitrary suprema are not available in semirings. In
a non-unital Kleene algebra, the $1$ is forgotten and the star 
replaced by the \emph{Kleene plus} $(-)^+:K\to K$, which satisfies
$x + x^+\cdot x^+ \le x^+$ and
$x + y \cdot y\le y\Longrightarrow x^+ \le y$
for all $x,y\in K$.

\begin{df}
  Languages of the form $\{\Gamma\}{\downarrow}$ for
  $\Gamma\in\Ob(\tro\cC)$ are \emph{atomic}.  The class
  $\Rat(\cC)\subseteq \Langs(\cC)$ of \emph{rational} languages is
  generated by the atomic languages and $\emptyset$ using $+$, $*$ and
  $(-)^+$.
\end{df}

The proof of the following fact is routine.

\begin{prp}
  The class $(\Rat(\cC),+,\emptyset,*,(-)^+)$ forms a non-unital
  Kleene algebra.
\end{prp}

The \emph{source} and \emph{target} of a language $L$ are defined as
\[
  \src(L)=\{\src(\Gamma)\mid \Gamma\in L\}\subseteq \Ob(\cC)
  \quad \text{and}\quad
  \tgt(L)=\{\tgt(\Gamma)\mid \Gamma\in L\}\subseteq \Ob(\cC).
\]
A language is \emph{simple} if its source and target each have precisely one element.

Every $L\in\Langs(\cC)$ can be decomposed into a union of simple
languages,
\begin{equation}
  \label{e:LangDecomp}
  L=\bigsqcup_{U\in \src(L)} \bigsqcup_{V\in \tgt(L)} {}_UL_V,
\end{equation}
where
\begin{equation}
   \label{e:Localization}
  \ilo ULV
  =\{\Gamma\in L\mid\src(\Gamma)=U,\; \tgt(\Gamma)=V\}\notag
  =\{\idtrack{U})\}\dcl *L * \{\idtrack{V}\}\dcl.
  \end{equation}

\begin{lem}
\label{l:RatSrcTgt}
	Let $L,M\in\Langs(\cC)$. Then
	\begin{enumerate}
	\item 
		$\src(L\cup M)=\src(L)\cup\src(M)$, $\tgt(L\cup M)=\tgt(L)\cup\tgt(M)$,
	\item
		$\src(L*M)\subseteq \src(L)$, $\tgt(L*M)\subseteq \tgt(M)$,
	\item
		$\src(L^+)=\src(L)$ and $\tgt(L^+)=\tgt(L)$.
	\end{enumerate}
\end{lem}

\begin{lem}
  \label{l:RatSrcTgtFinite}
  A language $L\in\Langs(\cC)$ is rational if and only if
  \begin{enumerate}[(1)]
  \item the sets $\src(L)$ and $\tgt(L)$ are finite, and
  \item ${}_UL_V$ is rational for all $U\in\src(L)$, $V\in\tgt(L)$.
  \end{enumerate}	
\end{lem}

\begin{proof}
  Suppose $L$ is rational.  By Lemma \ref{l:RatSrcTgt}, the
  rational operations preserve finiteness of sources and targets,
  which implies (1), while (2) follows from
  (\ref{e:Localization}).  If (1) and (2) hold, then
  rationality of $L$ follows from (\ref{e:LangDecomp}).
\end{proof}

\begin{cor}
	$\idlang\cC$ is a rational language if and only if the set $\Ob(\cC)$ is finite.
\end{cor}

\begin{exa}
  For the category defining $\cG$-automata,
  $\Ob(\cG)=\Sigma \cup \{\emptyset\}$ is finite, which explains why
  the algebra of standard rational languages includes the Kleene star.
  For $\oldsq$-automata, $\Ob(\oldsq)$ is not finite, so the algebra
  of rational languages of HDA uses the Kleene plus
  \cite{FJSZ_Kleene-Conf}.
\end{exa}

\section{Regular languages over d-categories}
\label{se:reglang}

Standard regular languages are recognised by finite automata, yet the
notion of finiteness must be adapted for presheaf automata.  Let $\cC$
be a d-category.
\begin{df}
  A $\cC$-presheaf $X$ is \emph{finitely generated}
  if there is a finite category $\cE$ and a functor $G:\cE\to\cC$ such
  that $X\simeq \widehat{G}$.
  A $\cC$-automaton has
  \emph{finite type} if the underlying presheaf is finitely generated 
  and has finitely many start and accept cells.
 \end{df}
 \begin{df}
  A $\cC$-language $L$ is
  \emph{regular} if $L=\Lang(X)$ for some finite-type $\cC$-automaton $X$.
  We write $\Reg(\cC)\subseteq\Langs(\cC)$ for the set of regular languages.
\end{df}

A criterion similar to Lemma \ref{l:RatSrcTgtFinite} holds for regular languages.

\begin{lem}
  \label{l:RegSrcTgtFinite}
  A language $L\in\Langs(\cC)$ is a regular if and only if
  \begin{enumerate}
  \item the sets $\src(L)$ and $\tgt(L)$ are finite, and
  \item ${}_UL_V$ is regular for all $U\in\src(L)$ and $V\in\tgt(L)$.
  \end{enumerate}	
\end{lem}
\begin{proof}
  Suppose $L$ is regular.  Then $\Lang(X)=L$ for a finite-type
  $\cC$-automaton $X$. If $U\in\src(L)$ ($V\in\tgt(L)$, respectively),
  then $X$ has a start (accept) cell of type $U$ ($V$), which implies
  (1).  For $U,V\in\cC$ let $\ilo UXV$ be the automaton with the same
  underlying presheaf as $X$ and with
  $\bot_{\ilo UXV}=\bot_X\cap X[U]$ and
  $\top_{\ilo UXV}=\top_X\cap X[V]$.  Then $\ilo UXV$ has finite type
  and $\Lang(\ilo UXV)=\ilo ULV$, which implies (2).

  Suppose $X(U,V)$ is a finite-type automaton and
  $\Lang(X(U,V))=\ilo ULV$. Then $\src(L)$ and $\tgt(L)$ are finite,
  $L$ is regular and
	\[
		\Lang\left(\bigsqcup_{U\in \src(L)}\bigsqcup_{V\in\tgt(L)} X(U,V)\right)=L.\qedhere
	\]
\end{proof}

\begin{df}
  A presheaf is \emph{finite} if its category of elements is.  An
  automaton is \emph{finite} if its underlying presheaf is finite and
  has finitely many start and accept cells.
\end{df}
Finiteness is not functorial: it depends on the natural equivalence
class of the underlying category.  Under some assumptions on the
underlying category $\cC$, finite and finite-type automata coincide.

\begin{lem}
  Suppose every representable $\cC$-presheaf is finite.  Then a
  $\cC$-presheaf is finite if and only if it is finitely generated.  A
  $\cC$-automaton is therefore finite if and only if it has finite
  type.
\end{lem}


\begin{proof}
	If a presheaf $X$ is finite, then it is finitely generated by $\pi_X$ (Lemma \ref{l:Density}).
	If $X\simeq \widehat{G}$, $G:\cE\to\cC$ and $\cE$ is finite,
	then the structural map
	\[
		\bigsqcup_{e\in \cE} \widehat{G(e)}
		\to
		\colim_{e\in\cE} \widehat{G(e)}
		=
		\widehat{G}
		\simeq X
	\]
	is a surjective map from a finite presheaf; hence $X$ is finite.
\end{proof}

The d-categories $\cG(\Sigma)$ and $\square$ have finite
representable presheaves. Hence all finite-type standard automata
and $\square$-automata are finite.  Examples of infinite
representable presheaves can be found in Sections \ref{s:VASS} -- \ref{s:HDAC}.

\begin{rem}
  Some categories of $\cC$-automata admit Kleene theorems stating that
  $\Rat(\cC)=\Reg(\cC)$ -- not only $\cG$-automata, but also
  $\oldsq$-automata \cite{FJSZ_Kleene-Conf}.  Whether something more
  general can be said is left for future work.
\end{rem}


\section{Open maps}
\label{se:openmaps}

Simulations and bisimulations are adequate notions for comparing
automata. Open maps~\cite{Joyal-Winskel-Nielsen_Bisimulation} provide
a categorical foundation for these concepts. Here we adapt it to
presheaf automata.  Let $\cC$ be a d-category.

\begin{df}
\label{d:OpenMap}
	A $\cC$-presheaf map $f:Y\to X$ 
	is
	\emph{future open} if for every formorphism $\varphi:V\to U$ in $\cC$,
	any diagram of solid arrows 
\begin{equation}
  \begin{tikzcd}
    \widehat{V} \arrow[d,swap,"\varphi_*"] \arrow[r,"y"] & Y \arrow[d,"f"] \\
    \widehat{U}\arrow[r,"x"] \arrow[ur,dotted,"\overline{y}"] & X
  \end{tikzcd}
\end{equation}	
has a filler $\overline{y}$.  Further, $f$ is \emph{past open} if a
filler exists for any backmorphism $\varphi$.
\end{df}

We present two criteria for maps to be future or past open. Both follow immediately from the Yoneda lemma.
\begin{lem}
	A $\cC$-presheaf map $f$
	is a future (past) open map if and only if
	for all $\varphi\in\forM\cC(V,U)$
	($\varphi\in\bckM\cC(V,U)$),
	 $y\in Y[V]$ and $x\in X[U]$
	 such that $X[\varphi](x)=f(y)$
	 there exists $\overline{y}\in Y[U]$
	 such that $Y[\varphi](\overline{y})=y$
	 and $f(\overline{y})=x$.\qed
\end{lem}

\begin{lem}
	A $\cC$-presheaf map $f$
	is future (past) open if each diagram of the form (A) (of the
        form (B)) 
	in $\dCat$ has a filler:
\begin{equation}
  \label{e:OpenStep}
  (A)\;
  \begin{tikzcd}%[row sep=large]
    \bot_\upstep \arrow[d,left hook->] \arrow[r,"y"] & \Cell(Y) \arrow[d,"\Cell(f)"] \\
    \upstep\arrow[r,"\phi"] \arrow[ur,dotted,->,"\psi"] & \Cell(X)
  \end{tikzcd}
  \qquad\qquad
  (B)\;
  \begin{tikzcd}%[row sep=large]
    \top_\downstep \arrow[d,left hook->] \arrow[r,"y"] & \Cell(Y) \arrow[d,"\Cell(f)"] \\
    \downstep\arrow[r,"\phi"] \arrow[ur,dotted,->,"\psi"] & \Cell(X)
  \end{tikzcd}
\end{equation}

\end{lem}


We focus on future open maps in what follows; results for past open
maps are similar.

\begin{lem}
  \label{l:OpenCatCrit}
  Let $f\in \psh\cC(Y,X)$.
  The following conditions are equivalent:
  \begin{enumerate}
  \item
    the map $f$ is future open,
   \item
   		every diagram (C) in $\dCat$ has a filler,
  \item
	  every diagram (D) in $\psh\cC$ has a filler,
  \item
	  every diagram (E) in $\psh\cC$ has a filler.
  \end{enumerate}
\begin{equation*}
(C)
    \begin{tikzcd}[ampersand replacement=\&]
      \bot_\cI \arrow[d,left hook->] \arrow[r,"y"] \& \Cell(Y) \arrow[d,"\Cell(f)"] \\
      \cI\arrow[r,"\alpha"] \arrow[ur,dotted,->,"\beta"] \& \Cell(X)
    \end{tikzcd}
    \qquad\quad
(D)
    \begin{tikzcd}[ampersand replacement=\&]
      \widehat{\src(\Gamma)} \arrow[d,left hook->] \arrow[r,"y"] \& Y \arrow[d,"f"] \\
      \Gamma\arrow[r,"{\boldsymbol\alpha}"] \arrow[ur,dotted,->,"{\boldsymbol\beta}"] \& X
    \end{tikzcd}
    \qquad\quad
  (E)
    \begin{tikzcd}[ampersand replacement=\&]
      \Gamma \arrow[d,left hook->] \arrow[r,"\boldsymbol\gamma"] \& Y \arrow[d,"f"] \\
      \Gamma*\Delta\arrow[r,"{\boldsymbol\alpha}"] \arrow[ur,dotted,->,"{\boldsymbol\beta}"] \& X
    \end{tikzcd}
  \end{equation*}
\end{lem}
\begin{proof}
  (2)$\iff$(3) follows from the Yoneda lemma and
  (4)$\implies$(3)$\implies$(1) is obvious.

	It remains to prove (1)$\implies$(4).  Suppose $f$ is
        future open.  We show that every diagram (E) has a filler by
        induction on the length of decompositions of
        $\Delta$ into elementary tracks.

	If $\Delta$ is an identity track object, then
        $\Gamma\cong\Gamma*\Delta$ and there is nothing to prove.  If
        $\Delta\simeq \downtrack{\psi}$, then the inclusion
        $\Gamma\to \Gamma*\Delta$ is an isomorphism of presheaves and
        again we are done.

	If $\Delta\simeq \uptrack{\varphi}$,
        $\varphi\in\forM\cC(V,U)$, then consider the following diagram
        of solid arrows:
	  \[
    \begin{tikzcd}[row sep=large]
      \widehat{V} \arrow[d,"{\varphi_*}" swap] \arrow[r,"\top"]
      &
      \Gamma \arrow[d,left hook->] \arrow[r,"\boldsymbol\gamma"]
      &
      Y \arrow[d,"f"]
      \\
      \widehat{U}\arrow[r,right hook->] \arrow[urr,dotted,->,"\boldsymbol\delta",pos=0.3]
      &
      \Gamma*\Delta\arrow[r,"\boldsymbol\alpha"] \arrow[ur,dotted,->,"\boldsymbol\beta" swap]
      &
      X
    \end{tikzcd}
  \]
  The left-hand square is a pushout diagram defining $\Gamma*\Delta$.
  By Definition \ref{d:OpenMap}, there exist a filler
  $\boldsymbol\delta$ (since $f$ is future open and $\varphi$ is a
  formorphism).  Further, maps $\boldsymbol\gamma$ and
  $\boldsymbol\delta$ induce a map $\boldsymbol\beta$ which is a
  required filler.

	If $\Delta$ is not elementary, then there exists a presentation $\Delta=\Delta'*\Delta''$
	with $\Delta'$, $\Delta''$ of smaller lengths:
	  \[
	\begin{tikzcd}[column sep=large]
		\Gamma
			\arrow[d,"i" swap]
			\arrow[r,"\boldsymbol\gamma"]
	&
		Y
			\arrow[dd,"f"]
	\\
		\Gamma*\Delta'
			\arrow[d,"j" swap]
			\arrow[ur,dotted,"\boldsymbol\delta"]
	&
	\\
		\Gamma*\Delta'*\Delta''
			\arrow[r,"\boldsymbol\alpha"]	  
      		\arrow[uur,dotted,"\boldsymbol\beta" swap]
	&
		X
    \end{tikzcd}
  \]
  Applying the induction hypothesis twice shows that there is a map
  $\boldsymbol\delta$ and then a map $\boldsymbol\beta$.
\end{proof}

\begin{prp}
  Let $f:Y\to X$ be a map of $\cC$-automata.  Let $f$ be future open,
  $\bot_X\subseteq f(\bot_Y)$ and $\top_Y=f^{-1}(\top_X)$.  Then
  $\Lang(Y)=\Lang(X)$.
\end{prp}
\begin{proof}
  If $\Gamma\in\Lang(X)$, then there is an accepting track
  $\boldsymbol\alpha:\Gamma\to X$.  By hypothesis, there is an element
  $y\in \bot_Y$ such that $f(y)=\src(\boldsymbol\alpha)$.  Let
  $\boldsymbol\beta:\Gamma\to Y$ be a fiiller for the diagram (D) of
  Lemma \ref{l:OpenCatCrit}.  Clearly
  $\src(\boldsymbol\beta)=y\in\bot_Y$ and
  $\tgt(\boldsymbol\beta)\in \top_Y$ since
  $f(\tgt(\boldsymbol\beta))=\tgt(\boldsymbol\alpha)\in\top_X$.  Thus
  $\boldsymbol\beta$ is accepting and  $\Gamma\in\Lang(Y)$.
\end{proof}


\section{Geometric models of concurrency}
\label{s:HDA}

\def\CSet{\mathbf{CSet}}
\def\CList{\mathbf{CList}}
\def\SCSet{\mathbf{SCSet}}
\def\SCList{\mathbf{SCList}}

As a proof of concept we now review several geometric models for
concurrency \cite{FJSZ_HDALang, FJSZ_Kleene-Arxiv, FGHMR_DAT,
  Grandis-Mauri_Cubical, vanGlabbeek_Expressiveness} and represent
them as presheaf automata.  The fundamental notion is that of consets
(concurrency sets) and concset maps, which is motivated by the
conclists and conclist maps for HDA introduced in
\cite{FJSZ_HDALang,FJSZ_Kleene-Arxiv}.

Fix an infinite set and call finite subsets of this set
\emph{concsets} (to enforce smallness of the categories below).

\begin{df}
  A \emph{concset map} from a concset $V$ to a concset $U$ is a pair
  $(f,\varepsilon)$ where $f:V\to U$ and $\varepsilon:U\to \{0,*,1\}$
  are functions such that $f$ is injective and
  $\varepsilon^{-1}(*)=f(V)$.  The composition of consets maps
  $(g,\eta):W\to V$ and $(f,\varepsilon):V\to U$ is the concset map
  $(gf,\theta):W\to U$ with
	\begin{equation}
	\label{e:ConcsetComposition}
		\theta(u)=
		\begin{cases}
			\varepsilon(u) & \text{for $u\not\in f(V)$}\\
			\eta(f^{-1}(u)) & \text{for $u\in f(V)$}
		\end{cases}.
	\end{equation}
	A concset map $(f,\varepsilon):V\to U$ is a formorphism if
        $\varepsilon(u)\neq 1$ for all $u\in U$, and a backmorphism
        if $\varepsilon(u)\neq 0$ for all $u\in U$.


If $(U,u_0),(V,v_0)$ are pointed sets, then a \emph{pointed concset map} 
$(f,\varepsilon):V\to U$ is defined as above, but
$f$ must preserve basepoints ($f(v_0)=u_0$)
and may map many elements to the basepoint (if $f(v)=f(v')=u$,
then $v=v'$ or $u=u_0$).
The formula for composition (\ref{e:ConcsetComposition}) remains valid.
\end{df}

\begin{rem}
  There is a 1-1 correspondence between pointed concset maps $V\to U$
  and partial concset maps $V\setminus\{v_0\}\to U\setminus\{u_0\}$,
  where partiality means that $f$ is not defined on the whole domain.
\end{rem}

Composition of concset maps (both pointed and unpointed) is
associative.  This allows defining several d-categories.  


\begin{enumerate}
\item
	the concset category $\CSet$ with
    concsets as objects
	and concset maps as morphisms;
\item
	the conclist category $\CList$
	of concsets with a strict total order $\intord$ (\emph{conclists})
	and order-preserving concset maps (\emph{conclist maps});
\item
	the pointed concset category $\CSet_*$
	of pointed concsets and basepoint-preserving concset maps;
\item
	the $\Sigma$-labelled concset category $\CSet(\Sigma)$
	over the alphabet $\Sigma$,
	of $\Sigma$-labelled concsets,
	which are pairs $(U,\lambda:U\to \Sigma)$,
	and label-preserving concset maps;
\item
	the $\Sigma$-labelled conclist category $\CList(\Sigma)$
	of labelled conclists and order-and-label-preserving concset maps;
\item
	the pointed conclist category $\CList_*$
	of pointed conclists, whose
	 objects are pointed concsets $(U,u_0)$
	with a total order $\intord$ on $U\setminus\{u_0\}$,
	and morphisms are basepoint-preserving concset maps
	$(f,\varepsilon):(V,v_0)\to(U,u_0)$ such that $f$ restricted
	to $f^{-1}(U\setminus\{u_0\})$ preserves $\intord$.
\end{enumerate}
Presheaves and automata over these d-categories coincide 
with existing models for concurrency:
\begin{enumerate}
\item The conclist category $\CList$ is equivalent to the category
  $\oldsq$ from Definition \ref{d:PrecubeCategory}. The
  functor $I:\oldsq\to\CList$ given by
  $I([n])=(1\intord \dotsm \intord n)$,
  $I(d^\alpha_i)=(f,\varepsilon)$, where
\[
	f(k)=\begin{cases}
		k & \text{for $k<i$}\\
		k+1 & \text{for $k\geq i$}
	\end{cases},
	\qquad
	\varepsilon(m)=\begin{cases}
		\alpha & \text{for $m=i$}\\
		* & \text{for $m\neq i$}
	\end{cases}
\]
gives rise to an equivalence of categories.  $\CList$-presheaves are
therefore equivalent to the precubical sets of \cite{FJSZ_HDALang} and
\cite{FGHMR_DAT}, and to the cubical sets of
\cite{vanGlabbeek_Expressiveness}.
\item
\label{i:CListStar}
The pointed conclist category $\CList_*$ is equivalent to the
  cubical category $\square$ of \cite{Goubault-Mimram_Relationship}
  and to the restricted cubical site $\mathbb{I}$ of
  \cite{Grandis-Mauri_Cubical}.
\item The concset category $\CSet$ and the pointed concset category
  $\CSet_*$ are equivalent to the symmetric precubical category and
  the symmetric cubical category of
  \cite{Goubault-Mimram_Relationship}.
\item The $\Sigma$-labelled conclist category $\CList(\Sigma)$
        is equivalent to the precubical category $\square$ of
        \cite{FJSZ_Kleene-Arxiv}.  $\CList(\Sigma)$-automata are thus
        equivalent to the higher-dimensional automata studied in
        \cite{FJSZ_HDALang,FJSZ_Kleene-Arxiv,vanGlabbeek_Expressiveness}.
      \item Presheaves over the labelled concset category
        $\CSet(\Sigma)$ are equivalent to the labelled symmetric
        precubical sets of \cite{Goubault-Mimram_Relationship}
        and closely connected to the cubical site $\mathbb{J}$ of \cite{Grandis-Mauri_Cubical}.
\end{enumerate}

We show one of the equivalences claimed in \ref{i:CListStar}.  The
proofs of 3.--5. are not entirely straightforward either, and details
are left for future work.

The \emph{cubical category} $\mathbb{I}$ \cite{Grandis-Mauri_Cubical} is the d-category defined as follows:
	\begin{itemize}
\item
	Objects are symbols $[n]$ for $n\geq 0$.
\item
	Morphisms are generated by $d^0_i,d^1_i\in \mathbb{I}([n-1],[n])$ and $e_i\in\mathbb{I}([n+1],[n])$ for $1\leq i\leq n$, and relations
	\[
		d^\varepsilon_{j}\circ d^\eta_{i}=d^\eta_{i}\circ d^\varepsilon_{j-1}
		\quad(j<i),
		\qquad
		e_{j}\circ e_i=e_{i-1}\circ e_j
		\quad(j<i),
	\]
	\[
		e_id_j
		=
		\begin{cases}
			d_je_{i-1} & \text{for $j<i$}\\
			\id & \text{for $j=i$}\\
			d_{j-1}e_i & \text{for $j>i$}
		\end{cases}.
	\]
\item
	$\forM{\mathbb{I}}$ is generated by the morphisms $d^0_i$ and $e_i$.
\item
	$\bckM{\mathbb{I}}$ is generated by the morphisms $d^1_i$ and $e_i$.
	\end{itemize}
We define a functor $F:\mathbb{I}\to \CList_*$ as
\[
	F([n])=(\{0,1\intord\dotsm\intord n\},0)
\]
and $F(d^\alpha_i:[n-1]\to[n])=(f^\alpha_i,\varepsilon^\alpha_i)$, $F(e_i:[n+1]\to[n])=(g_i,\zeta_i)$, where
\[
	f^\alpha_i(k)
	=
	\begin{cases}
		k & \text{for $k<i$}\\
		k+1 & \text{for $k\geq i$}
	\end{cases},
		\qquad
	\varepsilon^\alpha_i(m)=\begin{cases}
		\alpha & \text{for $m=i$}\\
		* & \text{for $m\neq i$}
	\end{cases},
\]
\[
	g_i(k)
	=
	\begin{cases}
		k & \text{for $k<i$}\\
		k-1 & \text{for $k>i$}\\
		0 & \text{for $k=i$},
	\end{cases}
	\qquad
	\zeta_i(m)=*.
\]
It can be shown that $F$ gives rise to an equivalence of d-categories.


\begin{rem}
  In the terminology of \cite{Grandis-Mauri_Cubical}, the conclist
  category $\CList$ contains only face morphisms.  By passing from
  conclists to consets we introduce symmetries.  Finally, passing from
  unpointed to pointed conclists or concsets adds degeneracies to the
  respective categories.
\end{rem}


\section{Vector additions systems with states as presheaf automata}
\label{s:VASS}

\def\vvec{\mathsf{vec}}

We now show that vector addition systems with states (VASSes)
\cite{Hopcroft-Pansion_Reachability} can be realised as presheaf
automata.  Vector additions systems and Petri nets are therefore
subsumed by presheaf automata.

\begin{df}
\label{d:VASS}
 An \emph{$r$-dimensional vector addition system with states}
(\emph{$r$-VASS}) is a pair $(Q,E)$, where
\begin{itemize}
\item
 $Q$ is a finite set of \emph{vertices},
 \item
 $E\subseteq Q\times \Z^r\times Q$
is a finite set of \emph{edges}.
\end{itemize}
We write $e=(\src(e),\vvec(e),\tgt(e))$ for
$e\in E$.  An \emph{run} of a VASS $(Q,E)$ is a sequence
\[
	(q_0,\sfu_0)\xrightarrow{e_1}(q_1,\sfu_1)\xrightarrow{e_2}
	\dotsm\xrightarrow{e_n}(q_n,\sfu_n)
\]
such that $q_k\in Q$,
$\sfu_k\in\N^r$,
$e_k\in E$,
$\src(e_k)=q_{k-1}$,
$\tgt(e_k)=q_k$
and $\sfu_{k}=\sfu_{k-1}+\mathsf{vec}(e_k)$
for all $k$.
\end{df}

An $r$-VASS is then essentially a $\Z^r$-labelled digraph $G_{(Q,E)}$
and thus a $\cG(\Z^r)$-presheaf. Yet such a presentation does not
yield the correct semantics.  We need to enrich the
underlying d-category.

For a set $A$ we write $\cF(A)$ for the
category with $\Ob(\cF(A))=A$ and $\cF(A)(a,b)=\{\iota_a^b\}$ for all
$a,b\in A$.  ($\cF(A)$ is naturally equivalent to the trivial
category.)  For a vector $\sfu\in\Z^r$, let $\sfu=\sfu^+-\sfu^-$ be the
decomposition into the positive and negative parts
($\sfu^+,\sfu^-\in\N^r$).

Let $\cV_r$ be the d-category with the underlying category
$\cG(\Z^r)\times \cF(\N^r)$ and d-structure given, for all
$\sfu\in\Z^r$ and $\sfv\in\N^r$, by
\begin{align*}
	\forM{\cV_r}
	&=\{(\sigma_{\sfv},\iota_{\sfu^-+\sfv}^\sfv)
	:(\emptyset,\sfu^-+\sfv)\to(\sfu,\sfv)\}
	\cup\{\text{identities}\},
\\
	\bckM{\cV_r}
	&=\{(\tau_{\sfv},\iota_{\sfu^++\sfv}^\sfv)
	:(\emptyset,\sfu^++\sfv)\to(\sfu,\sfv)\}
	\cup\{\text{identities}\}.
\end{align*}


There is a correspondence between $r$-VASSes and $\cV_r$-presheaves.
\begin{itemize}
\item
For an $r$-VASS $(Q,E)$ we define the $\cV_r$-presheaf $X=X_{(Q,E)}$
as
\begin{align*}
	X[(\emptyset ,\sfv)]
	&=
	\{(q,\sfv)\mid q\in Q\},
\\
	X[(\sfu ,\sfv)]
	&=
	\{(e,\sfv)\mid e\in E,\; \mathsf{vec}(e)=\sfu \},
\end{align*}
\begin{align*}
	X[\id_\emptyset, \iota_\sfw^\sfv](q,\sfv)
	&= (q,\sfw),
	&
	X[\id_\sfu, \iota_\sfw^\sfv](e,\sfv)
	&=(e,\sfw),
\\
	X[\sigma_\sfu, \iota_\sfw^\sfv](e,\sfv)
	&= (\src(q), \sfw),
	&
	X[\tau_\sfu, \iota_\sfw^\sfv](e,\sfv)
	&= (\tgt(q), \sfw).
\end{align*}
See Figure \ref{f:ElementsOfVASS} for an example.
\item
For a $\cV_r$-presheaf $X$, the corresponding VASS $(Q_X,E_X)$ is given by
\begin{align*}
	Q_X
	&=X[(\emptyset,\mathbf{0})],
	\\
	E_X
	&=\bigcup_{\sfu\in\Z^r}
	\{
		(
		X[(\sigma_\sfu,\iota_{\mathsf{0}}^{\mathsf{0}})](e),
		\sfu,
		X[(\tau_\sfu,\iota_{\mathsf{0}}^{\mathsf{0}})](e)
		)
		\mid
		e\in X[(\sfu,\mathsf{0})]
	\}.
\end{align*}
\end{itemize}

