% \end{equation}
% and the training phase requires the measurement of the control register to collect 
% the results of the individual internal classifiers in predicting some validation data. 
% After measurement, the state collapses to that of a randomly chosen internal classifier $c$, 
% determined by the measurement output of the control register:
% \begin{equation}\label{eq:6b}
%      \ket{\Phi_6}_{tr} = \frac{1}{\sqrt{p_c}} \ket{c} \ket{\phi_{c}}(\beta_0^c\ket{0}+\beta_1^c\ket{1}) \ket{0},
% \end{equation}
% where $p_c$ is the probability of measuring the control register in the basis state corresponding to the classifier $c$:
% \begin{equation}\label{eq:6c}
%     p_c = \frac{\left(\beta_0^c\right)^2 + \left(\beta_1^c\right)^2}{2^d}.
% \end{equation}
% Then, the output qubit is measured and statistics are collected by executing the circuit multiple times 
% to estimate $p_c$ and the single internal classifiers' predictions:
% \begin{equation}\label{eq:7a}
%     \mathbb{P}(0)_c = \frac{(\beta_0^c)^2}{\left(\beta_0^c\right)^2 + \left(\beta_1^c\right)^2}.
% \end{equation}

Upon a successful postselection (e.g., ancilla qubit in state $\ket{0}$), the classifier is executed:
\begin{equation}\label{eq:6a}
    \ket{\Phi_5}_{\text{tr}} = \frac{1}{2^{d/2}} \sum_{c=0}^{2^d-1} \ket{c} \ket{\phi_c} \ket{\varphi_c^\text{out}} \ket{0}.
\end{equation}
The training phase requires measuring the control register to collect 
the predictions of the individual classifiers on a validation dataset. 
After measurement, the state collapses to that of a randomly chosen internal classifier $c$, 
determined by the measurement output of the control register:
\begin{equation}\label{eq:6b}
    \ket{\Phi_6}_{\text{tr}} = \frac{1}{\sqrt{p_c}} \ket{c} \ket{\phi_c} \ket{\varphi_c^\text{out}} \ket{0},
\end{equation}
where $p_c$ is the probability of measuring the control register in the basis state corresponding to the classifier $c$,
which is proportional to the norm of its output state:
\begin{equation}\label{eq:6c}
    p_c = \frac{\braket{\varphi_c^\text{out} | \varphi_c^\text{out}}}{2^d}.
\end{equation}
Then, the observable $O$ is measured on the output qubits of $\ket{\varphi_c^\text{out}}$.
The prediction of the single internal classifier $c$ is then:
\begin{equation}\label{eq:7a}
    \mathbb{E}[O]_c = \frac{\bra{\varphi_c^\text{out}} O \ket{\varphi_c^\text{out}}}{\braket{\varphi_c^\text{out} | \varphi_c^\text{out}}}.
\end{equation}
These values are estimated by executing the circuit multiple times,
and are used to compute the aggregation weights $w_c$.

\begin{algorithm}[t!]
    \small
    \caption{Hybrid training procedure}\label{alg:training}
    \KwIn{validation set $D_{val}(x, y)$, training circuit $QC_{tr}$}
    %\KwOut{estimation of $p[i,c]$, $p_0[i,c]$}
    \KwOut{aggregation weights $w$}
    \For{$x_i \in D_{val}(x, y)$}{
        \For{$c \gets 0$ \textbf{to} $2^d-1$}{
            $k_0[c] \gets 0$\tcp*{init 0 counts for output qubit of each classifier}
            $k_1[c] \gets 0$\tcp*{init 1 counts for output qubit of each classifier}
        }
        \For{$s \gets 0$ \textbf{to} $N_{shots}-1$}{
            $c^s_i, o^s_i \gets QC_{tr}(x_i)$\tcp*{run the circuit for sample $x_i$}
            \eIf(\tcp*[f]{accumulate counts for classifier $c^s_i$}){$o^s_i = 0$}
            {
                $k_0[c^s_i]++$\;
            }{
                $k_1[c^s_i]++$\;
            }
        }
        \For{$c \gets 0$ \textbf{to} $2^d-1$}{
            $p[i,c] \gets (k_0[c] + k_1[c]) / N_{shots}$\tcp*{estimate probability $p_c$ (Eq. \ref{eq:6c})}
            $p_0[i,c] \gets k_0[c] / (k_0[c] + k_1[c])$\tcp*{estimate probability $\mathbb{P}(0)_c$ (Eq. \ref{eq:7a})}
        }
    }
    %\Return $p, p_0$\;
    $w \gets \textit{weights\_learning}(p, p_0)$\tcp*{compute weights $w$}
    \Return $w$\;
\end{algorithm}

The training circuit execution is reported in Algorithm \ref{alg:training}, 
which can be applied to predict the training set (or a different validation). 
For simplicity, here we assume the output of the internal classifiers to be a single qubit,
but the procedure can be generalized to multiple output qubits and observables.
In this setting, $O = \ket{0}\bra{0}$ is the observable for measuring the output qubit.
The expectation $\mathbb{E}[O]_c$ for the internal classifier $c$,
corresponds to the probability $\mathbb{P}(0)_c$ of measuring 0 in the output qubit.
The procedure estimates the values in Eqs. \ref{eq:6c}, \ref{eq:7a}, 
for each internal classifier $c$ and for each validation sample $x_i$,
that are used to compute the weights $w$ for the aggregation of the internal classifiers.
The algorithm iterates over the input samples $x_i$ and runs the training circuit 
for a determined number of shots $N_{shots}$, related to the quality of the estimation. 
Each circuit execution outputs a random classifier index $c^s_i$ and an output measurement $o^s_i$ for that classifier and current data sample $i$. 
Here we assume the circuit to output a successful realization, but in practice
the data selection circuit may fail, and the procedure should be repeated until a successful measurement is obtained.
The results are then accumulated, for each internal classifier and validation sample, and the output values are estimated. 
Afterwards, the individual outputs are used to calculate the weights $w$ for the classifiers to be used at test-time. 
These weights can be computed arbitrarily with classical or quantum procedures. 
A possibility is applying a weighting based on their performance on the training set, 
such as weighting by accuracy or by considering exponential weight decaying with errors. 
The chosen method involves optimization using logistic regression. 
The computed aggregation weights are then encoded in the amplitudes of the control register, 
taking into account positive weights. This enables us to consider an accuracy-weighted ensemble, 
having measured the performance in predicting the training set, or to tune the weight vector with a model fit.

\subsection{Data selection}

