\noindent Thanks to Proposition \ref{prop:reduced}, hypergraphs can always be assumed to have no pairs of indistinguishable vertices, up to some polynomial-time preprocessing. 



\section{Hypergraphs of rank~2}\label{sec:rank2}

\noindent In this section, we solve the game on hypergraphs of rank 2. Note that, by Proposition \ref{prop:1-edge}, the case of hypergraphs of rank 2 reduces to the case of 2-uniform hypergraphs i.e. graphs. Therefore, we will only consider graphs in this section.

\subsection{Some elementary graphs and their outcome}

\noindent We recall some vocabulary from the literature which will be useful, along with some notations. For any graph $G$, we denote by $2G$ the graph formed by two vertex-disjoint copies of $G$. We denote by $P_n$ and $C_n$ the {\em path} and the {\em cycle} on $n$ vertices respectively. If $x_1,\ldots,x_n$ are consecutive vertices along a path $P_n$ (resp. a cycle $C_n$), then that path (resp. cycle) may be denoted as $x_1 x_2 \cdots x_n$. The {\em bull} is the graph obtained by adding a pendent edge to two vertices of $C_3$ (see Figure \ref{fig:example_graphs}, left). The {\em 3-sunlet} is the graph obtained by adding a pendent edge to all vertices of $C_3$ (see Figure \ref{fig:example_graphs}, middle). A {\em pseudo-star} is any connected graph $G$ such that $|V(G)| \geq 3$ and containing a vertex $y$ such that all connected components of $G^{-y}$ are of size 1 or 2. An example pseudo-star is given on the right of Figure \ref{fig:example_graphs}. Note that $C_3$, $P_3$, $P_4$ and $P_5$ are pseudo-stars.


\begin{figure}[h]
	\centering
	\includegraphics[scale=.55]{Example_Graphs2.eps}
	\caption{Some elementary graphs.}\label{fig:example_graphs}
\end{figure}


\begin{proposition}\label{prop:graphs}
    $P_1$ and $P_2$ have outcome $\A$. The bull, $C_5$ and pseudo-stars have outcome $\SL$. The 3-sunlet, $C_4$ and $2P_3$ have outcome $\E$.
\end{proposition}

\begin{proof}
	Clearly, $o(P_1)=o(P_2)=\A$. It is also straightforward that $o(P_3)=\SL$: indeed, Avoider wins as second-to-last player because she only picks one vertex in total, and Enforcer wins as second-to-last player by picking a vertex of degree 1 whatever Avoider's first pick is. As a consequence, $o(2P_3)=\E$ by Theorem \ref{theo:union}. Since $C_4$, $C_5$, the bull, the 3-sunlet and pseudo-stars all contain $P_3$ as a subgraph, Enforcer wins on all these graphs as second-to-last player by Corollary \ref{prop:monotonicity} (Monotonicity Principle), so assume from now that Avoider is the second-to-last player.
	\begin{itemize}
	    \item[--] Let $xyzt$ be a $C_4$. Since $C_4$ is even, Avoider plays first. By symmetry, we can assume that Avoider starts by picking $x$. Enforcer then picks $z$, and Avoider loses since her next pick will fill the edge $xy$ or the edge $xt$.
	    \item[--] Let $xyztu$ be a $C_5$. Since $C_5$ is odd, Enforcer plays first. By symmetry, we can assume that Enforcer starts by picking $x$. Avoider then picks $y$, and wins by picking either $t$ or $u$ in the second round.
	    \item[--] Consider a bull $B$ formed by a $C_3$ $xyz$ plus edges $xu$ and $yv$. Since $B$ is odd, Enforcer plays first. After Enforcer's first pick, $x$ and $u$ are both free, or $y$ and $v$ are both free. By symmetry, assume the former. Avoider then picks $u$, and wins by not picking $x$ in the second round.
	    \item[--] Consider a 3-sunlet $S$ formed by a $C_3$ $xyz$ plus edges $xu$, $yv$ and $zw$. Since $S$ is even, Avoider plays first. If Avoider plays inside the cycle before Enforcer does, then she loses, since Enforcer will then force her to pick one of the other two vertices of the cycle eventually. Therefore, by symmetry, assume Avoider starts by picking $u$. Enforcer then picks $v$, and Avoider picks $w$. Enforcer finally picks $y$, and Avoider loses since her next pick will fill the edge $xu$ or the edge $zw$.
	    \item[--] Lastly, consider a pseudo-star $G$. By definition, there exists a vertex $y$ such that each component of $G^{-y}$ is a $P_1$ or a $P_2$. Therefore, the edges of $G^{-y}$ form a pairing of $G^{-y}$, so $o(G^{-y})=\A$ by Proposition \ref{prop:pairing} (Pairing Principle). Proposition \ref{prop:lastmove} thus ensures that Avoider wins on $G$ as second-to-last player. \qedhere
	\end{itemize}
\end{proof}


\subsection{Complete structural characterisation of the outcome}

\noindent Using the previous elementary examples, we are going to establish the following result, which solves the game for general graphs.

\begin{theorem}\label{theo:graphs}
    Let $G$ be a graph.
    \begin{itemize}[noitemsep,nolistsep]
		\item If $G$ does not contain $P_3$ as a subgraph, then $o(G)=\A$;
		\item If $G$ contains $2P_3$, $C_4$ or the 3-sunlet as a subgraph, then $o(G)=\E$;
		\item In all other cases, $o(G)=\SL$.
	\end{itemize}
\end{theorem}

\begin{corollary}\label{coro:graphs}
    The outcome of the Avoider-Enforcer game can be computed in polynomial time on hypergraphs of rank 2.
\end{corollary}

\noindent To prove Theorem \ref{theo:graphs}, we discuss depending on who is the last player. For both cases, we give two equivalent characterisations of the winner: one that describes the connected components (extensional) and one by forbidden subgraphs (intensional). Let us start with the case where Avoider is the last player, which is straightforward.

\begin{proposition}\label{prop:graphs_A}
	Let $G$ be a graph. The following three assertions are equivalent:
	\begin{enumerate}[noitemsep,nolistsep,label={\textup{(\arabic*)}}]
		\item Avoider wins on $G$ as last player.
		\item Every connected component of $G$ is $P_1$ or $P_2$.
		\item $G$ does not contain $P_3$ as a subgraph.
	\end{enumerate}
\end{proposition}

\begin{proof}
	It is clear that (3)$\implies$(2). Since Avoider loses on $P_3$ as last player by Proposition \ref{prop:graphs}, we also have (1)$\implies$(3) by Proposition \ref{prop:monotonicity} (Monotonicity Principle). Finally, if each connected component of $G$ is $P_1$ or $P_2$, then the edges of $G$ form a pairing of $G$ hence $o(G)=\A$ by Proposition \ref{prop:pairing} (Pairing Principle), so (2)$\implies$(1).
\end{proof}

\noindent The case where Enforcer is the last player is not difficult either, though slightly more involved. The key is the following lemma, which is purely a graph theory result.

\begin{lemma}\label{lem:graphs}
	The connected graphs that do not contain $2P_3$, $C_4$ or the 3-sunlet as a subgraph are exactly the following:
	\begin{enumerate}[noitemsep,nolistsep,label={\textup{\arabic*.}}]
		\item $P_1$;
		\item $P_2$;
		\item $C_5$;
		\item the bull;
		\item pseudo-stars.
	\end{enumerate}
\end{lemma}

\begin{proof}
	Let $G$ be a connected graph that does not contain $2P_3$, $C_4$ or the 3-sunlet as a subgraph. We distinguish between three cases:
	\begin{itemize}
		\item Firstly, suppose $G$ is a path $P_n$. Since $G$ contains no $2P_3$, we have $n \leq 5$. If $n=1$ (resp. $n=2$), then we are in Case 1 (resp. Case 2). If $n \in \{3,4,5\}$, then we are in Case 5.
		\item Secondly, suppose $G$ is a cycle $C_n$. Since $G$ contains no $2P_3$, we have $n \leq 5$. Moreover, since $G$ contains no $C_4$, we have $n \neq 4$. If $n=3$, then we are in Case 5. If $n=5$, then we are in Case 3.
		\item Lastly, suppose $G$ is neither a path nor a cycle. Since $G$ is connected, this means $G$ contains a vertex $x$ of degree at least 3. Let $y,z,t$ be three distinct neighbours of $x$. If $G^{-x}$ contains no $P_3$, then we are in Case 5. Therefore, we now assume that $G^{-x}$ contains a path $P$ on three vertices. Define $m = |\{y,z,t\} \cap V(P)|$.
			\begin{itemize}[noitemsep,nolistsep]
				\item[--] It is impossible that $m=3$. Indeed, if we had $P=yzt$ for instance, then $xyzt$ would be a $C_4$ in $G$.
				\item[--] It is impossible that $m \leq 1$. Indeed, if we had $y,z \not\in V(P)$ for instance, then $yxz \cup P$ would be a $2P_3$ in $G$.
				\item[--] In conclusion, we have $m=2$. Without loss of generality, assume that $V(P)=\{u,y,z\}$ for some $u \not\in\{x,y,z,t\}$. It is impossible that $P=yuz$, because $xyuz$ would be a $C_4$ in $G$. Therefore, we have $P=uyz$ or $P=yzu$: by symmetry, assume $P=uyz$. We get a bull $B$ in $G$ formed by the $C_3$ $xyz$ and the pendant edges $xt$ and $yu$. Finally, it is impossible that $G$ contains a sixth edge intersecting $V(B)$, because a $2P_3$, $C_4$ or 3-sunlet would appear in all cases: see Figure \ref{fig:cases_bull}. Since $G$ is connected, this means $G=B$, so we are in Case 4.


					\begin{figure}[h]
						\centering
						\includegraphics[scale=.5]{Cases_Bull2.eps}
						\caption{All possibilities of adding an edge (dashed line) connected to a bull, up to symmetries. The forbidden subgraph thus created is highlighted.}\label{fig:cases_bull}
					\end{figure}

			\end{itemize}
	\end{itemize}
	Conversely, it is clear that $P_1$, $P_2$, $C_5$, the bull and pseudo-stars are connected graphs which do not contain $2P_3$, $C_4$ or the 3-sunlet as a subgraph. This ends the proof.
\end{proof}

\begin{proposition}\label{prop:graphs_E}
	Let $G$ be a graph. The following three assertions are equivalent:
	\begin{enumerate}[noitemsep,nolistsep,label={\textup{(\arabic*)}}]
		\item Avoider wins on $G$ as second-to-last player.
		\item Every connected component of $G$ is $P_1$ or $P_2$, except for at most one which is either: $C_5$, the bull or a pseudo-star.
		\item $G$ does not contain $2P_3$, $C_4$ or the 3-sunlet as a subgraph.
	\end{enumerate}
\end{proposition}

\begin{proof}
	Since Avoider loses on $2P_3$, $C_4$ and the 3-sunlet as second-to-last player by Proposition \ref{prop:graphs}, we have (1)$\implies$(3) by Proposition \ref{prop:monotonicity} (Monotonicity Principle). If $G$ does not contain $2P_3$, $C_4$ or the 3-sunlet as a subgraph, then each connected component of $G$ is a $P_1$, $P_2$, $C_5$, bull or pseudo-star by Lemma \ref{lem:graphs}, moreover at most one is a $C_5$, bull or pseudo-star otherwise we would get a $2P_3$, so (3)$\implies$(2). Finally, recall that $o(P_1)=o(P_2)=\A$ and $o(C_5)=o(\text{bull})=o(\text{pseudo-star})=\SL$ by Proposition \ref{prop:graphs}. Therefore, using Theorem \ref{theo:union}, a disjoint union of copies of $P_1$ and $P_2$ has outcome $\A$, and adding one component which is a $C_5$, bull or pseudo-star makes the outcome $\SL$. Since $\A$ and $\SL$ are the two outcomes where Avoider wins as second-to-last player, we get (2)$\implies$(1).
\end{proof}

\begin{proof}[Proof of Theorem \ref{theo:graphs} and Corollary \ref{coro:graphs}]
    Theorem \ref{theo:graphs} clearly follows from Propositions \ref{prop:graphs_A} and \ref{prop:graphs_E}. Since testing whether a graph contains a fixed given subgraph can be done in polynomial time, Corollary \ref{coro:graphs} ensues.
\end{proof}



\section{Linear hypergraphs of rank 3}\label{section_rank3}

\noindent After settling hypergraphs of rank 2, a natural first step is to address linear hypergraphs of rank 3, similarly to what was done for the Maker-Breaker convention \cite{kutz}. In this section, we solve the game on linear hypergraphs of rank 3 when Avoider is the last player.

\subsection{Leaf-edges and reduced hypergraphs}

\noindent The most basic linear hypergraphs are linear trees. Let us start by observing some of their properties.

\begin{proposition}\label{prop:leafedge}
    Let $T$ be a linear tree.
    \begin{itemize}[noitemsep,nolistsep]
    \item If $T$ has no leaf-edge, then $T$ is an isolated vertex.
    \item If $T$ has exactly one leaf-edge, then $T$ has a single edge.
    \item If $T$ has exactly two leaf-edges $e$ and $e'$, then $T$ forms a linear simple walk $(e,\ldots,e')$.
   % \item Otherwise, $T$ has at least three leaf-edges.
    \end{itemize}
\end{proposition}

\begin{proof}
    %In the iterative process that defines trees, the last added edge is clearly a leaf-edge
    The first two assertions are straightforward. Let us prove the third one by induction on the number of edges. Clearly, if a linear tree has exactly two edges, then both are leaf-edges and they form a linear simple walk. Now, let $m \geq 2$ such that the property holds, and let $T$ be a linear tree with exactly two leaf-edges, obtained from an isolated vertex by adding edges $e_1,\ldots,e_{m+1}$ successively. Denote by $T_i$ the linear tree with edges $e_1,\ldots,e_i$. Since $T_2$ and $T_{m+1}=T$ have exactly two leaf-edges, and the number of leaf-edges never decreases during the process of adding edges, $T_m$ must also have exactly two leaf-edges $e_r$ and $e_s$ for some $1 \leq r,s \leq m$. Now, by the induction hypothesis, $T_m$ forms a linear simple walk $(e_r\ldots,e_s)$. As $e_{m+1}$ is a leaf-edge of $T_{m+1}$, one of $e_r$ and $e_s$ is not a leaf-edge of $T_{m+1}$. By symmetry, assume $e_s$ is not a leaf-edge of $T_{m+1}$: we have $e_{m+1} \cap e_s =\{x\}$ where $x$ is of degree 1 in $T_m$. Since $|e_{m+1} \cap V(T_m)|=1$, this implies that $e_s$ is the only edge of $T_m$ that intersects $e_{m+1}$, so $(e_r\ldots,e_s,e_{m+1})$ is a linear simple walk.
\end{proof}



\noindent Note that two vertices of degree 1 in the same leaf-edge of a hypergraph are indistinguishable, so Proposition \ref{prop:reduced} allows us to remove these two vertices and that leaf-edge without altering the outcome. Therefore, we introduce the following property, which we will freely assume throughout our study of the game on linear hypergraphs of rank 3.

\begin{definition}
	A hypergraph of rank 3 is {\em reduced} if it contains no leaf-edge of size 3.  % and no edge that is a superset of another edge.
	The {\em reduced hypergraph} of a hypergraph $H$ is obtained from $H$ as follows: remove every leaf-edge $e \in E(H)$ of size 3 as well as two vertices of degree 1 of $e$, then repeat the process on the remaining hypergraph until there is no leaf-edge anymore. % and edges that are supersets of other edges. 
	%\florian{plusieurs manières de le faire a priori, soit parce qu'on fait un ordre différent, soit parce qu'on ne choisit pas de garder le même sommet pour les 3-edges isolées}
	%\aline{L'ordre est pas hyper important non ? ca reste isomorphe à la fin ? il faut peut etre dire qu'on enleve que deux sommets quand c'est une 3 edge isolée}
    %no {\em leaf} i.e. no 3-edge with at least two vertices of degree 1, and no edge that is a superset of another edge.
\end{definition}

\noindent Note that the definition of a linear tree yields the following property.

\begin{observation}\label{obs:hypreduced}
Let $H$ be a 3-uniform hypergraph. The reduced hypergraph of $H$ is an isolated vertex if and only if $H$ is a linear tree.
%\florian{j'ai enlevé l'hypothèse "non-empty connected" qui me paraît inutile}\aline{ok}
\end{observation}

