\subsection{Some elementary linear hypergraphs of rank 3}

\begin{definition}
	We define the following linear hypergraphs of rank 3:
	\begin{itemize}[noitemsep,nolistsep]
		\item For distinct vertices $a$ and $b$, an {\em $ab$-chain} is a hypergraph $P$ which forms a linear simple walk $(e_1,\ldots,e_{\ell})$ in which $|e_i|=3$ for all $1 \leq i \leq \ell$ and $e_1$ (resp. $e_{\ell}$) is the only edge containing $a$ (resp. $b$). Such a walk is said to {\em represent} $P$. We say $\ell=|E(P)|\geq 1$ is the {\em length} of $P$. A {\em chain} is an $ab$-chain for some vertices $a$ and $b$.
		\item A {\em nunchaku} \cite{MBrank3} is a hypergraph $N$ formed by the edges of a linear simple walk $(e_1,\ldots,e_{\ell})$ in which $|e_i|=3$ for all $2 \leq i \leq \ell-1$ and $|e_1|=|e_{\ell}|=2$. We say $\ell=|E(N)|\geq 2$ is the {\em length} of $N$.
		\item A {\em cycle} is a hypergraph $C$ obtained from an $ab$-chain $P$ of length at least 2 by adding a 3-edge $\{a,b,c\}$ where $c \not\in V(P)$. We say $\ell=|E(C)|\geq 3$ is the {\em length} of $C$.
		\item The {\em prism} is the hypergraph $H$ obtained from a cycle $C$ of length 3 by adding a 3-edge containing the vertices that are of degree 1 in $C$.
	\end{itemize}
	See Figure \ref{fig:examples_rank3} for some illustrations.
\end{definition}

\begin{figure}[h]
	\centering
	\includegraphics[scale=.5]{Examples_rank3_2.eps}
	\caption{Some elementary linear hypergraphs of rank 3.}\label{fig:examples_rank3}
\end{figure}

\noindent Given a connected 3-uniform linear hypergraph $H$ and two distinct vertices $a,b \in V(H)$, we denote by $\dist_H(a,b)$ the length of a shortest $ab$-chain in $H$. The following lemma ensures in particular that $\dist_H$ is a metric on $V(H)$.

\begin{lemma}\label{lem:chains}
	Let $H$ be a linear hypergraph, and let $a,b,c \in V(H)$ be pairwise distinct. Let $P$ be an $ab$-chain and let $P'$ be a $bc$-chain. Then $P \cup P'$ contains an $ac$-chain.
\end{lemma}

\begin{proof}
	Let $(e_1,\ldots,e_{\ell})$ and $(e'_1,\ldots,e'_m)$ be linear simple walks representing $P$ and $P'$ respectively, with $a \in e_1$,  $b \in e_{\ell} \cap e'_1$ and $c \in e'_m$. If $c \in V(P)$, then we can define $1 \leq i \leq \ell$ as the minimum index such that $c \in e_i$, and the sequence $(e_1,\ldots,e_i)$ clearly is a linear simple walk which represents an $ac$-chain. A similar argument concludes if $a \in V(P')$. Therefore, we may assume that $a \not\in V(P')$ and $c \not\in V(P)$. Since $b \in V(P')$, we can define $1 \leq i \leq \ell$ as the minimum index such that $e_i \cap V(P') \neq \varnothing$, and $1 \leq j \leq m$ as the maximum index such that $e_i \cap e'_j \neq \varnothing$. The definitions of $i$ and $j$ ensure that the sequence $(e_1,\ldots,e_i,e'_j,\ldots,e'_m)$ is a simple walk, moreover it is linear since $H$ is. Finally, since $a \not\in V(P')$ and $c \not\in V(P)$, the only edge of this walk containing $a$ is $e_1$ and the only edge containing $c$ is $e'_m$, therefore it represents an $ac$-chain.
\end{proof}

%\begin{notation}
%	Given a connected 3-uniform linear hypergraph $H$ and two distinct vertices $a,b \in V(H)$, we denote by $\dist_H(a,b)$ the length of a shortest $ab$-chain in $H$. Lemma \ref{lem:chains} ensures that $\dist_H$ is a metric on $V(H)$.
%\end{notation}

\noindent We will see that nunchakus, prisms and cycles play a major role for the Avoider-Enforcer game on hypergraphs of rank 3. We now determine their outcome.


\begin{proposition}\label{prop:outcome_rank3}
Nunchakus have outcome $\SL$. The prism and cycles have outcome $\A$.
%We have $o(\text{nunchaku})=\SL$ and $o(\text{cycle})=o(\text{prism})=\A$.
\end{proposition}

\begin{proof}
	We first prove the result on nunchakus when Avoider is the last player (note that Avoider is also the first player since nunchakus are odd). We proceed by induction on length. A nunchaku of length 2 is simply a $P_3$ graph, on which we already know Avoider loses as last player. Now, let $N$ be a nunchaku of length $\ell \geq 3$, and assume that Avoider loses as last player on all nunchakus of length at most $\ell-1$. Let $a$ and $b$ be the vertices of degree 1 in the 2-edges of $N$. If Avoider's first pick is in one of the 2-edges, then she loses since this creates a 1-edge. Otherwise, Avoider's first pick $x$ creates two new nunchakus $N_1$ and $N_2$, both shorter than $N$, one of which does not contain $a$ and the other does not contain $b$ (see Figure \ref{fig:nunchaku_induction}). Enforcer can respond by picking $y \in \{a,b\}$, so that $N_i$ is a subhypergraph of the updated hypergraph $N^{+x-y}$ for some $i \in \{1,2\}$. The induction hypothesis ensures that Enforcer wins on $N_i$ as second-to-last player, so Enforcer wins on $N^{+x-y}$ as second-to-last player by Proposition \ref{prop:monotonicity} (Monotonicity Principle), therefore Enforcer wins on $N$ as second-to-last player.

	\begin{figure}[h]
		\centering
		\includegraphics[width=\textwidth]{Nunchaku_Induction.eps}
		\caption{Top: if $x$ is of degree 2 in $N$ (left) then $N^{+x}$ contains two disjoint nunchakus (right). Bottom: if $x$ is of degree 1 in $N$ (left) then $N^{+x}$ contains two nunchakus sharing a 2-edge (right).}\label{fig:nunchaku_induction}
	\end{figure}

	\noindent To show that Avoider wins on any nunchaku $N$ as second-to-last player, it suffices to show that there exists $y\in V(N)$ such that Avoider wins on $N^{-y}$ as last player, according to Proposition \ref{prop:lastmove}. Let $y$ be a vertex of degree 1 in a 2-edge of $N$: since $N^{-y}$ admits a pairing, as illustrated in Figure \ref{fig:nunchaku_pairing}, we know $o(N^{-y})=\A$ by Proposition \ref{prop:pairing} (Pairing Principle).

	\begin{figure}[h]
		\centering
		\includegraphics[width=\textwidth]{Nunchaku_Pairing.eps}
		\caption{$N$ is on the left, $N^{-y}$ is on the right with a pairing being represented.}\label{fig:nunchaku_pairing}
	\end{figure}

	\noindent It is clear that a cycle admits a pairing, where each vertex of degree 1 is paired with a neighbour of degree 2, so Avoider likewise wins on any cycle as last player. Finally, let $H$ be a prism, and suppose Avoider is the last player: since $H$ is even, this means Enforcer is the first player. Enforcer picks some vertex $y$, and Avoider picks some $x \in N(y)$ (the set of neighbours of $y$). Since $x$ is of degree 2 in $H$ (as is any vertex in a prism), this choice ensures that the updated hypergraph $H^{-y+x}$ contains only one 2-edge $e$. There are only two rounds of play left, so Alice simply has to pick some $z \not\in e$ in the next round to win.
\end{proof}




\subsection{Structural characterisation of the outcome when Avoider is the last player}

\noindent We are going to establish the following result.

\begin{theorem}\label{theo:3unif_A}
	Let $H$ be a reduced linear hypergraph of rank 3. The following two assertions are equivalent:
	\begin{enumerate}[noitemsep,nolistsep,label={\textup{(\arabic*)}}]
		\item Avoider wins on $H$ as last player.
		\item Each connected component of $H$ is a cycle, a prism, an isolated 2-edge or an isolated vertex.
	\end{enumerate}
\end{theorem}

\begin{corollary}\label{coro:3unif_A}
    Deciding whether a linear hypergraph of rank 3 has outcome $\A$ can be done in polynomial time.
\end{corollary}

\noindent First of all, notice that addressing the connected case is sufficient: indeed, by Theorem \ref{theo:union}, Avoider wins as last player if and only if Avoider wins on each connected component as last player. Also note that the result is trivial if there exists a 0-edge or a 1-edge, since Avoider then loses as last player.
\\ Enforcer's main idea is to rely on Avoider creating a nunchaku: since a nunchaku has outcome $\SL$ according to Proposition \ref{prop:outcome_rank3}, this would ensure Enforcer's win as second-to-last player. This happens more easily if Avoider is the first player. Therefore, we distinguish two cases depending on parity.

%\noindent First of all, notice that $H$ can be assumed to be connected: indeed, by Theorem \ref{theo:union}, Avoider wins on $H$ as last player if and only if Avoider wins on each connected component of $H$ as last player. Moreover, we can easily dismiss 1-edges and 2-edges, as we now show. If $H$ contains a 1-edge, then Avoider loses on $H$ as last player, so Theorem \ref{theo:3unif_A} holds in that case. If $H$ contains at least two 2-edges, then connectedness ensures that $H$ contains a nunchaku, which has outcome $\SL$, so Avoider loses as last player

\subsubsection{Odd case: Avoider is first and last}

\noindent We can first address the case where there exists a 2-edge.

\begin{proposition}\label{prop:3unif_A_odd}
	Avoider loses as last player on any odd connected linear hypergraph of rank 3 which contains a 2-edge.
\end{proposition}

\begin{proof}
	If Avoider plays her first move inside a 2-edge, then this creates a 1-edge. Otherwise, linearity and connectedness ensure that there exists a chain between the vertex that Avoider picks and a 2-edge, so Avoider's first move creates a nunchaku. In all cases, we get a subhypergraph that has outcome $\SL$, so Enforcer wins as second-to-last player by Proposition \ref{prop:monotonicity} (Monotonicity Principle).
\end{proof}

\noindent In the 3-uniform case, Avoider needs to play twice before a nunchaku can appear. After Avoider plays her first move, Enforcer wants to pick a non-cut vertex of the starting hypergraph, so that Avoider's second pick will necessarily be connected to the first by a chain. For this, the following lemma (which is not game-related in itself) is key.

\begin{lemma}\label{lem:NonCut1}
	Any connected reduced linear 3-uniform hypergraph which is not an isolated vertex has at least two non-cut vertices.
\end{lemma}

