	\begin{claim}\label{claim_NonCut3}
	    Let $y$ be a vertex that is not in the same connected component as $x$ in $H^{-u}$. Then $\dist_H(x,y)=\dist_H(x,u)$, and there exists an edge $e_y \supseteq \{u,y\}$ such that, for all shortest $xy$-chain in $H$, $e_y$ is the only edge of the chain containing $u$.
	\end{claim}
	\begin{proofclaim}[Proof of Claim \ref{claim_NonCut3}]
		Let $y$ be a vertex that is not in the same connected component as $x$ in $H^{-u}$: in other words, all $xy$-chains in $H$ contain $u$.
		Let $P$ be a shortest $xy$-chain in $H$, and let $e_y$ be its edge containing $y$. By definition of $u$, we have $\dist_H(x,y)\leq \dist_H(x,u)$, so $u$ cannot appear in any edge of $P$ other than $e_y$, otherwise we would get an $xu$-chain shorter than $P$ (see Figure \ref{fig:lemma_new}). By linearity of $H$, that edge $e_y$ must belong to all shortest $xy$-chains in $H$.
