$E_k^{(n)} = \sigma^{(n)}(\mu)$, see (\ref{eq:sigman}),  we deduce that $\mu\in \Lambda^{(n)}$ and  
by   the first part of the proof, 
$k = k_\mu$. We have proved the surjectivity  of the mapping $\Psi$.
\end{enumerate}

\noindent
As  $(E_k^{(n)})_{k\in J^{(n)}}$ is a  partition of the set $D_b$ by non-empty sets and  $J^{(n)} \subseteq \{1, 2, \dots, 2^n\}$, we get the inequality  $\text{card}\, J^{(n)} \leq \min(\text{card}\, D_b, 2^n)$.


\end{proof}
\subsection{Proof of Lemma \ref{lemma:muto}}
\label{subsec:proof:lemmamuto}
\lemmamutocmd*
\begin{proof}
    As   $\mu = (t_1, t_2, \dots, t_n)\in \Lambda^{(n)}$, we know that $\sigma^{(n)}(\mu) \not=\emptyset$ and 
    $t_n = \pm n$, see Definition \ref{def:LambdaN}. Moreover, by definition of the mappings  $\sigma^{(n)}$ and $\sigma^{(n-1)}$, see  (\ref{eq:sigman}), we have:
\begin{equation}\label{eq:kmusig}
\sigma^{(n)}(\mu) = \begin{cases}
 \sigma^{(n-1)}(\widetilde \mu) \cap Q_n    & \text{ if }\,  t_n = n  \\
  \sigma^{(n-1)}(\widetilde \mu) \cap \overline{Q_n}    & \text{ if }\,  t_n =  -n \end{cases}
  .
 \end{equation}
 We deduce that $\widetilde\mu\in\Lambda^{(n-1)}$.
 From the construction (\ref{eq:partition}) and the equalities 
 $\sigma^{(n)}(\mu) = E_{k_\mu}^{(n)}$ and $\sigma^{(n-1)}(\widetilde\mu) = E_{k_{\widetilde \mu}}^{(n-1)}$, we get:
\begin{equation}\label{eq:kmu11}
E^{(n)}_{k_\mu} = \begin{cases}
     E_{k_{\widetilde \mu}}^{(n-1)} \cap Q_n    & \text{ if }\,  t_n = n \\
  E_{k_{\widetilde \mu}}^{(n-1)} \cap  \overline{Q_n}& \text{ if }\,  t_n = - n
\end{cases} = \begin{cases}
     E_{k_{ \mu}}^{(n-1)} \cap Q_n    & \text{ if }\,  k_\mu \leq 2^{n-1} \\
  E_{k_{ \mu} - 2^{n-1}}^{(n-1)} \cap  \overline{Q_n}& \text{ if }\,  2^{n-1} < k_\mu  
\end{cases}.
\end{equation}
\noindent
As we have $E_{k_\mu}^{(n)} \not=\emptyset$, we deduce the equivalences 
$k_\mu \leq 2^{n-1}\Longleftrightarrow t_n = n$ and 
$k_\mu > 2^{n-1}\Longleftrightarrow t_n = - n$.

\begin{itemize}
\item If $k_\mu \leq  2^{n-1}$, then  $ E_{k_{\widetilde \mu}}^{(n-1)} \cap   Q_n =E_{k_{ \mu}}^{(n-1)} \cap Q_n  \not=\emptyset$, so 
 $E_{k_{\widetilde \mu}}^{(n-1)} \cap E_{k_{ \mu}}^{(n-1)}  \not=\emptyset$. As $(E_k^{(n-1)})_{1 \leq k \leq 2^{n-1}}$   is a partition of the set $D_b$, we get      $k_\mu = k_{\widetilde\mu}$.

\item If $k_\mu >   2^{n-1}$,  by replacing $Q_n$ by $\overline{Q_n}$ in the previous reasoning, we obtain in this case $k_\mu = k_{\widetilde\mu} + 2^{n-1}$.
\end{itemize}

\end{proof}


\subsection{Proof of Proposition \ref{prop:isom}}
\label{subsec:proof:propisom}
 \propisomcmd*
\begin{proof}
\noindent
To prove   the equivalence 
\[ \mu \preceq^{(n)} \mu' \Longleftrightarrow k_\mu \leq k_{\mu'} \quad \text{for all} \quad \mu, \mu' \in \Lambda^{(n)}, \]
which means that $\Psi$ is an isomorphism for order relations,
we proceed by induction on $n$ and rely on Lemma \ref{lemma:muto}.

\noindent
$\bullet\,$ Case  $n = 1$. From  Lemma \ref{lemma:LambdaN} and the definition  (\ref{eq:partition}) of the partition $(E_k^{(1)})_{1 \leq k \leq 2}$, we  deduce: 
  \[ \Lambda^{(1)} = \begin{cases} \{(1)\}& \text{ if } \quad \overline{Q_1} = \emptyset\\
 \{(-1)\} & \text{ if } \quad Q_1 = \emptyset\\
 \{(1),(-1)\} & \text{otherwise.}\end{cases} \quad \text{and} \quad 
 J^{(1)} = \begin{cases} \{1\}& \text{ if }\quad  \overline{Q_1} = \emptyset\\
 \{2\} & \text{ if }\quad Q_1 = \emptyset\\
 \{1,2\} & \text{otherwise.}
\end{cases}\]
\noindent
If $\overline{Q_1} = \emptyset$ or  $Q_1 = \emptyset$, the mapping  $\Psi : \Lambda^{(1)} \rightarrow J^{(1)}$ respects order relations. In the remaining case, we have   $(1) \prec^{(1)} (-1)$ and 
$\Psi((1)) = 1 < 2 = \Psi((-1))$.

\noindent
$\bullet\,$ Suppose that $n > 1$ and  the mapping %$\widetilde \Psi : 
%\Lambda^{n-1} \rightarrow J^{(n-1)}
%: \widetilde \mu \mapsto k_{{\widetilde \mu}}$ 
\begin{center}
\begin{tabular}{ll}
$\widetilde \Psi :$ & $\Lambda^{n-1} \rightarrow J^{(n-1)}$\\
&  $\widetilde \mu \mapsto k_{{\widetilde \mu}}$ 
\end{tabular}
\end{center}
respects order relations. Let us prove that the mapping 
%$\Psi : \Lambda^{(n)} \rightarrow J^{(n)} : \mu \mapsto k_\mu$ 
\begin{center}
\begin{tabular}{ll}
$\Psi :$ & $\Lambda^{n} \rightarrow J^{(n)}$\\
&  $ \mu \mapsto k_{\mu}$ 
\end{tabular}
\end{center}
respects order relations.

\noindent Let  $\mu = (t_1, t_2, \dots, t_n), \mu' = (t'_1, t'_2, \dots, t'_n) $ be in $\Lambda^{(n)}$. We must prove the equivalence  
$\mu \preceq^{(n)} \mu' \Longleftrightarrow k_\mu \leq k_{\mu'}  $.

\noindent Set      $\widetilde\mu = (t_1, t_2, \dots, t_{n-1})$ and $\widetilde{\mu'} = (t'_1, t'_2, \dots, t'_{n-1})$, so  $\mu = (\widetilde\mu, t_n)$ and $\mu' = (\widetilde{\mu'}, t'_n)$. 
From Definition \ref{def:LambdaN} and Lemma \ref{lemma:LambdaN}, we know  that:
\[ \widetilde \mu\in \Lambda^{(n-1)} \text{ and } t_n = \pm n \quad ;\quad \widetilde{\mu'}\in \Lambda^{(n-1)}  \text{ and } t'_n = \pm n\]
We remind   that the order relations $\preceq^{(n)}$ and $\preceq^{(n-1)}$ satisfy the following equivalence, see Definition \ref{def:orderrel}:
\[ \mu \preceq^{(n)} \mu' \Longleftrightarrow 
[t_n = n \text{ and } t'_n = -n ]\quad \text{or} \quad 
[\widetilde \mu \preceq^{(n -1)}\widetilde{\mu'} \text{ and } t_n = t'_n].\]
\noindent
To prove the equivalence  $\mu \preceq^{(n)} \mu' \Longleftrightarrow k_\mu \leq k_{\mu'}  $, we rely on (\ref{eq:kmu10}) and the induction hypothesis:
\begin{itemize}
    \item If  $\mu \preceq^{(n)} \mu'$  and  $t_n = n $  and $t'_n = -n$, then we deduce from (\ref{eq:kmu10})  $k_\mu \leq 2^{n-1} < k_{\mu'}$. 
    \item If  $\mu \preceq^{(n)} \mu'$  and  $t_n = t'_n $,  then  we have, see Definition \ref{def:orderrel}, 
  $\widetilde \mu \preceq^{(n -1)}\widetilde{\mu'} $. By the induction hypothesis,  we know that $k_{\widetilde \mu} \leq k_{\widetilde {\mu'}}$ and from  (\ref{eq:kmu10}) and  $t_n = t'_n$, it is easy to deduce the inequality $k_\mu \leq k_{\mu'}$.
\end{itemize}
 \noindent We have proven the implication $\mu \preceq^{(n)} \mu' \Longrightarrow k_\mu \leq k_{\mu'}  $.

\noindent
Suppose now that we have $ k_\mu \leq k_{\mu'}$,  then the indices $k_\mu$ and $k_{\mu'}$ necessarily satisfy:
\[ k_\mu \leq 2^{n-1} < k_{\mu'}\quad \text{or} \quad 
k_\mu \leq k_{\mu'} \leq 2^{n-1}\quad \text{or} \quad 
 2^{n-1} < k_\mu \leq k_{\mu'}.\]
 \noindent
By relying on (\ref{eq:kmu10}) and Definition \ref{def:orderrel}, we deduce:
 \begin{itemize}
     \item If $k_\mu \leq 2^{n-1} < k_{\mu'}$, then $t_n = n$ and  $t'_n = -n$,  which implies $\mu \preceq^{(n)} \mu'    $.
     \item If $k_\mu \leq k_{\mu'} \leq 2^{n-1}$, then $t_n = t'_n =n$ and $k_{\widetilde \mu} = k_\mu \leq k_{\mu'} = k_{\widetilde{\mu'}}$. By the induction hypothesis, we know that $\widetilde \mu \preceq^{(n -1)}\widetilde{\mu'} $ and by definition of the order relation $\preceq^{(n)}$, we have  $\mu \preceq^{(n)} \mu'$.
     \item If $2^{n-1} < k_\mu \leq k_{\mu'}  $, then $t_n = t'_n = - n$ and $k_{\widetilde \mu} = k_\mu  - 2^{n-1}\leq k_{\mu'} - 2^{n-1}= k_{\widetilde{\mu'}}$. We get $\mu \preceq^{(n)} \mu'    $ as in the previous case.
 \end{itemize}

\noindent
 We have proved the implication $\mu \preceq^{(n)} \mu' \Longleftarrow k_\mu \leq k_{\mu'}  $.






\end{proof}
