Let $\beta_n$  be the number of operations required to construct the set $\Lambda^{(n)}$.  We have $\beta_1 = 1$. Let us  prove:
\[ \forall n \geq 2,\, \beta_n = \beta_{n-1} + \omega^{(n-1)} + \text{card}\,(Z_{n-1}) \quad  \text{where} \quad \omega^{(n-1)} = \text{card}\, (\Lambda^{(n-1)}).\]
To construct $\Lambda^{(n)}$  from $\Lambda^{(n-1)}$, we have to construct   the two sets $\Lambda^{(n)}_+$  and  $\Lambda^{(n)}_-$ from $\Lambda^{(n-1)}$, which by    Lemma \ref{comp2} requires 
$\text{card}\,(X_{n-1} \cup Z_{n-1}) + \text{card}\,(Y_{n-1} \cup Z_{n-1})$ operations. Using Lemma \ref{comp1}, we deduce:
\begin{align}
 \beta_n   & = \beta_{n-1} + 
 \text{card}\,(X_{n-1} \cup Z_{n-1}) + \text{card}\,(Y_{n-1}\cup Z_{n-1})\nonumber\\
 &= \beta_{n-1} + 
 \text{card}\,(X_{n-1}) + \text{card}\,(Y_{n-1}) + 2 \,\text{card}\, (Z_{n-1})\nonumber\\
 & = \beta_{n-1} + \omega^{(n-1)} + \text{card}\, (Z_{n-1}).\nonumber\\
\end{align}
 \noindent
As we  have $\omega^{(n-1)} \leq \text{card}\, (D_b)$, see Lemma \ref{lemma:mutokmu}, 
and by  the  third statement of Lemma \ref{comp2}, we deduce   $\text{card}\,(Z_{n-1}) \leq \dfrac{\text{card}\,(D_b)}{2}$, we get the inequality: 
\[ \beta_n \leq \beta_{n-1} + \dfrac{3\cdot \text{card}(D_b)  }{2}.\]
\noindent
Using that $\beta_1 = 1$, we obtain  that
$\forall n \geq 1,\, \beta_n \leq 1 + \dfrac{3\cdot \text{card}(D_b) \cdot (n-1)}{2} \leq \dfrac{3\cdot \text{card}(D_b) \cdot n}{2}$.
\end{proof}


\subsection{Proof of Lemma \ref{lemma:hmutokmu}}
\label{subsec:proof:Hmu}
\Hmucmd*
\begin{proof}
We proceed by induction on $n$ and rely on   (\ref{eq:matrixmatrixrel}) and   (\ref{eq:kmu10}).

\noindent
$\bullet\,$ Case  $n = 1$. From  Lemma \ref{lemma:LambdaN} and  the definition of the partition $(E_k^{(1)})_{1 \leq k \leq 2}$, see (\ref{eq:partition}), we  deduce: 
  \[ \Lambda^{(1)} = \begin{cases} \{(1)\}& \text{ if } \quad \overline{Q_1} = \emptyset\\
 \{(-1)\} & \text{ if } \quad Q_1 = \emptyset\\
 \{(1),(-1)\} & \text{otherwise.}\end{cases} \quad \text{and} \quad 
 J^{(1)} = \begin{cases} \{1\}& \text{ if }\quad  \overline{Q_1} = \emptyset\\
 \{2\} & \text{ if }\quad Q_1 = \emptyset\\
 \{1,2\} & \text{otherwise.}
\end{cases}\]
\noindent
We remind that $M_1 = \begin{bmatrix}
s_1 & 1 \\
1 & r_1
\end{bmatrix}   $. Set $\mu = (1)$ and $\mu' = (-1)$. We distinguish the following cases: 

\begin{itemize}
\item  If  $\Lambda^{(1)} = \{(1)\}$ (respectively   $\Lambda^{(1)} = \{(-1)\}$),  then  we have $k_\mu = 1$
(respectively  $k_{\mu'} = 2$) and $H_\mu$ is the first row  (respectively $H_{\mu'} $ is the second row) of the matrix $M_1$.

\item  If  $\Lambda^{(1)} = \{(1),(-1)\}$, then  $k_\mu = 1$, 
   $k_{\mu'} = 2$  and $H_\mu = \begin{bmatrix}
       s_1 & 1
   \end{bmatrix}$,    $H_{\mu'} = \begin{bmatrix}
       1 & r_1
   \end{bmatrix}$, thus $H_\mu$   (respectively $H_{\mu'}$)  is the first row  (respectively   is the second row) of the matrix $M_1$.
\end{itemize}

\medskip
   \noindent
$\bullet\,$ Case  $n > 1$.  Suppose that for each $\widetilde\mu\in \Lambda^{(n-1)}$, the row matrix $H_{\widetilde\mu}$ is equal to    $k_{\widetilde\mu}$-th row     of the matrix $M_{n-1}$. 
Let $\mu = (t_1, \dots, t_{n-1}, t_n)\in \Lambda^{(n)}$. Set $\widetilde\mu = (t_1, \dots, t_{n-1})$. Then, by Lemma  \ref{lemma:LambdaN},    we have  $\widetilde\mu\in \Lambda^{(n-1)}$ and $t_n = \pm n$.

\noindent
Using  (\ref{eq:taumapping}), we get $H_\mu = \begin{bmatrix}
    H_{\widetilde\mu} &  L_{t_n}
\end{bmatrix}$. We distinguish the following cases: 

\begin{itemize}
\item If $t_n = n$, then by (\ref{eq:kmu10}), we have $k_\mu = k_{\widetilde\mu} \leq 2^{n-1}$.  Using  (\ref{eq:matrixmatrixrel})  and the induction hypothesis, we get:
 $$H_\mu = \begin{bmatrix}
    H_{\widetilde\mu}  & L_{n}
\end{bmatrix} = \begin{bmatrix}
    H_{\widetilde\mu}  & s_n  & 1 
\end{bmatrix}$$
is the $k_{\mu}$-th row  of the matrix $M_n$.


\item If $t_n = - n$, then by (\ref{eq:kmu10}), we have $k_\mu = k_{\widetilde\mu} +  2^{n-1} > 2^{n-1}$.  Using  (\ref{eq:matrixmatrixrel})  and the induction hypothesis, we get:
 $$H_\mu = \begin{bmatrix}
    H_{\widetilde\mu}  & L_{-n}
\end{bmatrix} = \begin{bmatrix}
    H_{\widetilde\mu}  & 1  & r_n 
\end{bmatrix}$$
is the $k_{\mu}$-th row  of the matrix $M_n$.
\end{itemize}

\end{proof}

\subsection{Proof of Lemma \ref{lemma:coM}}
\label{subsec:proof:coM}

\noindent
The idea behind the proof of the  formulas (\ref{eq:coefredM}) in Lemma \ref{lemma:coM} is based on:
\begin{enumerate}
    \item The use of formulas for computing  the coefficients of the unreduced matrix $M_n$ given  in  \cite{baaj2022learning}, which are based on the $n$   partitions $ (I_j^{n,\top}, I_j^{n, \bot})$ of  $I_n=\{1, 2, \dots, 2^n\}$.
    \item The following lemma,    which asserts that    for all   $j\in\{1, 2, \dots,n\}$,  the  bijective mapping  
    %$\Psi : \Lambda^{(n)} \rightarrow J^{(n)} : \mu  \mapsto k_\mu$,  
\begin{center}
\begin{tabular}{ll}
$\Psi : $ & $\Lambda^{(n)} \rightarrow J^{(n)}$\\
& $\mu  \rightarrow  k_\mu$ 
\end{tabular}
\end{center}
    (see Lemma \ref{lemma:mutokmu}) allows us to map    the partition   $ (\Lambda_j^{n,\top}, \Lambda_j^{n, \bot})$ of   the set  $\Lambda^{(n)}$, see (\ref{eq:Lnpart}), onto the partition  $(I_j^{n,\top} \cap J^{{n)}}, I_j^{n, \bot} \cap J^{(n)})$ of the set $J^{(n)}$.
\end{enumerate}

\begin{lemma}\label{lemma:Ltb}
Let $\mu =(t_1, t_2, \dots, t_n)\in \Lambda^{(n)}$
and $j\in\{1, 2, \dots, n\}$. Then, we have: 
\begin{enumerate}
    \item $k_\mu \in I_j^{n, \top} \Longleftrightarrow \mu\in \Lambda_j^{n, \top}$.
    \item $k_\mu \in I_j^{n, \bot} \Longleftrightarrow \mu\in \Lambda_j^{n, \bot}$.
\end{enumerate}
\end{lemma}

\begin{proof}
We remind that by Definition  \ref{def:Lj},  $\mu\in  \Lambda_j^{n, \top}$ (respectively $\mu\in \Lambda_j^{n, \bot}$) means that   $t_j = j$  (respectively $t_j = - j$).  
 We prove the two equivalences by induction on $n$.

\smallskip
\noindent For $n = 1$, we have:
 \[ \Lambda^{(1)} = \begin{cases} \{(1)\}& \text{ if } \quad \overline{Q_1} = \emptyset\\
 \{(-1)\} & \text{ if } \quad Q_1 = \emptyset\\
 \{(1),(-1)\} & \text{otherwise.}\end{cases}, \quad 
 J^{(1)} = \begin{cases} \{1\}& \text{ if }\quad  \overline{Q_1} = \emptyset\\
 \{2\} & \text{ if }\quad Q_1 = \emptyset\\
 \{1,2\} & \text{otherwise.}
\end{cases}\]
\noindent \text{and} \[ \quad I_1^{1, \top} = \{1\}, \quad I_1^{1,\bot} = \{2\}. \]
\noindent
By using the bijective mapping  
\begin{center}
\begin{tabular}{ll}
$\Psi : $ & $\Lambda^{(1)} \rightarrow J^{(1)}$\\
& $\mu  \mapsto  k_\mu$ 
\end{tabular}
\end{center}
%$\Psi : \Lambda^{(1)} \rightarrow J^{(1)} : \mu  \rightarrow  k_\mu$,$$ 
(see Lemma \ref{lemma:mutokmu}), we check that the two equivalences hold.

 \smallskip
\noindent
Assume now that $n > 1$ and that both equivalences hold  for $n - 1$. 
Let $\widetilde\mu = (t_1, t_2, \dots, t_{n-1})\in \Lambda^{(n-1)}$, so we have  $\mu = (\widetilde\mu, t_n)$  and $t_n = \pm n$. 
We rely on Lemma \ref{lemma:muto}
  and the following equalities:
\begin{equation}\label{eq:equal}
 \forall j\in \{1, 2, \dots, n-1\},\,
I_j^{n, \top} = I_j^{n -1, \top}\cup \tau_{2^{n-1}}I_j^{n - 1, \top} \text{ and }
I_j^{n, \bot} = I_j^{n -1, \bot}\cup \tau_{2^{n-1}}I_j^{n - 1, \bot}     
\end{equation}

\noindent where $\tau_{2^{n-1}}$ is the mapping $k \mapsto k + 2^{n-1}$.\\ 
$\bullet\,$
If $t_n = n\,$, i.e., $\,\mu\in\Lambda_n^{n,\top}$,  then we have: 
\[ k_\mu = k_{\widetilde\mu} \leq 2^{n-1}  \quad \text{(Lemma \ref{lemma:muto})}.\]
Thus, for $1 \leq j \leq n -1$, the two equivalences follow from the induction hypothesis and (\ref{eq:equal}).
For $j = n$, we have $I_n^{n, \top} = \{1, 2, \dots, 2^{n-1}\}$  and   $k_\mu \in I_n^{n, \top}$.

\noindent $\bullet\,$
If $t_n = -n\,$, i.e.,  $\,\mu\in\Lambda_n^{n,\bot}$, then we have: 
\[ k_\mu = k_{\widetilde\mu} + 2^{n-1}  \quad \text{(Lemma \ref{lemma:muto})}.  \]
Thus, for $1 \leq j \leq n -1$, the two equivalences follow from the induction hypothesis and (\ref{eq:equal}).
For $j = n$, we have $I_n^{n, \bot} = \{2^{n-1 }+ 1,   \dots, 2^{n}\}$ and   $k_\mu \in I_n^{n, \bot}$.

\end{proof}
\noindent We are now in position to prove Lemma \ref{lemma:coM}:
\lemcoMcmd*
\begin{proof}
\cite{baaj2022learning} proved the following formulas for the coefficients of the matrix $M_n = [m_{ij}]_{1 \leq i \leq 2^n, 1 \leq j \leq 2n}$:    
\begin{equation}\label{eq:coefMrap1}
   m_{i, 2j-1} =
   \begin{cases}
 s_j     & \text{ if }  i\in I_j^{n, \top} \\
  1 & \text{ if }  i\in I_j^{n, \bot}  
  \end{cases}
, \quad 
     m_{i, 2j} =
   \begin{cases}
 1     & \text{ if }  i\in I_j^{n, \top} \\
  r_j & \text{ if }  i\in I_j^{n, \bot} 
  \end{cases}.
  \end{equation}
As by Lemma \ref{lemma:hmutokmu}, the row of the matrix ${\cal M}_n$ with index $\mu\in \Lambda^{(n)}$ is equal to the row of the matrix $M_n$ with index $k_\mu$, we immediately deduce  from Lemma \ref{lemma:Ltb} and (\ref{eq:coefMrap1}) the formulas: 
\begin{equation} 
 \dot{m}_{\mu, 2j-1}  = m_{k_\mu, 2j -1} = 
   \begin{cases}
 s_j     & \text{ if }  \mu\in \Lambda_j^{n, \top} \\
  1 & \text{ if }  \mu\in \Lambda_j^{n, \bot}  
  \end{cases}
, \quad 
   \dot{m}_{\mu, 2j} = m_{k_\mu, 2j} =
   \begin{cases}
 1     & \text{ if }  \mu\in \Lambda_j^{n, \top} \\
  r_j & \text{ if }  \mu\in \Lambda_j^{n, \bot}  
   \end{cases}.
 \nonumber\end{equation}
\end{proof}


\subsection{Proof of Theorem \ref{theorem:YO}}
\label{subsec:proof:YO}
\theoremYOcmd*
\begin{proof}
First, let us recall that that we have $\dot{Y}_n = [\widetilde{\Pi}(\sigma^{(n)}(\mu)]_{\mu\in \Lambda^{(n)}}$ where 
$\sigma^{(n)}(\mu) = E_{k_\mu}^{(n)}$, see (\ref{eq:buildupsigman}) and Lemma \ref{lemma:mutokmu}. From  (\ref{eq:PiO}), we also have 
${\cal O}_n = [\Pi(E_{k_\mu}^{(n)}]_{\mu\in \Lambda^{(n)}}$.

\noindent
$\bullet\,$ As $X = [x_l]_{1\leq l \leq 2n}$ is a solution of the system  $(\Upsigma_n)$, we have for each $\mu\in \Lambda^{(n)}$:
\begin{align}\label{eq:A}
\widetilde{\Pi}(E_{k_\mu}^{(n)}) & = \min_{1 \leq l \leq 2n} \max(\dot{\gamma}_{\mu, l},  x_l)\nonumber\\
& = \min_{1 \leq j \leq n}\min(\max(\dot{\gamma}_{\mu, 2j -1}, x_{2j -1}), \max(\dot{\gamma}_{\mu, 2j}, x_{2j}))\nonumber\\
& = \min_{1 \leq j \leq n}\min(\max(\dot{\gamma}_{\mu, 2j -1}, s_j), \max(\dot{\gamma}_{\mu, 2j}, r_j))\\   
\nonumber\end{align}
\noindent where $\dot{\gamma}_{\mu, l}$ for $\mu\in \Lambda^{(n)}, 1\leq l \leq 2n$ are the coefficients of the matrix $\dot{\Gamma}_n$ of the system $(\Upsigma_n)$, see Lemma \ref{lem:coG}.\\
$\bullet\,$ As ${\cal O}_n := {\cal M}_n \Box_{\max}^{\min} I_n$, from (\ref{eq:PiO}), we get for each $\mu\in \Lambda^{(n)}$:
\begin{equation}\label{eq:B}
\Pi(E_{k_\mu}^{(n)})  
  = \min_{1 \leq j \leq n}\min(\max(\dot{m}_{\mu, 2j -1}, \lambda_j), \max(\dot{m}_{\mu, 2j}, \rho_{j})).    
\end{equation}
But, by using the commutativity of $\max$ and the formulas (\ref{eq:coefredM}) and (\ref{eq:coefredG}),  we get   for all $j\in\{1, 2, \dots n\}$ and $\mu\in \Lambda^{(n)}$: 
\[ \max(\dot{\gamma}_{\mu, 2j -1}, s_j) = \begin{cases}
 \max(\lambda_j, s_j)     & \text{ if }  \mu\in \Lambda_j^{n, \top} \\
  1 & \text{ if }  \mu\in \Lambda_j^{n, \bot}  
  \end{cases}=\max(\dot{m}_{\mu, 2j -1}, \lambda_j);  \]
\[ \max(\dot{\gamma}_{\mu, 2j}, r_j) = \begin{cases}
 1     & \text{ if }  \mu\in \Lambda_j^{n, \top} \\
  \max(\rho_j, r_j) & \text{ if }  \mu\in \Lambda_j^{n, \bot}  
   \end{cases} = \max(\dot{m}_{\mu, 2j}, \rho_j).  \]
It then follows from (\ref{eq:A}) and (\ref{eq:B}) that we have $\widetilde{\Pi}(E_{k_\mu}^{(n)}) = \Pi(E_{k_\mu}^{(n)})$ for all $\mu\in\Lambda^{(n)}$.
\end{proof}




\subsection{Proof of Lemma \ref{lem:coED}}
\label{subsec:proof:coED}
\lemcoEDcmd*

\begin{proof}
 Let us remind that for all $x, y, z$  in $[0, 1]$, we have:
 \[   x \epsilon \max(y, z) = \max(x \, \epsilon \, y, x \,\epsilon \, z), \quad \max(x,  x \,\epsilon \, y) = \max(x, y). \]
 Using (\ref{eq:coefredG}) and      for any $j\in \{1, 2, \dots n\}$, the partition $\Lambda^{(n)} = \Lambda^{n, \top}_j \cup \Lambda^{n, \bot}_j$ (see Definition  \ref{def:Lj}), we get:
\[ e_{2j -1}^{n, \downarrow}   = \max_{\mu\in \Lambda^{(n)}}\, \dot{\gamma}_{\mu, 2j - 1} \,\epsilon \dot{y}_{\mu}= \max_{\mu\in \Lambda_j^{n, \top}}\, \lambda_j  \,\epsilon \dot{y}_\mu=   \lambda_j  \,\epsilon \,\max_{\mu\in \Lambda_j^{n, \top}}\dot{y}_\mu 
  =   \lambda_j  \,\epsilon \,e_{2j -1}^{n, \uparrow}. \]
  \[ e_{2j}^{n, \downarrow}   = \max_{\mu\in \Lambda^{(n)}}\, \dot{\gamma}_{\mu, 2j} \,\epsilon \dot{y}_{\mu}= \max_{\mu\in \Lambda_j^{n, \bot}}\, \rho_j  \,\epsilon \dot{y}_\mu=   \rho_j  \,\epsilon \,\max_{\mu\in \Lambda_j^{n, \bot}}\dot{y}_\mu 
  =   \rho_j  \,\epsilon \,e_{2j}^{n, \uparrow}. \]
\noindent
From the obvious inequality $x \, \epsilon \, y \leq y$, we deduce that for all $l\in\{1, 2, \dots, 2n\}$, we have  $e_{l}^{n, \downarrow} \leq e_{l  }^{n, \uparrow}$.
\end{proof} 







\subsection{Proof of Proposition \ref{prop:coEDU}}
\label{subsec:proof:coEDU}
\propcoEDUcmd*



\begin{proof}
Let
$\dot{\Gamma_n} \Box_{\max}^{\min}{E}^{n,\uparrow} = [v_\mu]_{\mu\in \Lambda^{(n)}}$, we prove that for any $\mu\in \Lambda^{(n)}$, we have:
\[v_\mu = \min_{1 \leq j \leq n} z_{\mu, j} = u_\mu \quad \text{where} \quad 
z_{\mu, j} := 
   \begin{cases}
 \max(\lambda_j, e_{2j-1}^{n, \uparrow})     & \text{ if }  \mu\in \Lambda_j^{n, \top}   \\
  \max(\rho_j, e_{2j}^{n, \uparrow}) & \text{ if }  \mu\in \Lambda_j^{n, \bot}  
  \end{cases}.\]
In fact, we have:\[ u_\mu  = \min_{1 \leq l \leq 2n} \, 
  \max(\dot{\gamma}_{\mu, l}, e_l^{n, \downarrow}) 
   = \min_{1 \leq j \leq n} \, 
  \min(\max(\dot{\gamma}_{\mu, 2j -1}, e_{2j -1}^{n, \downarrow}), \max(\dot{\gamma}_{\mu, 2j }, e_{2j}^{n, \downarrow})),\]\noindent
   \[v_\mu = \min_{1 \leq l \leq 2n} \, 
  \max(\dot{\gamma}_{\mu, l}, e_l^{n, \uparrow}) 
   = \min_{1 \leq j \leq n} \, 
  \min(\max(\dot{\gamma}_{\mu, 2j -1}, e_{2j -1}^{n, \uparrow}), \max(\dot{\gamma}_{\mu, 2j }, e_{2j}^{n, \uparrow})).\]

 Using (\ref{eq:coefredG}), we can easily check that for all $j\in \{1, 2, \dots, n\}$, we have: 
 \[ \min(\max(\dot{\gamma}_{\mu, 2j -1}, e_{2j -1}^{n, \downarrow}), \max(\dot{\gamma}_{\mu, 2j }, e_{2j}^{n, \downarrow})) = 
 \begin{cases} 
 \max(\lambda_j, e_{2j-1}^{n, \downarrow})     & \text{ if }  \mu\in \Lambda_j^{n, \top}   \\
  \max(\rho_j, e_{2j}^{n, \downarrow}) & \text{ if }  \mu\in \Lambda_j^{n, \bot}  
  \end{cases}.\]
\[ \min(\max(\dot{\gamma}_{\mu, 2j -1}, e_{2j -1}^{n, \uparrow}), \max(\dot{\gamma}_{\mu, 2j }, e_{2j}^{n, \uparrow})) = 
 \begin{cases} 
 \max(\lambda_j, e_{2j-1}^{n, \uparrow})     & \text{ if }  \mu\in \Lambda_j^{n, \top}   \\
  \max(\rho_j, e_{2j}^{n, \uparrow}) & \text{ if }  \mu\in \Lambda_j^{n, \bot}  
  \end{cases}  =  z_{\mu, j}   .\]

As by Lemma \ref{lem:coED},   we have 
$e_{2j -1}^{n, \downarrow} = \lambda_j  \,\epsilon \,e_{2j -1}^{n, \uparrow}$ and 
$e_{2j}^{n, \downarrow} = \rho_j  \,\epsilon \,e_{2j}^{n, \uparrow}$, 
  the well-known relation $\max(x, x \,\epsilon\, y) = \max(x, y)$ leads to the equality
$$z_{\mu, j} = \begin{cases} 
 \max(\lambda_j, e_{2j-1}^{n, \downarrow})     & \text{ if }  \mu\in \Lambda_j^{n, \top}   \\
  \max(\rho_j, e_{2j}^{n, \downarrow}) & \text{ if }  \mu\in \Lambda_j^{n, \bot}  
  \end{cases}$$ for all $j\in\{1, 2, \dots, n\}$ and we obtain 
  $v_\mu = \min_{1 \leq j \leq n} z_{\mu, j} = u_\mu$.\footnote{The equality  $u_\mu = \min_{1 \leq j \leq n} z_{\mu, j}   $ was proved  in \cite{baaj2022learning}, with other notations,  for the non-reduced equation system $(\Sigma_n)$. Unfortunately, the proof of Lemma 2 of \cite{baaj2022learning} contains misprints (a min being written as a max).}
  \end{proof}



\subsection{Proof of Lemma \ref{lem:coEDOMEGA}}
