  \[ \rho_j^{n, \downarrow}   = \max_{\mu\in \Lambda^{(n)}}\, \dot{m}_{\mu, 2j} \,\epsilon \widetilde o_{\mu}= \max_{\mu\in \Lambda_j^{n, \bot}}\, r_j  \,\epsilon \widetilde o_{\mu}=   r_j  \,\epsilon \,\max_{\mu\in \Lambda_j^{n, \bot}}\widetilde o_\mu
