\section{Pseudocode of the HYPR algorithm}
\label{app:pseudocode}
In Algorithm \ref{alg:pseudocode} we show pseudocode for the HYPR algorithm. The algorithm is applied to batches of data, we omit the batch dimension in the pseudocode for simplicity. We denote the parallel computation of Jacobians as $\texttt{jac}$, where the first argument corresponds to the function to be differentiated, and \texttt{assoc\_scan} as the associative scan function, where the first argument defines the binary associative operator used by the scan algorithm.
\begin{algorithm}[!ht]
\DontPrintSemicolon
\caption{single-layer HYPR}
\label{alg:pseudocode}
\KwIn{$X^{1:T}\in\mathbb{R}^{T\times d}$} 
\KwIn{Network $\mathcal{N}$ with parameters $\theta = \{W_{\mathrm{ff}} \in \mathbb{R}^{d \times m},\; W_{\mathrm{rec}} \in \mathbb{R}^{m \times m},\; b \in \mathbb{R}^m\}$} 
\KwIn{Subsequence length $\lambda$}
\KwOut{Updated parameters $\theta$}
% Initialization
$\mathbf e^0 \gets \mathbf{0}$ \tcp*{$\in \mathbb R^{k\times d_{\theta}}$ with no.~of parameters $d_{\theta}$ in $\mathcal{N}$}
$\cumapg \gets \mathbf{0}$\;
\For{$\ell \leftarrow 1$ \KwTo $T / \lambda$}{
  $t_0 \gets (\ell-1)\,\lambda$\; 
  $\bar X \gets X^{(t_0+1)\ldots (t_0+\lambda)}$ \tcp*{get next subsequence $\bar X \in\mathbb R^{\lambda\times d}$}
  $I_{\mathrm{ff}} \gets \bar X\,W_{\mathrm{ff}} + b$ \tcp*{$I_{\mathrm{ff}}\in\mathbb R^{\lambda\times m}$ (parallel)}
  % \;
  {\vspace{10pt}}
  \tcc{S-stage (sequential)}
    {\vspace{4pt}}
  Initialize $\mathbf{s}^0 \leftarrow \mathbf{0}, \mathbf{y}^0 \leftarrow \mathbf{0}$ \;
  \For{$t \leftarrow 1$ \KwTo $\lambda$}{
    $I_{\mathrm{rec}}^t \gets W_{\mathrm{rec}}\,y^{t-1}$ \tcp*{$\in\mathbb R^m$}
    $I^t \gets I_{\mathrm{ff}}^t + I_{\mathrm{rec}}^t$ \;
    $\mathbf{s}^t \gets f(\mathbf{s}^{t-1}, I^t)$ \;
    $\mathbf{y}^t \gets g(\mathbf{s}^t)$  \;
    $\mathcal{L}^t \leftarrow \texttt{loss}(y^t)$ \tcp*{supervised or unsupervised loss function}
  }
    {\vspace{10pt}}
  \tcc{P-stage (parallel)}
    {\vspace{4pt}}
  $\bigl[\frac{\partial \mathbf{s}^1}{\partial \mathbf{s}^0},\,\dots,\,\frac{\partial \mathbf{s}^\lambda}{\partial \mathbf{s}^{\lambda-1}}\bigr],\bigl[\frac{\partial \mathbf{s}^1}{\partial I^1},\,\dots,\,\frac{\partial \mathbf{s}^\lambda}{\partial I^{\lambda}}\bigr] \leftarrow \texttt{jac}(f, \mathbf{s}^{0\ldots\lambda-1}, I^{1\ldots\lambda})$ 
  \;
  \tcp*{$\frac{\partial \mathbf{s}^{t+1}}{\partial \mathbf{s}^t}\in\mathbb{R}^{m\times k \times k}$, $\frac{\partial \mathbf{s}^{t}}{\partial I^t}\in\mathbb{R}^{m\times k}$, see Appendix~\ref{app:partial_grads}}
  $\bigl[\frac{d \mathcal{L}^1}{d \mathbf{s}^1},\,\dots,\,\frac{d \mathcal{L}^\lambda}{d \mathbf{s}^{\lambda}}\bigr]\gets \texttt{jac}(\{g,\texttt{loss}\}, \mathbf{s}^{1\ldots\lambda}, \mathbf{y}^{1\ldots\lambda})$ 
  \;
  \tcp*{$\frac{\partial \mathcal{L}^{t}}{\partial \mathbf{s}^t}\in\mathbb{R}^{m\times k}$, see Appendix~\ref{app:partial_grads}}
  $\bigl[\phi^{\lambda:1},\ldots,\;\phi^{\lambda:\lambda}\bigr] \gets \texttt{assoc\_scan}(\times, \bigl[\frac{\partial \mathbf{s}^1}{\partial \mathbf{s}^0},\,\dots,\,\frac{\partial \mathbf{s}^\lambda}{\partial \mathbf{s}^{\lambda-1}}\bigr])$ 
  \;
  \tcp*{$\phi^{\lambda:t} \in \mathbb{R}^{m \times k \times k}$, see text}
  $\mathbf{q}^{0\ldots \lambda} \gets \texttt{reverse\_scan}(\bigl[\frac{\partial \mathbf{s}^1}{\partial \mathbf{s}^0},\,\dots,\,\frac{\partial \mathbf{s}^\lambda}{\partial \mathbf{s}^{\lambda-1}}\bigr], \bigl[\frac{d \mathcal{L}^1}{d \mathbf{s}^1},\,\dots,\,\frac{d \mathcal{L}^\lambda}{d \mathbf{s}^{\lambda}}\bigr])$ 
  \;
  \tcp*{$\mathbf{q}^{t} \in \mathbb{R}^{m \times k}$, see Appendix \ref{app:backward_ssm}}
      $\mathbf e^\lambda \gets \mathbf e^0\,\phi^{\lambda:1} + \sum_{t=1}^{\lambda-1} \delta^t\,\phi^{\lambda:t+1} + \delta^\lambda$ 
      \;
      \tcp*{with $\delta^t=\frac{\partial \mathbf{s}^\lambda}{\partial I^\lambda}\frac{\partial I^t}{\partial \theta}$, decomposed as described in Appendix \ref{app:param_grads}}
  $[\tilde{\nabla} \theta]^{1:\lambda} \gets \mathbf{e}^0\delta^0 + \sum_{t=1}^\lambda \mathbf{q}^t \delta^t$ \;
    {\vspace{12pt}}
    $\mathbf e^0 \gets \mathbf e^\lambda$ \;
  $\cumapg \gets \cumapg + [\tilde{\nabla} \theta]^{1:\lambda}$ \;
}
$\theta \gets \texttt{optimizer}(\cumapg)$\;
\Return $\theta$ \;
\end{algorithm}
%
\section{Parameter gradients $\delta_{i}^t$}
\label{app:param_grads}
We intentionally separated the calculation of input $I_i^t$ given by Eq.~\eqref{eq:current} from the state transition $f$ in Eq.~\eqref{eq:state_transition} to emphasize that partial derivatives $\delta^t$ can be factorized into low-dimensional factors to significantly reduce the memory consumption and memory I/O of HYPR. By using these low-dimensional factors, the full parameter gradients $\delta^t$ are never materialized, enhancing performance and memory-efficiency of HYPR: For example for the feed-forward weight matrix $W_{\text{ff}} \in \mathbb{R}^{m \times d}$, parameter gradient $\delta^t_{W_{\text{ff}}}$ is given by the full Jacobian tensor $\frac{\partial S^t}{\partial W_{\text{ff}}} \in \mathbb{R}^{m \times k \times m \times d}$ with respect to the matrix $S^t \in \mathbb{R}^{m \times k}$ of all neuron states in time step $t$  and requires $\mathcal{O}(m^2 k d)$ memory. More specifically, its components are given as \mbox{$\bigl(\frac{\partial S^t}{\partial W_{\mathrm{ff}}}\bigr)_{ij\ell m}\;=\;\frac{\partial S^t_{ij}}{\partial W_{\mathrm{ff},\ell m}}$}. However, we found that this memory requirement can be drastically reduced by instead computing and caching some smaller matrices $D^t \in \mathbb{R}^{m \times k}$ with $D^t_{ij} = \fraci{\partial S^t_{ij}}{\partial I_{\text{ff},i}^t}$ together with vectors $\bar{\mathbf{x}}^t \in \mathbb{R}^d$ from subsequence $\bar{X}$. Note, that $\fraci{\partial I_{\text{ff},i}^t}{\partial W_{\text{ff},i}} = \bar{\mathbf{x}}^t$ for all neurons $i$, since all neurons receive the same input.
Together $D^t$ and $\bar{\mathbf{x}}^t$ consume only $\mathcal{O}(mk + d)$ memory and allow to efficiently perform the operations from Eq.~\eqref{eq:parallelizable_elig} and \eqref{eq:updates_hypr} using Einstein summations without ever materializing the large parameter gradient $\delta^t_{W_{\text{ff}}}$. 

Hence, we can express the components of $\delta^t$  that correspond to the parameters in the feed-forward weight matrix $W_{\text{ff}}$ in Eqs.~\eqref{eq:parallelizable_elig} and \eqref{eq:updates_hypr}  as
\begin{align}
    (\delta^t_{W_{\text{ff}}})_{ij\ell m} =  \biggl(\frac{\partial S^t}{\partial W_{\mathrm{ff}}}\biggr)_{ij\ell m} = \frac{\partial S^t_{ij}}{\partial W_{\mathrm{ff},\ell m}}  = \frac{\partial S_{ij}^t}{\partial I_{\text{ff},i}^t}\frac{\partial I_{\text{ff},i}^t}{\partial W_{\text{ff},im}^t} &=    \left\{
\begin{array}{ll}
D^t_{ij} \:\bar{\mathbf{x}}^t_m  & \text{if} \quad \ell=i \\
0 & \text{if} \quad \ell\neq i \\
\end{array}
\right. 
\end{align}
%
The same principle applies to $W_{\text{rec}}$, where $(\delta^t_{W_{\text{rec}}})_{ij\ell m} = D^t_{ij} \: \mathbf{y}^t_m   \;\; \text{if} \;\; \ell=i, \; \text{else} \; 0$. All matrices $D^t$ can be obtained in parallel as explained in Appendix \ref{app:partial_grads}.
%
\section{Efficient calculation of partial gradients}
\label{app:partial_grads}
%
All partial gradients involved in HYPR can be calculated efficiently in parallel. 
We first compute Jacobian matrices $J_{f,i}^t$ and $J_{g,i}^t$ of functions $f$ and $g$ from Eq.~\eqref{eq:state_transition}. The Jacobians are given by
\begin{equation}
\label{eq:jacobians}
    J_{f,i}^t = \begin{bmatrix}
         \frac{\partial s^t_{i,1}}{\partial s^{t-1}_{i,1}} & \dots & \frac{\partial s^t_{i,1}}{\partial s^{t-1}_{i,k}} & \frac{\partial s^t_{i,1}}{\partial I^{t}_{i}} \\
          \vdots & &  & \vdots  \\
         \frac{\partial s^t_{i,k}}{\partial s^{t-1}_{i,1}} & \dots & \frac{\partial s^t_{i,k}}{\partial s^{t-1}_{i,k}} & \frac{\partial s^t_{i,k}}{\partial I^{t}_{i}}
    \end{bmatrix} \in \mathbb{R}^{k \times (k+1)}, \qquad   J_{g,i}^t = \begin{bmatrix}
         \frac{\partial y^t_{i}}{\partial s^{t}_{i,1}}  \\
         \vdots \\
         \frac{\partial y^t_{i}}{\partial s^{t}_{i,k}}
    \end{bmatrix} \in \mathbb{R}^{k \times 1},
\end{equation}
where we recall that $k$ is the neuron state dimension. $s^t_{i,j}$ refers to the $j$-th state of neuron $i$ at time step $t$ and $I^{t}_{i}$ the input to neuron $i$ at time step $t$.
Given the cached latent states and outputs obtained in the S-stage, these Jacobians can be computed for all time steps of the subsequence in parallel. This operation has time complexity $\mathcal{O}(1)$, given sufficiently many concurrent processors. These Jacobian matrices can be obtained by using auto-differentiation frameworks, without requiring a model-dependent explicit implementation, referred to as \texttt{jac} in Algorithm \ref{alg:pseudocode}. This allows HYPR to be trivially adjusted to a broad variety of neuron models without requiring manual implementation work. Commonly, vector-Jacobian products (VJPs) are preferred over explicitly calculating Jacobians, since the Jacobians are usually large (see also Appendix \ref{app:param_grads}). However, in HYPR, we drastically reduced the dimensionality of these Jacobians $J_{f,i}^t$ and $J_{g,i}^t$ of functions $f$ and $g$ by dissecting the computation of scalar neuron input $I^t_i$ from the state-to-state transition function $f$. Hence, the Jacobians are computed w.r.t.~scalar input $I^t_i$ instead of high-dimensional parameter $\theta_{i}$ and hence are low-dimensional. This dissection allows the low-rank decomposed representation of parameter gradients $\delta^t$ described in Appendix \ref{app:param_grads}.

We can slice these Jacobians into partial derivatives $\frac{\partial \mathbf{s}_i^t}{\partial \mathbf{s}_i^{t-1}} \in \mathbb{R}^{k \times k}$, $\frac{\partial \mathbf{s}_i^t}{\partial I_i^{t}} \in \mathbb{R}^{k \times 1}$ and $\frac{\partial y_i^t}{\partial \mathbf{s}_i^{t}} \in \mathbb{R}^{k \times 1}$.
%
\section{Combining approximate backward and forward propagation}
\label{app:backward_ssm}
%
In this section we explain in detail how to obtain the backward formulation in Eq.~\eqref{eq:backward_ssm} from the forward-SSM formulation of the eligibility matrix from Eq.~\eqref{eq:elig_vector_ssm}. Consider a summative loss function $\mathcal{L} = \sum_t \mathcal{L}^t$. Then, APG $\apg$ (see Eq.~\eqref{eq:elig_vector_ssm2}) is given by 
\begin{align}
    \apg &= \frac{d \mathcal{L}^t}{d \mathbf{s}_i^t}\mathbf{e}_{i}^t \\
  &= \frac{d \mathcal{L}^t}{d \mathbf{s}_i^t}\left(\delta_{i}^t + \underbrace{A_i^t}_{\phi_i^{t:t}} \delta_{i}^{t-1} + \underbrace{A_i^t A_i^{t-1}}_{\phi_i^{t:t-1}} \delta_{i}^{t-2}  + \ldots + \underbrace{A_i^t \ldots  A_i^{2}}_{\phi_i^{t:2}} \delta_{i}^{1} + \underbrace{A_i^t \ldots  A_i^{1}}_{\phi_i^{t:1}} \mathbf{e}_{i}^{0}\right),
\end{align}
where in the second line, $\mathbf{e}_{i}^t$ is unrolled as in Eq.~\eqref{eq:elig_unrolled}.
The cumulative APG $[\apgnot]^{1:\lambda} = \sum_{t=1}^\lambda \apg$ is then given by the summation of all terms $\apg$ as
\begin{align}
\label{eq:cum_weight_upd_decomposed}
\sum_{t=1}^\lambda \apg
&=
\underbrace{\,\frac{d \mathcal{L}^1}{d \mathbf{s}_i^1}
\Bigl(\delta_{i}^{1}
+\phi_i^{1:1}\,\mathbf{e}_{i}^0\Bigr)}_{\apgnot^1} \\
%
&\qquad+\underbrace{\,\frac{d \mathcal{L}^2}{d \mathbf{s}_i^2}
\Bigl(\delta_{i}^{2}
+\phi_i^{2:2}\,\delta_{i}^{1}
+\phi_i^{2:1}\,\mathbf{e}_{i}^0\Bigr)}_{\apgnot^2} \nonumber\\
%
&\qquad+\cdots \nonumber\\
%
&\qquad+\underbrace{\frac{d \mathcal{L}^{\lambda-1}}{\delta_{i}^{\lambda-1}}
\Bigl(
\delta_{i}^{\lambda-1}
+\phi_i^{\lambda-1:\,\lambda-1}\,\delta_{i}^{\lambda-2}
+\phi_i^{\lambda-1:\,\lambda-2}\,\delta_{i}^{\lambda-3}
+\cdots
+\phi_i^{\lambda-1:\,1}\,\mathbf{e}_{i}^0
\Bigr)}_{\apgnot^{\lambda-1}} \nonumber\\
%
&\qquad+\underbrace{\frac{d \mathcal{L}^\lambda}{d \mathbf{s}_i^\lambda}
\Bigl(
\delta_{i}^{\lambda}
+\phi_i^{\lambda:\,\lambda}\,\delta_{i}^{\lambda-1}
+\phi_i^{\lambda:\,\lambda-1}\,\delta_{i}^{\lambda-2}
+\cdots
+\phi_i^{\lambda:\,1}\,\mathbf{e}_{i}^0
\Bigr)}_{\apgnot^\lambda}
\nonumber
\end{align}
where the term $\delta_{i}^{\lambda}$ appears once, the term $\delta_{i}^{\lambda-1}$ appears twice, and so on. A number of $\mathcal{O}(\lambda^2)$ cumulative state transition matrices $\phi^{r:s}$ with $r,s \in \{1,\ldots,\lambda\}, r\geq s$ would need to be calculated to parallelize this computation. Rearranging this equation by collecting all coefficients for $\delta_{i}^{1},\; \ldots, \; \delta_{i}^{\lambda}$ and $\mathbf{e}_{i}^0$ shows why the backward formulation is much more elegant to solve this problem:
\begin{align}
% \label{eq:reordered_cum_weight}
\sum_{t=1}^\lambda \Delta \theta_{i}^t
&= \ldots \nonumber\\[1ex]
&\quad+
\underbrace{\left(
  \frac{d \mathcal{L}^\lambda}{d \mathbf{s}_i^\lambda}
  \,A^\lambda A^{\lambda-1}
  +
  \frac{d \mathcal{L}^{\lambda-1}}{d \mathbf{s}_i^{\lambda-1}}
  A^{\lambda-1}
  +
  \frac{d \mathcal{L}^{\lambda-2}}{d \mathbf{s}_i^{\lambda-2}}
\right)}_{\mathbf{q}_i^{\lambda-2}}
 \delta_{i}^{\lambda-2}\nonumber\\
&\quad+
\underbrace{\left(
  \frac{d \mathcal{L}^\lambda}{d \mathbf{s}_i^\lambda}
  \,A^\lambda
  +
  \frac{d \mathcal{L}^{\lambda-1}}{d \mathbf{s}_i^{\lambda-1}}
\right)}_{\mathbf{q}_i^{\lambda-1}}
\delta_{i}^{\lambda-1} \nonumber\\
&\quad+ 
\underbrace{\left(
  \frac{d \mathcal{L}^\lambda}{d \mathbf{s}_i^\lambda}
\right)}_{\mathbf{q}_i^{\lambda}}
\delta_{i}^{\lambda} \nonumber\\
&= \mathbf{q}_i^\lambda \delta_{i}^{\lambda} + \mathbf{q}_i^{\lambda-1} \delta_{i}^{\lambda-1} +\ldots   + \mathbf{q}_i^1 \delta_{i}^{1} + \mathbf{q}_i^0 \mathbf{e}_{i}^{0}.
\label{eq:fully_resolved_weight_update}
\end{align}
This formulation is mathematically equivalent to Eq.~\eqref{eq:cum_weight_upd_decomposed}, but the individual APGs $\apg$ disappeared. This is possible, since we are only interested in their sum, not in the individual terms. The major advantage here is that vectors $\mathbf{q}_i^t \in \mathbb{R}^{1\times k}$ are much smaller than eligibility matrices $\mathbf{e}_{i}^t \in \mathbb{R}^{k \times d_{\theta}}$ and can be efficiently computed using the associative scan algorithm, as explained in Appendix \ref{app:backward_hypr}. Note, that for the implementation we replaced all $\delta_{i}^{t}$ by their low-rank representation from Appendix \ref{app:param_grads} which allows efficient parallel computation of Eq.~\eqref{eq:fully_resolved_weight_update} using Einstein summation.
%
\section{Computing $\mathbf{q}_i^t$ with the associative scan}
\label{app:backward_hypr}
%
Recall the linear SSM formulation from Eq.~\eqref{eq:q_recursive}:
\begin{equation}
    \mathbf{q}_i^t =  \mathbf{q}_i^{t+1}A_i^{t+1}  +  \ell^t_i
    \label{eq:q_recursive_app}
\end{equation}
with $\ell^t_i=\frac{d \mathcal{L}^t}{d \mathbf{s}_i^t}$. We can efficiently obtain the sequence $[\mathbf{q}_i^\lambda,\;\ldots,\;\mathbf{q}_i^0] = [\ell^\lambda_i,\;\; \ell^{\lambda-1}_i + \ell^\lambda_i A_i^{\lambda},\;\;  \ell^{\lambda-2}_i + \ell^{\lambda-1}_i A_i^{\lambda-1} + \ell^\lambda_i  A_i^{\lambda} A_i^{\lambda-1}]$ using the associative scan \cite{BlellochTR90}, as described in \cite{smithSimplifiedStateSpace2023a}: Given any sequence $[a,b,c,\ldots]$ of length $\lambda$ and a binary associative operator $\bullet$ which satisfies $(a\bullet b) \bullet c = a\bullet (b \bullet c)$, the sequence $[a,\;\; a\bullet b,\;\; a\bullet b \bullet c,\;\; \ldots]$ can be computed in $\mathcal{O}(\log \lambda)$ time complexity, given sufficient parallel processors are available.

We define tuples $p^t_i\myeq(A_i^{t+1},\ell^t_i)$ with $A_i^{\lambda+1}= \mathbf{I}$ as identity matrix, $\ell^0_i=0$ and binary associative operator $(a_1,a_2)\bullet (b_1, b_2) \myeq (b_1 \times a_1,\; b_1 a_2 + b_2)$, where subscripts $1$ and $2$ refer to the first and second tuple element respectively. Applying the associative scan using this binary associative operator on the sequence $[p^\lambda_i,\;\ldots,\;p^0_i]$ results in the sequence $[r^\lambda_i,\;\ldots,\;r^0_i]$ with
\begin{align}
    r^\lambda &= p^\lambda &= (A^{\lambda+1},\ell^\lambda) \\
    % p^{\lambda-1} = (A^{\lambda},\ell^(\lambda-1))
    r^{\lambda-1} &= p^\lambda \bullet p^{\lambda-1} &= (A^{\lambda}  A^{\lambda+1},\; A^{\lambda} \ell^{\lambda} + \ell^{\lambda-1}) \\
    r^{\lambda-2} &= p^\lambda \bullet p^{\lambda-1} \bullet p^{\lambda-2} &= (\underbrace{A^{\lambda-1} A^{\lambda} A^{\lambda+1}}_{\phi^{\lambda-2:\lambda+1}},\; \underbrace{A^{\lambda-1}A^{\lambda} \ell^{\lambda} + A^{\lambda-1}\ell^{\lambda-1} + \ell^{\lambda-2}}_{\mathbf{q}^{\lambda-2}}) \\
    \vdots
\end{align}
where we omitted neuron index $i$ for readability. From each resulting tuple $r^t=(\phi^{t:\lambda+1}, \mathbf{q}^t)$ we can extract  $\mathbf{q}^t$ as the second tuple element.
