\subsection{Balanced Resonate-and-Fire (BRF)}
%
The dynamics of the BRF~\citep{higuchi2024balanced} neuron model are given by:
%
\begin{align}
b^t &= p_{\omega} - b_{\text{offset}} - q^{t-1} \\
u^t &= u^{t-1} + \Delta t \cdot (b^t \cdot u^{t-1} - \omega \cdot v^{t-1} + I^t) \\
v^t &= v^{t-1} + \Delta t \cdot (\omega \cdot u^{t-1} + b^t \cdot v^{t-1}) \\
z^t &= \Theta( u^t - \theta - q^{t-1}) \\
q^t &= \alpha \cdot q^{t-1} + z^t
\end{align}
\noindent where $\theta$ is the base firing threshold, $\omega$ is the angular frequency parameter controlling oscillations, $p_{\omega} = \frac{-1 + \sqrt{1 - (\Delta t \cdot \omega)^2}}{\Delta t}$ is the divergence boundary, $b_{\text{offset}}$ is the dampening parameter, $q^t$ is an adaptation variable with $\alpha=0.9$ as adaptive decay factor, and $\Delta t$ is the simulation time step. We use $\Delta t = 0.01$ in all experiments. The BRF neuron generates a spike when the membrane potential $u^t$ exceeds the adaptive threshold $\theta + q^{t-1}$. In the BRF model the membrane potential is not reset after a spike. Instead, the adaptation variable $q^t$ increases by the spike output $z^t \in {0,1}$ and affects both the threshold for future spikes and the dampening term $b^t$ in the subsequent dynamics. We train $b_{\text{offset}}$ and $\omega$ together with the network weights.
We used the same weight initialization as in \citep{higuchi2024balanced}. 
\subsection{SE discretized adaptive Leaky Integrate and Fire (SE-adLIF) }
%
The temporal dynamics of the Symplectic-Euler(SE) discretized SE-adLIF~\citep{baronig2025advancingspatiotemporalprocessingspiking} neuron are given by
%
\begin{align}
% Discretized equations with time step dt
\hat{u}^t &= \alpha u^{t-1} + (1-\alpha)(I^t-w^{t-1}) \\
z^t &= \Theta( \hat{u}^t - \theta) \\
u^t &= \hat{u}^t(1-z^t) \\
w^t &= \beta w^{t-1} + (1-\beta)(au^t + bz^t) 
\end{align}
\noindent where $\tau_u$ and $\tau_w$ are the membrane potential and adaptation time constants, and $a = \rho\hat{a}, b= \rho\hat{b}$ are adaptation parameters. For all experiments, we keep $\rho=120$ fixed and initialize $\hat{a},\hat{b} \sim \mathcal{U}(0,1)$, which are trained together with other parameters. During training we clip both $\hat{a}$ and $\hat{b}$ in the range $[0,1]$. Further, we employ the same time constant interpolation as in \citep{baronig2025advancingspatiotemporalprocessingspiking} with the ranges $\tau_u\in[5,25]$ and $\tau_w\in[60,300]$ for all experiments.
We used the same weight initialization as in ~\citep{baronig2025advancingspatiotemporalprocessingspiking}.
\subsection{Adaptive Leaky Integrate and Fire (ALIF) }
%
The dynamics of the ALIF~\citep{yin2021accurateefficienttimedomainclassification} model are given by 
\begin{align}
a^t &= \rho \cdot a^{t-1} + (1-\rho) \cdot z^{t-1} \\
A^t &= b_{j0} + \beta \cdot a^t \\
u^t &= \alpha \cdot u^{t-1} + (1-\alpha) \cdot I^t - A^t \cdot z^{t-1} \\
z^t &= \Theta( u^t - A^t)
\end{align}
\noindent Where $\alpha = e^{-\Delta t/\tau_u}$ is the membrane potential decay factor, $\rho = e^{-\Delta t/\tau_a}$ is the adaptation decay factor, where $\tau_u$ is the membrane potential time constant, $\tau_a$ is the adaptation time constant. $\beta$ is the adaptation strength coefficient, and $A^t$ is the adaptive threshold. 
The ALIF neuron implements an adaptive threshold mechanism combined with a spike-triggered reset. The adaptation variable $a^t$ tracks the neuron's recent spiking history, increasing with each spike $z^{t-1}$. This creates a dynamic threshold $A^t = b_{j0} + \beta \cdot a^t$ that rises after spiking activity and implementing spike-frequency adaptation. After a spike, membrane potential $u^t$ is reset to 0.
\subsection{Leaky Integrator (LI)}
%
The dynamics of the LI neurons in the output layer are given by
\begin{align}
u^t &= \alpha \cdot u^{t-1} + (1-\alpha) \cdot I^t
\end{align}
\noindent where $\alpha = e^{-\Delta t/\tau_u}$ is the decay factor with time constant $\tau_u$.

\section{Training details and hyperparameters}
\label{app:training_and_hyperparams}
%
\subsection{Training details}
%
\textbf{Surrogate gradients:} We employed surrogate gradient functions that approximate the derivative of $\Theta(x)$. In our experiments, we utilize two common surrogate gradients. The first is the SLAYER~\citep{shrestha2018slayer} surrogate gradient, defined as $\frac{d\Theta(x)}{dx} \approx \alpha  c   e^{-\alpha|x|},$ where $\alpha=5$ controls the sharpness of the exponential curve and $c=0.2$ adjusts the amplitude of the gradient. The second approach is the double Gaussian~\cite{yin2021accurateefficienttimedomainclassification} surrogate gradient, given by $\frac{d\Theta(x)}{dx} \approx \gamma \left[(1+p) \cdot \text{G}(x; 0, \sigma_1) - 2p \cdot \text{G}(x; 0, \sigma_2) \right],$ where $\text{G}(x; \mu, \sigma)$ represents the Gaussian probability density function, $\sigma_1 = 0.5$ and $\sigma_2 = 6\sigma_1$ control the width of the Gaussian curves, $p=0.15$ adjusts the relative weight between the two Gaussians, and $\gamma=0.5$ is an overall scaling factor.

\textbf{Optimizer:} We used the ADAM~\citep{kingma2017adam} optimization algorithm with $\beta_1=0.9$, $\beta_2=0.999$ and $\epsilon = 1\text{e}-8$ but with different learning rates (see Appendix \ref{app:hyperparams}) for all experiments. For HYPR, we accumulated APGs over the entire sequence before applying the weight updates. We applied gradient clipping for all experiments: if the gradient norm exceeded a certain magnitude, we rescaled it to $m_\text{grad}$. The values of $m_\text{grad}$ are discussed in Appendix \ref{app:hyperparams}.

\textbf{Learning rate schedule:} We explored three different learning rate scheduling methods: constant, linear and cosine. In the constant scheduler, the learning rate was held constant throughout all training epochs. In the linear scheduler, we decayed it linearly from an initial learning rate $\eta^{\text{init}}$ to $0$ at the final epoch. In the cosine decay scheduler~\citep{loshchilov2022sgdr}, we define the learning rate $\eta^k$ at the $k$-the epoch as $\eta^k = \eta^{\text{init}}\cdot[0.5\cdot(1+\cos{(\pi\cdot k/{\text{\footnotesize\#epochs}})})]$.

\textbf{Loss functions:} Our network architecture uses leaky integrator neurons in the output layer that match the number $C$ of classes of the corresponding task. At each time step $t$, the network output $\bar{\mathbf{y}}^t \in \mathbb{R}^C$ was given by the vector of membrane potentials $\mathbf{u}^t \in \mathbb{R}^C$. Depending on the task and the training algorithm (BPTT or HYPR), we used different functions to compute a loss from the series of outputs $[\bar{\mathbf{y}}^1,\;\ldots,\;\bar{\mathbf{y}}^T]$.
The \textit{sum-of-softmax} loss was given by
\begin{equation}
    \mathcal{L} = \text{CE}\left(\text{softmax}\biggl(\sum_{t=t_0+1}^T \text{softmax}(\bar{\mathbf{y}}^t)\biggr), \mathbf{y}^*\right),
\end{equation}
where CE denotes the cross entropy loss, softmax is the softmax function, $\mathbf{y}^* \in \mathbb{R}^C$ a one-hot encoded target vector and $t_0$ defines the time step up to which the network output is ignored. $t_0$ is a hyperparameter and varies between different tasks and models and is shown in Appendix \ref{app:hyperparams}. The sum-of-softmax is not compatible with HYPR since no per-timestep loss $\mathcal{L}^t$ can be obtained at time step $t$ without back-propagating the loss through time. Therefore, we used a summative \textit{per-timestep loss}, given by
\begin{equation}
    \mathcal{L} = \frac{1}{T-t_0}\sum_{t=t_0+1}^T \mathcal{L}^t = \frac{1}{T-t_0}\sum_{t=t_0+1}^T\text{CE}\left(\text{softmax}\biggl(\sum_{t=t_0+1}^T \bar{\mathbf{y}}^t\biggr), \mathbf{y}^{*t}\right),
\end{equation}
where $\mathbf{y}^{*t}$ can be a per-timestep target (for example in the ECG task) or is the same for every time step (for example in SHD).

\textbf{Class prediction:}
To compute the accuracy, we obtained a class prediction $\hat{y}$ from $[\bar{\mathbf{y}}^1,\;\ldots,\;\bar{\mathbf{y}}^T]$ via three different methods:
\begin{align}
    \hat{y}\; &= \text{argmax}\biggl(\sum_{t=t_0+1}^T \text{softmax}(\bar{\mathbf{y}}^t)\biggr) & \text{(sum of softmax)} \\
    \hat{y}\; &= \text{argmax}\biggl(\sum_{t=t_0+1}^T \bar{\mathbf{y}}^t\biggr) & \text{(mean over time)} \\
    \hat{y}^t &= \text{argmax}(\bar{\mathbf{y}}^t) & \text{(per timestep)}.
\end{align}
The method of choice for each task and model is shown in Appendix \ref{app:hyperparams}.  

\textbf{Frameworks:}
We used the open source Python frameworks Jax \citep{jax2018github}, for calculation and automatic differentiation, Hydra\footnote{\url{https://hydra.cc}}, for configuring experiments, and Aim\footnote{\url{https://aimstack.io}} for experiment tracking.
