	\section{System Model and Problem Formulation}\label{SSMPF}
	\begin{figure}[!t]
		\centering
		\includegraphics[width=3.3in]{system_model.png}\\
		\caption{An illustration of the considered DTaaS provisioning over edge computing.}\label{model}
		\vspace{-0.7em}
