\section{Model problem}\label{sec:model}
%%
A linearized version of problem \eqref{eq:non-linear primale} reads as
\begin{equation}
\label{eq:linear primale}
\left\{
\begin{aligned}
& \text{ find $(\uu, p, \BB)$ such that}\\
&\begin{aligned}
\pss \, \uu -  \ns \, \bdiver (\beps (\uu) ) + (\bnabla \uu ) \,\cc    +  \TT \times \bcurl(\BB) - \nabla p &= \ff \qquad  & &\text{in $\Omega$,} 
\\
\diver \, \uu &= 0 \qquad & &\text{in $\Omega$,} 
\\
\psm \, \BB +  \nm \, \bcurl (\bcurl (\BB) ) - \bcurl(\uu \times \TT)  &= \GG \qquad  & &\text{in $\Omega$,} 
\\
\diver \, \BB &= 0 \qquad & &\text{in $\Omega$,} 
\end{aligned}
\end{aligned}
\right.
\end{equation}
coupled with the homogeneous boundary conditions
%
\begin{equation}
\label{eq:linear bc cond}
\uu = 0 \,, \quad 
\BB \cdot \nn = 0 \,,  \quad 
\bcurl(\BB) \times \nn = 0  \quad \text{on }\partial \Omega \, .
\end{equation}
%%
Here above we denote by $\pss$ and $\psm$ the reaction coefficients (constant for simplicity), and with $\TT, \cc$ the advective fields of the fluid and the magnetic field, respectively. For the time being, we assume $\TT \in \HH_0(\diver,\Omega) \cap  \boldsymbol{L}^3(\Omega)$, and $\cc \in \HH(\bcurl,\Omega) \cap  \boldsymbol{L}^3(\Omega)$ , with $\diver\,\cc = 0$.

We are interested in deriving a variational formulation of \eqref{eq:linear primale}. 
We introduce the spaces
\begin{equation}
\label{eq:spazi_c}
\VVc := \Hunozero \,, 
\quad
\WWc := \HH(\bcurl, \Omega)\,,
\quad
\Qc  := L^2_0(\Omega)  \,,
\end{equation}
%%
%%
that represent the velocity fields space, the magnetic induction space, and the space of pressures, respectively. 
Contrary to the convex setting, we emphasize that an  $\HH^1$-conforming space for the magnetic induction cannot be assumed. In the convex case, controlling both the divergence and the $\bcurl$ of a function ensures control over its gradient, which implies that the function belongs to $\HH^1(\Omega)$.
However, when the domain is non-convex, this control is weaker, and we can only conclude that the function lies in $\HH^{s}(\Omega)$ for some suitable $s > \frac{1}{2}$ depending on $\Omega$. 
In the velocity space, we introduce the following bilinear forms
\begin{equation}
\label{eq:forme_c1}
\as(\uu,  \vv) :=  (\beps(\uu), \, \beps (\vv) ) \,,
\qquad
c(\uu, \vv) :=  \left( ( \bnabla \uu ) \, \cc ,\, \vv  \right) \,,
\end{equation}
where the first one is obtained by multiplying the term $\diver(\beps(\uu))$ by a test function $\vv$, integrating by parts and using the boundary conditions. On $\WWc$, we define the form
\[
\am(\BB,  \HH) = (\bcurl (\BB), \bcurl (\HH)) \, .
\]
The coupling is represented by two forms: the first one controls the interaction between velocity and pressure, while the second one governs the coupling between velocity and magnetic induction
\begin{equation}
\label{eq:forme_c2}
\begin{aligned}
b(\vv, q) :=  (\diver \vv, \, q) \,, \qquad
d(\HH, \vv) :=  ( \bcurl (\HH ) \times \TT ,\, \vv) \,.
\end{aligned}
\end{equation}
We also introduce the kernel of the  bilinear form $b(\cdot,\cdot)$
that corresponds to the functions in $\VVc$ with vanishing divergence
\begin{equation}
\label{eq:Z}
\ZZc := \{ \vv \in \VVc \quad \text{s.t.} \quad \diver \, \vv = 0  \}\,.
\end{equation}
Then, we consider the following variational problem
\begin{equation}
\label{eq:linear variazionale}
\left\{
\begin{aligned}
& \text{find $(\uu, p, \BB) \in \VVc \times \Qc \times \WWc$,  such that} 
\\
&\begin{aligned}
\pss \, (\uu, \vv) + \ns \, \as(\uu, \vv) + c(\uu, \vv)  
-d(\BB, \vv)  + b(\vv, p) 
&= 
(\ff, \vv)  
&\,\,\, & \text{for all $\vv \in \VVc$,} 
\\
b(\uu, q) &= 0 
&\,\,\, & \text{for all $q \in \Qc$,}
\\
\psm \, (\BB, \HH) + \nm \, \am(\BB, \HH) + d(\HH, \uu) 
&= 
(\GG, \HH)  
&\,\,\, & \text{for all $\HH \in \WWc$.}
\end{aligned}
\end{aligned}
\right.
\end{equation}
%
As usual, we suppose that $\GG$ is $\boldsymbol{L}^2$-orthogonal to the gradients. We also remark that the boundary conditions on $\BB$, see \eqref{eq:linear bc cond}, are here weakly imposed. 
This problem is well posed by the Lax-Milgram lemma and standard theory of mixed problems.

\section{Notations and preliminary results}
\label{sec:prelim}

In this section, we introduce the notation and some useful results that will be used throughout the rest of the paper.
We consider a family of decompositions $\{ \Omega_h\}_h$ of the domain $\Omega$ into non-overlapping tetrahedrons $E$. 
We denote with $h_E$ the diameter of each element and with $h := \max_{E \in \Omega_h} h_E$ the  mesh size of $\Omega_h$.
Let $\mathcal{N}_h$ be the set of vertices in $\Omega_h$;
given $\zeta \in \mathcal N_h$, we denote with $\omegaz$ the collection of elements $E$ in $\Omega_h$ such that $\zeta \in \partial E$.
We adopt the same mesh assumptions as in \cite{BDV:2024}. The first assumption is classical in the FEM framework. It states that the elements in the decomposition are not excessively stretched, which is necessary to achieve optimal approximation results.

\smallskip
\noindent
\textbf{(MA1) Shape regularity assumption:}

\noindent
The mesh family $\left\{ \Omega_h \right\}_h$ is shape regular: it exists a  positive  constant $c_{\rm{M}}$ such that each element $E \in \{ \Omega_h \}_h$ is star shaped with respect to a ball of radius $\rho_E$ with  $h_E \leq c_{\rm{M}} \rho_E$. 

\smallskip
\noindent
The second assumption is specific to the case 
$k=1$. While this assumption is required for theoretical purposes, it is not overly restrictive.\\
\textbf{(MA2) Mesh agglomeration with stars macroelements:}

There exists a family of conforming meshes $\{ \widetilde{\Omega}_h \}_h$ of $\Omega$ with the following properties:
% (i) $\{ \widetilde{\Omega}_h \}_h$ satisfies \textbf{(MA1)};  
(i) it exists a positive constant $\widetilde{c}_{\rm{M}}$ such that each element $M \in \widetilde{\Omega}_h$ is a finite  (connected) agglomeration of elements in $\Omega_h$, i.e., it exists $\omegaEh \subset \Omega_h$ with ${\rm{card}}(\omegaEh) \leq \widetilde{c}_{\rm{M}}$ and $M = \cup_{E \in \omegaEh} E$;
(ii) for any $M \in \widetilde{\Omega}_h$ it exists $\zz \in \mathcal{N}_h$ such that $\omegaz \subseteq M$.
% with $ h_{M} \lesssim \widetilde{c}_{\rm{M}} h_{\zz}$.
\smallskip
\noindent
%
We observe that assumption \textbf{(MA1)} readily implies that the mesh is locally quasi-uniform. This means that the diameter of a face is uniformly bounded by the diameters of the elements containing the face and that the sizes of two adjacent elements are comparable.

The set of all the faces in the mesh $\Omega_h$ is denoted by $\Edges$. This set is divided into internal faces $\EdgesI$ and boundary faces $\EdgesB$. Given an element $E\in\Omega_h$, the set of faces of that element is denoted with $\EdgesE$. 
Furthermore, given an element $E \in \Omega_h$, we denote with $\nn^E$ the unit outward normal to that element, while $\nn^f$ denotes the unit normal to a face $f$. In particular, if $f \in \EdgesI$ we have that $\nn^f =  \nn^E$ or $\nn^f = - \nn^E$, while if $ f \in \EdgesB$ it holds $\nn^f = \nn^E = \nn.$
The jump and the average operators on $f \in \EdgesI$ are defined for every piecewise continuous function w.r.t. $\Omega_h$ respectively by
\[
\begin{aligned}
\jump{\phi}_f(\xx) &:=
\lim_{s \to 0^+} \left( \phi(\xx - s \nn_f) - \phi(\xx + s \nn_f) \right)
\\
\media{\phi}_f(\xx) &:= 
\frac{1}{2}\lim_{s \to 0^+} \left( \phi(\xx - s \nn_f) + \phi(\xx + s \nn_f) \right)
\end{aligned}
\]
and $\jump{\phi}_f(\xx) = \media{\phi}_f(\xx) = \phi(\xx)$ on $f \in \EdgesB$.
Given a positive integer $m \in \N$ and a subset $S \subseteq \Omega_h$, we introduce the standard polynomial spaces:
\begin{itemize}
\item $\Pk_m(\omega)$ is the set of polynomials on $\omega$ of degree $\leq m$, with $\omega$ a generic set;
%
\item $\Pk_m(S) := \{q \in L^2\bigl(\cup_{E \in S}E \bigr) \quad \text{s.t.} \quad q|_{E} \in  \Pk_m(E) \quad \text{for all $E \in S$}\}$ is the set of piecewise discontinuous polynomials;
%
\item $\Pkc_m(S) := \Pk_m(S) \cap C^0\bigl(\cup_{E \in S}E \bigr)$ is the set of piecewise continuous polynomial.
\end{itemize}
%
Given $s \in \R^+$ and  $p \in [1,+\infty]$, we define the standard broken Sobolev spaces as:
%
\begin{itemize}
\item $W^s_p(\Omega_h) := \{\phi \in L^2(\Omega) \quad \text{s.t.} \quad \phi|_{E} \in  W^s_p(E) \quad \text{for all $E \in \Omega_h$}\}$,
\end{itemize}
equipped with  the usual broken norm 
$\Vert \cdot \Vert_{W^s_p(\Omega_h)}$ 
and seminorm 
$\vert \cdot \vert_{W^s_p(\Omega_h)}$. Similarly, we denote with $\HH^{\regb}(\bcurl,\Omega_h)$ the space of vectorial $\boldsymbol L^2(\Omega)$ functions $\HH$ such that $\HH_{|E}\in \HH^{\regb}(\bcurl,E)$ for every $E\in\Omega_h$, endowed with the corresponding broken norm.
Furthermore, we introduce the following space
\begin{itemize}
\item $\mathbb{O}_{k-1}(\Omega_h) := 
\Pkc_{k-1}(\Omega_h)$  for $k>1$, or 
$\mathbb{O}_{k-1}(\Omega_h) := \Pk_{0}(\widetilde{\Omega}_h)$  for $k=1$.
\end{itemize}
%
Fix a face $f\in\EdgesI$ shared by two elements $E^+$ and $E^-$.
%
For any $p \in [1,\infty]$, we will use the notation
\[
\| V\|_{L^{p}(f^\pm)} := \max 
\{ 
\| V\|_{L^{p}(f^+)}, 
\| V\|_{L^{p}(f^-)}
\} 
\]
to denote the $L^p$ norm of a function that is not continuous across $f$. Above $f^+$ (resp., $f^-$) is the face $f$ considered as part of the boundary $\partial E^+$ (resp., $\partial E^-$).
In the paper, the symbols $\gtrsim$ and $\lesssim$ denote inequalities that hold up to a constant depending solely on the order of the method $k$, the domain $\Omega$, and the regularity of the mesh $\Omega_h$.
This constant does not depend on the model parameters $\psm$, $\pss$, $\ns$, $\nm$, $\cc$, and $\TT$, nor on the loadings $\mathbf{f}$, $\GG$, or the solution $(\uu, p, \BB)$. \\
We conclude this section by mentioning some useful preliminary results.
\begin{lemma}[Trace inequality]
\label{lm:trace}
Under the mesh assumption \textbf{(MA1)}, for any $E \in \Omega_h$ and for any  function $v \in H^s(E)$ with $  \frac{1}{2} < s \leq 1$, it holds 
\[
\sum_{f \in \EdgesE}\|v\|^2_{f} \lesssim h_E^{-1}\|v\|^2_{E} + h_E^{2s-1}| v|^2_{s,E} \,.
\]
\end{lemma}

\begin{lemma}[Bramble-Hilbert]
\label{lm:bramble}
Under the mesh assumption \textbf{(MA1)}, let $m \in {\mathbb N}$.  We denote with
$\Pzerok{m} \colon L^2(\Omega_h) \to \Pk_m(\Omega_h)$ the  $L^2$-projection operator onto the space of piecewise polynomial functions. For any $E \in \Omega_h$ and for any  smooth enough function $\phi$ defined on $\Omega$, it holds 
\[
% \begin{aligned}
\Vert\phi - \Pzerok{m} \phi \Vert_{W^r_p(E)} \lesssim h_E^{s-r} \vert \phi \vert_{W^s_p(E)} 
\qquad  \text{$s,r \in \N$, $r \leq s \leq m+1$, $p \in [1, \infty]$.}
% \end{aligned}
\]
\end{lemma}

\begin{lemma}[Inverse estimate]
\label{lm:inverse}
Under the mesh assumption \textbf{(MA1)}, let $m \in {\mathbb N}$. 
Then for any $E \in \Omega_h$ and for any $p_m \in \Pk_m(E)$ it holds 
\[
\|p_m\|_{W^s_p(E)} \lesssim h_E^{-s} \|p_m\|_{L^p(E)} 
\]
where the involved constant only depends on $m,s,p,c_{\rm{M}}$.
\end{lemma}
We consider an interpolation operator that maps sufficiently smooth piecewise discontinuous functions into the space of more regular functions. This interpolation operator is commonly referred to in the literature as an averaging operator \cite{burman:2004, EG:2017, BDV:2024}. 
Specifically, our goal is to take a piecewise polynomial $p$ of degree $k-1$ and return a piecewise polynomial of the same degree that belongs to $\mathbb{O}_{k-1}(\Omega_h)$. The proof of the following proposition can be found in \cite{BDV:2024}.
\begin{proposition} \label{prp:oswald}
Let Assumption \textbf{(MA1)} hold. Furthermore, if $k=1$ let also Assumption \textbf{(MA2)} hold. Then, it exists a projection operator $\intcip \colon \Pk_{k-1}(\Omega_h) \to \mathbb{O}_{k-1}(\Omega_h)$
such that for any $p_{k-1} \in \Pk_{k-1}(\Omega_h)$   the following holds:
\[
\sum_{E \in \Omega_h}h_E^2  \Vert (I- \intcip) p_{k-1} \Vert_E^2 \lesssim 
\sum_{f \in \EdgesI}
h_f^3 \Vert \jump{p_{k-1}}_f\Vert_f^2
\, .
\]
Furthermore, using a triangular inequality combined with a trace inequality, and the regularity of the mesh, it holds
\[
\sum_{E \in \Omega_h}h_E^2  \Vert (I- \intcip) p_{k-1} \Vert_E^2 \lesssim 
\sum_{E \in \Omega_h}
h_E^2 \Vert p_{k-1}\Vert_E^2
\, .
\]
\end{proposition}

