\section{The stabilized finite element method}
\label{sec:discrete}
\subsection{Discrete spaces}
Given a positive integer $k$ that represents the order of the method, we introduce the following polynomial spaces
\begin{equation}
\label{eq:spazi_d}
\begin{aligned}
\VVd := [\Pk_k(\Omega_h)]^3 \cap &\HH_0(\diver,\Omega) \, , \quad  
\WWd := [\Pk_k(\Omega_h)]^3 \cap \WWc \, , \\
&\Qd  := \Pk_{k-1}(\Omega_h) \cap Q \, .
\end{aligned}
\end{equation}
%%
For the discrete velocity field $\VVd$, we select standard $\HH(\diver)$-conforming Brezzi-Douglas-Marini $\boldsymbol{{\rm BDM}}_k$ elements, while for the magnetic induction we select Nédéléc elements of the second kind.
We introduce the discrete kernel space
\[
\ZZd := \{ \vv_h \in \VVd \quad \text{s.t.} \quad \diver \, \vv_h = 0  \}\, ,
\]
and thanks to the choice of the $\boldsymbol{{\rm BDM}}_k$ elements that maintain the pressure robustness of the method, we have the inclusion $\ZZd \subseteq \ZZc$.
We have to introduce two interpolation operators. The first one maps functions in $\HH^1(\Omega)$ into the space $\VVd$, mapping the continuous kernel into the discrete kernel, see for instance \cite{boffi-brezzi-fortin:book,ernguer-book-1}. 
\begin{lemma}[Interpolation operator on $\VVd$]
\label{lm:int-v}
Under the Assumption \textbf{(MA1)} let $\PVVd \colon \VVc \to \VVd$ be the standard degree-of-freedom interpolation operator defined in the BDM space.
Then: 

\noindent
$(i)$ if $\vv \in \ZZc$ then $\vvi \in \ZZd$;

\noindent
$(ii)$ for any $\vv \in \ZZc$
\begin{equation}
\label{eq:orth-v}
\left(\vv - \, \vvi, \,  \pp_{k-1} \right) = 0 \quad \text{for all $\pp_{k-1} \in [\Pk_{k-1}(\Omega_h)]^3$;}
\end{equation}

\noindent
$(iii)$ for any $\vv \in \VVc \cap \HH^{s+1}(\Omega_h)$, with $0 \leq s \leq k$, for all $E \in \Omega_h$, it holds
%
\begin{equation}
\label{eq:int-v}
\vert \vv - \vvi \vert_{m,E} \lesssim h_E^{s+1-m} \vert \vv \vert_{s+1,E} 
\qquad \text{for $0\leq m\leq s+1$.}
\end{equation}
\end{lemma}
The second interpolation concerns the spaces $\WWc$, see for instance \cite{AV:1999}. 
A notable property is that this interpolant also approximates the $\bcurl$ of the function.
\begin{lemma}[Interpolation operator on $\WWd$]\label{lm:int-w}
Under the Assumption \textbf{(MA1)} let $\PWWd \colon \WWc \to \WWd$ be the interpolation operator of \cite{AV:1999}. 
If the function satisfies also $\HH \in \HH^r(\bcurl, \Omega)$ for $\frac{1}{2} < r \leq k+1$, the following estimates hold
\[
\begin{aligned}
&| \HH - \PWWd \HH |_{m,E} \lesssim h_E^{r-m} | \HH |_{\HH^r(\bcurl, E)} \quad &\text{for $0\leq m\leq r$}\, ,  \\
&| \bcurl(\HH - \PWWd \HH) |_{m,E} \lesssim h_E^{\tilde{r}-m}| \bcurl(\HH) |_{\tilde{r}, E} \quad &\text{for $0\leq m\leq \tilde r$}\, ,
\end{aligned}
\]
where $\tilde r := \min \{ r,k \}$.
\end{lemma}

\subsection{Discrete problem}

From now on, we assume that the advective fields satisfy the following regularity requirements, in addition to the minimal conditions detailed at the beginning of Section \ref{sec:model}:
\begin{itemize}
\item the advective velocity field $\cc \in \boldsymbol{W}^1_ \infty(\Omega_{h0})  \cap \HH_0(\diver, \Omega)$, 
\item the advective magnetic induction $\TT \in \boldsymbol{W}^2_ \infty(\Omega_{h0})  \cap {\bf W}$,
\end{itemize}
where $\Omega_{h0}$ is a coarse mesh such that all the meshes in the family $\{ \Omega_h \}_h$ are a refinement of $\Omega_{h0}$. Note that our assumption is purposefully more general than assuming $\cc \in \boldsymbol{W}^1_ \infty(\Omega)$, $\TT \in \boldsymbol{W}^2_ \infty(\Omega)$ since it allows also for advective fields in the corresponding discrete spaces ($\VVd$ and $\WWd$, respectively). This is compatible with the situation when the linearized problem is thought of as originated by a fixed point iteration of the fully nonlinear magnetohydrodynamic equations. Our condition is set on $\Omega_{h0}$, and not on $\Omega_h$, simply because our data $\cc,\TT$ are given and should not depend on the mesh parameter $h$.

In addition, before introducing the discrete problem, we preliminary make the following assumption on the  solution $\uu$ of problem \eqref{eq:linear variazionale}.

\smallskip
\noindent
\textbf{(RA1) Regularity assumption for the consistency:}

\noindent
Let $\uu \in \ZZc$ be the velocity solution  of Problem \eqref{eq:linear variazionale}, then $\uu$ belongs to $\HH^{r}(\Omega)$ for some $r> 3/2$. \medskip

We consider the following discrete problem 
\begin{equation}
\label{eq:linear fem}
\left\{
\begin{aligned}
& \text{find $(\uu_h, p_h, \BB_h) \in \VVd \times \Qd \times \WWd$,  such that} 
\\
&\begin{aligned}
\pss \,(\uu_h, \vv_h) + \ns \, \ash(\uu_h, \vv_h) + c_h(\uu_h, \vv_h) + &
\\ 
-d(\BB_h, \vv_h)   + J_h(\uu_h, \vv_h) + b(\vv_h, p_h) 
&= 
(\ff, \vv_h)  
&\,\,\, & \text{for all $\vv_h \in \VVd$,} 
\\
b(\uu_h, q_h) &= 0 
&\,\,\, & \text{for all $q_h \in \Qd$,}
\\
\psm \,(\BB_h, \HH_h) + \nm \,\am(\BB_h, \HH_h) + d(\HH_h, \uu_h) 
&= 
(\GG, \HH_h)  
&\,\,\, & \text{for all $\HH_h \in \WWd$,}
\end{aligned}
\end{aligned}
\right.
\end{equation}
where the discrete bilinear forms are defined as:
%%
\begin{equation}
\label{eq:forme_d}
\begin{aligned}
\ash(\uu_h,  \vv_h) &:=  (\beps_h(\uu_h) ,\, \beps_h(\vv_h))
- \sum_{f \in \Edges} (\media{\beps_h(\uu_h)\nn_f}_f ,\, \jump{\vv_h}_f)_f  +
\\
&- \sum_{f \in \Edges} (\jump{\uu_h}_f ,\, \media{\beps_h(\vv_h) \nn_f}_f)_f 
+ 
\bdma \sum_{f \in \Edges} h_f^{-1} (\jump{\uu_h}_f ,\,\jump{\vv_h}_f)_f \, ,
\\
c_h(\uu_h, \vv_h) &:=  (( \bnabla_h \uu_h ) \, \cc, \, \vv_h )
- \sum_{f \in \EdgesI} ( (\cc \cdot \nn_f) \jump{\uu_h}_f ,\, \media{\vv_h}_f)_f +
\\
& + 
\bdmc \sum_{f \in \EdgesI} (\vert \cc \cdot \nn_f \vert \jump{\uu_h}_f, \, \jump{\vv_h}_f )_f \, .
\end{aligned}
\end{equation}
To stabilize the method and obtain feasible numerical solutions in the hyperbolic limit, we include the following jump penalization term in the formulation of the discrete problem
\begin{equation}
\label{eq:J}
\begin{aligned}
J_h(\uu_h, \vv_h) &:=   \sum_{f \in \Edges} \bdmJ  \bigl(
\jump{\TT \times \uu_h}_f , \jump{\TT \times \vv_h}_f \bigr)_f \\
& \qquad +
\sum_{f \in \EdgesI} \bdmJJ h_f^2 
\bigl(\jump{\bcurl_h (\uu_h \times \TT)}_f  ,\jump{\bcurl_h (\vv_h \times \TT)}_f 
\bigr)_f \, ,
\end{aligned}
\end{equation}
where $\bdmJ$ and $\bdmJJ$ are two parameters that will be fixed later. In contrast to the standard CIP term commonly found in the literature \cite{burman:2004, BDV:2024}, we emphasize that our approach considers the jump of the $\bcurl$ rather than the jump of the full gradient.
\begin{remark}
It is possible to consider the following alternative $J_h(\cdot,\cdot)$:
\[
\begin{aligned}
J_h(\uu_h, \vv_h) &:=  \sum_{f \in \Edges} 
\Vert \TT\Vert_{\boldsymbol{L}^\infty(f^\pm)}^2 
 \bdmJ (\jump{\uu_h}_f ,  \jump{\vv_h}_f)_f \\
&\qquad + 
\sum_{f \in \EdgesI}
\Vert \TT\Vert_{\WW^1_\infty(f^\pm)}^2
\bdmJJ  h_f^2 (\jump{\bnabla_h \uu_h}_f  , \jump{\bnabla_h \vv_h}_f )_f \, .
\end{aligned}
\]
\end{remark}
Finally, we define the bilinear form
\begin{equation}
\label{eq:astab}
\begin{aligned}
\astab(\uu_h, \BB, \vv_h, \HH_h) := &
\pss (\uu_h, \vv_h) + \psm (\BB, \HH_h) + 
\ns \ash(\uu_h, \vv_h) + \nm \am(\BB, \HH_h) 
\\  
& 
+ c_h(\uu_h, \vv_h) -d(\BB, \vv_h)   + d(\HH_h, \uu_h) + J_h(\uu_h, \vv_h) \,.
\end{aligned}
\end{equation}
Problem \eqref{eq:linear fem} can be written also in the following pressure-independent form
\begin{equation}
\label{eq:Astabprob}
\left\{
\begin{aligned}
& \text{find $(\uu_h,\BB_h) \in \ZZd  \times \WWd$,  such that} 
\\
&\astab(\uu_h, \BB_h, \vv_h, \HH_h) = (\ff, \vv_h) + (\GG, \HH_h) \quad   \text{for all $\vv_h \in \ZZd$} , \, \text{for all $\HH_h \in \WWd$} \, .
\end{aligned}
\right.
\end{equation}

\begin{remark}
All the forms above are intended to be extendable to any sufficiently regular function. In particular, if the solution $\uu$ of the continuous problem \eqref{eq:linear variazionale} satisfies (RA1), the following consistency property holds
\begin{equation}\label{eq:consistency}
\astab(\uu-\uu_h, \BB-\BB_h, \vv_h, \HH_h) = 0 \quad   \text{for all $\vv_h \in \ZZd$} , \, \text{for all $\HH_h \in \WWd$} \, .
\end{equation}
\end{remark}

\begin{remark}\label{rem:Bh:kernel}
Exploiting the third equation in \eqref{eq:linear fem} and choosing $\HH_h$ as the gradient of a polynomial $p \in \Pkc_{k+1}(\Omega_h)$, we obtain that
\[
(\BB_h, \nabla p) = 0 \quad \forall p \in \Pkc_{k+1}(\Omega_h) \, ,
\]
which is the classical discrete divergence-free condition for Nédéléc elements.
\end{remark}

\section{Theoretical analysis}
\label{sec:theoretical}
\subsection{Inf-sup condition}

We introduce the following norms and seminorms, which depend on the equation parameters and on the mesh:
\begin{equation}
\label{eq:norme}
\begin{aligned}
\normas{\uu}^2 &:= 
\pss \Vert \uu \Vert^2 + \ns \Vert \beps_h(\uu) \Vert^2 + 
\ns \, \bdma\!\sum_{f \in \Edges} h_f^{-1} \Vert \jump{\uu}_f \Vert_{f}^2 \, ,
\\
\normaupw{\uu}^2 &:= \bdmc\!\sum_{f \in \EdgesI}  \Vert \vert \cc \cdot \nn_f \vert^{1/2} \jump{\uu}_f \Vert_{f}^2 \, ,
\\
\normacip{\uu}^2 &:=
\bdmJ\sum_{f \in \Edges}  \Vert \jump{\TT \times \uu}_f \Vert_{f}^2 \, ,
+
\bdmJJ\sum_{f \in \EdgesI}  h_f^2 \Vert \jump{\bcurl_h(\uu\times \TT_h)}_f \Vert_{f}^2\\
\normacurl{\uu}^2 &:=
\gamma^{-1} \, \sum_{E \in \Omega_h} h_E^2 \, \| \bcurl_h(\uu \times \TT_h) \|^2_{E} \, .
\end{aligned}
\end{equation}
where the global parameter $\gamma := \max\{h, \nm\}$ (hence $\gamma^{-1} := \min\{h^{-1},\nm^{-1}\}$) and $\TT_h$ is the best piecewise constant approximation of $\TT$ in $L^2(\Omega)$.

\begin{remark}\label{rem:scaling}
We are aware that $h$ and $\nm$ have different physical dimensions, so that in principle the comparison $\gamma := \max\{h, \nm\}$ would require a suitable preliminary scaling of these quantities. However, it is common practice in the literature concerning finite element analysis of advection-diffusion-reaction problems to ignore this aspect and assume that the involved quantities are already properly scaled. Here, we follow this approach.
\end{remark}

The stability norms are obtained by summing these norms and seminorms
\begin{equation}
\label{eq:normeVW}
\begin{aligned}
\normastab{\uu}^2 &:= 
\normas{\uu}^2 + \normaupw{\uu}^2 + \normacip{\uu}^2 + \normacurl{\uu}^2 \,, \\
\normam{\BB}^2 &:= 
\psm \Vert \BB \Vert^2 + \nm \Vert \bcurl (\BB) \Vert^2 \,.
\end{aligned}
\end{equation}

\begin{remark}\label{rem:thetaequiv}
In the definitions of the seminorm $\normacurl{\cdot}$ and the second term in $\normacip{\cdot}$, we have considered the approximation $\TT_h$ instead of $\TT$.
This choice was made to simplify the theoretical analysis of the method.
 We emphasize that controlling the norms with $\TT_h$, along with the $\boldsymbol L^2$-norm of $\vv_h$, ensures the control of the corresponding norms with $\TT$ as we show briefly here below (and also the converse holds true). In fact, using triangular inequality, an inverse estimate and standard approximation results together with inverse estimates for polynomials, we obtain 
\[
\begin{aligned}
\| \bcurl_h(\vv_h \times \TT_h) \|^2_{E} 
&\leq 
\| \bcurl_h(\vv_h \times \TT) \|^2_{E} + \| \bcurl_h(\vv_h \times (\TT_h - \TT)) \|^2_{E}  \\
&\lesssim
\| \bcurl_h(\vv_h \times \TT) \|^2_{E} + | \vv_h |_{1,E}^2\|\TT_h - \TT \|^2_{\boldsymbol{L}^\infty(E)} \\
& \qquad+
\| \vv_h \|_E^2 | \TT_h - \TT |^2_{\WW^1_\infty(E)}\\
& \lesssim\| \bcurl_h(\vv_h \times \TT) \|^2_{E} 
+ 
|\TT|^2_{\WW^1_\infty(E)}\|\vv_h\|^2_{E} \, ,  \\
\end{aligned}
\]
for all $\vv_h \in \ZZd$ (but, obviously, it holds also for all $\vv_h \in \VVd$). For the seminorm $\normacip{\cdot}$, we have that
\[
\begin{aligned}
\sum_{f\in\EdgesI} h_f^2 \| \jump{\bcurl(\vv_h \times \TT_h) } \|^2_{f}
&\leq
\sum_{f\in\EdgesI} h_f^2 \| \jump{\bcurl(\vv_h \times \TT) } \|^2_{f} \\
&\qquad+
\sum_{f\in\EdgesI} h_f^2 \| \jump{\bcurl(\vv_h \times (\TT_h-\TT)) } \|^2_{f}\, .
\end{aligned}
\]
Noting that
\[
\begin{aligned}
\sum_{f\in\EdgesI} h_f^2 \| \jump{\bcurl(\vv_h \times (\TT_h-\TT)) } \|^2_{f} 
\leq
\sum_{f\in\EdgesI} h_f^2 \bigl(&\| \bcurl(\vv_h \times (\TT_h-\TT))  \|^2_{f^+} 
\\
&\qquad + \| \bcurl(\vv_h \times (\TT_h-\TT))  \|^2_{f^-} \bigr) \, ,
\end{aligned}
\]
and using approximation estimates for $\TT \in \WW^1_\infty(\Omega_h)$, a scaled trace inequality and inverse estimates on $\vv_h$, we easily obtain
\begin{equation}\label{eq:tt-tth}
\begin{aligned}
\sum_{f\in\EdgesI} h_f^2 \| \jump{\bcurl(\vv_h \times (\TT_h-\TT)) } \|^2_{f}
&\lesssim
\sum_{f \in \EdgesI}h_f^2  
\| \nabla \vv_h \|^2_{\boldsymbol{L}^2(f^\pm)} \| \TT - \TT_h \|^2_{\boldsymbol{L}^{\infty}(f^\pm)} + \\
& \qquad+ \sum_{f \in \EdgesI}h_f^2\| \vv_h \|^2_{\boldsymbol{L}^2(f^\pm)} | \TT |^2_{\WW^1_{\infty}(f^\pm)}
\\
& \lesssim 
\sum_{E \in \Omega_h} h_E \| \vv_h \|^2_{E} |\TT|^2_{\WW^1_\infty(E)}
\lesssim h \,|\TT|^2_{\WW^1_\infty(\Omega_h)} \| \vv_h \|^2 \, .
\end{aligned}
\end{equation}
Hence
\[
\sum_{f\in\EdgesI} h_f^2 \| \jump{\bcurl(\vv_h \times \TT) } \|^2_{f}
\leq
\sum_{f\in\EdgesI} h_f^2 \| \jump{\bcurl(\vv_h \times \TT_h) } \|^2_{f}
+
 \sum_{E \in \Omega_h} h_E | \TT|^2_{\WW^1_\infty(\Omega_h)} \| \vv_h\|^2_E
\]
 %
\end{remark}
%
The proof of the inf-sup stability is divided into two parts.
First, we control all the terms appearing in the previous definition, except for $\normacurl{\cdot}$, by testing the bilinear form $\astab(\cdot, \cdot, \cdot, \cdot)$ with a symmetric entry.
To handle the remaining term, we use a suitable interpolant of a function close to $\bcurl(\cdot \times \TT)$ and construct a function that satisfies a form of inf-sup condition with respect to such interpolant.

We omit the proof of the following result since it can be obtained with a standard argument in DG theory; we only underline that also Remark \ref{rem:thetaequiv} needs to be used to bound the $\normacip{\cdot}^2$ term in the right-hand side.

\begin{proposition}
\label{prp:coe}
Let the mesh assumptions \textbf{(MA1)}, and \textbf{(MA2)} if $k=1$. Assume the consistency assumption \textbf{(RA1)} holds.
If the parameter $\bdma$ in \eqref{eq:forme_d} is sufficiently large there exists a real positive constant $\ccoe$ such that for all $\vv_h \in \ZZd$ and $\HH_h \in \WWc$ the form $\astab(\cdot, \cdot, \cdot, \cdot)$ defined in \eqref{eq:astab} satisfies
%
\[
\astab(\vv_h, \BB_h, \vv_h, \BB_h) \geq 
\ccoe \left( \normas{\vv_h}^2 + \normaupw{\vv_h}^2 + \normacip{\vv_h}^2 + \normam{\BB_h}^2 \right) \, ,
\]
where the coefficient $\ccoe$ does not depend on the mesh size $h$ and on the problem parameters $\pss$, $\psm$, $\ns$, $\nm$, $\cc$, and $\TT$.
\end{proposition}
The following result aims to establish control over $\normacurl{\vv_h}$.
 We emphasize that, in the previous proposition, we managed to control all the terms in the norm except for 
$\normacurl{\vv_h}$.
%%
\begin{proposition} \label{prp:preliminary inf sup}
Let the mesh assumptions \textbf{(MA1)}, and \textbf{(MA2)} if $k=1$. Assume that the consistency assumption \textbf{(RA1)} holds. 
Then for any $(\vv_h, \BB_h) \in \ZZd \times \WWd$ it exists $\HH_h \in \WWd$ such that
\begin{equation}\label{newprop:objective}
\begin{aligned}
\astab(\vv_h, \BB_h, 0, \HH_h) &\geq C_1\normacurl{v_h}^2 -C \Big(\bdmJJ^{-1} \normacip{\vv_h}^2 + (1 + \psm  h) \normam{\BB_h}^2
\\ & \qquad      +  \frac{| \TT |^2_{\WW^1_\infty(\Omega_h)^3} \,  h}{\pss} \| \vv_h \|^2_S 
+  \left(\frac{\bdmJ + \bdmJJ}{\bdmJ\,\bdmJJ} \right) \normacip{\vv_h}^2\Big) \, ,
\end{aligned}
\end{equation}
where the constants $C_1$ and $C$ does not depend on the mesh size $h$ and on the problem parameters $\pss$, $\psm$, $\ns$, $\nm$, $\cc$, and $\TT$.
\end{proposition}
%
\begin{proof}
We start by constructing $\HH_h$. We introduce $\pp_h\in\mathbb{O}_{k-1}(\Omega_h)$ as the interpolant of $\bcurl_h(\vv_h \times \TT_h)$ defined in Proposition~\ref{prp:oswald}.
Let $\hat\HH_h \in \Pkc_k(\Omega_h) \cap \WWc$ be the function constructed in \cite{BDV:2024} Lemma 4.2 that satisfies the following two inequalities:
\begin{equation}\label{eq:infsupHH}
\left\{
\begin{aligned}
&\sum_{E \in \Omega_h} h_E^{-2} \| \hat\HH_h \|_E^2 \lesssim \sum_{E \in \Omega_h} h_E^{2} \| \pp_h \|_E^2 \, , \\
&(\hat\HH_h, \pp_h) \gtrsim \sum_{E \in \Omega_h} h_E^{2} \| \pp_h \|_E^2 \, .
\end{aligned}
\right .
\end{equation}
Finally, we define $\HH_h = \gamma^{-1} \hat \HH_h$ and proceed to show that it satisfies \eqref{newprop:objective}. 

\noindent
We observe that, since the third entry is equal to zero, we easily obtain that
\begin{equation}\label{eq:equalToZero}
\pss (\vv_h, 0) = 
\ns \, \ash(\vv_h, 0) = c_h(\vv_h, 0) = d(\BB, 0)   = J_h(\vv_h, 0) = 0 \, .
\end{equation}
Now, we estimate the nonzero terms. Using Cauchy-Schwarz inequality, property \eqref{eq:infsupHH}, the stability of the interpolant in Proposition~\ref{prp:oswald}, and the regularity of the mesh, we obtain
\begin{equation}\label{eq:smh_estimate}
\begin{aligned}
| \psm (\BB_h, \HH_h) |
&\geq
- \psm \| \BB_h \| \| \HH_h \| \\
&\gtrsim 
-\psm\left( \sum_{E \in \Omega_h} h_E^2 \, \| \BB_h \|^2_E\right)^{\frac{1}{2}} \left( \sum_{E \in \Omega_h} h_E^{-2} \, \| \HH_h \|^2_E\right)^{\frac{1}{2}} \\
&=
-\psm\left( \sum_{E \in \Omega_h} h_E^2 \, \| \BB_h \|^2_E\right)^{\frac{1}{2}} \gamma^{-1}\left( \sum_{E \in \Omega_h} h_E^{-2} \, \| \Hat{\HH}_h \|^2_E\right)^{\frac{1}{2}} \\
&\gtrsim 
-\psm \, h^{\frac{1}{2}} \, \| \BB_h \| \gamma^{-\frac{1}{2}} \left( \sum_{E \in \Omega_h} h_E^{2} \, \| \pp_h \|^2_E\right)^{\frac{1}{2}} \\
&\gtrsim 
-\psm \, h^{\frac{1}{2}} \, \| \BB_h \| \normacurl{\vv_h} 
\gtrsim 
-\psm^{\frac{1}{2}} \, h^{\frac{1}{2}} \, \normam{\BB_h} \normacurl{\vv_h} \, .
\end{aligned}
\end{equation}
The bilinear form $\am(\BB_h,\HH_h)$ is estimated in a very similar way, by using also a polynomial inverse estimate and the fact that $\gamma \geq \nm$. We get

\begin{equation}\label{eq:amh_estimate}
\begin{aligned}
| \am (\BB_h, \HH_h) |
&\geq
- \nm \| \bcurl (\BB_h) \| \| \bcurl (\HH_h) \| \\
&\gtrsim 
-\nm\left( \sum_{E \in \Omega_h}  \| \bcurl (\BB_h) \|^2_E\right)^{\frac{1}{2}} \left( \sum_{E \in \Omega_h}  \| \bcurl (\HH_h) \|^2_E\right)^{\frac{1}{2}} \\
&\gtrsim
-\nm^{\frac{1}{2}}\normam{\BB_h} \left( \sum_{E \in \Omega_h} h_E^{-2} \, \| \HH_h \|^2_E\right)^{\frac{1}{2}} 
\!\gtrsim
-\nm^{\frac{1}{2}}\normam{\BB_h} \gamma^{-1}\!\left( \sum_{E \in \Omega_h} h_E^{-2} \, \| \hat{\HH}_h \|^2_E\right)^{\frac{1}{2}} \\
&\gtrsim 
-\nm^{\frac{1}{2}}\normam{\BB_h} \gamma^{-1}\left( \sum_{E \in \Omega_h} h_E^2 \, \| \bcurl_h(\vv_h \times \TT_h) \|^2_E\right)^{\frac{1}{2}} \gtrsim 
-\normam{\BB_h} \normacurl{\vv_h}\, .
\end{aligned}
\end{equation}
For the bilinear form $d(\HH_h,\vv_h)$, thanks to integration by parts, we have that %%
\begin{equation}\label{eq:d-form_h}
\begin{aligned}
d(\HH_h, \vv_h) 
&= 
(\bcurl (\HH_h) \times \TT, \vv_h) \\
&=
(\bcurl_h (\TT \times \vv_h), \HH_h) 
+
\sum_{E \in \Omega_h}
(\HH_h \times \nn_E ,   \TT  \times \vv_h)_{\partial E} \, .
\end{aligned}
\end{equation}
The first term is split as
\[
\begin{aligned}
(\bcurl_h (\TT \times \vv_h), \HH_h) 
&=
(\bcurl_h ((\TT - \TT_h) \times \vv_h) , \HH_h) 
+
(\bcurl_h (\TT_h \times \vv_h) , \HH_h) \\
&=
(\bcurl_h ((\TT - \TT_h) \times \vv_h) , \HH_h) \\
& \qquad + (\bcurl_h (\TT_h \times \vv_h) - \pp_h, \HH_h) \\
& \qquad + (\pp_h, \HH_h) \\
& =: T_{\TT,1} + T_{\TT,2} + T_{\TT,3} \, .
\end{aligned}
\]
\textit{Estimate of $T_{\TT,1}$:} Thanks to the regularity of $\TT$, we have that
\begin{equation*}
\begin{aligned}
(\bcurl_h ((\TT - \TT_h) \times \vv_h) , \HH_h)
& \geq
- \left( \sum_{E \in \Omega_h} h_E^2 \|\bcurl_h ((\TT - \TT_h) \times \vv_h)\|_E^2 \right)^{\frac{1}{2}} \\
& \qquad \left( \sum_{E \in \Omega_h} h_E^{-2} \| \HH_h\|_E^2 \right)^{\frac{1}{2}} \, .
\end{aligned}
\end{equation*}
Using the vector calculus identity,
\begin{equation}\label{eq:curl-identity}
\bcurl(A \times B) = (\diver B) \, A - (\diver A) \, B + (\bnabla A) B - (\bnabla B) A \, ,
\end{equation}
and a polynomial inverse estimate combined with standard approximation results, we can easily obtain
\[
\|\bcurl_h ((\TT - \TT_h) \times \vv_h)\|^2_E \leq |\TT|_{\WW^1_\infty(\Omega_h)} \, \| \vv_h \|_E \, .
\]
Hence, using the same steps as the previous estimates, we have that
\[
\begin{aligned}
(\bcurl ((\TT - \TT_h) \times \vv_h) , \HH_h)
& \gtrsim
- \left( \sum_{E \in \Omega_h} h_E^2 |\TT|_{\WW^1_\infty(\Omega_h)} \, \| \vv_h \|_E \right)^{\frac{1}{2}} \\
& \qquad \gamma^{-1}\left( \sum_{E \in \Omega_h} h_E^2 \, \| \bcurl_h(\vv_h \times \TT_h) \|^2_E\right)^{\frac{1}{2}} \\
& \gtrsim
-
| \TT |_{\WW^1_\infty(\Omega_h)} h^{\frac{1}{2}} \| \vv_h \| \, \normacurl{\vv_h} \\
&\gtrsim
-
\left( \frac{| \TT |^2_{\WW^1_\infty(\Omega_h)} \,  h}{\pss}\right)^{\frac{1}{2}} \| \vv_h \|_S \, \normacurl{\vv_h} \, .
\end{aligned}
\]
%
\textit{Estimate of $T_{\TT,2}$:} Using Proposition \ref{prp:oswald}, the definition and properties of $\HH_h$, and recalling that $h_E \le h$, 
we obtain
\[
\begin{aligned}
(\bcurl_h (\TT_h \times \vv_h) - \pp_h, \HH_h)
& \gtrsim
-\left( \sum_{f \in \EdgesI} h_f^3 \| \jump{\bcurl_h(\TT_h \times \vv_h)}\|_f^2\right)^{\frac{1}{2}} \\
& \qquad \gamma^{-1} \left(  \sum_{E \in \Omega_h} h_E^{2} \, \| \bcurl_h(\vv_h \times \TT_h) \|^2_E\right)^{\frac{1}{2}} \\
&\gtrsim - \left(\frac{1}{\bdmJJ}\right)^{\frac{1}{2}} \normacip{\vv_h}\normacurl{\vv_h}
\, .
\end{aligned}
\]
\textit{Estimate of $T_{\TT,3}$:} Using the definition of $\HH_h$ and the properties of $\hat\HH_h$ yields
\[
(\pp_h, \HH_h) 
=
\gamma^{-1} (\pp_h, \hat\HH_h)
\gtrsim
\gamma^{-1} \sum_{E \in \Omega_h} h_E^2 \| \pp_h \|^2_E \, .
\]
Now, using triangular inequality, we observe that
\[
\|  \bcurl_h(\vv_h \times \TT_h) \|^2_E
\leq
2\| \pp_h \|^2_E 
+ 
2\|  \bcurl_h(\vv_h \times \TT_h)  - \pp_h\|^2_E \, ,
\]
which implies 
\[
\| \pp_h \|^2_E
\geq
\frac{1}{2}\|  \bcurl_h(\vv_h \times \TT_h) \|^2_E
-
\|  \bcurl_h(\vv_h \times \TT_h)  - \pp_h\|^2_E
 \, .
\]
Using Proposition \ref{prp:oswald}, we obtain
\[
\begin{aligned}
(\pp_h, \HH_h) 
&\geq
 \frac{1}{2}\gamma^{-1} \sum_{E \in \Omega_h} \left( h_E^2\|  \bcurl_h(\vv_h \times \TT_h) \|^2_E
- C h_E^3 \| \jump{\bcurl_h(\vv_h \times \TT_h)} \|^2_{\partial E} \right) \\
& \geq
\frac{1}{2}\normacurl{v_h}^2 - C \gamma^{-1} \bdmJJ^{-1} h \normacip{\vv_h}^2
 \geq \frac{1}{2}\normacurl{v_h}^2 - C \bdmJJ^{-1} \normacip{\vv_h}^2
\, ,
\end{aligned}
\]
where in the last inequality we simply used that $\gamma^{-1} h \le 1$ by the definition of $\gamma$.
% To conclude the proof, we have to estimate the boundary term of \eqref{eq:d-form_h}. First, we recall that thanks to the boundary conditions, we have that
% \[
% \begin{aligned}
% (\HH_h \times \nn_f) \cdot  (\vv_h \times \TT) 
% & =
% (\HH_h \cdot \vv_h) (\TT \cdot \nn_f) -
% (\HH_h \cdot \TT) (\vv_h \cdot \nn_f) = 
% (\HH_h \cdot \vv_h) (\TT \cdot \nn_f) \,.
% \end{aligned}
% \]
% %
% {\color{blue}Carlo: questa proprietà è vera solo sul bordo di $\Omega$, ma non capisco dove si usa qui sotto. LORE: concordo, era retaggio del vecchio modo (paper convesso). Manuel, se torna anche a te elimina pure la frase soprastante...} \\
% %
% {\color{red}Il secondo termine qui sopra non dovrebbe essere moltiplicato per $\gamma^{-1}$? Che poi si combinerebbe con l'h ecc...}. {\color{blue} {\bf Carlo}: sì, mi sembra che ci voglia il fattore $\gamma^{-1}$ anche per il secondo termine a destra nell'ultima riga. Quindi direi che nella stima \eqref{newprop:almost} il fattore $\Big(\frac{h}{\bdmJJ} + \bdmJ^{-1} \Big)$ dovrebbe diventare $\Big(\frac{\bdmJ + \bdmJJ}{\bdmJ\,\bdmJJ} \Big)$, che peraltro mi pare più sano dal punto di vista dimensionale. Di conseguenza cambierebbe anche il corrispondente termine in \eqref{newprop:objective}. Non mi sembra che il cambiamento abbia impatto in altri punti}.  {\color{magenta} [LORE: concordo in toto. Ho inserito in magenta una proposta di modifica, dunque qua sopra e nelle due equazioni indicate da Carlo.]}

Using Cauchy-Schwarz inequality, Proposition \ref{prp:oswald}, the definition of the jump operator, trace inequality, and \eqref{eq:infsupHH}, we have that
\[
\begin{aligned}
\sum_{E \in \Omega_h}
(\HH_h \times \nn_E ,   \TT  \times \vv_h)_{\partial E}
&\gtrsim -
\left(
\bdmJ^{-1} \sum_{f \in \Edges } \| \HH_h \|^2_f
\right)^{\frac{1}{2}}
\left( \bdmJ
\sum_{f \in \Edges } \| \jump{\vv_h \times \TT} \|^2_f
\right)^{\frac{1}{2}} \\
&\gtrsim -
\left(
\bdmJ^{-1}\sum_{E \in \Omega_h} h_E^{-1}\| \HH_h \|^2_E
\right)^{\frac{1}{2}}
\normacip{\vv_h} \\
&\gtrsim -
\gamma^{-\frac{1}{2}}\left(
\bdmJ^{-1}\sum_{E \in \Omega_h} h_E^{-2}\| \hat\HH_h \|^2_E
\right)^{\frac{1}{2}}
\normacip{\vv_h} \\
&\gtrsim -
\bdmJ^{-\frac{1}{2}}
\normacip{\vv_h}
\normacurl{\vv_h}\, .
\end{aligned}
\]
Gathering all the above estimates, we have obtained
\begin{equation}\label{newprop:almost}
\begin{aligned}
\astab(\vv_h, \BB_h, 0, \HH_h) &\geq \tilde C_1\normacurl{\vv_h}^2 - \tilde C_2\bdmJJ^{-1} \normacip{\vv_h}^2  \\
& \qquad - \tilde C_3\Big((1 + \psm  h) \normam{\BB_h}^2 
+
\frac{| \TT |^2_{\WW^1_\infty(\Omega)^3} \,  h}{\pss} \| \vv_h \|^2_S \\
& \qquad \qquad +  \Big(\frac{\bdmJ + \bdmJJ}{\bdmJ\,\bdmJJ} \Big) \normacip{\vv_h}^2\Big)^\frac{1}{2}\normacurl{v_h}^2 \, ,
\end{aligned}
\end{equation}
