In the following lemma, we prove that $\normam {\HH_h}$ is controlled by the norms of $\vv_h$.
\begin{lemma}[Continuity of the norm]
\label{lem:norm-cont}
Let the mesh assumptions \textbf{(MA1)}, and \textbf{(MA2)} if $k=1$. Assume that the consistency assumption \textbf{(RA1)} holds.
Then the test function $H_h$ introduced in Proposition \ref{prp:preliminary inf sup} satisfies 
\[
\normam{\HH_h}^2 
\lesssim
\dfrac{\psm}{\pss} \| \TT \|^2_{\boldsymbol{L}^\infty(\Omega_h)} \normas{\vv_h}^2 
+
\normacurl{\vv_h}^2 \,. 
\]
\end{lemma}

\begin{proof}
We need to estimate the two terms that appear in the definition of $\normam{\HH_h}$. For the first one, we have
\[
\begin{aligned}
\psm \| \HH_h\|^2
&=
\psm \, \gamma^{-2} \, \| \hat \HH_h\|^2
\leq
\psm \sum_{E} h_E^{-2} \| \hat \HH_h\|^2_E \\
&\lesssim
\psm \sum_{E} h_E^{2} \| \pp_h\|^2_E 
\lesssim
\psm \sum_{E} h_E^{2} \| \bcurl_h(\vv_h \times \TT_h)\|^2_E \\
&\lesssim
\psm \| \TT \|_{\boldsymbol{L}^\infty(\Omega_h)}^2 \| \vv_h\|^2 
\lesssim
\dfrac{\psm}{\pss} \| \TT \|^2_{\boldsymbol{L}^\infty(\Omega_h)} \normas{\vv_h}^2 \, .
\end{aligned}
\]
For the second term, we  use an inverse polynomial inequality, property \eqref{eq:infsupHH}, and the definition of $\gamma$
%%
\[
\begin{aligned}
\nm \| \bcurl (\HH_h)\|^2
&\lesssim
\nm \sum_{E \in \Omega_h} h_E^{-2} \| \HH_h \|^2
=
\nm \, \gamma^{-2}\,\sum_{E \in \Omega_h} h_E^{-2} \| \hat\HH_h \|^2 \\
%&\lesssim
%\nm \, h^{-2}\,\sum_{E \in \Omega_h} h_E^{-2} \| \HH_h \|^2 \\
&\lesssim
\gamma^{-1}\,\sum_{E \in \Omega_h} h_E^{2} \| \bcurl_h(\vv_h \times \TT_h) \|^2_E = \normacurl{\vv_h}^2 \,. 
\end{aligned}
\]
