\begin{theorem}\label{th:cip-inf-sup}
Let the mesh assumptions \textbf{(MA1)}, \textbf{(MA2)} if $k=1$. Assume that the consistency assumption \textbf{(RA1)} holds. 
We have that:
\begin{equation} \label{eq:infsup}
\normastab{\vv_h} + \normam{\BB_h} 
\lesssim 
\sup_{(\ww_h,\mathbf{K}_h) \in \ZZd \times \WWd} \dfrac{\astab(\vv_h, \BB_h, \ww_h, \mathbf{K}_h)}{\normastab{\ww_h} + \normam{\mathbf{K}_h}}
\qquad \text{$\forall (\vv_h,\BB_h) \in \ZZd \times \WWd$.}
\end{equation}
\end{theorem}
\begin{proof}
The proof becomes standard in light of the previous derivations.
