taking $(\ww_h,\mathbf{K}_h) = \kappa (\vv_h,\BB_h) +  (0,\HH_h)$ for a sufficiently large $\kappa$, in addition to recalling Lemma \ref{lem:norm-cont}.
Here, $\HH_h$ is defined as in Proposition \ref{prp:preliminary inf sup}.
\end{proof}

\subsection{Error analysis}
Let $(\uu, p, \BB)$ and $(\uu_h, p_h, \BB_h)$ 
%\in \VVd \times \Qd \times \WWd$ 
be the solutions of \eqref{eq:linear variazionale} and \eqref{eq:linear fem} respectively. 
We introduce the following notations that will be useful for the error analysis
\begin{equation}
\label{eq:fquantities}
\eei := \uu - \uui\,, \qquad 
\eeh := \uu_h - \uui\,, \qquad 
\EEi := \BB - \BBi\,, \qquad 
\EEh := \BB_h - \BBi \,,
\end{equation}
where $\uui$ and $\BBi$ are defined in Lemma \ref{lm:int-v} and Lemma \ref{lm:int-w}. We define also the following quantity
\begin{equation}
\label{eq:quantities}
\begin{aligned}
\ls^2 &:= \max \biggl\{ 
\pss h^2 \,,  \max_{f \in \EdgesI} \Vert  \cc \cdot \nn_f \Vert_{\boldsymbol{L}^\infty(f)} h \,,
\Vert  \TT \Vert_{\WW^1_\infty(\Omega_h)}^2  h \,,
\ns%(1 + \bdma + \bdma^{-1}) 
\biggr\} \,.
%\\
%\lm^2 &:= \max \{ \psm  \,, \nm \} \,.
\end{aligned}
\end{equation}
We begin the error analysis with the following proposition.
\begin{proposition}\label{prp:abstrac}
Let $(\uu, \BB) \in \ZZc \times \WWc$ and $(\uu_h,  \BB_h) \in \ZZd \times \WWd$ be the solutions of \eqref{eq:linear variazionale} and \eqref{eq:linear fem} respectively. 
It holds that
\[
\normastab{\uu - \uu_h} + \normam{\BB - \BB_h}
\lesssim
\Xi_\mathcal{I}
+
\Xi_h \, ,
\]
where the two error quantities are defined as
\[
\Xi_{\mathcal I} := \normastab{\eei} + \normam{\EEi} \, ,
\]
and
\[
\Xi_h :=
\sup_{(\ww_h,\mathbf{K}_h) \in \ZZd \times \WWd} \dfrac{\astab(\uu, \BB, \ww_h, \mathbf{K}_h) -
\astab(\uui, \BBi, \ww_h, \mathbf{K}_h) }{\normastab{\ww_h} + \normam{\mathbf{K}_h}} \, .
\]
\end{proposition}
%%
\begin{proof}
Using triangular inequality, we have that
\[
\normastab{\uu - \uu_h} + \normam{\BB - \BB_h}
\leq
\normastab{\eei} + \normam{\EEi}
+
\normastab{\eeh} + \normam{\EEh} \, .
\]
Applying Theorem \ref{th:cip-inf-sup} and the consistency property \eqref{eq:consistency}, we obtain
\[
\begin{aligned}
\normastab{\eeh} + \normam{\EEh}
&\lesssim
\sup_{(\ww_h,\mathbf{K}_h) \in \ZZd \times \WWd} \dfrac{\astab(\eeh, \EEh, \ww_h, \mathbf{K}_h)}{\normastab{\ww_h} + \normam{\mathbf{K}_h}} \\
&\lesssim
\sup_{(\ww_h,\mathbf{K}_h) \in \ZZd \times \WWd} \dfrac{\astab(\uu_h, \BB_h, \ww_h, \mathbf{K}_h) -
\astab(\uui, \BBi, \ww_h, \mathbf{K}_h) }{\normastab{\ww_h} + \normam{\mathbf{K}_h}} \\
&\lesssim
\sup_{(\ww_h,\mathbf{K}_h) \in \ZZd \times \WWd} \dfrac{\astab(\uu, \BB, \ww_h, \mathbf{K}_h) -
\astab(\uui, \BBi, \ww_h, \mathbf{K}_h) }{\normastab{\ww_h} + \normam{\mathbf{K}_h}} \, .
\end{aligned}
\]
The proof is concluded by recalling the definitions of $\Xi_\mathcal I$ and $\Xi_h$.
\end{proof}

To properly estimate the rate of convergence of our method, we make the following stronger assumptions. Note that we allow for magnetic fields not in $H^1(\Omega)$, since we are considering also non-convex lipschitz domains.

\smallskip
\noindent
\textbf{(RA2) Regularity assumptions on the exact solution (error analysis):} 

\noindent
Assume that:
\begin{itemize}
\item the velocity field satisfies
$\uu \in \HH^{\regu}(\Omega_h)$ 
for some $\frac{3}{2} < \regu \leq k+1,$
\item the magnetic field satisfies
$\BB \in \HH^{\regb}(\bcurl,\Omega_h)$ 
for some $\frac{1}{2} < \regb \leq k+1.$ 
\end{itemize}


\begin{lemma}[Interpolation error]
Let Assumption \textbf{(MA1)} hold.
Furthermore, if $k=1$ let also Assumption \textbf{(MA2)} hold. Then, under the regularity assumption \textbf{(RA2)}, it holds that
\[
\Xi_\mathcal I^2 \lesssim
\ls^2 \, h^{2\regu-2} \vert \uu \vert_{\regu, \Omega_h}^2
+
\psm h^{2\regb}   |\BB|^2_{\HH^\regb(\bcurl,\Omega_h)} 
+
\ns h^{2\tilde \regb}|\bcurl(\BB)|^2_{\tilde\regb,\Omega_h}\, ,
\]
%
where $\tilde \regb := \min \{ r,k \}$, see Lemma \ref{lm:int-w}. 
%
\end{lemma}
%
\begin{proof}
We recall that
\[
\Xi_\mathcal I = \normastab{\eei} + \normam{\EEi} \, .
\]
Exploiting the definition of $\normastab{\cdot}$ and following the same steps of \cite{BDV:2024}, we have that
\begin{align}
\label{eq:eiS}
\normas{\eei}^2 
& \lesssim
(\pss h^2 + \ns(1 + \bdma)) h^{2\regu-2} \vert \uu \vert_{\regu, \Omega_h}^2 \lesssim \ls^2 h^{2\regu-2} \vert \uu \vert_{\regu, \Omega_h}^2\,,
\\
\label{eq:eiupw}
\normaupw{\eei}^2 
& \lesssim
\bdmc \max_{f \in \EdgesI} \Vert \cc \cdot \nn_f \Vert_{\boldsymbol{L}^\infty(f)}
h^{2\regu-1} \vert \uu\vert_{\regu, \Omega_h}^2 \lesssim \ls^2 h^{2\regu-2} \vert \uu \vert_{\regu, \Omega_h}^2\, .
\end{align}
For the jump term in the norm, we have that
\[
\normacip{\eei}^2 =
\bdmJ\sum_{f \in \Edges}  \Vert \jump{\TT \times \eei}_f \Vert_{f}^2
+
\bdmJJ\sum_{f \in \EdgesI}  h_f^2 \Vert \jump{\bcurl_h(\eei\times \TT_h)}_f \Vert_{f}^2 \, .
\]
For the first term, using trace inequality and Lemma \ref{lm:int-w}, we obtain that
\begin{equation}\label{eq:eiJ1}
\begin{aligned}
\bdmJ \sum_{f \in \Edges} 
\|\jump{\TT \times \eei}_f \|^2_f  
&\lesssim
\bdmJ \sum_{f \in \Edges} \| \TT \|_{\boldsymbol{L}^\infty(f^\pm)}^2 \| \eei \|^2_f \\
&\lesssim
\bdmJ \sum_{f \in \Edges} \| \TT \|_{\boldsymbol{L}^\infty(f^\pm)}^2 \bigl(h_E^{-1}\| \eei \|^2_E + h_E| \eei |^2_{1,E} \bigr) \\
&\lesssim \bdmJ \max_{f \in \Edges}\| \TT \|_{\boldsymbol{L}^\infty(f^\pm)}^2 h^{2\regu-1} | \uu|^2_{\regu,\Omega_h} \lesssim \ls^2 h^{2\regu-2} | \uu|^2_{\regu,\Omega_h}\, .
\end{aligned}
\end{equation}
Similarly, on the other term, using \eqref{eq:curl-identity} together with the fact that $\TT_h$ is piecewise constant and $\diver (\eei)=0$, we obtain 
\begin{equation}\label{eq:eiJ2}
\begin{aligned}
\bdmJJ \sum_{f \in \EdgesI} 
h_f^2 \|\jump{\bcurl_h (\eei \times \TT_h)}_f\|^2
&\lesssim
\bdmJJ \sum_{f \in \EdgesI} h_f^2 \| \TT_h \|^2_{\boldsymbol{L}^{\infty}(f^\pm)} \| \nabla \eei \|^2_{\boldsymbol{L}^2(f^\pm)}
\lesssim
\ls^2 h^{2\regu-2}| \uu|^2_{\regu,\Omega_h} \, .   
\end{aligned}
\end{equation}
Combining \eqref{eq:eiJ1} and \eqref{eq:eiJ2}, we have
\[
\normacip{\eei}^2 \lesssim \ls^2 h^{2\regu-2} | \uu |_{\regu,\Omega_h}^2 \, .
\]
For $\normacurl{\eei}$, recalling \eqref{eq:curl-identity}, we have that
\[
\begin{aligned}
\normacurl{\eei}^2 &=
\gamma^{-1} \, \sum_{E \in \Omega_h} h_E^2 \, \| \bcurl_h(\eei \times \TT_h) \|^2_{E}
\lesssim
\gamma^{-1} \, \sum_{E \in \Omega_h} h_E^2 \| \TT \|_{L^{\infty}(\Omega_h)}^2 \| \nabla \eei \|^2_{E}\\
&\lesssim
h^{2\regu-1} \| \TT \|^2_{\boldsymbol{L}^\infty(\Omega_h)} | \uu |^2_{\regu,\Omega_h} \lesssim \ls^2 h^{2\regu-2} |\uu|_{\regu,\Omega_h}^2 \, .
\end{aligned}
\]
For the magnetic field, we have to use the interpolation estimate of Lemma \ref{lm:int-w}. It holds that
\[
\begin{aligned}
\normam{\EEi}^2  &\lesssim \sum_{E \in \Omega_h} \psm h^{2\regb}_E  |\BB|^2_{\HH^\regb(\bcurl,E)} 
+
\sum_{E \in \Omega_h}\nm h_E^{2\tilde \regb}|\bcurl(\BB)|^2_{\tilde\regb,E} \\
&\lesssim  \psm h^{2\regb}  |\BB|^2_{\HH^\regb(\bcurl,\Omega_h)} 
+
\nm h^{2\tilde \regb}|\bcurl(\BB)|^2_{\tilde\regb,\Omega_h}\, .
\end{aligned}
\]
\end{proof}

\begin{lemma}\label{lm:eh estimate} Let Assumption \textbf{(MA1)} hold.
Furthermore, if $k=1$ let also Assumption \textbf{(MA2)} hold. Then, under the regularity assumption  \textbf{(RA2)}. It holds that
\[
\begin{aligned}
\Xi_h^2
&\lesssim
(\ls^2 + \gs^2 + \gm^2) h^{2\regu-2} \vert \uu\vert^2_{\regu, \Omega_h}
 +
 \ns h^{2\tilde \regb}|\bcurl(\BB)|^2_{\tilde\regb,\Omega_h} \\
 & \quad +
(\psm h^{2\regb} + (\gs^2+\gm^2 +1 )
h^{2\regb-1} 
) \bigl |\BB|_{\HH^{\regb}(\bcurl,\Omega_h)}^2 
\, ,
\end{aligned}
\]
where
\begin{equation}
\label{eq:gamma}
\begin{aligned}
% \gs^2 &:= \min\{ \pss^{-1} h^2,  \, \ns^{-1} h^4, \, \pss^{-1} h^4\} \Vert\cc\Vert_{\WW^1_\infty(\Omega_h)}^2 + \pss^{-1} h\Vert\TT\Vert_{\WW^1_\infty(\Omega_h)}^2\, ,\\
\gs^2 &:= \min\{ \pss^{-1} h^2,  \, \max\{\pss^{-1},\ns^{-1}\}h^4\} \Vert\cc\Vert_{\WW^1_\infty(\Omega_h)}^2 + \pss^{-1} h\Vert\TT\Vert_{\WW^1_\infty(\Omega_h)}^2\, ,\\
\gm^2 &:=
\min\{ \psm^{-1} h^2,  \, \nm^{-1} h^4 \} 
\Vert\TT\Vert_{\WW^1_\infty(\Omega_h)}^2 + \gamma h^{-1} \,.
\end{aligned}
\end{equation}
