\begin{proof}
We recall that by definition
\[
\begin{aligned}
\astab(\uu, \BB, \ww_h, \mathbf{K}_h) &-
\astab(\uui, \BBi, \ww_h, \mathbf{K}_h)\\
&\qquad=
\bigl( \pss (\eei, \ww_h) + \ns \ash(\eei, \ww_h) \bigr)
+
\bigl(\psm (\EEi, \mathbf{K}_h) + \nm \am(\EEi, \mathbf{K}_h)  \bigr) 
\\  
& \qquad
+ c_h(\eei, \ww_h) -d(\EEi, \ww_h)   + d(\mathbf{K}_h, \eei) + J_h(\eei, \ww_h) 
=: \sum_{i=1}^6 \alpha_i \,.
\end{aligned}
\]
We need to estimate each of these six terms. Some of these terms are estimated similarly to \cite{BDV:2024}, so we only state the result.

\noindent
$\bullet$ Estimate of $\alpha_1$ and $\alpha_3$: using the same calculations of \cite{BDV:2024}, we have that
\begin{align}
\label{eq:alpha13-f}
\alpha_1 
\lesssim \ls \, h^{\regu-1} \vert \uu \vert_{\regu, \Omega_h} \normastab{\ww_h}
\, , \qquad
\alpha_3 \lesssim
(\ls + \gs) h^{\regu-1} \vert \uu\vert_{\regu, \Omega_h} 
\normastab{\ww_h} \,.
\end{align}
%
% {\color{blue}Carlo: si tiene traccia di $\mu_a$ ma non di $\mu_c$? Inoltre, non mi torna $\alpha_3$.}
%

\noindent
$\bullet$ Estimate of $\alpha_2$: Using the interpolation estimate of Lemma \ref{lm:int-w}, we have that
\begin{equation}
\begin{aligned}
\bigl(\psm (\EEi, \mathbf{K}_h) + \nm \am(\EEi, \mathbf{K}_h)  \bigr)  
&\leq 
\psm \| \EEi \| \|\mathbf{K}_h\| 
+
\nm \| \bcurl(\EEi) \| \, \|\bcurl(\mathbf{K}_h)\| \\
&\lesssim
\bigl(\psm^\frac{1}{2} h^{\regb} \bigl |\BB|_{\HH^{\regb}(\bcurl,\Omega_h)} 
+
\nm^\frac{1}{2} h^{\tilde \regb}  |\bcurl(\BB)|_{\tilde \regb,\Omega_h} \bigr)\normam{\mathbf{K}_h}
\, .
\end{aligned}
\end{equation}
\noindent
$\bullet$ Estimate of $\alpha_4$: 
Following \cite{BDV:2024}, it holds that by integration by parts
\begin{equation}
\label{eq:alpha-4}
\begin{aligned}
\alpha_4 & = 
(\EEi , \bcurl_h (\ww_h  \times (\TT - \TT_h))) +
(\EEi , \bcurl_h (\ww_h  \times \TT_h)) +
\\
& +
\sum_{f \in \Edges}
(\EEi \times \nn_f , \jump{\ww_h  \times \TT})_f 
=: \sum_{j=1}^3 \alpha_{4,j} \, .
\end{aligned}
\end{equation}
For the first term, mimicking the steps of \cite{BDV:2024} we have that
\begin{equation}
\label{eq:alpha4-1}
\begin{aligned}
\alpha_{4,1}
\lesssim
\gs
h^{\regb-\frac{1}{2}} \vert \BB \vert_{\HH^{\regb}(\bcurl,\Omega_h)} 
\normas{\ww_h} \, .
\end{aligned}
\end{equation}
%%
Thanks to the definition of $\normacurl{\cdot}$, we obtain
\[
\begin{aligned}
\alpha_{4,2} = ( \EEi \,, \bcurl_h (\ww_h  \times \TT_h) )
&\lesssim
\left( \sum_{E \in \Omega_h} h_E^{-2} \| \EEi\|^2_E\right)^\frac12
\left( \sum_{E \in \Omega_h} h_E^{2} \| \bcurl_h (\ww_h  \times \TT_h)\|^2_E\right)^\frac12 \\
&\lesssim
\gamma^\frac12 \left( \sum_{E \in \Omega_h} h_E^{-2} \| \EEi\|^2_E\right)^\frac12
\normacurl{\ww_h} \\
& \lesssim \gamma^{\frac{1}{2}} h^{\regb-1} | \BB|_{\HH^r(\bcurl,\Omega_h)}\normacurl{\ww_h} \\
&\lesssim {\gm} h^{\regb-\frac12} | \BB |_{\HH^{\regb}(\bcurl,\Omega_h)} \normacurl{\ww_h} \, .
\end{aligned}
\]
%%
Finally,
\begin{equation}
\label{eq:alpha4-3}
\begin{aligned}
\alpha_{4,3} & \leq
\biggl(\bdmJ^{-1} \sum_{f \in \Edges}
\Vert \EEi \Vert_{f}^2 \biggr)^{1/2} \normacip{\ww_h}
 \lesssim
\biggl(\bdmJ^{-1} \sum_{E \in \Omega_h}
(h_E^{-1} \Vert \EEi \Vert_{E}^2 + 
h_E^{2\hat\regb-1} \vert \EEi \vert_{\hat\regb,E}^2) \biggr)^{1/2} \normacip{\ww_h}
\\
& \lesssim
h^{\regb-\frac{1}{2}} |\BB|_{\HH^\regb(\bcurl,\Omega_h)} \normacip{\ww_h}
\lesssim
h^{\regb-\frac{1}{2}} \vert \BB \vert_{\HH^\regb(\bcurl,\Omega_h)}
\normacip{\ww_h}
\end{aligned}
\end{equation}
where $\hat\regb := \min\{\regb,1\}$.
%%

\noindent
$\bullet$ Estimate of $\alpha_5$: Exploiting the orthogonality property of the interpolation operator, and standard approximation results, we obtain
\begin{equation}
\label{eq:alpha5-f}
\begin{aligned}
\alpha_5 & = 
(\bcurl (\mathbf K_h) \times \TT \,, \eei )
= (\bcurl (\mathbf K_h) \times (\TT-\TT_h) \,, \eei  )
\\
& \leq \sum_{E \in \Omega_h}
\Vert \TT - \TT_h \Vert_{\boldsymbol{L}^\infty(E)}
\Vert \bcurl (\mathbf K_h) \Vert_{E} 
\Vert \eei \Vert_{E}
\\
& \lesssim \sum_{E \in \Omega_h}
h_E \Vert \TT \Vert_{\WW^1_\infty(E)}
\Vert \bcurl (\mathbf K_h) \Vert_{E} 
\Vert \eei \Vert_{E}
\\
& \lesssim 
\Vert \TT \Vert_{\WW^1_\infty(\Omega_h)}
\Vert \eei \Vert
\biggl(\sum_{E \in \Omega_h}
h_E^2 
\Vert \bcurl (\mathbf K_h) \Vert_{E}^2 \biggr)^{1/2} 
\\
& \lesssim 
\min \{ \psm^{-1/2},  \nm^{-1/2} h\} 
\Vert \TT \Vert_{\WW^1_\infty(\Omega_h)}
h^{\regu} \vert \uu \vert_{\regu, \Omega_h}
\normam{\mathbf K_h} 
\\
& \lesssim 
\gm h^{\regu-1} \vert \uu \vert_{\regu, \Omega_h}
\normam{\mathbf K_h} \, .
\end{aligned}
\end{equation}

\noindent
$\bullet$ Estimate of $\alpha_6$: 
By definition, we have that
\[
\begin{aligned}
\alpha_6 &= \sum_{f \in \Edges} \bigl( \bdmJ 
( \jump{\TT \times \eei}_f , \jump{\TT \times \ww_h}_f \bigr)_f \\
& \qquad +
\bdmJJ h_f^2 
\bigl(\jump{\bcurl_h (\eei \times \TT)}_f  ,\jump{\bcurl_h (\ww_h \times \TT)}_f 
\bigr)_f =: \sum_{j=1}^2 \alpha_{6,j} \, .
\end{aligned}
\]
On the first one, using \eqref{eq:eiJ1}, we have that
\[
\begin{aligned}
\alpha_{6,1}
&=
\bdmJ\sum_{f \in \Edges} \bigl( \jump{\TT \times \eei}_f , \jump{\TT \times \ww_h}_f \bigr)_f \lesssim
\normacip{\eei} \normacip{\ww_h} \lesssim
\ls h^{\regu-1} |\uu|_{\regu,\Omega_h}\normastab{\ww_h} \, .
\end{aligned}
\]
Using the Cauchy-Schwarz and triangular inequalities, estimates in the same spirit of \eqref{eq:tt-tth}, and bound \eqref{eq:eiJ2}, we obtain (without showing all the details)
\[
\begin{aligned}
\alpha_{6,2}
&\leq
\bdmJJ \sum_{f \in \EdgesI} 
h_f^2 \bigl(\jump{\bcurl_h (\eei \times \TT)}_f  ,\jump{\bcurl_h (\ww_h \times \TT)}_f 
\bigr)_f \\
& \lesssim
\left(\bdmJJ \sum_{f \in \EdgesI} 
h_f^2 \bigl(\|\jump{\bcurl_h (\eei \times (\TT-\TT_h))} \|^2_f + \|\jump{\bcurl_h (\eei \times \TT_h)} \|^2_f\bigr) \right)^{\frac{1}{2}}\normastab{\ww_h} \\
& \lesssim
\left(\normacip{\eei}^2 
+ \sum_{E \in \Omega_h} \| \TT \|_{\WW^1_\infty(E)}^2  
\big( h_E \|\eei\|^2_E + h_E^{2\regu+1} |  \eei |^2_{\regu,E} \big)
\right)^{\frac{1}{2}}\normastab{\ww_h}\\
&\lesssim
\ls h^{\regu-1} |\uu|_{\regu,\Omega_h}\normastab{\ww_h} \, .
\end{aligned}
\]
%
Note that, differently from \eqref{eq:tt-tth} and since $\eei$ is not a discrete function, here above we applied a scaled trace inequality from $\HH^1(f)$ to $\HH^s(E)$, with $f$ face of element $E$ (we recall $s>3/2$ by assumption), instead of an inverse inequality. \\
%{\color{magenta} [LORE: c'era qua una giusta osservazione di Carlo, che ho implementato. Vedi parte blu di testo qua sopra e modifica nella equazione.]}
%
\end{proof}
Collecting the previous result we obtain the final estimate.
\begin{theorem}\label{thm:convergence}
Let Assumption \textbf{(MA1)} hold. Furthermore, if $k=1$ let also Assumption \textbf{(MA2)} be valid. Then, under the regularity assumption  \textbf{(RA2)} it holds
\[
\begin{aligned}
\normastab{\uu - \uu_h}^2 + \normam{\BB - \BB_h}^2
&\lesssim
(\ls^2 + \gs^2 + \gm^2) h^{2\regu-2} \vert \uu\vert^2_{\regu, \Omega_h}
 +
 \ns h^{2\tilde \regb}|\bcurl(\BB)|^2_{\tilde\regb,\Omega_h} \\
 & \quad +
(\psm h^{2\regb} + (\gs^2+\gm^2+1 )
h^{2\regb-1}
) \bigl |\BB|_{\HH^{\regb}(\bcurl,\Omega_h)}^2 
\, .
\end{aligned}
\]
\end{theorem}

We now study the error on the pressure variable. We first recall that, exploiting the inf-sup condition for the $\boldsymbol{{\rm BDM}}$ elements and the Poincarè inequality, there exists $\ww_h \in \VVd$ such that
\begin{equation}
\label{eq:p-infsup}
\Vert \ww_h \Vert_{1,h} \lesssim 1 \,, 
\qquad \text{and} \qquad
\Vert p_h - \Pi_{k-1} p\Vert 
\lesssim b(\ww_h \,, p_h - \Pi_{k-1} p) \,.
\end{equation}
where the discrete norm is defined by:
$$
\Vert \ww_h \Vert_{1,h}^2 := \sum_{E \in \Omega_h} \Vert \ww_h \Vert_{1,E} 
+ \sum_{f \in \Edges}  h_f^{-1} \Vert \jump{\ww_h}_f \Vert_{f}^2 \, .
$$
%%
Furthermore, thank to the inclusion $\diver(\VVd) \subseteq \mathbb P_{k-1}(\Omega_h)$, it also holds
\begin{equation}
\label{eq:p-orth}
b(\vv_h \,, p) =
b(\vv_h \,, \Pi_{k-1} p)
\qquad 
\text{for all $\vv_h \in \VVd$.}
\end{equation}
%
We are now ready to prove the following error estimates.
%
\begin{theorem}[Error estimates for the pressure]
\label{thm:conv pre}
Under the same assumptions as in Theorem~\ref{thm:convergence}, we have that
\begin{equation}\label{p-est-first}
\begin{aligned}
\Vert p - p_h \Vert
&\lesssim 
(\ts + \ls + \Vert \cc \Vert_{\boldsymbol{L}^\infty(\Omega)} \pss^{-1/2} )
 %\bdma^{-1/2}) 
\normastab{\uu - \uu_h}   +
\nm^{-\frac{1}{2}} \normam{\BB - \BB_h}
+ 
h^k \, \vert p \vert_{k, \Omega_h} \, , 
\end{aligned}
\end{equation}
where $\ts^2 := \max\{\ns, \pss\}.$
%
Furthermore, assuming that
\begin{equation}\label{eq:jump-assumption}
% h_f^{-\frac{1}{2}} \media{\ww_h}_f \times \jump{\TT}_f \lesssim 1 \quad\mbox{for every face},
\Vert \jump{\TT} \Vert_{\boldsymbol{L}^\infty(f)}\lesssim h_f \Vert \TT \Vert_{\WW^1_\infty(\omega_f)} \quad \forall f \in \Edges \, ,
\end{equation}
with $\omega_f$ denoting the union of the elements sharing the face $f$, the following improved estimate (avoiding the term $\nm^{-\frac{1}{2}}$) holds true:
\begin{equation}\label{p-est-second}    
\begin{aligned}
\Vert p - p_h \Vert
&\lesssim 
(\ts + \ls + \Vert \cc \Vert_{\boldsymbol{L}^\infty(\Omega)} \pss^{-1/2} )
%(1 + \bdma^{-1/2}) 
\normastab{\uu - \uu_h} + h^k \, \vert p \vert_{k, \Omega_h} 
% {\color{magenta} \Vert \TT \Vert_{\WW^1_\infty(\Omega_h)} \psm^{-1/2} %(1 + \bdma^{-1/2})
% \normam{\BB - \BB_h}}
% + 
 \\
& 
 + \Vert \TT \Vert_{\WW^1_\infty(\Omega_h)} \big( \psm^{-1/2}\normam{\BB - \BB_h} + h^{r} \Vert \BB \Vert_{\HH^{r}(\bcurl,\Omega)} \big)  \, .
\end{aligned}
\end{equation}
