\begin{proof}
We only sketch the proof since it follows standard arguments in this type of problems and analogous steps with respect to \cite{BDV:2021}. We first recall that from Lemma \ref{lm:bramble} it holds
\begin{equation}\label{eq:proj-err}
\| p - \Pi_{k-1} p \|
\lesssim
h^{k} | p |_{k,\Omega_h} \, .
\end{equation}
%
Exploiting estimates \eqref{eq:p-infsup} and equation \eqref{eq:p-orth} in Problems \eqref{eq:linear variazionale} and \eqref{eq:linear fem}, we obtain
\begin{equation}
\label{eq:p-error}
\begin{aligned}
\Vert p_h -  \Pi_{k-1} p\Vert  &
\lesssim
b(\ww_h \,, p_h - \Pi_{k-1} p)
=
b(\ww_h \,, p_h - p)
\\
& =
\bigl( \pss(\uu - \uu_h, \ww_h) + \ns \ash(\uu - \uu_h, \ww_h) \bigr)+
c_h(\uu - \uu_h, \ww_h) + \\  
&
-d(\BB - \BB_h, \ww_h)    + J_h(\uu - \uu_h, \ww_h)
 =: \sum_{i=1}^4 \beta_i \,.
\end{aligned}
\end{equation}
Following Lemma \ref{lm:eh estimate} and \cite{BDV:2024}, we infer
\begin{equation}
\label{eq:beta}
\begin{aligned}
\beta_1 & \lesssim \ts %(1 + \bdma^{-1/2}) 
\normastab{\uu - \uu_h} \,,
\\
\beta_2 & \lesssim (\ls 
%\bdma^{-1/2} 
+ 
\Vert \cc \Vert_{\boldsymbol{L}^\infty(\Omega)} \pss^{-1/2}
%(1 + \bdma^{-1/2})) 
)\normastab{\uu - \uu_h} \,,
%\\
%\beta_3 & \lesssim 
%\Vert \TT \Vert_{\WW^1_\infty(\Omega_h)} \psm^{-1/2} \normam{\BB - \BB_h} + {\color{red}??} \,,
\\
\beta_4 & \lesssim 
\ls
%(1 + \bdma^{-1/2}) 
\normastab{\uu - \uu_h} \, .
\end{aligned}
\end{equation}
The term $\beta_3$ can be directly estimated as
\begin{equation}\label{eq:beta3_plain}
\beta_3 
= 
( \bcurl ((\BB-\BB_h)) \times \TT ,\, \ww_h)_\Omega
\lesssim
\nm^{-\frac{1}{2}} \normam{\BB - \BB_h} \, .
\end{equation}
Therefore, estimate \eqref{p-est-first} follows from \eqref{eq:proj-err}, \eqref{eq:p-error}, \eqref{eq:beta} and \eqref{eq:beta3_plain}.
%
% In this approach, the magnetic diffusion is accounted for in the estimate without a scaling in $h$. 
%
To prove estimate \eqref{p-est-second}, we treat the term $\beta_3$ in a different way, as we show briefly here below. We start by noting that
%
\begin{equation}\label{jump-ave}
\jump{\ww_h \times \TT}_f
=
\jump{\ww_h}_f \times \media{\TT}_f
+
\media{\ww_h}_f \times \jump{\TT}_f \, .
\end{equation}
%
After integrating by parts and applying \eqref{jump-ave} we obtain 
%%
$$
\begin{aligned}
\beta_3 & = \sum_{E \in \Omega_h} (\BB-\BB_h, \, \bcurl(\ww_h \times \TT))_E  
+ \sum_{f \in \Edges} ((\BB-\BB_h)\times \nn_f, \, \jump{\ww_h}_f \times \media{\TT}_f)_f \\
& + \sum_{f \in \Edges} ((\BB-\BB_h)\times \nn_f, \, \media{\ww_h}_f \times \jump{\TT}_f)_f 
=: \sum_{i=1}^3 \beta_{3,i} \, .
\end{aligned}
$$
We estimate the three terms above using H\"older and trace inequalities. The first two addenda are handled easily, using $\TT \in \WW^1_\infty(\Omega_h)$ and $\Vert \ww_h \Vert_{1,h} \lesssim 1$ (thus we avoid showing the details). The third term is bounded by 
$$
\beta_{3,3} \leq \sum_{f \in \Edges} h_f^{1/2} \Vert \BB-\BB_h \Vert_{\boldsymbol{L}^2(f^\pm)} h_f^{1/2}
\Vert \ww_h \Vert_{\boldsymbol{L}^2(f^\pm)} h_f^{-1} \Vert \jump{\TT} \Vert_{\boldsymbol{L}^\infty(f)} \, ,
$$
which by trace inequalities, using \eqref{eq:jump-assumption} and again $\Vert \ww_h \Vert_{1,h} \lesssim 1$ yields
$$
\beta_{3,3} \lesssim \Vert \TT \Vert_{\WW^1_\infty(\Omega_h)} \left( 
\sum_{E \in \Omega_h} \Vert \BB-\BB_h \Vert_E + h_E^2 | \BB-\BB_h |_{1,E}^2
\right)^{1/2} \, .
$$
We bound the term here above by first adding and subtracting $\BBi$, then using a triangle inequality, finally applying approximation estimates for $\BB - \BBi$ and inverse inequalities for $\BBi - \BB_h$. Such calculations lead to 
$$
\begin{aligned}
\beta_{3,3} 
&\lesssim 
\Vert \TT \Vert_{\WW^1_\infty(\Omega_h)} 
\big(  \|\BBi - \BB_h\| + h^r \Vert \BB \Vert_{\HH^r(\bcurl,\Omega)} \big) \\
& \lesssim
\Vert \TT \Vert_{\WW^1_\infty(\Omega_h)} 
\big(  \|\BB - \BB_h\|
+
\|\BB - \BBi\| + h^r \Vert \BB \Vert_{\HH^r(\bcurl,\Omega)} \big) \\
& \lesssim
\Vert \TT \Vert_{\WW^1_\infty(\Omega_h)} 
\big(  \psm^{-\frac{1}{2}}\normam{\BB - \BB_h}+ h^r \Vert \BB \Vert_{\HH^r(\bcurl,\Omega)} \big)  \, .
\end{aligned}
$$
% \begin{equation}\label{eq:beta3_jump}
% \beta_3  \lesssim 
% \Vert \TT \Vert_{\WW^1_\infty(\Omega_h)} \psm^{-1/2}(1 + \bdma^{-1/2}) \normam{\BB - \BB_h} \, . 
% \end{equation}
%
Estimate \eqref{p-est-second} now follows from \eqref{eq:proj-err}, \eqref{eq:p-error}, \eqref{eq:beta} and the above bounds for $\beta_3$.

