:=
\begin{bmatrix}
\sin(\pi x) \cos(\pi y) \cos(\pi z)\\
\cos(\pi x) \sin(\pi y) \cos(\pi z)\\
-2 \cos(\pi x) \cos(\pi y) \sin(\pi z)
\end{bmatrix} ,
\qquad
\BB(x,y,z) 
:=
\begin{bmatrix}
\sin(\pi y) \\
\sin(\pi z) \\
\sin(\pi x)
