\subsubsection{Local Finite Element Spaces}
\noindent Let $\mathbb{Q}_1(\hat{\mathcal{Q}})$ denote the piecewise-linear Lagrange finite element space defined over the reference element $\hat{\mathcal{Q}}$. Then, we define
the local finite element space over an arbitrary element $\mathcal{Q}$ in the physical subdomain $\Omega_{int}$ as
\begin{align*}
V_h^{int}(\mathcal{Q})&= \{ v : v= \hat{v}\circ \bar{F}_\mathcal{Q}^{-1}, \hat{v}\in \mathbb{Q}_1(\hat{\mathcal{Q}}) \}, \end{align*}
with the standard nodal degrees of freedom:
\begin{equation*}
S_{V_h^{int}}= \{v(a_i): a_i\in \mathcal{Q},\ 1\le i\le 8\}.
\end{equation*}

\noindent Let $V_h^b(\hat{\mathcal{Q}})$ denote the NURBS-enhanced finite element space defined over the reference element $\hat{\mathcal{Q}}$ using the basis functions listed in \eqref{eq:basis-hybrid-R-transformed}. 
\noindent Thus,  
\begin{align}
    V_h^b(\hat{\mathcal{Q}}):=span\{\tilde{N}_i: 1\le i\le n_{cp}+4\}
\end{align}
with the degrees of freedom 
\begin{align*}
S_{\hat{V}_{h}^b}&=\{\hat{v}(\hat{a}_{\textbf{i}}): \hat{a}_{\textbf{i}}\in \hat{\mathcal{Q}},\  \text{where}\
\hat{a}_i=(\hat{a}_{\textbf{i}}^1,\hat{a}_{\textbf{i}}^2, 1)\ 
\text{for}\  (n_{cp}+1)\le i\le (n_{cp} +4),\  \hat{a}_i=(\gamma_{\textbf{i}}^1,\gamma_{\textbf{i}}^2,0)\\ &
\text{for}\  1\le i\le n_{cp}\ \text{and}\
\gamma_{\textbf{i}}\in \mathcal{G}_h\},
\end{align*}
\noindent where the tuples $\{(\hat{a}_{\textbf{i}}^1,\hat{a}_{\textbf{i}}^2)\}$ denote the coordinates of the $\mathbb{Q}_1$ finite element nodes over $[0,1]^2$  and
$\mathcal{G}_h$ indicates the Greville mesh associated with the face of $\hat{\mathcal{Q}}$ that serves as the reference domain of the NURBS face of $\mathcal{Q}\in \mathcal{T}_h^b$ Figure~\ref{fig:dofs} illustrates the degrees of freedom in the reference and physical domains. For illustrative purposes, the parametric domain of the NURBS face is shown at $\zeta=1$ (instead of $\zeta=0$ as in the formulations).
\begin{lemma}\label{lem:unisolvency}
$S_{\hat{V}_h^b}$ unisolves $V_h^b(\hat{\mathcal{Q}})$. 
\end{lemma}

\begin{proof}
First, note that the dimension of $V_h^b(\hat{\mathcal{Q}})$ equals the cardinality of $S_{\hat{V}_h^b}$. Then, let $\hat{v}\in V_h^b(\hat{\mathcal{Q}})$, thus, write $\hat{v}(\hat{x})=\sum\limits_{i=1}^{n_{cp}+4} l_i \tilde{N}_i(\hat{x})$. Now, suppose that $\hat{v}(\hat{a}_j)=0$ for $\forall j\in \{1,\dots, n_{cp}+4\}$.
Since $\tilde{N}_i(a_j)=\delta_{ij}$, this yields
\begin{align*}
    \hat{v}(\hat{a}_j)&= \sum\limits_{i=1}^{n_{cp}+4} l_i \tilde{N}_i(\hat{a}_j)=l_j=0, \quad \forall j\in \{1,2,\dots,n_{cp}+4\}.
\end{align*}
Thus, $\hat{v}=0$ on $\hat{\mathcal{Q}}$.
\end{proof}

\noindent Then, we define the local NURBS-enhanced finite element space over an arbitray element $\mathcal{Q}$ in the physical subdomain $\Omega_{\mathcal{B}}$ as follows:
\begin{align*}
V_h^{b}(\mathcal{Q})&= \{ v: v= \hat{v}\circ \tilde{F}_\mathcal{Q}^{-1}, \hat{v}\in V_h^{b}(\hat{\mathcal{Q}}) \}. 
\end{align*}
\noindent Let $S_{V_{h}^b}$ be the set of degrees of freedom that correspond to the degrees of freedom listed in $S_{\hat{V}_{h}^b}$ in the physical domain. 
The invertibility of $\tilde{F}_\mathcal{Q}$ and the unisolvency of $S_{\hat{V}_{h}^b}$ implies that $S_{V_{h}^b}$ unisolves $V_h^{b}(\mathcal{Q})$.
\begin{remark}
    \noindent Since $\tilde{F}_\mathcal{Q}$ is not arbitrarily regular, a function in $H^s(\hat{\mathcal{\mathcal{Q}}})$ may not be mapped to a function in $H^s(\mathcal{\mathcal{Q}})$ under $\tilde{F}_\mathcal{Q}$, that is, having $V_h^b(\hat{\mathcal{Q}})\subset H^1(\hat{\mathcal{Q}})$ would not necessarily yield an $H^1$ space in the physical domain. 
    However, since $\tilde{F}_\mathcal{Q}$ is sufficiently regular due to our assumptions on $S$ and $S^{-1}$ in Section~\ref{sec:transforms}, we can assume that $V_h^b(\mathcal{Q})\subset H^1(\mathcal{Q})$. Furthermore, since we assume that the splines are at least continuous, below we can define $V_h^b$ such that $V_h^b\subset H^1(\Omega_{\mathcal{B}})$.
\end{remark}
\subsubsection{Global Finite Element Space}
We define the global finite element space for $\Omega_{int}$ as follows: \begin{align*}
V_h^{int}&= \{ v \in H^1(\Omega_{int}): v|_{\mathcal{Q}}\in V_h^{int}(\mathcal{Q}),\ v\ \text{is continuous at}\\ & \text{all vertices}\ a_i\ \text{in}\ \mathcal{T}_h^{(i)},\ \forall \mathcal{Q}\in \mathcal{T}_h^{(i)} \}, \end{align*}
\noindent Then, we define the global finite element space for $\Omega_{\mathcal{B}}$ as: \begin{align*}\label{eq:global-fespace}
V_h^{b}&= \{ v \in H^1(\Omega_{\mathcal{B}}): v|_{\mathcal{Q}}\in V_h^b(\mathcal{Q}),\ v\ \text{is continuous at}\\ & \text{the interior nodes}\ a_i\ \text{in}\ \mathcal{T}_h^{(b)},\ \forall \mathcal{Q}\in \mathcal{T}_h^{(b)}\}, 
\end{align*}
Thus, the global function space over $\Omega$ becomes:
\begin{equation}\label{eq:global-fespace}
    V_h:=\{v\in H^1(\Omega): v|_{\Omega_{int}}\in V_h^{int}, v|_{\Omega_{\mathcal{B}}}\in V_h^b \}
\end{equation}
\noindent And, we may write $V_h:= V_h^{int}\oplus V_h^b$.
\color{black}
\subsubsection{Global Finite Element Spaces with Boundary Conditions}
To impose homogeneous Dirichlet boundary conditions on the global finite element spaces, it suffices to modify the global space defined over the boundary layer of the domain, thus, we first define
\begin{align*}
V_h^{b,0}(\mathcal{Q})&= \{ v: v= \hat{v}\circ \tilde{F}_\mathcal{Q}^{-1}, \hat{v}\in V_h^{b}(\hat{\mathcal{Q}}), v|_{\mathcal{Q}\cap \partial \Omega}=0 \}. 
\end{align*}
\noindent Then, the global finite element space for $\Omega_{\mathcal{B}}$ becomes: 
\begin{align*}
V_h^{b,0}&= \{ v \in H^1(\Omega_{\mathcal{B}}): v|_{\mathcal{Q}}\in V_h^{b,0}(\mathcal{Q}),\ v\ \text{is continuous at}\\ & \text{at the interior nodes}\ a_i\ \text{in}\ \mathcal{T}_h^{(b)},\ \forall \mathcal{Q}\in \mathcal{T}_h^{(b)}\}.
\end{align*}
\noindent This yields the following global function space over $\Omega$:
\begin{align}\label{eq:global-fespace-bc}
    V_h^0:=\{v\in H^1_0(\Omega): v|_{\Omega_{int}}\in V_h^{int}, v|_{\Omega_{\mathcal{B}}}\in V_h^{b,0} \}
\end{align}
As in earlier, we may write $V_{h,0}:= V_h^{int}\oplus V_h^{b,0}$.\\
Note that in the Galerkin formulation of isogeometric analysis, homogeneous boundary conditions can be exactly enforced by setting the control variables to zero \cite{hughes}.
\subsection{Numerical Integration}
Classical Gaussian quadrature rules consisting of $n$ points allow an exact integration of polynomials of order $(2n-1)$
\cite{gen_gauss}. 
In Galerkin-type formulations, element-wise Gaussian quadrature is optimal for standard finite element methods and has been used extensively for quadrilateral and hexahedral finite elements\cite{hughes_ni}. 
However, it has been shown that Gaussian quadrature rule is suboptimal in isogeometric analysis since it disregards the interelement continuity of the smooth spline basis functions \cite{hughes_ni,zou21,zou22}. To construct efficient quadrature rules for isogeometric analysis,  the interelement continuity levels of splines need to be taken into account. Thus, rules that involve more than a single element need to be constructed as smoothness across the element boundaries would reduce the number of degrees of freedom that would be required by the standard continuous finite elements for the same mesh. Such reductions in the number of degrees of freedom (therefore, the number of basis functions) yield reductions also in the number of quadrature points required for exact integration. Various efficient quadrature rules with reduced sets of quadrature points were presented in \cite{auricc,zou22, hughes_ni}. \\
\noindent Zou et al. \cite{zou21} have shown that Greville quadrature rules yield comparable accuracy as full Gaussian quadrature rules but are significantly more efficient than the full Gaussian quadrature in isogeometric analysis. The authors, however, also pointed out that Greville quadrature weights may be negative in regions where element sizes change abruptly. Therefore, non-uniform knot vectors may involve negative Greville quadrature weights. Negative quadrature weights may cause instability, thus, are not preferred in numerical or engineering analysis. A Gauss-Greville quadrature rule was introduced in \cite{zou22} to address these negative quadrature weight issues where they occur by means of various checks and adaptations of the quadrature rule to be employed. \\
\noindent In this manuscript, our goal is to provide quadrature rules that would yield optimal accuracy for the numerical approximations of the integrals involved in the variational formulations of second-order partial differential equations. In this regard, we employ the Gauss-Legendre quadrature rule\cite{quarteroni} for the hexahedral elements in $\Omega_{int}$, and for the elements in $\Omega_{\mathcal{B}}$, we propose a new quadrature rule which hybridizes the Greville quadrature rule introduced in \cite{zou21} and the Gauss-Legendre quadrature rule. We assume that the knot vectors forming the NURBS surfaces are uniform, thus, the Greville weights are non-negative. Multi-dimensional quadrature rules are obtained from the tensor product of suitable one-dimensional rules in both isogeometric analysis and the finite element analysis carried over tensor-product meshes.  Since the spline basis functions and the finite element basis functions we utilize are tensor products of piecewise-polynomials in one-dimension, we use one-dimensional quadrature rules to derive the two-dimensional quadrature rules that we need to utilize in the derivation of our hybrid quadrature rule in three-dimensions.\\ 
Recall that a 1D function $f$ can be numerically integrated over a domain $I$ by a set of tuples $\{(x_i,w_i)\}_{i=1}^n$ that satisfy:
\begin{align}\label{eq:gen-quad}
    \int\limits_{I} f(\alpha) d\alpha\approx\sum\limits_{i=1}^n f(x_i)w_i
\end{align}
where $\{x_i\}$'s are called the quadrature points and $\{w_i\}$'s are the weights associated with them. Note that the quadrature order must be sufficiently high for the integrand so that \eqref{eq:gen-quad} can be written as an equality rather than an approximation.\\
\noindent The Greville  quadrature rule for B-splines uses the Greville points associated with the B-spline basis functions as the quadrature points and determines the quadrature weights by solving a linear moment fitting problem in each parametric direction\cite{zou22}. Precisely, if we let $\{x_i\}$ be the Greville points calculated as in Equation~\eqref{eq:grevpts}, then the weights $\{w_i\}$ are determined by solving the moment-fitting system of equations of the form\cite{zou22}:
\begin{align}\label{eq:quad_w}
\begin{bmatrix}
\int\limits_{I} N_1(\eta)d\eta\\
\int\limits_{I} N_2(\eta)d\eta\\
.\\
.\\
.\\
\int\limits_{I} N_n(\eta)d\eta
\end{bmatrix} =\begin{bmatrix}
 N_1(x_1)\ N_1(x_2) \dots N_1(x_n) \\
 N_2(x_1)\ N_2(x_2) \dots N_2(x_n) \\
 \dots \\
 \dots \\
 \dots\\
 N_n(x_1)\ N_n(x_2) \dots N_n(x_n) \\
\end{bmatrix}\begin{bmatrix}
w_1\\
w_2\\
.\\
.\\
.\\
w_n
\end{bmatrix}
\end{align}
where $N_i$ denotes a B-spline basis function of degree $p$ and the moments on the left-hand side are computed as follows \cite{johannessen, chui2004nonstationary}
\begin{equation*}
\int\limits_{I} N_i(\eta)dx=\frac{\eta_{i+p+1}-\eta_i}{p+1},
\end{equation*}
\noindent  Thus, the quadrature rule can exactly integrate all linear combinations of the univariate B-spline basis functions $\{N_i\}_{i=1}^n$ if the determinant of the matrix in Equation~\eqref{eq:quad_w} is non-zero \cite{zou21}.\\
\noindent To ensure numerical stability, discrete Galerkin forms must be rank-sufficient under quadrature. In \cite{zou21}, it is mentioned that using the Greville points as the quadrature points yields stiffness and mass matrices that are free of rank deficiency regardless of the mesh sizes and the polynomial degrees. However, the authors also noted that even though the matrices are full rank, the system can still suffer from spurious modes due to a lack of integration accuracy. Thus, 
accurate integration of the spline basis functions is still necessary for eliminating spurious modes and obtaining a well-conditioned system and accurate results\cite{zou21}. This issue was addressed by defining a reduced Gaussian quadrature rule which yields more accurate integration than the Greville quadrature for polynomial degrees $p>2$ even with less quadrature points than the full Gaussian quadrature in \cite{zou22}, but it was also noted that for $p=2$, both the Greville quadrature and the reduced Gaussian quadrature rules yield optimal convergence. In this research, it suffices to use B-spline basis functions with $p=2$, thus, with the Greville quadrature rule, we can still obtain optimal convergence while numerically integrating functions over the surface.\\ 
\noindent Note that while working with the variational formulations involving NURBS basis, one would encounter integrals of the following form
\begin{align}\label{eq:sampleint}
\int R_i(\alpha) R_j(\beta)  J_c(\alpha, \beta)
\end{align}
\noindent where $J_c(\alpha,\beta)$ is a function that involves the Jacobian (or the inverse of the Jacobian) of the geometric map and the coefficients of the partial differential equation. Since both the NURBS map and the weight function $W(\alpha, \beta)$ are piecewise smooth functions defined on the initial coarse mesh where the geometry is exactly represented and they remain unchanged during refinement, it can be assumed that $J_c(\alpha,\beta)$ and $W(\alpha,\beta)$ are constant as in \cite{hughes_ni}.  Thus, while determining the quadrature rule  for computing the integrals that involve NURBS basis functions in our formulations, we can utilize the Greville quadrature rule that can be used for evaluating integrals involving B-spline basis functions. In other words, it suffices to utilize a quadrature rule that would exactly approximate the following integral instead of the integral in~\eqref{eq:sampleint}:
\begin{align}\label{eq:sampleint_red}
\int N_i(\alpha)N_j(\beta)
\end{align}
\noindent Therefore, for the NURBS-enhanced elements, we construct a new quadrature rule by hybridizing the Greville quadrature rule for the B-splines and the one-point Gaussian quadrature rule in two dimensions. 
First, by scaling and translation, we redefine the domain of the geometric map as $[-1,1]^3$ since the Gauss-Legendre quadrature rule in 3D is defined over $[-1,1]^3$. (It is easy to see that $G: \mathbb{R}^3 \to \mathbb{R}^3$ such that $G(v)=2v-\vec{1}$ would transform $[0,1]^3$ into $[-1,1]^3$). 
Then, the initial procedure for constructing the new quadrature rule is as follows: 
\begin{itemize}
    \item Let $\tilde{q}=(0,0)$ be the single Gaussian quadrature point with weight $w=4$ over $[-1,1]^2$. Then, move it to the $z=1$ plane and obtain a quadrature point $q^G=(0,0,1)$, keeping $w$ unchanged.
    \item Suppose $\{\gamma_{ij}:=(\gamma_i,\gamma_j)\}\in [-1,1]^2$ are the pulled-back Greville quadrature points with weights $\{w_{ij}:=w_iw_j\}$. Then, move them to $z=-1$ plane to get the quadrature points of the form $q^{Gr}_{ij}=(\gamma_i, \gamma_j,-1)$. The weights associated with $w_{i}$ (similarly, $w_j$) can be computed by solving the system in Equation~\eqref{eq:quad_w} using the one-dimensional set of B-spline basis functions involved in the description of the NURBS-enhanced element. 
\end{itemize}
Now, we can derive the quadrature points for the NURBS-enhanced elements by weighting and scaling as follows:
\begin{align}
    \tilde{q}^{\mathcal{B}}_{k}&:=(\frac{q^G_x\sqrt{w}+q^{Gr}_xw_{i}}{\sqrt{w}+w_i}, \frac{q^G_y\sqrt{w}+q^{Gr}_yw_{j}}{{\sqrt{w}+w_j}},\frac{q^G_zw+q^{Gr}_zw_{ij}}{w+w_{ij}}),\ k=1,2,\dots,n_{cp}, \label{eq:hybrid_quad_pts-new}\\
q^{\mathcal{B}}_{k}&:=\frac{\tilde{q}^{\mathcal{B}}_{k}}{|\tilde{q}^{\mathcal{B}}_{k}|},\ k=1,2,\dots,n_{cp},\label{eq:hybrid-quad-pts-new2}
\end{align}
where  $k:=(j-1)n_1+i$ and we denoted the $x$ ($y$ and $z$, resp.) component of $q^{Gr}_{ij}$ by $q^{Gr}_x$ ($q^{Gr}_y$, $q^{Gr}_z$, resp.) dropping the point indices $i$ and $j$ to simplify notation.\\
Note that the novel quadrature points also lie in $[-1,1]^3$ and they carry over the influence of the weights associated with the quadrature points originating from the opposite faces of the cube $[-1,1]^3$ in a consistently proportional and systematic manner. Finally, the weights corresponding to these quadrature points  can be computed via the general quadrature formulation~\eqref{eq:gen-quad} using the hybrid basis functions~\eqref{eq:basis-hybrid-R-transformed} as follows:\\ Let $\hat{v}\in V_h^b(\hat{Q})$, then we may write $\hat{v}(\hat{x})=\sum\limits_{k=1}^{n_{cp}+4} \hat{v}(\hat{x}_k) \tilde{N}_k(\hat{x})$, where $\{\hat{x}_k\}$ denotes the set of nodes. This yields
\begin{align*}
    \int_{\hat{Q}} \hat{v}(\hat{x})\ d\hat{x}&=\sum\limits_{k=1}^{n_{cp}+4}\hat{v}(\hat{x}_k)\int_{\hat{Q}} \tilde{N}_k(\hat{x}) d\hat{x}
\end{align*}
Thus, to obtain a quadrature rule that would provide an exact integration of a function in $V_h^b(\hat{Q})$ over $\hat{Q}$, we need to ensure the exact integration of each $\tilde{N}_k$ over $\hat{Q}$, that is,  we need to find $\{w^{\mathcal{B}}_i\}_{i=1}^n$ such that

\begin{align}\label{eq:hybrid-quad-derive}
    \int_{\hat{Q}} \tilde{N}_k(\hat{x}) d\hat{x}=\int_{\hat{Q}_G} (\tilde{N}_k\circ G^{-1})(\tilde{x}) d\tilde{x}=
    \sum\limits_{i=1}^n \tilde{N}_k(q^{\mathcal{B}}_{i}) w^{\mathcal{B}}_i,\quad \text{for all}\ k=1,2,\dots,n_{cp+4},
\end{align}
where $\hat{Q}_G:=[-1,1]^3$, and the number of quadrature points $n:=n_{cp}$ by definition in \eqref{eq:hybrid-quad-pts-new2}. We let $\hat{N}_k:=(\tilde{N}_k\circ G^{-1})$ and $m:=n_{cp}+4$ for notational simplicity, and write the overdetermined system that results from \eqref{eq:hybrid-quad-derive} in matrix form as follows:
\begin{align}\label{eq:quad_w_hybrid_overdetermined}
\begin{bmatrix}
\int\limits_{\hat{Q}_G} \hat{N}_1(\eta)d\eta\\
\int\limits_{\hat{Q}_G} \hat{N}_2(\eta)d\eta\\
.\\
.\\
.\\
\int\limits_{\hat{Q}_G} \hat{N}_{m}(\eta)d\eta
\end{bmatrix} =\begin{bmatrix}
 \hat{N}_1(q_1^{\mathcal{B}})\ \hat{N}_1(q_2^{\mathcal{B}}) \dots \hat{N}_1(q_n^{\mathcal{B}}) \\
\hat{N}_2(q_1^{\mathcal{B}})\ \hat{N}_2(q_2^{\mathcal{B}}) \dots \hat{N}_2(q_n^{\mathcal{B}}) \\
 \dots \\
 \dots \\
 \dots\\
 \hat{N}_{m}(q_1^{\mathcal{B}})\ \hat{N}_{m}(q_2^{\mathcal{B}}) \dots \hat{N}_{m}(q_n^{\mathcal{B}}) \\
\end{bmatrix}\begin{bmatrix}
w^{\mathcal{B}}_1\\
w^{\mathcal{B}}_2\\
.\\
.\\
.\\
w^{\mathcal{B}}_n
\end{bmatrix}
\end{align}
where we need to solve for the weight vector $\textbf{w}^{\mathcal{B}}:=[w_i^{\mathcal{B}}]$. Therefore, we define 
\begin{align}\label{eq:quad_w_hybrid_least-squares_p}
\mathbf{A}:=\begin{bmatrix}
 \hat{N}_1(q_1^{\mathcal{B}})\ \hat{N}_1(q_2^{\mathcal{B}}) \dots \hat{N}_1(q_n^{\mathcal{B}}) \\
\hat{N}_2(q_1^{\mathcal{B}})\ \hat{N}_2(q_2^{\mathcal{B}}) \dots \hat{N}_2(q_n^{\mathcal{B}}) \\
 \dots \\
 \dots \\
 \dots\\
 \hat{N}_{m}(q_1^{\mathcal{B}})\ \hat{N}_{m}(q_2^{\mathcal{B}}) \dots \hat{N}_{m}(q_n^{\mathcal{B}}) \\
\end{bmatrix},\quad 
\textbf{b}:=\begin{bmatrix}
\int\limits_{\hat{Q}_G} \hat{N}_1(\eta)d\eta\\
\int\limits_{\hat{Q}_G} \hat{N}_2(\eta)d\eta\\
.\\
.\\
.\\
\int\limits_{\hat{Q}_G} \hat{N}_{m}(\eta)d\eta
\end{bmatrix} 
\end{align}
As $\mathbf{A}\mathbf{w}^{\mathcal{B}}= \mathbf{b}$ does not yield a unique solution $\mathbf{w}^{\mathcal{B}}$, we use the least-squares method to find  $\mathbf{w}^{\mathcal{B}}$ that minimizes $\|\mathbf{A}\mathbf{w}^{\mathcal{B}}-\mathbf{b}\|^2$. 
We note that $n_{cp}\ge 4$ since there are $(p+1)^2$ basis functions (thus, control points and Greville points) active over each boundary element.\\
 In the special case where $n:=n_{cp}=4$, thus, $m:=n_{cp}+4=8$, thus, $m=2n$, the  numerical integration achieves the same optimality rate as the Gaussian quadrature, in the sense that the number of quadrature points $n$  satisfies $n\le \frac{m+1}{2}$.
\begin{remark}
    Note that some of the integrals would involve differentials of the basis functions. However, we require accurate integration of all terms, that is, we need to be able to integrate functions of the largest polynomial degree accurately. Therefore, we only focus on the integrals of the form \eqref{eq:sampleint_red}. 
\end{remark}

    \noindent The derivation of a hybrid quadrature rule using a two-point Gaussian quadrature rule rather than a one-point Gaussian quadrature rule can be done in a similar fashion. Such derivation would require repeating~\eqref{eq:hybrid_quad_pts-new}  for both of the Gaussian quadrature points and yield $2n$ quadrature points.\\

\noindent Now we show how we would numerically compute volumetric and surface integrals in the physical domain using the quadrature rules mentioned above. Let $\hat{F}:=F\circ G^{-1}$. Consider
\begin{align}\label{eq:gen_int}
    \int_{Q} f(x)\ dx &=\int_{\hat{Q}_G} f(\hat{F}(\tilde{x}))\ |J_{\hat{F}}(\tilde{x})|\ d\tilde{x}
\end{align}
\noindent where $f\in L^2(\Omega)$ is an arbitrary function.\\ \\
\eqref{eq:gen_int} can be computed numerically as follows:
\begin{align*}
    \int_{\hat{Q}_G} f(\hat{F}(\tilde{x}))\ |J_{\hat{F}}(\tilde{x})|\ d\hat{x}
    &\approx \sum\limits_{l} \hat{f}(q^{(l)}) w^{(l)} |J_{\hat{F}}(q^{(l)})|
\end{align*}
\noindent where $\hat{f}:=f\circ \hat{F}$, $(q^{(l)}, w^{(l)})$ denotes a Gauss-Legendre quadrature point and weight pair if $Q\in \mathcal{T}_h^{(i)}$ and a hybrid quadrature point with its corresponding weight if $Q\in \mathcal{T}_h^{(b)}$.\\


\noindent Similarly, let $\hat{S}:= S\circ g^{-1}$, where $g$ is a bijective map from $[0,1]^2$ to $[-1,1]^2$ obtained via scaling and translation, and $Q_g:=[-1,1]^2$. Then, any scalar surface integral over a NURBS boundary face is given by

\begin{equation}
    \int_{\mathcal{P}} f(s)\ ds =\int_{\hat{Q}_g} f(\hat{S}(\tilde{s}))\ |J_{\hat{S}}(\tilde{s})|\ d\tilde{s}
\end{equation}
\noindent and numerically, such an integral can be approximated as follows
\begin{align*}
 \int_{\hat{Q}_g} f(\hat{S}(\tilde{s}))\ |J_{\hat{S}}(\tilde{s})|\ d\tilde{s}
    &\approx \sum\limits_{m} \hat{f}(q^{(m)}) w^{(m)} |J_{\hat{S}}(q^{(m)})|
\end{align*}
\noindent where $\hat{f}:=f\circ \hat{S}$, and $\{(q^{(m)},w^{(m)})\}$ are the images of two-dimensional Greville quadrature points under $g$ and their associated weights.
\subsection{Refinement}
\noindent In this subsection, we describe a new refinement strategy that can be employed for refining the NURBS-enhanced elements to complement our theoretical framework. In isogeometric analysis \cite{hughes}, $\Omega$ is often described via a coarse mesh consisting of only a few elements, while the approximate solution is computed on a refined mesh. Thus, the NURBS parametrization, $S$, which is defined over a patch and the weight function, $W$, are determined over the coarsest mesh.  During the refinement of the mesh and space, control points are adjusted to keep $S$ unchanged and the weights associated with the control points are adjusted to keep $W$ unchanged. Therefore, the refinement of splines is generally based on the refinement of function spaces while the underlying knot-spans are implicitly refined\cite{bazilevs2010}.\\ 
\noindent In this paper, we use $h$-refinement for finite elements and its equivalent in IGA, namely, the knot insertion for NURBS. As described in \cite{hughes}, after a knot insertion, the number of basis functions and the number of control points are increased by one although the geometry and the parametrization of the NURBS surface are preserved. Therefore, a new set of basis functions with a new set of control points is defined in a way to preserve the continuity of the surface, since the knot insertions that result in knot repetitions would reduce the continuity. We note that we use knot insertion as a refinement strategy only for the boundary surface of the domain.\\ 
\noindent Suppose $\mathcal{T}_{h_0}$ is the coarsest mesh, and define a family of meshes $\{\mathcal{T}_h\}_{h>0}$ as described in Section~\ref{sec:method}. As we insert knots to the knot spans, we update the set of Greville points and the piecewise bilinear functions that are dual to these points.
In the interior of the domain, we do the h-refinement for h values of $\frac{1}{2}$,$\frac{1}{4}$, and $\frac{1}{8}$, respectively. Over the boundary layer, we consider a uniform refinement of the boundary, that is, we insert same number of knots in each direction. Thus, each element $I_Q\in \mathcal{T}_S^p$ is respectively subdivided into $2$, $4$ and $8$ new elements that correspond to the newly defined knot spans on the two-dimensional NURBS reference domain. This enables preserving the one-to-one correspondence between interior and exterior faces of the boundary layer elements that are opposite to each other, thus, the blending function method can be used without any modifications. After the refinement via one knot insertion in every direction of the NURBS parametric domain and the discretization parameter is halved in the interior region, we have four hexahedrals each of which has a single face on the NURBS boundary (See Figure~\ref{fig:nurbsrefe}). Each one of these hexahedrals are images of the reference cube under the map $\tilde{F}_{Q}$. \\
\noindent The tensor product construction implies that a modification of a Bezier element propagates through the entire parameter space. In knot insertion, this is an important limitation as it prohibits local refinement. In numerical simulations where physical fields may change rapidly, local refinement may be required. 
Various techniques such as T-splines \cite{tspline, borden-t}, locally refined B-splines \cite{patrizi}, hierarchical B-splines 
\cite{forsey,evans2020hierarchical} and hierarchical NURBS \cite{hierNURBS} have been developed to address this issue. However, local mesh refinement is beyond the scope of this manuscript.
