\subsection{A necessary condition for the existence of MRD $M$-codes}

We now derive a necessary condition for the existence of an MRD $M$-code.

\begin{theorem}\label{McodeMRD}
 Let $M\in {\rm M}_n(\KK)$. If there exists an MRD $M$-code $\Cc\neq\LL^n$, then $\mu_M=\pi^\ell$, where $\ell\geq 1$ and $\pi\in\KK[x]$ is a monic polynomial which is irreducible over $\KK$.
\end{theorem}

\begin{proof}
Let $\Cc$ be an $M$-code with parameters $[n,k]$.
Assume that $M_1(\Cc)=n-k+1$. Keeping the notation of Corollary \ref{coroweightM}, let $i_0\in\Lambda$ such that 
$$M_1(\Cc)=M_1(\Cc_{i_0}).$$

We then have $M_1(\Cc)\leq n_{i_0}\deg(f_{i_0})-k_{i_0}+1$.
On the other hand, we have $k=\displaystyle\sum_{i=1}^s k_i$ and $n=\displaystyle\sum_{i=1}^s n_i\deg(f_i).$
It follows that for all $i\neq i_0$, we have $k_i=n_i\deg(f_i)$.
Thus, if $s\geq 2$, one of the $\Cc_i$'s equals $\LL^{k_i}$, and thus satisfies $M_1(\Cc_i)=1$. Corollary \ref{coroweightM} then yields $M_1(\Cc)=1$.
Therefore $n=k$, and thus $\Cc=\LL^n$. Consequently, if there is an MRD $M$-code different from $\LL^n$, then $s=1$. In this case, we have $\mu_M=\pi^\ell$, where $\pi=f_1$ and $\ell=m_1$. 
\end{proof}

\begin{remark}
 The previous necessary condition is obviously not sufficient, as the case of $M=I_n$ already shows.   
\end{remark}

\begin{corollary}
Let $n\geq 2$ be an integer prime to ${\rm char}(\KK)$. Then, there is no MRD $M$-code $\Cc$ different from $\LL^n$ in the following situations: 
    \begin{enumerate}[label=(\roman*)]
        \item $M=C_{x^n-1}^\ell$, where $\ell\mid n$;
        \item $M=C_{x^n+1}$, where $n$ is odd integer;
        \item $M=C_{x^n-a}$, where $a$ is a non-zero $p$-th power in $\KK$ for some prime divisor $p$ of $n$.
    \end{enumerate}
\end{corollary}

\begin{proof}
The minimal polynomial of $M$ is $x^{n_0}-1$ in the first case, where $n=n_0\ell$, $x^n+1$ in the second case and $x^n-a$ in the third case. The assumption on $n$ implies that in all cases, $\mu_M$ is separable. In particular, if $\mu_M=\pi^r$ for some monic irreducible polynomial $\pi\in\KK[x]$ , then $r=1$, that is, $\mu_M$ is irreducible. But none of these three polynomials are irreducible, in view of the various assumptions made in each case. The previous theorem then yields the desired result.
\end{proof}

\begin{remarks}~

\begin{enumerate}
    \item The first item of the previous corollary generalizes the fact that no cyclic code different from $\LL^n$ is MRD (see \cite[Proposition $37$]{DucOggier1}).
\\
    \item If $\KK=\mathbb{F}_q$ and $p$ does not divide the order of $a\in\mathbb{F}_q^\times$, then $a$ is a $p$-th power in $\mathbb{F}_q$. Indeed, by assumption, there exists $u,v\in\mathbb{Z}$ such that $u p+v o(a)=1$. We then easily get that $a=(a^u)^p$.
\\
\\
    In particular, item $(3)$ of the previous corollary may be applied in this case. For example, if $n$ is coprime to $q(q-1)$, then $a$ is a $p$-th power for any prime divisor $p$ of $n$, and there is no MRD constacyclic code for any $a\in \mathbb{F}_q^\times$ in this case (except $\LL^n$).
    \end{enumerate}
\end{remarks}


\section{The case of $M$-cyclic codes}\label{sec-Mcyclic}


\subsection{$M$-cyclic codes and their rank weight hierarchy.}\label{subsec-Mcycl}

The goal of this short subsection is to apply our previous results to the case of $M$-cyclic codes. In this situation, everything may be translated in terms of generator polynomials. 

\begin{theorem}\label{weightMFrobcyclic}
  Let $M\in {\rm M}_n(\KK)$  be a cyclic matrix, with minimal polynomial $f\in\KK[x]$. Let us write $f=f_1^{m_1}\cdots f_s^{m_s},$
 where $f_1,\ldots,f_s\in\KK[x]$ are pairwise distinct irreducible monic polynomials, and $m_1,\ldots,m_s\geq 1$.


Let $g\in\LL[x]$ be a monic divisor of $f$ of degree $n-k$, and write $g=g_1\cdots g_s$, where $g_i$ is a monic divisor of $f_i^{m_i}$.

For $i\in\left\llbracket 1,s\right\rrbracket$, set $d_i= m_i\deg(f_i)$ and $k_i= m_i\deg(f_i)-\deg(g_i)$. 

Let $\Lambda=\{ i\in\left \llbracket 1,s\right\rrbracket \mid  g_i\neq f_i^{m_i}\}$, and for all $i\in\Lambda$, let $\Cc_i\subset\LL^{d_i}$ be the $f_i^{m_i}$-polynomial code with generator polynomial $g_i$.
Then, for all  $r\in\left\llbracket 1,k\right\rrbracket$, we have $$M_r(\Cc_g)=\underset{\substack{\sum_{i\in\Lambda}r_i=r \\ r_i \in\left\llbracket 0,k_i\right\rrbracket}}{\min} \displaystyle\sum_{i\in\Lambda} M_{r_i}(\Cc_i).$$

Moreover, for all $i\in\Lambda$, and for all $r_i\in\left\llbracket 1,k_i\right\rrbracket$, we have $$ M_{r_i}(\Cc_i)\leq \deg(g_i)+r_i.$$



In particular, for all $r\in\left\llbracket 1,k\right\rrbracket$, we have $$M_r(\Cc_g) \leq\underset{\substack{\sum_{i\in\Lambda}r_i=r \\ r_i \in\left\llbracket 0,k_i\right\rrbracket}}{\min} \displaystyle\left(\sum_{\underset{r_i\neq 0}{i\in \Lambda}}(\deg(g_i))\right) +r.$$  
\end{theorem}

\begin{proof}
 Let ${\bf v}\in\KK^n$ be a cyclic vector for $M$, so that $\Cc_g=\{{\bf v}g(M)^tP(M)^t \mid P\in \LL[x]\}$.

Write $f=gh$. Then $\Cc_g=\ker(h(M))$. Indeed, we have $$\dim_\LL(h(M))=\deg({\rm gcd}(h,f))=\deg(h)=n-\deg(g)=\dim_\LL(\Cc_g),$$
as well as the inclusion $\Cc_g\subset \ker(h(M))$, since for all $P\in \in\LL[x]$, we have $${\bf v} g(M)^t P(M)^t h(M)^t={\bf v}P(M)^t f(M)^t=0.$$
Now, we apply Theorem \ref{weightMFrob} to conclude, after noticing that ${\rm gcd}(h, f_i^{m_i})\neq 1$ if and only if $g_i\neq f_i^{m_i}$.
\end{proof}

\begin{corollary}\label{coroweightMcyclic}
 Keeping the notation of Theorem \ref{weightMFrobcyclic}, we have $$M_1(\Cc_g)=\min_{i\in\Lambda}(M_1(\Cc_i))\leq \underset{i\in\Lambda}{\min} (\deg(g_i))+1, $$

as well as $$M_k(\Cc)=\sum_{i\in\Lambda}M_{k_i}(\Cc_i)\leq \sum_{i\in\Lambda} m_i\deg(f_i). $$
\end{corollary}


\begin{corollary}
Keeping the notation of Theorem \ref{weightMFrobcyclic}, let $\Gamma=\{i\in \left\llbracket 1,s\right\rrbracket \mid g_i=1 \}$, and set $d_\Gamma=\displaystyle\sum_{i\in\Gamma}m_i\deg(f_i)$.

 Then, for all $r\in\left\llbracket 1, d_\Gamma\right\rrbracket$, we have $M_r(\Cc)=r$.
\end{corollary}

\begin{example}\label{exmkMcyclic}

Let $\KK=\FF_3, \LL=\FF_{3^{10}}$, and let $M=C_f\in {\rm M}_9(\KK)$, where $$f=(x^2+1)^2(x+1)^3(x-1)^2.$$ Finally, let $g=(x-i)(x-1)^2\in\LL[x]$, where  $i\in\LL$ satisfies $i^2=-1$. Then $\Cc_g$ has dimension $6$.

Moreover, setting $f_1=x^2+1, f_2=x+1, f_3=x-1$, we have $\Lambda=\{1,2\}$  and $M_1(\Cc_g)\leq 2$ and $M_4(\Cc_g)\leq 7$, while the standard Singleton bound gives $M_1(\Cc_g)\leq 5$ and $M_4(\Cc_g)\leq 9$. 

Then, since $\Gamma =\{ 2\}$, we have $M_r(\Cc_g) =r$ for $r\in \llbracket 1,3\rrbracket$ and $4\leq  M_r(\Cc_g) \leq 7$ for $r\in \llbracket 4,6\rrbracket$.
\end{example}


Theorem \ref{genexfrob} also yields the following result, again noticing that $\Cc_g=\ker(h(M))$, where $f=gh$.

\begin{theorem}
Let $M\in {\rm M}_n(\KK)$  be a cyclic matrix, with minimal polynomial $f\in\KK[x]$. Let us write $f=f_1^{m_1}\cdots f_s^{m_s},$
 where $f_1,\ldots,f_s\in\KK[x]$ are pairwise distinct irreducible monic polynomials, and $m_1,\ldots,m_s\geq 1$.

For $i\in\left\llbracket 1,s\right\rrbracket$, let $d_i=m_i\deg(f_i)$. 



Let $g\in\LL[x]$ be a monic divisor of $f$ of degree $n-k$, and write $g=g_1\cdots g_s$, where $g_i$ is a monic divisor of $f_i^{m_i}$.

Let $h\in \LL[x]$ such that $f=gh$. Set $\Lambda=\{ i\in\left \llbracket 1,s\right\rrbracket \mid  g_i\neq f_i^{m_i}\}$.

Assume that ${\rm gcd}(h, f_i^{m_i})$ has degree $1$ for all $i\in\Lambda$, and let ${\bf w}_i\in\LL^{d_i}$ be the vector of coefficients of $g_i$.

  Then, $\Cc$ has dimension $\vert \Lambda\vert$, and  for all $r\in\left\llbracket 1, \vert\Lambda\vert\right\rrbracket$, we have $$M_r(\Cc)=\underset{\substack{J\subset\left\llbracket 1,\vert\Lambda\vert\right\rrbracket \\ \vert J\vert =r}}{\min} \left(\sum_{j\in J}{\rm wt}_R({\bf w}_j)\right).$$
\end{theorem}

\subsection{Counting $M$-cyclic codes with first rank weight equal to $1$ }\label{subsec-P}

The goal of this subsection is to give a characterization of $M$-cyclic codes with first rank weight equal to $1$.
For, according to Lemma \ref{lemme1motFq}, we need to understand the intersection of an arbitrary $M$-cyclic code with $\KK^n$.

This is the content of following result.

\begin{theorem}\label{Mcequal1}
Let $M\in{\rm M}_n(\KK)$ be a cyclic matrix with minimal polynomial $f$. Write  $f=f_1^{m_1}\cdots f_s^{m_s}$, where $f_1,\ldots,f_s\in\KK[x]$ are pairwise distinct monic irreducible polynomials of $\KK[x]$, and $m_1,\ldots,m_s\geq 1$.

Let  $g\in\LL[x]$ be a monic divisor of $f$, and write $g=g_1\cdots g_s$, where $g_i\mid f_i^{m_i}$ in $\LL[x]$.

For $i\in\left\llbracket 1,s\right\rrbracket$, set $\ell_i=\left\lbrace\begin{array}{cl}
  0 &\mbox{ if }g_i=1 \cr \min\{\ell\in\left\llbracket 1,m_i\right\rrbracket\mid\ \  g_i\mid f_i^\ell\}& \mbox{ if }g_i\neq 1 \end{array}\right.$

Finally, let  $d=n-\displaystyle\sum_{i=1}^s\ell_i\deg(f_i)$, and let ${\bf v}\in \KK^n$ be a cyclic vector for $M$.

Then the following properties hold: 

\begin{enumerate}
\item we have $ \displaystyle g \cdot\LL[x] \cap \KK[x] = \prod_{i=1}^sf_i^{\ell_i} \cdot \KK[x]$;
\\
\\
\item 
the map $Q\in\KK[x]_{<d}\mapsto \displaystyle {\bf v}(\prod_{i=1}^sf_i^{\ell_i})(M)^tQ(M)^t\in\Cc_g\cap \KK^n$ is an isomorphism of $\KK$-vector spaces.
\\
\\
\noindent In particular, we have $\dim_\KK(\Cc_g\cap\KK^n)=\displaystyle\sum_{i=1}^s(m_i-\ell_i)\deg(f_i)$;
\\
\item we have $M_1(\Cc_g)=1$ if and only if there exists $i\in \left\llbracket 1,s\right\rrbracket$ such that $\ell_i\leq m_i-1$, that is, such that $g_i\mid f_i^{m_i-1}$.
\end{enumerate}
\end{theorem}
\begin{proof}
Since $f_1,\ldots,f_s$ are irreducible and pairwise distinct, $f_1^{m_1},\ldots,f_s^{m_s}$  are pairwise coprime in $\KK[x]$, and therefore in $\LL[x]$ since the gcd of polynomials is invariant under scalar extensions. 
    We may then write $g=g_1\cdots g_s$, where $g_i$ is a monic divisor of $f_i^{m_i}$ in $\LL[x]$.

    Let us prove item 1. 
    Note that by definition, we have $g_i\mid f_i^{\ell_i}$ for all $i\in\left\llbracket 1,s\right\rrbracket$.
    This implies that $g\mid \displaystyle\prod_{i=1}^sf_i^{\ell_i}$.
    Hence, $\displaystyle\prod_{i=1}^sf_i^{\ell_i}\in g\cdot\LL[x]\cap\KK[x]$.
    Note now that $g\cdot \LL[x]\cap\KK[x]$ is an ideal of $\KK[x]$ which contains $\displaystyle\prod_{i=1}^sf_i^{\ell_i}$. In particular, it is generated by a monic polynomial $P\in\KK[x]$  dividing $\displaystyle\prod_{i=1}^sf_i^{\ell_i}$. Hence, $P=\displaystyle \prod_{i=1}^sf_i^{r_i}$, where $r_i\in\left\llbracket 0,\ell_i\right\rrbracket$.
    Now, $g\mid P$, so for all $i\in\left\llbracket 1,s\right\rrbracket$, we have $g_i\mid P$, and thus $g_i\mid f_i^{r_i}$.
    If $g_i=1$, then $\ell_i=0$ and thus $r_i=0=\ell_i$. If $g_i\neq 1$, the definition of $\ell_i$ implies that $r_i\geq\ell_i$, and thus $r_i=\ell_i$. All in all, we get $P=\displaystyle\prod_{i=1}^sf_i^{\ell_i}$, as required.


We now prove item 2. Note that, for any $P\in\LL[X]_{<n}$, we have ${\bf v}P(M)^t\in\KK^n$ if and only if $P\in \KK[x]_{<n}$.
Indeed, assume that ${\bf v}P(M)^t\in\KK^n$. Since ${\bf v} $ is a cyclic vector for $M$, there exists $Q\in \KK[x]_{<n}$ such that ${\bf v}P(M)^t={\bf v}Q(M)^t$. By Lemma \ref{interKn}, we have $P=Q\in\KK[x]_{<n}$.
Hence, for all $P\in \LL[x]_{<n}$, we have ${\bf v} P(M)^t\in\Cc_g\cap \KK^n$ if and only if $P\in g\cdot\LL[X]\cap \KK[x]_{<n}$.
By item 1., we have $$ g\cdot \LL[X]\cap \KK[x]_{<n}=(g\cdot \LL[x]\cap\KK[x])\cap\KK[x]_{<n}=   \left(\prod_{i=1}^sf_i^{\ell_i} \cdot \KK[x]\right)\cap \KK[x]_{<n}= \prod_{i=1}^sf_i^{\ell_i}\cdot \KK[x]_{<d}.$$

The $\KK$-linear map $Q\in\KK[x]_{<d}\mapsto \displaystyle {\bf v}(\prod_{i\in I}f_i)(M)^tQ(M)^t\in\Cc_g\cap \KK^n$ is then surjective. It is also injective since ${\bf v}$ is a cyclic vector for $M$.

The formula for the dimension of $\Cc_g\cap\KK^n$ follows immediately, noticing that we have the equality $\deg(f)=n$, since $M$ is a cyclic matrix.

We finally prove item 3. By Lemma \ref{lemme1motFq}, we have $M_1(\Cc_g)=1$ if and only if $\Cc_g\cap\KK^n\neq \{0\}$, that is, if and only if $\dim_\KK(\Cc_g\cap\KK^n)\neq 0.$ By item 2., this means that $\ell_i\leq m_i-1$ for some $i\in\left \llbracket 1,s\right\rrbracket$, which is equivalent to say that $g_i\mid f_i^{m_i-1}$.
\end{proof}

\begin{corollary}\label{allM11}
Let $M\in{\rm M}_n(\KK)$ be a cyclic matrix with minimal polynomial $f$. Write  $f=f_1^{m_1}\cdots f_s^{m_s}$, where $f_1,\ldots,f_s\in\KK[x]$ are pairwise distinct monic irreducible polynomials of $\KK[x]$, and $m_1,\ldots,m_s\geq 1$.

Then every non-zero $M$-cyclic code has first rank weight equal to $1$ if and only if $f_1,\ldots,f_s$ are irreducible in $\LL[x]$.
\end{corollary}

\begin{proof}
Assume that $f_1,\ldots,f_s$ are irreducible in $\LL[x]$, and let $g\in\LL[x]$ be a divisor of $f$. Then $g=f_1^{r_1}\cdots f_s^{r_s}$, where $r_i\in\left\llbracket 0,m_i\right\rrbracket$ for all $i\in\left\llbracket 1,s\right\rrbracket$. 
Hence, if $\Cc_g\neq\{0\}$, that is, if $g\neq f$,  there exists $i\in \left\llbracket 1,s\right\rrbracket$ such that $g_i\mid f_i^{m_i-1}$. By item 3. of the previous theorem, we get $M_1(\Cc_g)=1$.

Conversely, assume that one of the $f_i$'s is reducible in $\LL[x]$, say $f_1$. Let $p_1\in\LL[x]$ be a divisor of $f_1$ different from $1$ and $f_1$, and set $g=p_1^{m_1} f_2^{m_2}\cdots f_s^{m_s}$. By construction, $g\neq f$, and $\Cc_g$ is non-zero. Now, we have $\ell_i=m_i$ for all $i\in\left\llbracket 1,s\right\rrbracket$, so $M_1(\Cc_g)\neq 1$.
\end{proof}

When $f$ is square-free, with the notation of Theorem \ref{Mcequal1}, we have $\ell_i=0$ if ${\rm gcd}(g,f_i)=1$, and $\ell_i=1$ if ${\rm gcd}(g,f_i)\neq 1$. In this situation, the results of Theorem \ref{Mcequal1} translate as follows.

\begin{theorem}\label{Mcequal1sqfree}
Let $M\in{\rm M}_n(\KK)$ be a cyclic matrix with minimal polynomial $f$. Assume that $f$ is square-free, and write  $f=f_1\cdots f_s$, where $f_1,\ldots,f_s\in\KK[x]$ are pairwise distinct monic irreducible polynomials of $\KK[x]$.

Let  $g\in\LL[x]$ be a monic divisor of $f$, and set $I=\{ i\in\left\llbracket 1,s\right\rrbracket\mid {\rm gcd}(g,f_i)\neq 1\}$. 

Finally, let  $d_I=\displaystyle\sum_{i\notin I}\deg(f_i)$, and let ${\bf v}\in \KK^n$ be a cyclic vector for $M$.

Then the following properties hold: 

\begin{enumerate}
\item We have $ \displaystyle g \cdot\LL[x] \cap \KK[x] = \left(\prod_{i\in I}f_i\right) \cdot \KK[x]$;
\\
\\
\item 
the map $Q\in\KK[x]_{<d_I}\mapsto \displaystyle {\bf v}(\prod_{i\in I}f_i)(M)^tQ(M)^t\in\Cc_g\cap \KK^n$ is an isomorphism of $\KK$-vector spaces.
\\
\\
\noindent In particular, we have $\dim_\KK(\Cc_g\cap\KK^n)=\displaystyle\sum_{i\notin I}\deg(f_i)=n-\sum_{i\in I}\deg(f_i)$;
\\
\item we have $M_1(\Cc_g)=1$ if and only if there exists $i\in \left\llbracket 1,s\right\rrbracket$ such that $g$ is coprime to $f_i$ in $\LL[X]$.
\end{enumerate}
\end{theorem}

We would like now to study the proportion of $M$-codes  $\Cc\subset\LL^n$ with minimal rank distance equal to $1$.

To obtain nicer formulas, we will in fact compute here  codes  $\Cc\subset\LL^n$ with minimal rank distance {\bf  different} from $1$ (this means that either $\Cc=\{0\}$ or $\Cc\neq\{0\}$ and $M_1(\Cc)\geq 2$). We will further assume that the irreducible divisors of the minimal polynomial of $M$ are separable in order to make the statements more enlightening. This condition will be automatically fulfilled when $\KK$ is a perfect field, such as a finite field or a field of characteristic $0$.

We then have the following theorem.


\begin{theorem}\label{thmDenombrement}
      Let $M\in{\rm M}_n(\KK)$ be a cyclic matrix with minimal polynomial $f\in\KK[x]$. Assume that all irreducible divisors of $f$ in $\KK[x]$ are separable, and write  $f=f_1^{m_1}\cdots f_s^{m_s}$, where $f_1,\ldots,f_s\in\KK[x]$ are pairwise distinct separable irreducible  monic polynomials of $\KK[x]$, and $m_1,\ldots,m_s\geq 1$.

    \noindent If $P\in\LL[x]$, let $\delta_{\LL}(P)$ be the number of irreducible divisors of $P$ in $\LL[x]$.

    \noindent Then, the proportion $\mathbb{P}$ of $M$-cyclic codes  $\Cc\subset\LL^n$ with minimal rank distance different from $1$ is $$\mathbb{P} = \displaystyle \prod_{i=1}^s\left( 1- \left(\dfrac{m_i}{m_i+1}\right)^{\delta_{\LL}(f_i)}\right).$$

    In particular, we have $$\prod_{i=1}^s\dfrac{1}{m_i+1}\leq \mathbb{P}\leq \prod_{i=1}^s\left( 1- \left(\dfrac{m_i}{m_i+1}\right)^{\deg(f_i)}\right).$$

Moreover :
    \begin{enumerate}
        \item we have $\mathbb{P}=\displaystyle\prod_{i=1}^s\dfrac{1}{m_i+1}$ if and only if $f_1,\ldots,f_s$ are irreducible in $\LL[x]$, if and only if all non-zero $M$-cyclic codes have first rank weight equal to $1$;
        \\
        \\
        \item we have $\mathbb{P}=\displaystyle \prod_{i=1}^s\left( 1- \left(\dfrac{m_i}{m_i+1}\right)^{\deg(f_i)}\right)$  if and only if $f$ totally splits in $\LL[x]$.
    \end{enumerate}
\end{theorem}

\begin{proof}
First, the number $N$ of $M$-codes $\Cc\subset\LL^n$ equals the number of monic divisors of $f$ in $\LL[x]$. Such a divisor $g$ may be written in a unique way as $g=g_1\cdots g_s$, where $g_i$ is a monic divisor of $f_i^{m_i}$ in $\LL[x]$.
Since $f_i$ is separable, it is the product of $\delta_\LL(f_i)$ pairwise distinct monic irreducible polynomials in $\LL[x]$. Thus, the valuation of each irreducible factor of $f_i^{m_i}$ in $\LL[x]$
 is $m_i$, so that there are exactly $(m_i+1)^{\delta_\LL(f_i)}$ divisors of $f_i^{m_i}$ in $\LL[x]$. Hence, we get $$ N=\prod_{i=1}^s (m_i+1)^{\delta_\LL(f_i)}.$$

By item 3 of Theorem \ref{Mcequal1}, an $M$-code $\Cc$ with generator $g$ satisfies $M_1(\Cc)\neq 1$ if and only if $g_i\nmid f_i^{m_i-1}$ for all $i\in\left\llbracket 1,s\right\rrbracket$. Therefore, the number $N'$ of codes satisfying the required property is $$N'=\prod_{i=1}^s \left((m_i+1)^{\delta_\LL(f_i)}- m_i^{\delta_\LL(f_i)}\right).$$
Since $\mathbb{P}=\dfrac{N'}{N}$, we get the required formula.

To prove the rest of the theorem, note first that, for all $P\in \LL[x]$ of degree $\geq 1$, we have 
$1\leq \delta_\LL(P)\leq \deg(P)$. Moreover, we have 
$\delta_\LL(P)=1$ if and only if $P$ is irreducible in $\LL[x]$, and  $\delta_\LL(P)=\deg(P)$ if and only if $P$  totally splits in $\LL[x]$.

That being said, for all $i\in\left\llbracket 1,s\right\rrbracket$, we have  $1\leq \delta_\LL(f_i)\leq \deg(f_i)$, and thus $$1-\dfrac{m_i}{m_i+1}\leq\left( 1- \left(\dfrac{m_i}{m_i+1}\right)^{\delta_{\LL}(f_i)}\right)\leq\left( 1- \left(\dfrac{m_i}{m_i+1}\right)^{\deg(f_i)}\right) \ \mbox{ for all }i\in\left\llbracket 1,s\right\rrbracket.$$
Multiplying everything yields the desired inequality.


Moreover, the lower bound is attained if and only if we have $\dfrac{m_i}{m_i+1}=\left( \dfrac{m_i}{m_i+1}\right)^{\delta_\LL(f_i)}$ for all $i\in\left\llbracket 1,s\right\rrbracket$, that is $  \delta_\LL(f_i)=1$ for all  $i\in\left\llbracket 1,s\right\rrbracket$, which is equivalent to say that $f_i$ is irreducible in $\LL[x]$ for all \ $i\in\left\llbracket 1,s\right\rrbracket$. This is also equivalent to the fact that  all non-zero $M$-cyclic codes have first rank weight equal to $1$ by Corollary \ref{allM11}.

A similar reasoning shows that the upper bound is attained if and only if each $f_i$ splits completely in $\LL[x]$, which is equivalent to say that $f$ splits completely in $\LL[x]$. 
\end{proof}

We would like now to apply the previous theorem when $\KK$ and $\LL$ are finite fields. First, recall the following lemma (cf. \cite[Theorem 3.46]{LidlNiederreiter}).

\begin{lemma}\label{lemfactofinite}
Let $f\in\FF_q[x]$ be a monic irreducible polynomial, and let $m\geq 1$. Then $f$ factors in $\FF_{q^m}[x]$  as the product of $d$ monic irreducible polynomials of same degree $\dfrac{\deg(f)}{d}$, where $d={\rm gcd}(m,\deg(f))$.
\end{lemma}  

The following corollary is then immediate, taking into account that all irreducible polynomials of $\FF_q[x]$ are separable.



\begin{corollary}\label{coroDenombrementfq}

      Let $M\in{\rm M}_n(\FF_q)$ be a cyclic matrix with minimal polynomial $f\in\FF_q[x]$. Write  $f=f_1^{m_1}\cdots f_s^{m_s}$, where $f_1,\ldots,f_s\in\FF_q[x]$ are pairwise distinct irreducible monic polynomials of $\FF_q[x]$, and $m_1,\ldots,m_s\geq 1$.



    \noindent Then, the proportion $\mathbb{P}$ of $M$-cyclic codes  $\Cc\subset\FF_{q^m}^n$ with minimal rank distance different from $1$ is $$\mathbb{P} = \displaystyle \prod_{i=1}^s\left( 1- \left(\dfrac{m_i}{m_i+1}\right)^{{\rm gcd}(m,\deg(f_i))}\right).$$

    In particular, we have $$\prod_{i=1}^s\dfrac{1}{m_i+1}\leq \mathbb{P}\leq \prod_{i=1}^s\left( 1- \left(\dfrac{m_i}{m_i+1}\right)^{\deg(f_i)}\right).$$

Moreover :
    \begin{enumerate}
        \item we have $\mathbb{P}=\displaystyle\prod_{i=1}^s\dfrac{1}{m_i+1}$ if and only if any of the following equivalent conditions is satisfied:
\\        
        \begin {enumerate}

        \item ${\rm gcd}(m,\deg(f_i))=1$ for all $i\in\left\llbracket 1,s\right\rrbracket$
\\
        \item $f_i$ is irreducible in $\LL[x]$ for all $i\in\left\llbracket 1,s\right\rrbracket$
  \\      
        \item all non-zero $M$-cyclic codes have first rank weight equal to $1$
        \end{enumerate}
\medskip 
        \item we have $\mathbb{P}=\displaystyle \prod_{i=1}^s\left( 1- \left(\dfrac{m_i}{m_i+1}\right)^{\deg(f_i)}\right)$  if and only if  any of the following equivalent conditions is satisfied:
   \\     
        \begin{enumerate}
         \item $\deg(f_i)\mid m$ for all $i\in\left\llbracket 1,s\right\rrbracket$
\\
    \item $f$ totally splits in $\LL[x]$.
    \end{enumerate}
    \end{enumerate}
\end{corollary}

We conclude this section by applying this corollary to cyclic codes. To do so, we need some results about the factorization of $x^n-1$ over finite fields. We then recall the following facts. 

\begin{definition}(\cite[Definition 2.44]{LidlNiederreiter})\label{defcycloto}
    Let $q$ be a prime power, and let $n$ be a positive integer coprime to $q$. Let us denote by $\zeta\in\overline{\FF}_q$ a primitive $n$-th root of unity. The {\it $n$-th cyclotomic polynomial} over $\FF_q$ is $$\Phi_{n,\FF_q} = \prod_{\substack{s=1 \\ {\rm gcd}(s,n)=1}}^n(x-\zeta^s).$$
    One may show that $\Phi_{n,\FF_q}\in\FF_q[x]$.
\end{definition}

\begin{theorem}(\cite[Theorems 2.45 and 2.47]{LidlNiederreiter})\label{lemmeordrecycloto}
    Let $q$ be a prime power, and let $n$ be a positive integer coprime to $q$. Then, the following properties hold:

    \begin{enumerate}
        \item we have  $x^n-1 = \displaystyle \prod_{d\vert n}\Phi_{d,\FF_q}$;
        \\
        \\
        \item the polynomial $\Phi_{n,\FF_q}$ factors into $\dfrac{\varphi(n)}{o_n(q)}$ pairwise distinct monic irreducible polynomials  of the same degree $o_n(q)$ in $\FF_q[x]$, where $\varphi(n)$ is the Euler totient function and $o_n(q)$ is the multiplicative order of $q$ in $(\mathbb{Z}/d\mathbb{Z})^\times$.
    \end{enumerate}
\end{theorem}

We then get the following result.

\begin{corollary} \label{denombCYCLIC}
    Let $n$ be a positive integer, $q$ a prime power integer, and assume that $gcd(q,n)=1$. 

    Let $ t_{d,q} = \dfrac{\varphi(d)}{o_d(q)}$ and $n_{d,q} = \dfrac{o_d(q)}{o_d(q^m)}$, where $\varphi$ is the Euler's totient function and $o_d(q)$ is the multiplicative order of $q$ in $(\mathbb{Z}/d\mathbb{Z})^\times$.

    Finally, set $s=\displaystyle\sum_{d\mid n}t_{d,q}$.


    Then, the proportion of cyclic codes in $\FF_{q^m}[x]/(x^n-1)$ of minimal rank distance different from $1$ is $$\mathbb{P} = \displaystyle \prod_{d\vert n} (1-2^{-n_{d,q}})^{t_{d,q}}.$$
In particular, $$\dfrac{1}{2^s}\leq \mathbb{P}\leq \prod_{d\vert n} (1-2^{-o_d(q)})^{t_{d,q}}$$
Moreover :
    \begin{enumerate}
        \item we have $\mathbb{P}=\dfrac{1}{2^s}$ if and only if any of the following equivalent conditions is satisfied:
\\        
        \begin {enumerate}

        \item ${\rm gcd}(m,o_n(q))=1$ 
\\
        \item $f_i$ is irreducible in $\FF_{q^m}[x]$ for all $i\in\left\llbracket 1,s\right\rrbracket$
  \\      
        \item all non-zero $M$-cyclic codes have first rank weight equal to $1$
        \end{enumerate}

        \medskip

        \item we have $\mathbb{P}=\displaystyle  \prod_{d\vert n} (1-2^{-o_d(q)})^{t_{d,q}}$ iif and only if if and only if any of the following equivalent conditions is satisfied:
   \\     
        \begin{enumerate}
         \item $o_n(q)\mid m$
\\
    \item $f$ totally splits in $\FF_{q^m}[x]$.
    \end{enumerate}
    \end{enumerate}
\end{corollary}

\begin{proof}
    A cyclic code is just a $C_{x^n-1}$-code, so $f = x^n-1$. 

    Since $n$ is coprime to $q$, we know that $f = x^n-1 = \displaystyle\prod_{d\vert n} \Phi_{d,\FF_q}$. Using Theorem \ref{lemmeordrecycloto}, we get that for all $d\mid n$, 
    $\Phi_{d,\FF_q}$ splits into $t_{d,q}=\dfrac{\varphi(d)}{o_d(q)}$ irreducible polynomials in $\FF_q[x]$, each one of degree of $o_d(q)$.

In particular, $x^n-1$ splits into $s=\displaystyle\sum_{d\mid n} t_{d,q}$ pairwise distinct irreducible factors in $\FF_q[x]$. 

Now, by Lemma \ref{lemfactofinite}, each irreducible factor of degree $d$ splits into ${\rm gcd}(m, o_d(q))=n_{d,q}$ irreducible factors in $\FF_{q^m}[x]$. Everything then follows from Corollary \ref{coroDenombrementfq}, after noticing that $o_d(q)\mid o_n(q)$ for all $d\mid n$ in order to get the last part.
\end{proof}

\begin{remark}\label{remarqueConsta}
   It would be tempting to apply the result of this section to other families of codes, such as constacyclic codes. 
   In \cite[Theorem $18$]{Graner}, an explicit factorization of $x^n-a\in\FF_q[x]$ is proposed when $n$ is coprime to $q$. However, the formula is quite cumbersome, and the degrees of the various irreducible factors, as well as the number of irreducible factors of prescribed degree, do not seem very easy to compute. Anyway, the resulting formula for $\mathbb{P}$ would be probably complicated and not very enlightening.


   However, the case of negacyclic codes may be handled quite easily. Indeed, if $n\geq 1$ is an integer such that $2n$ is coprime to $q$, then we have $x^{2n}-1=(x^n-1)(x^n+1)$. If $n=2^rn'$, where $n'$ is odd, it is then easy to deduce that $X^n+1=\displaystyle\prod_{d'\mid n'}\Phi_{2^{r+1}d',\FF_q}$. Reasoning as in the case of cyclic codes, one may obtain results similar to those described in Corollary  \ref{denombCYCLIC}. 
   This is particularly easy when $n$ is odd, since in this case we have $x^n+1=\displaystyle\prod_{d\mid n}\Phi_{2d,\FF_q}=\displaystyle\prod_{d\mid n}\Phi_{d,\FF_q}(-x),$ and the conclusion of Corollary \ref{denombCYCLIC} holds without change.
   Details are left to the reader.
\end{remark}

\subsection{An explicit formula for the last rank distance of $M$-cyclic codes}\label{subsec-Mk}

The goal of this short section is to compute the last generalized rank distance of an $M$-cyclic code.

We start with a lemma, which is valid for arbitrary linear codes.

\begin{lemma}\label{lemmedernierpoids}
    For any linear code $\Cc \subset \LL^n$ with parameters $[n,k]$, we have $$M_k(\Cc) = n - \dim_{\KK}(\Cc^{\perp}\cap \KK^n).$$
\end{lemma}
\begin{proof}
    Using Definition \ref{DefJurriusPelik}, we get $M_k(\Cc) = \underset{\substack{\mathcal{\mathcal{D}} \subset \Cc \\ \dim (\mathcal{\mathcal{D}}) = k}}{\min} \text{wt}_R(\mathcal{\mathcal{D}}) = \text{wt}_R(\Cc)$. 

    By \cite[Remark 2.12]{BerhuyFaselGarotta}, we have ${\rm Rsupp}(\Cc) =\left({\rm  Res}(\Cc^{\perp})\right)^{\perp}$, where ${\rm Res}(\mathcal{D})$ denotes $\mathcal{D}\cap\KK$ for any $\LL$-linear subspace $\mathcal{D}$ of $\LL^n$. Hence, we get $${\rm wt}_R(\Cc) = \dim_{\KK}(\text{Rsupp}(\Cc)) = \dim_{\KK}((\mathcal{C}^{\perp}\cap \KK^n)^{\perp}) = n- \dim_{\KK}(\Cc^{\perp}\cap \KK^n).$$
\end{proof}

In order to apply this result to compute the last rank distance of $\Cc$, we need to determine $\Cc^\perp$.

Recall now that if $M$ is a cyclic matrix, then $M^t$ is also a cyclic matrix (one way to check this quickly is to use the standard fact that an $n\times n$ matrix is cyclic if and only if its minimal polynomial has degree $n$). 

Therefore, the next proposition makes sense (see also \cite{lininv}).

\begin{proposition}\label{hdual}
Let $M\in{\rm M}_n(\KK)$ be a cyclic matrix with minimal polynomial $f\in\KK[x]$. If  $\Cc$ is an $M$-cyclic code, then $\Cc^\perp$ is an $M^t$-cyclic code. 

More precisely, if $f=gh$, where $g\in\LL[x]$ is the generator polynomial of $\Cc$, then $h$ is the generator polynomial of $\Cc^\perp$.  
\end{proposition}

\begin{proof}
We first have to show that if $\cv'\in \Cc^\perp$, then so is $\cv' (M^t)^t=\cv' M$.

Assume that $\cv'\in\LL^n$ satisfies $\cv'\cv^t=0$ for all $\cv\in \Cc$. 
Then, for all $\cv\in\Cc$, we have $$(\cv' M)\cv^t=\cv'(\cv M^t)^t=0,$$
since $\cv M^t\in\Cc$ by definition of an $M$-code. 
Hence, $\Cc^\perp$ is an $M^t$-cyclic code, as required. 

Now, let ${\bf v}, {\bf w}\in\KK^n$ be cyclic vectors for $M$ and $M^t$ respectively. Keeping the notation of the proposition, if $g$ has degree $n-k$, then $\Cc=\Cc_g$ has dimension $k$. Consequently, $\Cc^\perp$ has dimension $n-k$. Note now that $h$ has degree $k$, so that $\Cc_h$  also has dimension $n-k$. Hence, to prove that $h$ is the generator polynomial of $\Cc^\perp$, it is enough to prove that $\Cc_h\subset \Cc^\perp=\Cc_g^\perp$.

But, for all $P_1,P_2\in\LL[x]$, we have $${\bf w}h(M^t)^t P_1(M^t)^t ({\bf v}g(M)^tP_2(M)^t)^t={\bf w} (hP_1P_2g)(M) {\bf v}^t={\bf w}(P_1P_2f)(M){\bf v}^t=0,$$ since $f$ is the minimal polynomial of $M$.
This concludes the proof.
\end{proof}

We may now state and prove the main theorem of this subsection.


\begin{theorem}\label{ThmDernierDistance}
Let $M\in {\rm M}_n(\KK)$ be a cyclic matrix with minimal polynomial $f\in\KK[x]$. Write $f=f_1^{m_1}\cdots f_s^{m_s}$, where $f_1,\ldots,f_s$ are pairwise distinct monic irreducible polynomials of $\KK[x]$, and $m_1,\ldots,m_s\geq 1$.

    Let $\Cc\subset \LL^n$ be an $M$-cyclic code of dimension $k$, and let $g$ be its generator polynomial.

Write $g=g_1\cdots g_s$, where $g_i\mid f_i^{m_i}$ in $\LL[x]$.

For $i\in\left\llbracket 1,s\right\rrbracket$, set $$\ell_i=\left\lbrace\begin{array}{cl}
  0 &\mbox{ if }g_i=1 \cr \min\{\ell\in\left\llbracket 1,m_i\right\rrbracket\mid\ \  g_i\mid f_i^{\ell_i}\}& \mbox{ if }g_i\neq 1 \end{array}\right.,$$

  and $$\ell'_i= \left\lbrace\begin{array}{cl}0 &\mbox{ if }g_i=f_i^{m_i} \cr \min\{\ell'\in\left\llbracket 1,m_i\right\rrbracket\mid\ \  f_i^{m_i-\ell'}\mid g_i \}& \mbox{ if }g_i\neq f_i^{m_i}\end{array}\right. .$$


    Then we have  $$M_k(\Cc) =\sum_{i=1}^s \ell'_i \deg(f_i)=\sum_{\substack{1\leq i \leq s \\ g_i\neq f_i^{m_i}}}\ell'_i\deg(f_i),$$
    as well as 
    $$M_{n-k}(\Cc^{\perp}) =   \sum_{i=1}^s \ell_i \deg(f_i)= \sum_{\substack{1\leq i \leq s \\ {\rm gcd}(g, f_i) \neq 1}}\ell_i \deg(f_i).$$
\end{theorem}

\begin{proof}
The previous lemma shows that $M_{n-k}(\Cc^\perp) = n - \dim_{\KK}(\Cc\cap \KK^n)$. The second equality is then a direct application of Theorem \ref{Mcequal1}.

Now, recall from Proposition \ref{hdual} that $\Cc^\perp$ is an $M^t$-cyclic code, with generator polynomial $h$, where $f=gh$. Write $h=h_1\cdots h_s$, where $h_i\mid f_i^{m_i}$ in $\LL[x]$. Then we have $h_i=1$ if and only if $g_i=f_i^{m_i}$ and furthermore, for all $\ell'\in \left\llbracket 1, m_i \right\rrbracket$, we have $h_i\mid f_i^{\ell'}$ if and only if $f_i^{m_i-\ell'}\mid g_i$. 



Since $M^t$ has minimal polynomial $f$, we may apply Theorem \ref{Mcequal1} to get the first equality.
\end{proof}

\begin{corollary}
Let $M\in {\rm M}_n(\KK)$ be a cyclic matrix with minimal polynomial $f\in\KK[x]$. Write $f=f_1^{m_1}\cdots f_s^{m_s}$, where $f_1,\ldots,f_s$ are pairwise distinct monic irreducible polynomials of $\KK[x]$, and $m_1,\ldots,m_s\geq 1$.

    Let $\Cc\subset \LL^n$ be an $M$-cyclic code of dimension $k$, and let $g$ be its generator polynomial.
    Then we have  $M_k(\Cc) = n$ if and only if $f_i\nmid g$ for all $i\in\left\llbracket 1,s\right\rrbracket$.
\end{corollary}

\begin{proof}
  With the notation of the previous theorem, we have $M_k(\Cc)=n$ if and only if $\ell'_i=m_i$ for all $i\in\left\llbracket 1,s\right\rrbracket$. Now, note that $\ell'_i<m_i$ if and only if $f_i\mid g_i$. The result follows, taking into account that $f_i\mid g_i$ is equivalent to $f_i\mid g$.  
\end{proof}

\begin{example}\label{exmkMcyclicctd}
Let us continue Example \ref{exmkMcyclic}. 

Recall that $\KK=\FF_3, \LL=\FF_{3^{10}}$,  $M=C_f\in {\rm M}_9(\KK)$, where $$f=(x^2+1)^2(x+1)^3(x-1)^2.$$ Now, we consider  $g=(x-i)(x+1)^2(x-1)^2\in\LL[x]$, where  $i\in\LL$ satisfies $i^2=-1$. Then $\Cc_g$ has dimension $4$.

Since $f_1=x^2+1, f_2=x+1, f_3=x-1$, we have $\ell'_1=2, \ell'_2=1$ and $\ell'_3=0$, and thus $M_4(\Cc_g)=5$.

In particular, the bound proposed in Corollary \ref{coroweightMcyclic} is not sharp.
\end{example}
Once again, when $f$ is square-free, the results may be translated in a nicer way.

\begin{theorem}\label{ThmDernierDistancesqfree}
Let $M\in {\rm M}_n(\KK)$ be a cyclic matrix with minimal polynomial $f\in\KK[x]$. Assume that $f$ is square-free, and write $f=f_1\cdots f_s$, where $f_1,\ldots,f_s$ are pairwise distinct monic irreducible polynomials of $\KK[x]$.

    Let $\Cc\subset \LL^n$ be an $M$-cyclic code of dimension $k$, and let $g$ be its generator polynomial.

    Then we have  $$M_k(\Cc) = \sum_{\substack{1\leq i \leq s \\ f_i\nmid g}}  \deg(f_i)= n \ -  \sum_{\substack{1\leq i \leq s \\ f_i\mid g}}  \deg(f_i),$$
    as well as 
    $$M_{n-k}(\Cc^{\perp}) =  \sum_{\substack{1\leq i \leq s \\ {\rm gcd}(g, f_i) \neq 1}}\hspace{-0.3cm}\deg(f_i)= n \ - \hspace{-0.35cm} \sum_{\substack{1\leq i \leq s \\ {\rm gcd}(g, f_i) =1}}\hspace{-0.3cm}\deg(f_i).$$
\end{theorem}


\begin{example}
    Let $\KK=\FF_7$ and $\LL=\FF_{7^4}$, and let us consider the $[4,2]$-cyclic code $\Cc \subset \FF_{7^4}^4$ generated by $g = (x-1)(x-(4\omega^2-2))$, where $\omega$ is a generator of the cyclic group $\FF_{7^4}^\times$ satisfying $\omega^4 = \omega^2+1$. In particular $(1,\omega,\omega^2,\omega^3)$ is an $\FF_7$-basis of $\FF_{7^4}$. 

We have $x^4-1=(x-1)(x+1)(x^2+1)\in\FF_7[x]$. 



    Since ${\rm gcd}(g,x+1)=1$, we have $M_1(\Cc)=1$ by Theorem \ref{Mcequal1}. 
     Now, the only irreducible divisor of $x^4-1$ in $\FF_7[x]$ dividing $g$ is $x-1$, so Theorem \ref{ThmDernierDistance} gives us $M_2(\Cc) = 4 - \deg(x-1) = 3$. 

    One may recover this result directly as follows. Any codeword $\cv\in\Cc$ has the form $\cv=(a\alpha+b, -a(\alpha+1)+b\alpha, a-b\alpha,b)$ for some $a,b\in\LL$, where  $\alpha=4\omega^2-2$. Now, easy manipulations show that $${\rm Span}_\KK(a\alpha+b, -a(\alpha+1)+b\alpha, a-b\alpha,b)={\rm Span}_\KK(a\alpha, a-b\alpha,0,b).$$
    In particular, ${\rm wt}_R(\cv) \leq 3$ for all $\cv\in\Cc$. Moreover, for $a=\omega^2$ and $b=\omega$, one may check that $a\alpha, a-b\alpha$ and $b$ are $\KK$-linearly independent, so that the corresponding codeword has rank weight equal to $3$. By Remark \ref{remarkmaxrank}, we finally get that $M_2(\Cc)=3$.
\end{example}


\begin{remark}
When $f$ is square-free, the fact that $g_i\neq f_i$ is equivalent to say that $f_i\nmid g$, and the previous theorem shows that the bound of Corollary \ref{coroweightMcyclic} is sharp.    
\end{remark}

\section{Conclusion}

In this paper, we  studied the rank weight hierarchy for the so-called class of $M$-codes over an arbitrary field extension. The study of the generalized weights of this class is very relevant since it encompasses lots of well-known codes such as cyclic codes, quasi-cyclic codes and polynomial codes. 
We obtained upper bounds for the rank weight hierarchy of such codes, generalizing the work of \cite{Limoggier} for quasi-cyclic codes. Along the way, we derived a necessary condition for the existence of an MRD $M$-code in terms of the minimal polynomial of $M$, generalizing the fact that no cyclic codes are MRD. 
Finally, we studied a natural generalization of $f$-polynomial codes, namely $M$-cyclic codes, which corresponds to the case where $M$ is a cyclic matrix. We gave a necessary and sufficient condition for an $M$-cyclic code to have the first rank weight equals to $1$ in terms of its generator polynomial, and studied the proportion of such codes, with an application to cyclic and negacyclic codes. Finally, we obtained closed-form formulas for the last generalized rank weight of a $M$-cyclic code and its dual.










