%\[		 f_1=\De_1(f_0)+\sum_{i=1}^{I}\sum_{j=1}^{J}\sum_{\lambda\in \Lambda_{i,j}}\frac{a_{i,j,\lambda}}{\lambda(b_i^j)},\]
