Using the $g_0$ that was obtained by Abramov's reduction~\eqref{eq:reductionformula},
we define an exact WZ-form $\omega_0:= \bigl(\De_1(g_0),\ldots,\De_n(g_0)\bigr)$,
which we remove from the given WZ-form~$\omega$. To this end, we let
$\widetilde{f}_i:=f_i-\De_i(g_0)$ and observe that $\bigl(\widetilde{f}_1,\ldots,\widetilde{f}_n\bigr)$ is still a WZ-form, which implies that for each $k\in \{2,\ldots,n\}$, $\De_{k}(\widetilde{f}_1)$
is $ \si_{1} $-summable. Note that $ \sum_{i=1}^{I}\sum_{j=1}^{J}\widetilde{f}_{1,i,j} $ is the orbital decomposition of $\widetilde{f}_1 $ with respect to $ x_1 $ and $ G $. By Theorem~\ref{thm:decompkeepprop}, for each $ i,j$, we have $\De_k\bigl(\widetilde{f}_{1,i,j}\bigr) $ is $ \si_1 $-summable. Then we can focus on each orbital component of $\widetilde{f}_1$ in a linear $K(\xh)$-subspace $ U_{b,m}^G $.

%Furthermore, we will do some proper arrangements of the orbits, probably separating out an exact WZ-pair with respect to $(\De_1,\De_k)$, and then apply the bivariate strategy to get one element w.r.t.~$\si_1,\si_k$ in the isotropy group of $ f_1-\De_1(f_0) $. Combining these cases together it comes out the integer-linearity that we expect.
\begin{remark}\label{rmk:pairwise}
  We claim that $a\in K(\x)\setminus K(\xh)$ is pairwise shift-invariant if
  and only if for each $ k\in \{2,\ldots,n\} $, there exist $L_k, N_k\in \bZ$
  with $L_k \neq 0$, such that $ \si_{k}^{L_k}(a)=\si_{1}^{N_k} (a)$. The
  necessity follows from Definition~\ref{def:shiftinvariant}. For the
  sufficiency, we combine for any $k,s\in \{2,\ldots,n\}$ the
  $N_s$-fold application of $ \si_{k}^{L_k}(a)=\si_{1}^{N_k} (a)$
  with the $N_k$-fold application of  $ \si_{s}^{L_s}(a)=\si_{1}^{N_s} (a)$ to obtain
  \[
    \si_k^{L_kN_s}(a)=\si_1^{N_kN_s}(a)=\si_{s}^{L_sN_k}(a).
  \]
  If $ N_k=N_s=0 $, then $ a $ is free of $ x_k$ and $x_s $ which implies that
  $\si_k^{1}(a)=\si_s^{1}(a) $.
\end{remark}	
\begin{lemma}\label{lemma:subspaceWZ-forms}
	Let $ f_1= \sum_{\lambda\in \Lambda}{a_{\lambda}}/{\lambda(b^m)}\in U_{b,m}^G $ with $ \Lambda\subset E $ and the $ \lambda(b)$ being in distinct $\left\langle \si_1 \right\rangle  $-orbits. If $ \De_{k}(f_1) $ is $ \si_{1} $-summable for each $ k\in \{2,\ldots,n\} $, then all of the $ a_{\lambda} $ and $ b $ are integer-linear of the same type.
\end{lemma}
\begin{proof}
	By Remark~\ref{rmk:pairwise} and Lemma~\ref{lemma:pairwiseinteger}, it is sufficient to show that for each $ k\in \{2,\ldots,n\} $, there exist $ L_k, N_k \in \bZ  $  with $ L_k $ nonzero such that $ \si_{k}^{L_k}(b)=\si_{1}^{N_k} (b)$ and $ \si_{k}^{L_k}(a_{\lambda})=\si_{1}^{N_k} (a_{\lambda})$ for all $ \lambda\in \Lambda$. Let $ E_k:=\left\langle \si_2,\ldots,\si_{k-1},\si_{k+1},\ldots,\si_n\right\rangle $.
	For each $ \lambda\in \Lambda \subset E $, there exist $ t_{\lambda}\in \bZ, \ \eta_{\lambda}\in E_k  $ such that $ \lambda=\si_k^{t_\lambda}\eta_{\lambda} $, and therefore
	\[f_1=\sum_{\lambda \in \Lambda }\frac{a_{\lambda}}{\si_k^{t_\lambda}\eta_{\lambda}(b^m)}.\]
%	Assume that $ \eta_{\lambda}(b)\sim_{\left\langle \si_1,\si_k \right\rangle }\eta_{\lambda'}(b) $, i.e., there exist integers $ s , w $ such that $ \eta_{\lambda'}(b)=\si_1^s\si_k^w \eta_{\lambda}(b) $, applying the reduction formula~\eqref{eq:reductionformula} yields
%	\[
%	\frac{a_{\lambda'}}{\si_k^{t_{\lambda'}}\eta_{\lambda'}(b^m)}=\De_1(g)+\frac{\si_1^{-s}(a_{\lambda'})}{\si_k^{t_{\lambda'}+w}\eta_{\lambda}(b^m)},
%	\]
%	for some $g\in K(\x)$ of the form~\eqref{eq:reductiong}.
%	\[ g=
%	\begin{cases}
%	\sum_{i=0}^{s-1}\frac{\si_1^{i-s}(a_{\lambda'})}{\si_{1}^{i}\si_k^{t_{\lambda'}+w}\eta_{\lambda}(b^m)}, &\text{if }  s\geq 0 ;\\[0.7em]
%	-\sum_{i=s}^{-1}\frac{\si_1^{i-s}(a_{\lambda'})}{\si_{1}^{i}\si_k^{t_{\lambda'}+w}\eta_{\lambda}(b^m)}, &\text{if }  s<0.	
%	\end{cases}
%	\]
	By applying the reduction formula~\eqref{eq:reductionformula} once again, we can rewrite $ f_1 $ in the form
	\begin{equation}\label{eq:rewritef1}
	f_1=\De_1(f_{1,k})+\sum_{\eta\in \Lambda_k}\sum_{\ell=0}^{T_{\eta}}\frac{\widetilde{a}_{\eta,\ell}}{\si_{k}^{\ell}\eta(b^m)},
	\end{equation}
	where $\Lambda_k\subset E_k$, $ \eta(b)\not\sim_{\left\langle \si_1,\si_k\right\rangle } \eta'(b)$ if $ \eta\neq \eta' $, $ \si_k^{\ell}(b)\not\sim_{\left\langle \si_1 \right\rangle }\si_k^{\ell'}(b)$ if $\ell\neq \ell' $, and $ \widetilde{a}_{\eta,T_\eta}\neq 0 $ for each~$ \eta  $. Furthermore, we assume that this representation is such that $T_\eta \geq0 $ is as small as possible.
	Note that $ \sum_{\ell=0}^{T_{\eta}} {\widetilde{a}_{\eta,\ell}}/{\si_k^{\ell}\eta(b^m)}\in U_{\eta(b),m}^{ \left\langle \si_1,\si_k\right\rangle }$. Recall that by our assumption $ \De_k(f_1) $ is $ \si_1 $-summable. Then by Theorem~\ref{thm:decompkeepprop}, we have that $ \De_k\Bigl(\sum_{\ell=0}^{T_{\eta}} {\widetilde{a}_{\eta,\ell}}/{\si_k^{\ell}\eta(b^m)}\Bigr) $ is $ \si_1 $-summable for each~$\eta$.  Now Lemma~\ref{lemma:cyclicproof} implies that there exist integers $ S_{\eta} $ such that
\begin{gather}
  \si_k^{T_{\eta}+1}\bigl(\eta(b)\bigr) = \si_1^{S_{\eta}}\bigl(\eta(b)\bigr),
  \label{eq:shiftinvarianceofb}\\
  \si_k^{T_{\eta}+1}(\widetilde{a}_{\eta,0}) = \si_1^{S_{\eta}}(\widetilde{a}_{\eta,0}),
  \label{eq:shiftinvarianceofa}\\
  \widetilde{a}_{\eta,\ell} = \si_k^{\ell}(\widetilde{a}_{\eta,0}),\quad
  \forall \ell\in \{0,\ldots,T_{\eta}\}.
  \label{eq:shiftstepofa}
\end{gather}
Applying $\eta^{-1}$ to both sides of Equation~\eqref{eq:shiftinvarianceofb} yields
$\si_k^{T_{\eta}+1}(b)=\si_1^{S_{\eta}}(b)$ since $ G $ is commutative.
Since the $ \si_k^\ell(b) $ are in distinct $ \left\langle \si_1\right\rangle$-orbits,
we have $ T_{\eta}=T_{\eta'}$ and  $S_{\eta}=S_{\eta'}$ for any two
$\eta, \eta' \in \Lambda_k$. Let $ L_k:=T_{\eta}+1 $ and $ N_k:=S_\eta $, then $ L_k $
is the minimal positive integer such that
$ \si_k^{L_k}(b)\sim_{\left\langle \si_1\right\rangle } b $ and
$\si_k^{L_k}(b)=\si_1^{N_k}(b) $. According to Equations~\eqref{eq:shiftinvarianceofa}
and~\eqref{eq:shiftstepofa}, we have
$\si_k^{L_k}(\widetilde{a}_{\eta,\ell})=\si_1^{N_k}(\widetilde{a}_{\eta,\ell})$
for each~$\eta$ and~$\ell$. We observe that
\[
  \res_{\si_{1}}\bigl(f_1,\lambda(b),m\bigr)=[a_{\lambda}]
  \quad \text{and} \quad
  \res_{\si_1}\bigl(f_1,\si_k^{\ell}\eta(b),m\bigr)=[\widetilde{a}_{\eta,\ell}].
\]
	For each $ \lambda\in \Lambda $, there exists a unique pair $ (\eta,\ell) $ where $  \eta\in \Lambda_k,\ell\in \{0,\ldots,T_{\eta}\}$ such that $ \lambda(b)\sim_{\left\langle \si_1 \right\rangle }  \si_k^\ell\eta(b)$. By Definition~\ref{def:polynomialresidue} we have $a_{\lambda}\sim_{\left\langle \si_1 \right\rangle }\widetilde{a}_{\eta,\ell}   $.
	Now Lemma~\ref{lemma:isotropygroupinvariant} implies that $\si_k^{L_k}(a_\lambda)=\si_1^{N_k}(a_\lambda)$.
\end{proof}

We are now ready to give the proof of Theorem~\ref{thm:decompthm}.
\begin{proof}
  We proceed by induction on~$n$. For the base case $n=1$, the theorem follows
  from the fact that any univariate rational function is a uniform WZ-form.
  % For $n=2$, it follows from Theorem~\ref{thm:structureWZ-pairs}.
  For $n\geq 2$ suppose that the theorem holds for any WZ-forms in $n-1$ variables.
  As in Lemma~\ref{lemma:subspaceWZ-forms}, we focus on each component of
  the orbital decomposition of~$f_1$ and rewrite it as in~\eqref{eq:rewritef1}.
  Next we use the cyclic operator to describe $ f_1 $ in a more precise way as
  \[
    f_1=\De_1(f_{1,k})+\frac{\si_k^{L_k}-1}{\si_k-1}\bullet
    \sum_{\eta\in \Lambda_k}\frac{\widetilde{a}_{\eta,0}}{\eta(b^m)}.
  \]
  Suppose that $L_k,N_k\in \bZ$ with $L_k\neq0$ such that
  \[
    \si_k^{L_k}\Biggl(\frac{\widetilde{a}_{\eta,0}}{\eta(b^m)}\Biggr) =
    \si_1^{N_k}\Biggl(\frac{\widetilde{a}_{\eta,0}}{\eta(b^m)}\Biggr) .
  \]
  For each $ k\in \{2,\ldots,n\} $, let
  \[
    f_k'= \De_k(f_{1,k})+\frac{\si_1^{N_k}-1}{\si_1-1} \bullet
    \sum_{\eta\in \Lambda_k}\frac{\widetilde{a}_{\eta,0}}{\eta(b^m)}.
  \]
  Then one can easily check that $ \De_k(f_1)=\De_1(f_k') $ with $ f_k' $ and $ f_1 $ being integer-linear of the same type. For $ k,\ell \in \{2,\ldots,n\} $ with $ k\neq \ell  $, we have
	$	\De_k(f_1)=\De_1(f_k') $ and $\De_\ell(f_1)=\De_1(f_\ell')$, from which it follows that
	\[
	\De_\ell\De_1(f_k')=\De_\ell\De_k(f_1)=\De_k\De_1(f_\ell').
	\]

Thus $ \De_1\bigl(\De_\ell(f_k')-\De_k(f_\ell')\bigr)=0 $, i.e., $ \De_\ell(f_k')-\De_k(f_\ell')\in K(\xh) $. By construction, we have $ f_{1,k}\in U_{b,m}^G $ and $ f_2',\ldots,f_n' \in U_{b,m}^G$. By Lemma~\ref{lemma:invariantspace}, also $\De_\ell(f_k')-\De_k(f_\ell')$ is an element of $ U_{b,m}^G$. According to the definition of $  U_{b,m}^G $ in~(\ref{eq:orbitalsubspace}), one has
\[
  U_{b,m}^G \cap K(\xh)=\{0\}.
\]
Thus $ \De_\ell(f_k')-\De_k(f_\ell')=0 $.
By Definition~\ref{def:uniformWZ-formdefinition}, $ (f_1,f_2',\ldots,f_n') $ is a uniform WZ-form in $U_{b,m}^G$, denoted by $\omega_{i,j}$ for some $i,j$.

In conclusion, from the orbital decomposition of~$f_1$, we can obtain a
WZ-form $(f_1,f_2',\ldots,f_n')$ which is one exact WZ-form $\omega_0$ plus
several uniform WZ-forms~$\omega_{i,j}$. Note that there may remain a WZ-form
of the form $ (0,f_2-f_2',\ldots,f_n-f_n')$. From the compatibility
conditions~\eqref{eq:compatiblehyperarithmetic}, we have for each
$ k\in \{2,\ldots,n\} $ that $ \De_1(f_k-f_k')=\De_k(0)=0 $, so
$ f_k-f_k' \in K(\xh)$. Hence the remaining form can be viewed as an
$(n-1)$-variable WZ-form w.r.t.~$(\De_2,\ldots,\De_n)$. By the induction
hypothesis, the proof is completed.
\end{proof}
Note that this decomposition is not unique, because of two aspects.
When a WZ-form is both exact and uniform, see Remark~\ref{rmk:exactuniform},
we choose to put it into the exact part, which minimizes the uniform part.
Second, the final result depends on the operators in~$G$ that are chosen
for the orbital decomposition.
Next we give an example to illustrate how the decomposition works.
\begin{example}\label{ex:tripleWZ}
  Let $ \omega=(f,g,h)\in K(x,y,z)^3 $ be a WZ-form with
  \begin{align*}
    f &= \sum_{\ell=0}^{3}\frac{1}{4x+6y+5z+\ell},\\
    g &= \sum_{\ell=0}^{5}\frac{1}{4x+6y+5z+\ell}+\sum_{\ell=0}^{2}\frac{1}{3y+2z+\ell},\\
    h &= \sum_{\ell=0}^{4}\frac{1}{4x+6y+5z+\ell}+\sum_{\ell=0}^{1}\frac{1}{3y+2z+\ell}.
  \end{align*}
  It is easy to check that $(f,g,h)$ satisfy the following compatibility conditions:
  \[
    \big\lbrace\De_y(f)=\De_x(g), \ \De_z(f)=\De_x(h),  \ \De_z(g)=\De_y(h)\big\rbrace.
  \]
  Let $b=4x+6y+5z$ be the same as in Example~\ref{ex:orbitalresidue}, while
  the rational function~$f$ here is different. In terms of~$b$ it can be
  written as
  \[
    f=\frac{1}{b}+\frac{1}{\si_x^{-1}\si_z(b)}+
    \frac{1}{\si_x^{-1}\si_y(b)}+\frac{1}{\si_x^{-3}\si_z^{3}(b)},
  \]
  but note that this representation is not unique.
  Similarly, let $c=3y+2z$ and rewrite
  \[
    \sum_{\ell=0}^{2}\frac{1}{3y+2z+\ell}=
    \frac{1}{c}+\frac{1}{\si_{y}^{-1}\si_z^{2}(c)}+\frac{1}{\si_z(c)}.
  \]
  Then we can decompose~$\omega$ into an exact WZ-form plus two uniform WZ-forms:
	\begin{align*}
		f&=\De_x(a+\bar{a}) + \biggl(\De_x(a_2)+ \frac{\si_y^2-1}{\si_y-1}\cdot\frac{\si_z^2-1}{\si_z-1}\bullet \dfrac{1}{b} \biggr) +
		\frac{\si_y^0-1}{\si_y-1}\cdot\frac{\si_z^3-1}{\si_z-1}\bullet \frac{1}{c}\\
		&=\De_x(a+\bar{a})+\biggl(\De_x(a_3)+\frac{\si_z^4-1}{\si_z-1}\cdot \frac{\si_y-1}{\si_y-1}\bullet \dfrac{1}{b}\biggr)+\frac{\si_z^3-1}{\si_z-1}\cdot\frac{\si_y^0-1}{\si_y-1}\bullet \frac{1}{c},\\
		g&=\De_y(a+\bar{a})+\biggl( \De_y(a_2)+\frac{\si_x^3-1}{\si_x-1}\cdot \frac{\si_z^2-1}{\si_z-1}\bullet \dfrac{1}{b}\biggr) +\frac{\si_x-1}{\si_x-1}\cdot \frac{\si_z^3-1}{\si_z-1}\bullet \frac{1}{c},\\
		h&=\De_z(a+\bar{a})+\biggl(\De_z(a_3)+\frac{\si_x^5-1}{\si_x-1}\cdot\frac{\si_y-1}{\si_y-1}\bullet \dfrac{1}{b}\biggr)+\frac{\si_x-1}{\si_x-1}\cdot\frac{\si_y^2-1}{\si_y-1}\bullet \frac{1}{c}.
	\end{align*}
	where
	\begin{align*}
	    &a=-\dfrac{1}{\si_x^{-1}\si_z(b)}-\dfrac{1}{\si_x^{-1}\si_y(b)}-\dfrac{1}{\si_x^{-3}\si_z^3(b)}-\dfrac{1}{\si_x^{-2}\si_z^3(b)}-\frac{1}{\si_x^{-1}\si_z^3(b)} ,\\
		&a_2=\frac{1}{\si_y\si_z(b)},\quad
		a_3=-\dfrac{1}{\si_x^{-1}\si_z^2(b)},\quad
		\bar{a}=-\frac{1}{\si_y^{-1}\si_z^{2}(c)}.
	\end{align*}
	As we can see, the first uniform WZ-form has type~$(4,6,5)$, while
        the second one has type~$(0,3,2)$.
\end{example}


\section{Structure of uniform WZ-forms}\label{sec:uniformWZ-forms}

Theorem~\ref{thm:decompthm} tells us how every WZ-form can be decomposed into
exact and uniform WZ-forms. While exact WZ-forms are easy to describe and to
construct, Definition~\ref{def:uniformWZ-formdefinition} only allows us to
check whether a given tuple is a uniform WZ-form, but this characterization is
not explicit enough to construct such forms. In this section, we use a
difference homomorphism in order to write a uniform WZ-form in terms of its
integer-linear type and a single univariate rational function. Then we finish
our proof of the additive Ore--Sato theorem.

Let $(A,\bsi) $ and $(A,\btau) $ be two difference
rings, where $ \bsi=(\si_1,\ldots,\si_n )$ and $
\btau=(\tau_1,\ldots,\tau_n) $. A homomorphism (resp.\ isomorphism)
$ \phi\colon A  \rightarrow  A $ is called a difference homomorphism
(resp.\ isomorphism) from $(A,\bsi) $ to  $(A,\btau) $
if $ \phi \circ \si_{i}=\tau_i \circ \phi $ for each $i \in \{1,\dots,n\}$.
In other words, for each~$i$ there is a commutative diagram:
\begin{center}
  \begin{tikzcd}
    A \arrow{r}{ \si_i } \arrow{d}{ \phi }& A \arrow{d}{ \phi }\\
    A  \arrow{r}{ \tau_i } & A
  \end{tikzcd}
\end{center}

\begin{lemma}\label{lemma:differencehomomorphism}
  Given a unimodular matrix $ \mathbf{D}\in \bZ^{n\times n} $, i.e.,
  $\mathbf{D}^{-1}\in \bZ^{n \times n}$, we define a ring isomorphism
  $\phi \colon K(\x) \to  K(\x)$ by $\phi(\x)=\mathbf{D}\cdot\x$.
  Furthermore, we let the $\sigma_i$ act on vectors as
  $\sigma_i(\x)=\x+\e_i$, where $\e_i$ denotes the $i$-th unit vector.
  If we define $\tau_i(\x)=\x+\mathbf{D}^{-1}\cdot\e_i$
  for all $i\in\{1,\dots,n\}$, then $ \phi $ is a difference isomorphism
  from $ \bigl(K(\mathbf{x}),\bsi\bigr) $ to
  $\bigl(K(\mathbf{x}),\btau\bigr)$.
\end{lemma}
\begin{proof}
  We have to check that $ \phi \circ \si_{i}=\tau_i \circ \phi $. For the
  left-hand side we get
  \[
    \phi(\si_{i}(f(\x))) = \phi(f(\x+\e_i)) = f(\mathbf{D}\cdot\x+\e_i),
  \]
  and the right-hand side gives
  \[
    \tau_i(\phi(f(\x))) = \tau_i\bigl(f(\mathbf{D}\cdot\x)\bigr) =
    f\bigl(\mathbf{D}\cdot(\x+\mathbf{D}^{-1}\cdot\e_i)\bigr) = f\bigl(\mathbf{D}\cdot\x+\e_i\bigr).
  \] This completes the proof. 
\end{proof}

Given $ f_1,\ldots,f_n\in K(\x) $ satisfying the compatibility
conditions~\eqref{eq:compatiblehyperarithmetic}, then
\cite[Theorem~2]{Bronstein2005} shows that there exists a difference ring extension $
\bigl(K(\x)[H],\bsi\bigr)$ of $ \bigl(K(\x),\bsi\bigr) $, where $ H $ is a
hyperarithmetic expression with certificates~$f_1,\ldots,f_n $. A difference
homomorphism from $ \bigl(K(\x),\bsi\bigr)$ to $ \bigl(K(\x),\btau\bigr)$
can naturally be extended to the corresponding difference ring extensions.

% Work-around for citing inside [...]
\newcommand\citePropNineAP{\cite[Proposition~9]{AbramovPetkovsek2002a}}
\begin{lemma}[\citePropNineAP]\label{lemma:integermatrix}
	For every integer vector $ \mathbf{v}=(v_1,\dots,v_n) $ there is an integer matrix $ \mathbf{D}\in \mathbb{Z}^{n\times n} $ with the first row $ \mathbf{v} $ and $ \det (\mathbf{D})=\gcd (v_1,\ldots,v_n) $.
\end{lemma}

Next we use such a matrix $\mathbf{D}$ to construct the difference homomorphism.
\begin{theorem}\label{thm:structureUniWZ-forms}
	Let $ \bigl(f_1(\mathbf{v}
	\cdot \mathbf{x}),\ldots,f_n(\mathbf{v}\cdot \mathbf{x})\bigr) $ be a uniform WZ-form of type~$ \mathbf{v} $, then there exist constants $ \mu_1,\ldots,\mu_n \in K $ and a univariate rational function $r \in K(z) $ such that for each $ i\in \{1,\ldots,n\} $,
	\[
	f_i(\mathbf{v}\cdot\mathbf{x})=\mu_{i}+\sideset{}{_0^{v_i}}\sum_{\ell}r(\mathbf{v} \cdot \mathbf{x}+\ell) .
	\]
\end{theorem}
\begin{proof}
	Let $ H(\mathbf{x}) $ be a hyperarithmetic expression, and let $f_1(
	\vv\cdot\mathbf{x}),\ldots,f_n(\vv\cdot\mathbf{x})$ be its  certificates. That is to say for each $ i $,
	\begin{equation}\label{eq:hyperarithmetic}
		\si_{i}\bigl(H(\mathbf{x})\bigr)=H(\mathbf{x}) + f_i(\mathbf{v} \cdot \mathbf{x}).
	\end{equation}
	Without loss of generality, we can assume that $ \gcd(v_1,\ldots,v_n)=1 $. By Lemma~\ref{lemma:integermatrix}, there exists an integer matrix $ \mathbf{D}=(d_{ij})\in \bZ^{n\times n} $ with $ \det (\mathbf{D})=1 $ whose first row is $ \mathbf{v} $.
	Let $ \phi\colon K(\mathbf{x}) \rightarrow K(\mathbf{x}) $ such that
	\[ \phi\bigl(f(\mathbf{x})\bigr)=f\bigl(\mathbf{D}^{-1}\cdot\mathbf{x}\bigr),\ \text{for all } f(\mathbf{x})\in K(\mathbf{x}). \]
	By Lemma~\ref{lemma:differencehomomorphism}, $ \phi $ is a difference isomorphism from $ \bigl(K(\mathbf{x})[H],\bsi\bigr) $ to $ \bigl(K(\mathbf{x})[H],\btau\bigr) $, where $ \tau_i(\x)=\x+\mathbf{D}\cdot\e_i$ for all $ i $ in $\{1,\ldots,n\} $.
	Applying the operator $ \phi $ to Equation~\eqref{eq:hyperarithmetic} yields
	\begin{align*}
		\phi\bigl(\si_{i}\bigl(H(\mathbf{x})\bigr)\bigr)&=
                \phi\bigl(H(\mathbf{x})\bigr) + \phi\bigl(f_i(\mathbf{v} \cdot \mathbf{x})\bigr),\\
		\tau_i \bigl(\phi\bigl(H(\mathbf{x})\bigr) & =\phi\bigl(H(\mathbf{x})\bigr) + f_i(x_1).
	\end{align*}
	Let $ H'(\mathbf{x})=\phi\bigl(H(\mathbf{x})\bigr) $, then it follows that  $ \tau_i\bigl(H'(\mathbf{x})\bigr)=H'(\mathbf{x}) + f_i(x_1)$.
	For any integer $ m>0$ and $ i\in \{1,\ldots,n\} $ we have
	\begin{align}
	  \tau_i^{m}\bigl(H'(\mathbf{x})\bigr)&= H'(\x) + \sum_{j=0}^{m-1}f_i\bigl(x_1+jd_{1i}\bigr)
          =: H'(\x) + f_{i,m}(x_1),\label{eq:tauim}\\
	  \tau_i^{-m}\bigl(H'(\mathbf{x})\bigr) &= H'(\x) - \sum_{j=1}^{m}f_i\bigl(x_1-jd_{1i}\bigr)
          =: H'(\x) + f_{i,-m}(x_1).\label{eq:tauimm}
	\end{align}
	Let $ \mathbf{D}^{-1}=:\bigl(\widetilde{d}_{ij}\bigr)_{n\times n} $, then for all $  i\in \{1,\ldots,n\} $ we can rewrite $\si_i$ in terms of $\tau_1,\dots,\tau_n$:
	\[
	  \si_{i} = \prod_{j=1}^{n}\tau_j^{\widetilde{d}_{ji}}.
	  %= \btau^{\mathbf{D}^{-1}\cdot\e_i}
	\]
	By applying \eqref{eq:tauim} and \eqref{eq:tauimm} repeatedly, we obtain $\si_{i}\bigl(H'(\x)\bigr) = H'(\x)+f_{i}'(x_1)$ for some univariate rational function~$f_i'$.
    That is to say, $\De_i\bigl(H'(\mathbf{x})\bigr)=f_{i}'(x_1)$. By the compatibility conditions~\eqref{eq:compatiblehyperarithmetic} we have that $\De_1\bigl(f'_k(x_1)\bigr) = \De_k\bigl(f'_1(x_1)\bigr) = 0$, and thus
    $ f_k' \in K$ for all $ k\in \{2,\ldots,n\} $.
	Then an easy induction shows that
	 \[H'(\mathbf{x})\simeq F'(x_1)+\sum_{k=2}^{n}f_{k}'x_k,\]
	 where $ F'(x_1) $ is a solution of the difference equation $ y(x_1+1)-y(x_1)=f_1'(x_1) $.
	Next, we can recover $ H(\x) $ as follows,
	\begin{align*}	
		H(\x)&= \phi^{-1}\bigl(H'(\x)\bigr)\\
		&=H'\bigl(\mathbf{D}\cdot\mathbf{x}\bigr)\\
		&\simeq F'(\mathbf{v}\cdot\x)+\sum_{k=2}^{n}f_{k}'\biggl(\sum_{i=1}^{n}d_{ki}x_i\biggr) \\
		&=F'(\mathbf{v}\cdot\x)+\sum_{i=1}^{n}\biggl(\sum_{k=2}^{n}f_{k}'d_{ki}\biggr)x_i,
	\end{align*}
	where $ F'(\mathbf{v}\cdot \x+1)-F'(\mathbf{v})=f_1'(\mathbf{v}\cdot \x) $.
	Write that $ \mu_{i}:=\sum_{k=2}^{n}f_{k}'d_{ki} $. Then for each $ i\in \{1,\ldots,n\} $,
	\[
		f_i(\mathbf{v}\cdot\mathbf{x})=\De_{i}\bigl(H(\mathbf{x})\bigr)=
		\begin{cases}
			\displaystyle \ \mu_{i}+\sum_{\ell=0}^{v_i-1}f_1'(\mathbf{v} \cdot \mathbf{x}+\ell),& \text{if }  v_i > 0;\\[0.4 em]
		\ 	\mu_i , & \text{if }  v_i=0; \\[0.4 em]
		\ 	\displaystyle \mu_{i}-\sum_{\ell=v_i}^{-1}f_1'(\mathbf{v} \cdot \mathbf{x}+\ell), & \text{if }   v_i <0.
		\end{cases}
	\]
	Finally we let the univariate rational function $ r$ be defined as $ f_1' $.
\end{proof}
Eventually we obtain Theorem~\ref{thm:addOreSato} by combining
Theorems~\ref{thm:decompthm} and~\ref{thm:structureUniWZ-forms}. Note that we
can disregard the $\mu_i$ since the constant tuple $(\mu_1,\ldots,\mu_n)$
itself can be viewed as an exact WZ-form. We show that any
hyperarithmetic expression can be described, up to conjugation, as a rational
function plus a $ K $-linear combination of polygamma functions.  First we
employ the partial fraction decomposition on the univariate function $ r $
over $ K $:
\[
  r(z)=\sum_s\sum_t\frac{\beta_{s,t}}{(z+\alpha_s)^t},
\]
where $\alpha_s, \beta_{s,t} \in K$ and $s, t\in \bN $, both with finite support.

According to the recurrence formula of polygamma functions~\cite[(5.15)]{NIST:DLMF}
\[
  \psi^{(t)}(z+1)-\psi^{(t)}(z)=\frac{(-1)^tt!}{z^{t+1}},\quad t=0,1,\ldots
\]
we have
\[
  \psi^{(t)}(z+\alpha_s+1)-\psi^{(t)}(z+\alpha_s)=\frac{(-1)^tt!}{(z+\alpha_s)^{t+1}}.
\]
Then the hyperarithmetic expression $ H' $ with certificates
\[
  \Bigl( \sideset{}{_0^{v_1}}\sum_{\ell}r(\mathbf{v} \cdot \mathbf{x}+\ell),\ldots,
  \sideset{}{_0^{v_n}}\sum_{\ell}r(\mathbf{v} \cdot \mathbf{x}+\ell)\Bigr)
\]
is conjugate to
\[
  \sum_s\sum_t \frac{\beta_{s,t+1}}{(-1)^t t!}\psi^{(t)}(\mathbf{v}\cdot \x+\alpha_s).
\]
\begin{corollary}
  Any hyperarithmetic expression is conjugate to
  \[
    a+\sum_{\vv\in V}\sum_s\sum_t \beta_{\vv,s,t}\psi^{(t)}(\vv\cdot \x+\alpha_{\vv,s}),
  \]
  where $a\in K(\x)$, $ V\subset\bZ^{n} $, $ s,t\in \bN $,
  and for each $\vv$, we have $ \beta_{\vv,s,t},\alpha_{\vv,s}\in K $.
\end{corollary}
\begin{example}
	Let $ H $ be a hyperarithmetic expression with certificates~$ (f,g,h) $ as in Example~\ref{ex:tripleWZ}. Then $ H $ is conjugate to
	$ \psi^{(0)}(4x+6y+5z)+\psi^{(0)}(3y+2z)$.
\end{example}


\section{An algorithm for the minimal decomposition of WZ-forms}\label{sec:implementation}

Now we will present an algorithm for computing additive representations of WZ-forms based on the recursive idea in the proof of Theorem~\ref{thm:addOreSato}. 
{Furthermore, we require that in such a representation the uniform WZ-forms are minimal,  which we call \lq \lq the minimal decomposition\rq \rq. Therefore with this algorithm we can decide the exactness of WZ-forms by checking whether the uniform part is zero or not.  

\begin{definition}[Additive representation]
  Given a WZ-form $\omega = (f_1,\ldots,f_n)$, there is a decomposition of the form
  \[
    \omega = \bigl(\De_1(a),\ldots,\De_n(a)\bigr)+
    \sum_{\mathbf{v}\in V}\Bigl(
    \sideset{}{_0^{v_1}}\sum_{\ell}r_{\mathbf{v}}(\mathbf{v} \cdot \mathbf{x}+\ell),\ldots,
    \sideset{}{_0^{v_n}}\sum_{\ell}r_{\mathbf{v}}(\mathbf{v} \cdot \mathbf{x}+\ell) \Bigr).
  \]
  We call the list $\bigl( a, V, \{r_{\mathbf{v}}\}_{\mathbf{v}\in V} \bigr)$ an
  \emph{additive representation} of~$ \omega $. 
This decomposition is called \lq \lq minimal \rq \rq if it has minimal degree in the denominator of each~$r_{\mathbf{v}}(z)$.
\end{definition}

Let $\omega = (f_1,\ldots,f_n)\in K(\x)^n$ be a WZ-form.
First, we apply Abramov's reduction~\cite{Abramov1971}
with respect to the variable $ x_1 $ to decompose $f_1$ into
\[f_1= \De_1(g_0)+\sum_{i=1}^{I}\sum_{j=1}^{J}\frac{a_{i,j}}{b_i^j},\]
where $ g_0\in K(\xh)[x_1] $, $ a_{i,j},b_i \in K[\xh][x_1] $ with
$ \deg_{x_1}(a_{i,j})<\deg_{x_1}(b_i) $,  and the $ b_i $ are in distinct
$ \langle\si_1 \rangle$-orbits.

By Lemma~\ref{lemma:subspaceWZ-forms}, each $ {a_{i,j}}/{b_i^j} $ is
integer-linear of some type~$ \mathbf{v}_i $.
In order to compute the type of each simple fraction in the above decomposition,
we are reduced to the following problem.
\begin{problem}[Integer-linear testing]
	Given a polynomial $p\in K[\x]$, decide whether there exist $u\in K[z]$ and $\mathbf{v}\in \bZ^n$ such that $p = u(\mathbf{v}\cdot \x)$.
\end{problem}
This problem can be solved by the algorithm \texttt{IntegerLinearDecomp}~\cite{Huang2019}.
Applying it to the numerator and the denominator of each simple fraction $a_{i, j}/b_i^j$ yields
\[\frac{a_{i,j}}{b_i^j}=u_{i, j}(\mathbf{v}_i\cdot \x),\]
where $u_{i, j}\in K(z)$ and $\mathbf{v}_i\in \bZ^n$ with the first entry $v_{i, 1}$ being nonzero.
By collecting the simple fractions of the same type, we obtain
\[f_1=\De_1(g_0)+\sum_{\mathbf{v}\in V}  u_{\mathbf{v}}(\mathbf{v}\cdot \x),\]
where $V \subset \bZ^n$ is a finite set and $u_{\mathbf{v}}\in K(z)$ for each ${\mathbf{v}}\in V$.
The next step is to write the rational function $u_{\mathbf{v}}$ into the form
\[
u_{\mathbf{v}}(z)=\sideset{}{_0^{v_1}}\sum_{\ell} r_{\mathbf{v}}(z +\ell),
\]
where $r_{\mathbf{v}} \in K(z)$. Note that $r_{\mathbf{v}}$ must be a rational solution of the difference equation
\[y(z+v_1) - y(z)=u_{\mathbf{v}}(z+1) - u_{\mathbf{v}}(z),\]
which can also be solved by Abramov's reduction.

Let $ \omega_0:= \bigl(\De_1(g_0),\ldots,\De_n(g_0)\bigr) $ and $ \omega_{\mathbf{v}}:=\bigl(f_{1,\mathbf{v}},\ldots,f_{n,\mathbf{v}}\bigr) $, where for each $ k\in \{1,\ldots,n\} $,
\[
f_{k,\mathbf{v}} := \sideset{}{_0^{v_k}}\sum_{\ell} r_{\mathbf{v}}(\mathbf{v}\cdot\x +\ell).
\]
Then $ \omega $ can be written as a summation of one exact WZ-form, several uniform WZ-forms and a ``degenerate'' WZ-form:
\[
\omega= \omega_0+\sum_{\mathbf{v}\in V} \omega_{\mathbf{v}}+\widetilde{\omega}.
\]
In order to get the minimal uniform WZ-forms in the sense that the denominator of each~$r_{\mathbf{v}}$ has the lowest possible degree in~$z$, we require the application of Abramov's reduction on~$r_{\mathbf{v}}$ again. The following example illustrates that this step is needed to minimize~$r_{\mathbf{v}}$.
	\begin{example}
		Let $ \omega=(f,g,h)\in K(x,y,z)^3 $ be a WZ-form with
		\begin{align*}
			f &= \Delta_x\biggl(\frac{1}{(4x+6y+5z+1)^2}\biggr)+\sum_{\ell=0}^{3}\frac{1}{4x+6y+5z+\ell},\\
			g &= \Delta_y\biggl(\frac{1}{(4x+6y+5z+1)^2}\biggr)+ \sum_{\ell=0}^{5}\frac{1}{4x+6y+5z+\ell},\\
			h &= \Delta_z\biggl(\frac{1}{(4x+6y+5z+1)^2}\biggr)+ \sum_{\ell=0}^{4}\frac{1}{4x+6y+5z+\ell}.
		\end{align*}
		Since the residue of Abramov's reduction is not unique, we may get the following decomposition of~$f$,
		\begin{align*}
			f &= \Delta_x\left( \frac{1}{(4x+6y+5z+1)^2} - \frac{1}{4x+6y+5z+1}\right)  \\
			& + \frac{1}{4x+6y+5z} + \frac{1}{4x+6y+5z+5}+ \frac{1}{4x+6y+5z+2} + \frac{1}{4x+6y+5z+3} .
		\end{align*}
		The univariate function in~$Z$ corresponding to the uniform WZ-form is
		\[r_{\mathbf{v}}(Z) = \frac{1}{Z} - \frac{1}{Z+1} + \frac{1}{Z+2}. \]
		Obviously we would anticipate it to be~${1}/{Z}$. This accident can happen because $4x+6y+5z+1$ and $4x+6y+5z+5$ are in the same $\sigma_x$-orbit, and Abramov's reduction on~$f$ cannot see which one will lead to the minimal~$r_{\mathbf{v}}$. However, we observe that the difference is the summable part of~$r_{\mathbf{v}}$ with respect to~$Z$, which finally can be removed by modifying the exact part of~$f$. In this case,
		\[
		\sum_{\ell=0}^{3} \left(\frac{1}{Z+2+\ell} - \frac{1}{Z+1+\ell}\right) = \frac{1}{Z+5}-\frac{1}{Z+1}.
		\]
		After substituting $Z$ with~$4x+6y+5z$ on the right-hand side of the above equation, we obtain~$\Delta_x\bigl( \frac{1}{4x+6y+5z+1}\bigr)$. The modification is done by absorbing it into the previous exact part of~$f$.
	\end{example}
If $\widetilde{\omega}$ is nonzero, then we proceed with the induction step by repeating the above process for
$ \widetilde{\omega} $ which only involves $(n-1) $-variables.
The above process for computing additive representations of WZ-forms
is summarized in Algorithm~\ref{alg:WZFormDecomp} and is illustrated in
Example~\ref{ex:decomp}. Note that $\omega$ is exact if and only if the output is~$(a,\varnothing,\varnothing)$, which is equivalent to that the uniform part is zero. 
Our Maple code for implementing Algorithm~\ref{alg:WZFormDecomp} is available at
\[
\text{\url{http://www.mmrc.iss.ac.cn/~schen/AddOreSato.html}}
\]
We provide a worst-case complexity analysis of Algorithm~\ref{alg:WZFormDecomp} in terms of arithmetic operations in the base field.
Let $K[\mathbf{x}]_d$ denote the set of polynomials in $K[\mathbf{x}]$ whose degree in $x_i$ is no more than $d$ for each~$i = 1,2,\ldots,n$. Let $K(\mathbf{x})_d$ denote the set of rational functions in $K(\mathbf{x})$ with numerators and denominators in~$K[\mathbf{x}]_d$. The \lq\lq big Oh\rq\rq~notation $O$ is referred to the cost of an algorithm ``up to a constant factor" and the \lq\lq soft Oh\rq\rq~notation $\widetilde{O}$ may further neglect some logarithmic factors. We define the max-norm of the multivariate polynomial~$f = \sum_{i_1,\ldots,i_n} f_{i_1,\ldots,i_n} x_1^{i_1}\cdots x_n^{i_n} \in \mathbb{Q}[\mathbf{x}] $ as
\[ \| f \|_{\infty} = \max_{i_1,\ldots,i_n} |f_{i_1,\ldots,i_n}| .\]

We first recall some known facts on complexity estimates.
%A polynomial in $\mathbb{Q}[\mathbf{x}]$ can be factored into the product of irreducible factors with no more than $\widetilde{O}(d^{7n-1})$ operations in~$\mathbb{Q}$~\cite{ArjenK1987}.
 The irreducible factorization of a univariate polynomial~$f \in \bZ[x]$ of degree~$d \geq 1$ with max-norm $\| f \|_{\infty} =A$ takes $\widetilde{O}(d^6\cdot(d+\log A))$ operations in $\bZ$ (see~\cite[Theorem 16.23]{BookMCA2013}).
The partial fraction decomposition of an element in $K(x)_d$ with a given factorization of its denominator takes no more than $\widetilde{O}(d)$ operations in~$K$ (see~\cite[Section 5.11]{BookMCA2013}).
Multi-point evaluation and interpolation in $K[\mathbf{x}]_d$ from the given values on $O(d^m)$ points which form an $m$-dimensional tensor product grid can be done with $\widetilde{O}(md^m)$ operations in $K$ (see~\cite[Theorem 1]{JorisEric2013}).
Let $f(\mathbf{x}) = \prod_{\ell=1}^{s} \bar{f}_\ell(\mathbf{x})$ be a multivariate factorization of~$f(\mathbf{x})\in \bZ[\mathbf{x}]$ over~$\mathbb{Q}$. Then Mahler's bound in~\cite{Mahler1962} using Gelfond's inequality  leads to
\[
	\prod_{\ell=1}^{s} \|\bar{f}_\ell\|_{\infty} \leq 2^{nd}(d+1)^{n/2} \|f\|_{\infty}.
\]
According to~\cite{Huang2019}, the multivariate integer-linear decomposition of $f \in \mathbb{Z}[\mathbf{x}]$ with~$\|f\|_{\infty} = A$ takes $(n + \log A +d)^{O(1)}$ word operations.

Let~$f_1,\ldots, f_n \in \mathbb{Z}(\mathbf{x})_d$ with their max-norms bounded by~$A \in \bN$.
We claim that the total cost of Algorithm~\ref{alg:WZFormDecomp} is $\widetilde{O}\bigl(n^{O(1)}d^{O(n)}\log A\bigr)$ operations in~$\mathbb{Q}$.
The cost of the algorithm before the recursive loop (line 30  of Algorithm~\ref{alg:WZFormDecomp}) is dominated by the irreducible partial fraction decomposition of $f_1 \in \mathbb{Q}(\mathbf{x})_d$ with respect to~$x_1$,
where all simple fractions are of degree in~$x_j, \ j=2,\ldots,n $ bounded by~$d^2$.
To obtain partial fraction decompositions with respect to $x_1$ over $\bQ(x_2, \ldots, x_n)$, we take the strategy of multi-point evaluation and interpolation, i.e., first evaluating the rational function for variables  $(x_2, \ldots, x_n)$
at many points, performing the univariate irreducible partial fraction decompositions with respect to $x_1$, and then recovering the desired decompositions over $\bQ(x_2, \ldots, x_n)$ by rational interpolation.
To be sufficient for recovering the final result,  we need to evaluate~$x_2,\ldots,x_n$ at~$O(d^{2(n-1)})$ many good points which takes~$\widetilde{O}\bigl((n-1)d^{2(n-1)}\bigr)$ operations in~$\mathbb{Q}$.
For each point, the univariate irreducible partial fraction decompositions takes~$\widetilde{O}(d^6 \cdot (d+ \log A))$ operations in~$\mathbb{Q}$,
which is the dominating cost of the irreducible factorization of the denominator. Finally, we need the rational interpolation to recover~$O(d)$ coefficients in~$\bQ(x_2,\ldots,x_n)$, where each coefficient costs $\widetilde{O}\bigl((n-1)d^{2(n-1)}\bigr)$ operations in~$\mathbb{Q}$. Thus before line 30, the total cost is
\[\widetilde{O}\bigl((n-1)d^{2(n-1)}\cdot d + d^{2(n-1)}\cdot d^{6}\cdot (d+\log A) \bigr).\]

From the special structure of WZ-forms, we observe that the degree bound will not be changed in the recursive steps,
and the max-norms of denominators appeared in irreducible partial fraction decompositions are uniformly bounded by $\widetilde{A} := 2^{nd}(d+1)^{n/2}A$. The exact parts during the computation will
always be expressed in a sparse representation. This idea was used to get a polynomial-time algorithm for univariate rational summation in~\cite{Gerhard2003}. Let~$T(n,d,A)$ denote the worst-case running cost of Algorithm~\ref{alg:WZFormDecomp}  in terms of operations in~$\mathbb{Q}$. According to the previous discussions, we have
\[T(n,d,A) = \widetilde{O}\left((n-1)d^{2n-1} + d^{2n+4}\cdot (d+ \log A)\right) + \widetilde{T}(n-1, d, \widetilde{A}),\]
where  $\widetilde{T}(n-1, d, \widetilde{A})$ satisfies the recursive formulae
\begin{gather*}
	\widetilde{T}(m-1,d, \widetilde{A}) = \widetilde{O}\bigl((m-2)d^{2m-3} + d^{2m+2}\cdot (d+ \log \widetilde{A})\bigr) + \widetilde{T}(m-2, d, \widetilde{A})
\end{gather*}
for all $m = 3,\ldots, n$.
By solving the recurrence relation, we conclude that~$T(n,d,A)$ is $\widetilde{O}\bigl(n^{O(1)}d^{O(n)}\log A\bigr)$.

%In the sense of multipoint evaluation and interpolation, it takes $\widetilde{O}((n-1)d^{2(n-1)}\cdot d + d^{2(n-1)}\cdot d^{6}\cdot (d+\log A) )$ operations in $\bQ$. Note that in the recursive steps, the degree bound will not be changed, and the max-norms will only be expanded due to the factorization of multivariate polynomials~\cite{Mahler1962}. Specifically, sparse representation is used in exact part following~\cite{Gerhard2003}. Altogether the algorithm requires~$\widetilde{O}(n^{O(1)}d^{O(n)}\log A)$ operations in~$\mathbb{Q}$.

\begin{algorithm}
	\caption{WZ-form decomposition algorithm}  \label{alg:WZFormDecomp}
	\textbf{Function:} \texttt{WZFormDecomp}$\bigl(
	(f_1,\ldots,f_n),\x,Z\bigr)$\\
	\textbf{Input:} WZ-form $ (f_1,\ldots,f_n)\in K(\x)^n $, $\x=(x_1,\dots,x_n)$, and
	a new variable~$ Z $\\
	\textbf{Output:} Its additive representation: $ \bigl(a, V, R = \{r_{\mathbf{v}}\}_{\mathbf{v}\in V}\bigr)$
	\begin{algorithmic}
		\If{$ f_1=0 $}
		\State $( {a}, {V}, {R}) \gets \texttt{WZFormDecomp}\bigl(
		(f_2,\ldots,f_n),(x_2,\ldots,x_n),Z\bigr)$
		\For{$ {\mathbf{v}}=(v_2,\ldots,v_n)$ in $V$}
		\State $ {\mathbf{v}}\gets (0,v_2,\ldots,v_n) $
		\EndFor
		\State\Return $ ( {a}, {V}, {R}) $
		\EndIf

		\State  Call \texttt{AbramovReduction}:
		$f_1= \De_1(g_0)+\sum_{i=1}^{I}\sum_{j=1}^{J}{a_{i,j}}/{b_i^j}$, { $a \gets g_0$}
		\If{$ n=1 $}
		\State\Return $\bigl(g_0, \bigl((1)\bigr), \bigl(f_1-\De_1(g_0)\bigr) \bigr)$
		\EndIf

		\For{$ 1\leq i \leq I $}
		\State Call \texttt{IntegerLinearDecomp}: $b_i=q_i(\vw_i\cdot \x) $
		with $q_i\in K[Z]$
		\EndFor
		\State $ V \gets (\vv_1,\ldots,\vv_m)$ with $\{\vv_1,\ldots,\vv_m\}=\{\vw_1,\dots,\vw_I\}$
		and $\vv_i\neq\vv_j$ for $i\neq j$
		%the $ \vv_i $ are pairwise distinct
		\For{$ 1 \leq k \leq m $}
		\State $ u_k \gets 0 $
		\For{$1 \leq i \leq I  $}
		\If{the integer-linear type of $b_i$ is $\vv_k = (v_{k,1},\ldots,v_{k,n}) $}
		\For{$ 1 \leq j \leq J $}
		\State Perform the substitution $\vv_k\cdot\x\to Z$ in $a_{i,j}$
		so that $a_{i,j}\in K[Z]$
		\State $u_k \gets u_k+ a_{i,j}/q_i^j$
		\EndFor
		\EndIf
		\EndFor
		\State Call \texttt{AbramovReduction}: $\si_z(h_k)-h_k=u_{k}(v_{k,1}z+1)-u_{k}(v_{k,1}z)$
		\State $ r_k \gets h_k(1/v_{k,1} Z) $, { $r_k = \Delta_Z(g_k) + \widetilde{r}_k $, $a \gets a + g_k(\vv_k \cdot \x)$}
		\EndFor
		\State { $ R \gets (\widetilde{r}_1,\ldots,\widetilde{r}_m) $}
		\For{$ 2 \leq k \leq n $}
		\State $\displaystyle f_k' \gets f_k{- \Delta_k(a) - \sum_{i=1}^m \sideset{}{_0^{v_{i,k}}}\sum_\ell
			\widetilde{r}_i(\mathbf{v}_{i}\cdot \x + \ell)}$
		\EndFor
		\If{$ f_k' \neq 0 $ for some $ k $}
		\State $(a', V', R')\gets
		\texttt{WZFormDecomp}\bigl((f_2',\ldots,f_n'),(x_2,\ldots,x_n),Z\bigr)$
		\For{$\mathbf{v}'=(v_2,\ldots,v_n)$ in $V'$}
		\State $\mathbf{v}'\gets (0,v_2,\ldots,v_n) $
		\EndFor
		\State $ a \gets a+a' $, \ $ V \gets \texttt{Join}(V, V')$, \ $ R \gets \texttt{Join}(R, R') $
		\EndIf
		\State \Return $ (a,V,R) $
	\end{algorithmic}
\end{algorithm}

\begin{example}
  \label{ex:decomp}
  Let $\omega = (f,g,h) \in K(x,y,z)^3$ be a WZ-form with respect to
  $ (\De_x,\De_y,\De_z) $, specifically,
  \begin{align*}
    f &= \frac{xyz-y^2z-yz^2+yz-1}{x-y-z+1},\\
    g &= \frac{x^2z-xyz-xz^2+xy-y^2-yz-1}{x-y-z},\\
    h &= \frac{x^2y-xy^2-xyz+xz-yz-z^2-1}{x-y-z}.
  \end{align*}
  Employing Abramov's reduction on $ f $ yields
  \[f= \De_x(xyz)+\frac{1}{-x+y+z-1}.\]
  Then we record the following exact WZ-form as a part of $ \omega $:
  \[ \omega_0:=\bigl(\De_x(xyz),\De_y(xyz),\De_z(xyz)\bigr) .\]
  Obviously from the decomposition of $ f $ there is only one integer-linear type $ \mathbf{v}=(-1,1,1) $ and the corresponding univariate rational function is $ r_{\mathbf{v}}=1/Z $. It is easily checked that there is no summable part in~$r_{\mathbf{v}}$. Then a uniform WZ-form shows up as a part of~$ \omega $:
  \[
    \omega_{\mathbf{v}}=\Bigl(\frac{1}{-x+y+z-1},\frac{1}{-x+y+z},\frac{1}{-x+y+z}\Bigr) .
  \]
  Then we can update $ \omega$ by subtracting $ \omega_0$ and
  $ \omega_{\mathbf{v}} $ and obtain $\widetilde{\omega}=(0,y,z)$, which is
  equivalent to the WZ-pair $ (y,z) $ with respect to $ (\De_y,\De_z) $. By
  simple manipulations we can see that it is an exact WZ-pair:
  \[
    \Bigl( \De_y\bigl(\tfrac{1}{2}y^2+\tfrac{1}{2}z^2\bigr),
    \De_z\bigl(\tfrac{1}{2}y^2+\tfrac{1}{2}z^2\bigr)\Bigr) .
  \]
  Combining this exact WZ-form with the previous one we can update $ \omega_0 $ as:
  \[
    \omega_0=\Bigl(
    \De_x\bigl(xyz+\tfrac{1}{2}y^2+\tfrac{1}{2}z^2\bigr),
    \De_y\bigl(xyz+\tfrac{1}{2}y^2+\tfrac{1}{2}z^2\bigr),
    \De_z\bigl(xyz+\tfrac{1}{2}y^2+\tfrac{1}{2}z^2\bigr)
    \Bigr).
  \]
  Finally the decomposition works as $ \omega=\omega_0+\omega_{\mathbf{v}} $, i.e.,
  the additive representation of $ \omega $ is
  \[
    \Bigl(xyz+\tfrac{1}{2} y^2+\tfrac{1}{2} z^2,\left\lbrace(-1,1,1)\right\rbrace,\{1/Z\}\Bigr).
  \]
\end{example}


