Following~\cite{Seliger:Springer:2000,Yang:SCL:2015}, we consider the following fault detection observer for~\eqref{Fault-explicit-state-space-BattBee}:
\begin{subequations}\label{residual-dynamics}
\begin{align}
\dot {\hat x} &=A \hat x +Bu + L r,\\
r &= y- h(\hat x) - D u , 
\end{align}
\end{subequations}
where $\hat x$ is the observer's state, and $r$ is the residual in prediction of $y$. When there is no fault, $\hat x$ is an estimate of $x$, and $r$ is small in general. Defining $\tilde x = x - \hat x$ and using~\eqref{Fault-explicit-state-space-BattBee}-\eqref{residual-dynamics}, we have
\begin{subequations}\label{residual-dynamics-rewrite}
\begin{align}
\dot {\tilde x } &= A \tilde x - L \Psi(x, \hat x)   \tilde x, \\ \label{r-xtilde-relation}
r & = \Psi(x, \hat x)  \tilde x,
\end{align}
\end{subequations}
when $f_i=0$ for $i=1,2,3$, where $L$ is a gain matrix, and 
\begin{align*}
\Psi(x, \hat x) &= \begin{bmatrix}
0 & \psi(x, \hat x)  & 0 & 0 \cr
0 & 0 & 0 & 1
\end{bmatrix}, \\ 
\psi(x, \hat x) &= { U( \mathbf{e}_2 x) - U \left( \mathbf{e}_2 \hat x \right) \over \mathbf{e}_2 \left( x - \hat x \right) }.
\end{align*}
For a LiB cell, the OCV function $U(\cdot)$ is inherently Lipschitz-continuous and monotonically increasing. It hence holds that
\begin{align*}
 \underline{\psi} \leq \psi(x, \hat x) \leq \bar \psi,
\end{align*}
where $ \underline{\psi}, \bar \psi>0$ are the minimum and maximum slopes of $U(\cdot)$. 

\begin{thm}\label{Detection-Observer-Stability}
When $f_i=0$ for $i=1,2,3$, the fault detection observer in~\eqref{residual-dynamics} is asymptotically stable if there exist $P>0$, $Q>0$, and $L$ such that 
\begin{align}\label{LMI-condition}
A^\top P +P A - H^\top L^\top P - P L H +Q \leq 0,
\end{align}
for 
\begin{align*}
H =  \begin{bmatrix}
0 & \underline \psi  & 0 & 0 \cr
0 & 0 & 0 & 1
\end{bmatrix}, \ \mbox{and} \ 
H =  \begin{bmatrix}
0 & \bar \psi  & 0 & 0 \cr
0 & 0 & 0 & 1
\end{bmatrix}. 
\end{align*}
\end{thm}

\begin{proof}
Consider the Lyapunov function candidate $V(\tilde x) = {1 \over 2} \tilde x^\top P \tilde x$. Given~\eqref{residual-dynamics-rewrite}, $\dot V$ is
\begin{align*}
\dot V =\tilde x^\top \left[ A - L \Psi(x, \hat x)  \right]^\top P \tilde x + \tilde x^\top P \left[ A   - L \Psi(x, \hat x)  \right] \tilde x.
\end{align*} 
According to~\cite{Zemouche:AUTO:2013}, if~\eqref{LMI-condition} holds, we have
\begin{align*}
\dot V \leq - \tilde x^\top Q \tilde x<0,
\end{align*}
for $\tilde x \neq 0$. Therefore, the observer in~\eqref{residual-dynamics} is asymptotically stable. 
\end{proof}


Theorem~\ref{Detection-Observer-Stability} indicates that, when there is no fault, $ r \rightarrow 0$ when $t\rightarrow\infty$. But it is often inadequate to compare $r$ to zero in practice to identify the occurrence of a fault, due to the transient behavior of $r$. To overcome this issue, we instead consider the following residual evaluation functions:
\begin{subequations}\label{J2-Jinfty-def}
\begin{align}
J_2 (t) &= \sqrt{ \int_0^t \|r(\tau )\|^2 d \tau }, \\ 
J_\infty (t) &=  \sup \left\{ \|r(\tau ) \|, 0\leq \tau<t \right\}, 
\end{align}
\end{subequations} 
where $ \| \cdot \|$ denotes the Euclidean norm of a vector. The design of $J_2 $ and $J_\infty$ is inspired by norms for signals---specifically, $J_2(\infty)$ and $J_\infty(\infty)$ are the $\mathcal{L}_2$- and $\mathcal{L}_\infty$-norms of the residual signal $r(0 \rightarrow t)$ under fault-free conditions, respectively. %A reader is referred to~\cite{Toscano:Springer:2013} for the formal definitions of signal norms. 
The following lemma shows the upper bounds for $J_2$ and $J_\infty$. 

% analogous, though not identical, to 

\begin{lem}\label{Threshold-lemma}
Suppose that $f_i=0$ for $i=1,2,3$ for~\eqref{Fault-explicit-state-space-BattBee}, and that Theorem~\ref{Detection-Observer-Stability} holds. If $\| \tilde x (0) \| \leq \delta $ and $\epsilon P - Q \leq 0$ for some $\epsilon >0$, then
\begin{align}\label{Detection-conditions}
J_2(t) \leq J_{2,\threshold}, \ \ \ 
J_\infty(t) \leq J_{\infty,\threshold},
\end{align}
where
\begin{align*}
 J_{2, \threshold} &= \sqrt{ \max\left\{ \bar \psi^2, 1 \right\} \cdot \lambda_{\max}(P)  \over \epsilon \cdot \lambda_{\min} (P)}  \delta , \\
J_{\infty, \threshold} &= \sqrt{ \max\left\{ \bar \psi^2, 1 \right\} \cdot \lambda_{\max} (P) \over \lambda_{\min} (P)} \delta .
\end{align*}
\end{lem}

\begin{proof}
Following Theorem~\ref{Detection-Observer-Stability}, there exists $\epsilon>0$ such that $\epsilon P- Q \leq 0$. We thus have
\begin{align*}
\dot V \leq - \tilde x^\top Q \tilde x \leq - \epsilon V. 
\end{align*}
By the comparison principle~\cite{Khalil:Pearson:2001}, $ V \leq e^{-\epsilon t} V (0) $. Since $V \geq \lambda_{\min} (P) \cdot \| \tilde x \|^2$, we have
\begin{align*}
 \| \tilde x \|^2 \leq  { e^{-\epsilon t} \over \lambda_{\min} (P) } V (0)  \leq { \lambda_{\max} (P) \over \lambda_{\min} (P) } \delta^2  e^{-\epsilon t}
\end{align*}
Then, by~\eqref{r-xtilde-relation}, we have
\begin{align*}
\|r\|^2 &= \tilde x^\top \Psi^\top (x, \hat x) \Psi(x, \hat x) \tilde x \leq \tilde x^\top \bar \Psi^\top \bar \Psi  \tilde x 
\\ &\leq \max\left\{ \bar \psi^2, 1 \right\} \cdot \|\tilde x\|^2 \\ 
& \leq { \max\left\{ \bar \psi^2, 1 \right\} \cdot \lambda_{\max} (P) \over \lambda_{\min} (P)} \delta^2 e^{-\epsilon t} 
\end{align*} 
With this, we can obtain $J_2(t) \leq J_2(\infty) \leq J_{2, \threshold} $ and $J_\infty(t) \leq J_\infty(\infty) \leq J_{\infty, \threshold} $, thus proving~\eqref{Detection-conditions}. 
\end{proof}

Based on Lemma~\ref{Threshold-lemma}, we introduce the following decision logic for fault detection:
\begin{equation}\label{detection-logic}
\begin{aligned}
J_p(t) &\leq J_{p,\threshold} \ \Rightarrow \ \mbox{no TR/ISC fault has occurred},\\
J_p(t) &> J_{p,\threshold} \ \Rightarrow \ \mbox{a TR/ISC fault has occurred},
\end{aligned}
\end{equation}
where $p=2$ or $\infty$. By applying this logic in conjunction with continuous residual evaluation by computing $J_2(t)$ or $J_\infty(t)$, fault occurrence can be monitored and identified. 

For the BattBee model, the only nonlinearity appears in the OCV function $U(\cdot)$. This function is amenable to piecewise linearization for LiBs~\cite{Farakhor:TTE:2023}. Leveraging this property, we can derive some direct and tighter thresholds for $J_2$ and $J_\infty$. Along this line, we approximate $U(V_s)$ as a set of $m$ linear functions:
\begin{align*}
U(V_s) = a_i V_s + b_i, 
\end{align*} 
where $a_i$ and $b_i$ are the slope and intercept of the $i$-th segment when $ \undersl{V}_{s,i} \leq V_s < \oversl V_{s,i}$ for $i=1,2,\ldots,m$. Here $ \undersl{V}_{s,i}$ and $\oversl V_{s,i}$ are the lower and upper bounds of the $i$-th segment. Then, we can translate~\eqref{Fault-explicit-state-space-BattBee} into a collection of linear models, $\mathcal{M}_i$ for $i=1,2,\ldots, m$:
\begin{align}\label{Fault-explicit-state-space-BattBee-linearized}
\mathcal{M}_i: \left\{
\begin{aligned}
\dot  x &= (A + A_f f_1 ) x + B u + B_f f_2,\\
z &= C_i x + Du +D_f f_3,
\end{aligned}
\right.
\end{align}
where
\begin{align*}
z &= \begin{bmatrix}
V - b_i \cr T_s
\end{bmatrix}, \ \ \ 
C_i = \begin{bmatrix}
0 & a_i & 0 & 0 \cr
0 & 0 & 0 & 1
\end{bmatrix}. 
\end{align*}
Given $\mathcal{M}_i$, a linear fault detection observer can be designed following~\eqref{residual-dynamics} and~\cite{Patton-Frank-Clark:Springer:2000,Li-Ding:AUTO:2017,Xu:CCA:2007}:
\begin{subequations}\label{residual-dynamics-linearized}
\begin{align}\label{State-observer-linearized}
\dot {\hat x} &= A \hat x + B u + L_i \left( y - C_i x - Du \right),  \\
r &= z - C_i x - Du.
\end{align}
\end{subequations}
In the case of no fault, we have 
\begin{align*}
\dot {\tilde x } & = \tilde A_i \tilde x, \ \ \
r  = C_i  \tilde x,
\end{align*}
where $ \tilde A_i = A   - L_i C_i $. As a result, 
\begin{align*}
r = C_i e^{\tilde A_it} \tilde x(0). % = M_i(t) \tilde x(0) 
\end{align*}
To evaluate the residual's behavior, we continue to use $J_2$ and $J_\infty$ in~\eqref{J2-Jinfty-def}. 

\begin{lem}\label{Threshold-lemma-linearized}
Suppose that $f_i=0$ for $i=1,2,3$ for~\eqref{Fault-explicit-state-space-BattBee-linearized}, that $(A,C_i)$ is detectable for $i=1,2,\ldots,m$, and that $\| \tilde x (0) \| \leq \delta $. Then, in the regime of $\mathcal{M}_i$, 
\begin{align}\label{Detection-conditions-linearized}
J_2(t) \leq J_{2,\threshold}^i, \ \ \ 
J_\infty(t) \leq J_{\infty,\threshold}^i,
\end{align}
where
\begin{align*}
 J_{2, \threshold}^i &= \left \| \sqrt{ W_i} \right \| \delta , \ \ W_i = \int_0^\infty  e^{\tilde A_i^\top t} C_i^\top C_i e^{\tilde A_i t} dt, \\
J_{\infty, \threshold}^i &=  \sup_\tau \left\{ \left \|   C_i e^{\tilde A_i \tau}  \right\| \delta  , \; 0 < \tau < \infty \right\} . 
\end{align*}
\end{lem}

\begin{proof}
We have
\begin{align*}
J_2(t) &\leq  \sup_{\| \tilde x (0) \| \leq \delta} \sqrt{ \int_0^\infty \|r (\tau)\|^2 d \tau } \\
&=  \sup_{\| \tilde x (0) \| \leq \delta} \sqrt{ \int_0^\infty \tilde x^\top(0) e^{\tilde A_i^\top t} C_i^\top C_i e^{\tilde A_it} \tilde x(0) dt } \\
&= \sup_{\| \tilde x (0) \| \leq \delta} \sqrt{ \tilde x^\top(0) \underbrace{ \int_0^\infty  e^{\tilde A_i^\top t} C_i^\top C_i e^{\tilde A_it} dt }_{W_i} \tilde x(0) } \\
&= \left \| \sqrt{ W_i} \right \| \delta
%&J_2(t) \leq  \sup_{\| \tilde x (0) \| \leq \delta} \sqrt{ \int_0^\infty \|r (\tau)\|^2 d \tau } \\
%& \quad =  \sup_{\| \tilde x (0) \| \leq \delta} \sqrt{ \int_0^\infty \tilde x^\top(0) e^{\tilde A_i^\top t} C_i^\top C_i e^{\tilde A_it} \tilde x(0) dt } \\
%&\quad = \sup_{\| \tilde x (0) \| \leq \delta} \sqrt{ \tilde x^\top(0) \underbrace{ \int_0^\infty  e^{\tilde A_i^\top t} C_i^\top C_i e^{\tilde A_it} dt }_{W_i} \tilde x(0) } \\
%&\quad = \left \| \sqrt{ W_i} \right \| \delta
\end{align*}
Similarly,
\begin{align*}
J_\infty(t)&  \leq \sup_{\| \tilde x (0) \| \leq \delta} \left\{ \|r (\tau)\|  , 0 \leq \tau < \infty \right\}\\
&= \sup_{\| \tilde x (0) \| \leq \delta} \left\{ \sqrt{ \tilde x^\top(0)  e^{\tilde A_i^\top \tau} C_i^\top C_i e^{\tilde A_i \tau} \tilde x(0) } ,  0 \leq \tau < \infty \right\} \\
&\leq \sup_\tau \left\{ \left \|  C_i e^{\tilde A_i \tau} \right \| \delta  , 0 \leq \tau < \infty \right\}.
%&J_\infty(t)  \leq \sup_{\| \tilde x (0) \| \leq \delta} \left\{ \|r (\tau)\|  , 0 \leq \tau < \infty \right\}\\
%&\quad = \sup_{\| \tilde x (0) \| \leq \delta} \left\{ \sqrt{ \tilde x^\top(0)  e^{\tilde A_i^\top \tau} C_i^\top C_i e^{\tilde A_i \tau} \tilde x(0) } ,  0 \leq \tau < \infty \right\} \\
%, 0 \leq \tau < \infty \right\}.
\end{align*}
This completes the proof.
\end{proof}

Note that the notation $\|\cdot\|$ is slightly abused above to also represent the induced 2-norm of a matrix, without causing confusion from the context. Furthermore, it is known that $W_i$ is the observability Gramian for $\mathcal{M}_i$ with no fault, satisfying the following Lyapunov equation:
\begin{align*} 
\tilde A_i^\top W_i + W_i \tilde A_i = - C_i^\top C_i. 
\end{align*} 
By solving this Lyapunov equation, one can directly compute $W_i$ and then $ J_{2,\threshold}^i$. Finally, by leveraging Lemma~\ref{Threshold-lemma-linearized}, we can employ the decision logic in~\eqref{detection-logic} to perform TR and ISC detection. 

%In practice, one can choose the large $J_2$ or $J_\infty$$$

We have the following remarks to address some practical considerations in implementing the above fault detection approach based on the piecewise linearized models. First, to determine $\mathcal{M}_i$ corresponding to the operating condition of the LiB cell, the current state can be continuously estimated using~\eqref{State-observer-linearized} when no fault has been identified. Second, inevitable model inaccuracy and measurement noises can mildly alter the behavior of the residual signals to cause $J_2$ and $J_\infty$ to exceed their theoretical values under normal operating conditions, potentially triggering false alarms. To alleviate this, we suggest to modify $J_2$ as
\begin{align}\label{eqn:J2-with-forgetting-factor}
J_2(t) = \sqrt{\int_0^t \eta^{(t - \tau)} \| r (\tau)\|^2 \, d\tau}, 
\end{align}
where $0<\eta<1$ is a forgetting factor to give exponentially decreasing weight to older residual values. In the discrete-time domain, $J_2$ can be recursively computed via
\begin{align*}
J_2 (k+1 ) = \sqrt{ \eta J_2^2(k)+\| r (k+1)\|^2 \Delta t },
\end{align*}
where $k$ is the discrete time index and $\Delta t$ is the sampling period. The choice of $\eta$ should balance the accuracy and robustness against uncertainty in fault detection; typically, $\eta$ is chosen to be slightly less than 1. In general, $J_\infty$ is less sensitive to the impact of model and measurement uncertainty. However, it is still beneficial to slightly increase $J_{\infty, \threshold}^i$ to make the fault detection more robust. Finally, for the sake of conservatism, one can select $J_{p,\threshold}$ for $p=2$ or $\infty$ as 
\begin{align*}
  J_{p,\threshold} = \max_{i} \left\{ J_{p,\threshold}^i, i=1,2,\ldots, m \right\}. 
\end{align*}
This conservative choice will help reduce the chance of false alarming in practical applications. %Finally, we emphasize that fault detection 

