\paragraph{Preliminaries.} %Consider a decentralized multi-task reinforcement learning (MTRL) setting in which each agent \(i \in \mathcal{I}\) is assigned a unique Markov Decision Process (MDP) corresponding to task \(\tau \in \mathcal{T}\). 
Each task \(\tau \in \mathcal{T}\) is modeled as an MDP defined by the tuple \(\mathcal{M} = \left\langle \mathcal{S}, \mathcal{A}, \mathcal{P}, \mathcal{R}, \gamma \right\rangle\), where \(\mathcal{S}\) is the state space, \(\mathcal{A}\) is the action space, \(\mathcal{P}(s'|s,a)\) is the transition probability function, \(\mathcal{R}(s,a)\in\mathbb{R}\) is the reward received after taking action \(a\) in the state \(s\), and \(\gamma\in[0,1]\) is the discount factor. An agent interacts with its environment and aims to learn a policy \(\pi_\tau : \mathcal{S}\to \mathcal{A}\) that maximizes the expected discounted return,
\begin{equation}
   J_\tau(\pi_\tau)=\mathbb{E}_{\pi_\tau}\left[\sum_{t=0}^{\infty}\gamma^t_\tau \mathcal{R}_\tau (s_t,a_t)\right]. 
   \label{eq:objective}
\end{equation}

\paragraph{Mask Representations.}
The mask representation used in this study relies on a frozen backbone network \(\Phi\) that must be the same for all agents. Each policy \(\pi_\tau\) is implicitly parameterized through a sparse mask \(\phi_\tau\), such that \(\pi_\tau=\pi_{\Phi\odot g(\phi_\tau)}\), where \(\odot\) denotes the Hadamard product, and \(g(\cdot)\) is a binarization function applied during the forward pass. The mask \(\phi_\tau\) consists of a set of real-valued score vectors, one per layer of the shared backbone network \(\Phi\), which select a sparse, task-specific subnetwork from \(\Phi\) without modifying its parameters. The scores are binarized during the forward pass to produce a hard mask that is used for inference. The binarization is performed during inference, using the element-wise thresholding function,
\begin{equation} \label{eq:binarization}
    g(\phi_\tau)_\ell =
    \begin{cases}
        1 & \text{if } (\phi_\tau)_\ell > \epsilon \\
        0 & \text{otherwise}
    \end{cases}, \quad \text{with } \epsilon = 0 \quad,
\end{equation}
where \(g(\phi_\tau)\) denotes the full binary mask and \(\ell\) indexes the layers of the backbone network \(\Phi\). During the backward pass, gradients are computed with respect to the real-valued mask parameters \(\phi_\tau\), and updates are performed using the straight-through estimator (STE) \citep{wortsman2020supermasks} to enable learning through the non-differentiable binarization step.

\subsection{Wasserstein Task Embeddings for Online Reinforcement Learning}
\label{sec:wasserstein_sim}
A key intuition in this study is that knowledge composition is effective if policies from other agents are acquired only when they are likely to be beneficial, and because they have been derived from related tasks. This hypothesis was verified with an ablation study. MOSAIC implements this idea by computing task embeddings from trajectory data and using them to identify semantically related peers via geometric proximity. This idea builds on work in latent task inference and representation learning \citep{Zintgraf2019VariBAD:Meta-Learning, Achille_2019_ICCV}, adopting a non-parametric approach aligned with prototype-based and optimal transport methods \citep{yarats2021reinforcementlearningprototypicalrepresentations, Chu2023Meta-ReinforcementClustering, liu2022wasserstein}.

Unlike gradient-based adaptation techniques \citep{Lan2019MetaPolicy}, which are unstable in RL and costly at inference time, MOSAIC computes task embeddings through training-free distributional comparisons, making them well-suited for decentralized, real-time systems requiring modular policy reuse without supervision. To support these requirements, MOSAIC extends the Wasserstein Task Embedding (WTE) framework of \citet{liu2022wasserstein} to the RL domain by defining an online embedding function over batches of state-action-reward (SAR) tuples drawn from an agent's replay buffer. For task \(\tau\), the agent maintains an empirical task distribution \(\mu_\tau \in \mathcal{P}(\mathbb{R}^d)\), defined as,
\begin{equation}\label{eq:embedding_distribution}
    \mu_\tau = \frac{1}{N}\sum_{t=1}^{N} \delta_{x_t}, \quad \text{where} \quad x_t=(s_t, a_t, r_t) \quad \text{and} \quad x_t \sim \mathcal{D}_\tau,
\end{equation}
where \(\mathcal{D}_\tau\) denotes the replay buffer for task \(\tau\), and each \(x_t \in \mathbb{R}^d\) is a state-action-reward (SAR) tuple. The tuple dimensionality is given by \(d=d_s+d_a+d_r\), where \(d_s\), \(d_a\), and \(d_r\) are the dimensions of the state, action, and scalar reward, respectively. In our experiments, we use \(N=128\) samples to compute the empirical task distribution. \(\delta_{x_t}\) denotes the Dirac measure centered at the sample \(x_t\). A fixed synthetic reference distribution \(\mu_0\) is defined as,
\begin{equation}\label{eq:reference_distribution}
    \mu_0 = \frac{1}{M}\sum_{m=1}^M \delta_{x_m^0},
\end{equation}
where \(x_m^0 \sim \text{Uniform}(-1,1)^d\) is sampled once during initialization and fixed thereafter. We fix \(M=50\) as the number of reference points in the synthetic distribution. This shared reference is used across all agents and enables them to align their embeddings in a shared latent space without centralized training or supervision. The 2-Wasserstein distance between \(\mu_\tau\) and \(\mu_0\) is computed by solving the optimal transport problem,
\begin{equation}
    \gamma^* = \arg\min_{\gamma \in \mathbb{R}^{N\times M}} \sum_{t=1}^N\sum_{m=1}^M \gamma_{t m} \| x_t - x^0_m \|^2, \quad \text{s.t. }\gamma_{tm}\ge0, \gamma\mathbf{1}_M=\frac{1}{N}\mathbf{1}_N,\gamma^\top \mathbf{1}_N=\frac{1}{M}\mathbf{1}_M,
\end{equation}
where \(\mathbf{1}_N\) and \(\mathbf{1}_M\) are vectors of ones in \(\mathbb{R}^N\) and \(\mathbb{R}^M\), respectively. The Wasserstein task embedding operator \(\psi\) maps the task distribution \(\mu_\tau\) to a vector \(v_\tau \in \mathbb{R}^{M\times d}\) via the barycenter projection of \(\gamma^*\) on \(\{x_t\}_{t=1}^N\),
\begin{equation} \label{eq:embedding_mapping}
    v_\tau = \psi(\mu_\tau) = \left[ \sum_{t=1}^N \gamma_{tm}^* x_t \right]_{m=1}^M.
\end{equation}
This mapping places each task \(\tau\) in a shared latent space, where metrics can be used to quantify task relationships. A 2-point moving average is used to smooth behavioral fluctuations and stabilize evolving policies in MOSAIC. This embedding strategy enables agents to reason about task-relatedness in constant time, without additional training or forward passes. Importantly, it fits the online and asynchronous nature of agentic RL systems, while remaining robust to evolving policies and lightweight enough for continuous use in edge-deployed systems.

\subsection{Knowledge Selection and Sharing}
\label{sec:selection}
Agents communicate maintaining a list of IP addresses and ports for other agents, which allows them to be located anywhere on the Internet. Each agent \(i \in \mathcal{I}\) can directly communicate with all other agents \(j \in \mathcal{I},\ j \ne i\) at any time.
\paragraph{Phase 1: Query-Metadata.}
At any time, an agent \(i\) can initiate a task embedding query (TEQ) by broadcasting its current task embedding \(v_i\), iteration performance \(r_i\), and its IP/port (Figure \ref{fig:approach}(B)). Upon receiving the TEQ, each peer agent \(j\ne i\) responds with its most recent task embedding \(v_j\) and associated performance score \(r_j\).

\paragraph{Phase 2: Mask Selection and Acquisition.}
Once the agent has received query responses (QR) with relevant embeddings from other agents, it computes the cosine similarity between its own embedding and those of each peer,
\begin{equation}
    d_{\text{cos}}(v_i, v_j) = \frac{ \langle \text{vec}(v_i), \text{vec}(v_j) \rangle }{ | \text{vec}(v_i) | \cdot | \text{vec}(v_j) | }, \quad d_{\text{cos}} \in [-1, 1].
\end{equation}
In practice, cosine similarities between Wasserstein task embeddings are typically positive. Cosine similarity was observed to perform better than Euclidean distance in preliminary tests, and showed scale-invariance and empirical robustness in high-dimensional settings. To identify useful policies, agent \(i\) applies two heuristic filters based on similarity and performance:
\begin{align}
    \mathbb{I}_{\text{align}}(i, j) &= 
    \begin{cases}
        1 & \text{if } d_{\text{cos}}(v_i, v_j) > \theta, \\
        0 & \text{otherwise}
    \end{cases} \tag{Criterion 1} \label{eq:criterion_align} \\[1ex]
    \mathbb{I}_{\text{perf}}(i, j) &= 
    \begin{cases}
        1 & \text{if } r_j > r_i, \\
        0 & \text{otherwise}
    \end{cases} \tag{Criterion 2} \label{eq:criterion_perf}
\end{align}
with \(\theta=\) set to \(0.5\) in all experiments. The first criterion promotes semantic alignment between tasks, revealing latent similarities that may lead to effective transfer (see Figure~\ref{fig:heatmaps}). The second ensures that agents only acquire masks from peers whose performance exceeds their own, avoiding noisy or under-trained policies that can degrade performance. Criterion 2 guards against the frequent false positives seen when comparing poorly trained policies that yield deceptively similar embeddings. The selection criteria can also be used on the peers after they receive the query. This method acts as a bandwidth-efficient alternative that enables communication without affecting the overall outcome of the approach. Additionally, this method offers a scalable pathway for extensions to lifelong learning, which are discussed in Appendix~\ref{sec:mask_composition_ll}.

The peer masks that pass both criteria are stored as the set \(P_{c+1}=\{\phi_1,...,\phi_K\}\), where each \(\phi_k\) denotes a mask received from a selected peer. This two-phase strategy ensures that agents acquire knowledge that is not only relevant but also demonstrably effective.

\subsection{Knowledge Composition}
\label{sec:knowledge_comp}
Masks received from other agents meeting the two selection criteria above have been pretrained on tasks that are likely related to, or share similarities with, the agent's current task. As originally shown in \cite{ben2022lifelong}, a linear combination of masks, weighted with trainable parameters \(\beta\), can lead to beneficial policy search in RL. MOSAIC exploits this idea by combining policies that have been trained on the local agent, plus those received from other agents. In this study, the \(\beta\) values are computed via softmax over a set of beta parameters optimized in log-space, \( \tilde{\beta} \in \mathbb{R}^{1 + |P_c|} \), where \(P_c\) is the number of masks received. During the forward pass, the agent constructs the linearly combined, binarized mask,
\begin{equation}\label{eq:linearcombination}
    \phi_\tau^\text{lc} = g\left(\beta_\tau \phi_\tau + \sum_{k=1}^{|P_{c+1}|}\beta_k\phi_k \right),
\end{equation}
where \( \phi_\tau \) is the agent's own task mask, and \( \phi_k \) is the \( k \)-th peer mask. The parameters \( \beta_\tau \) and \( \beta_k \) are the softmax-normalized values derived from \( \tilde{\beta} \), for \(\phi_\tau\) and \(\phi_k\), respectively. The resulting binary mask, \( \phi_\tau^{\text{lc}} \), is then used to modulate the backbone parameters, yielding the final policy \( \pi_\tau \). Using the STE method, the agent updates the \(\beta\) parameters and \(\phi_\tau\) via backpropagation, keeping all the \(\phi_k\) masks fixed.

\paragraph{Reward-Guided Initialization.} The trainable \(\beta\) parameters are ideal to enable gradient descent to discover which policy is most beneficial on the current task. However, given the available information, one question is: What is a good initial weighting for the set of masks that include the local mask and those received from other agents? MOSAIC proposes a reward-guided weighting mechanism to set the initial values. While such values can be later tuned by gradient descent, an ablation study suggested that performing a good initial guess leads to a significant advantage. The intuition is that an agent with low performance may favor external knowledge, while an agent with higher returns could rely more on their own policies. The initial set of \(\beta\) is given by
\begin{equation}\label{eq:reward-guided-init}
    \beta_{\tau} = 0.5 + 0.5r, \quad \beta_k = \frac{0.5(1 - r)}{|P_{c+1}|}\quad,
\end{equation}
where \(r \in [0,1]\) is the agent's normalized average return over the most recent iteration and \(|P_{c+1}|\) is the number of peer masks received during a communication event. This scheme encourages a smooth shift from exploration to self-reliance as learning progresses.

The process just described occurs multiple times, and specifically, each time new masks are received. Therefore, before a new set of peer masks \(P_{c+1}\) is integrated, the agent performs a consolidation operation that combines its current task mask \(\phi_\tau\) with the set of previous peer masks \(P_c\). This is done using a weighted linear combination similar to the forward pass. The resulting consolidated mask updates the existing \(\phi_\tau\),
\begin{equation}
        \phi_\tau \gets \beta_\tau\phi_\tau + \sum_{k=1}^{|P_c|}\beta_k\phi_k\quad.
        \label{eq:consolidation}
\end{equation}
The consolidation reduces multiple currently held peer masks to one without affecting the policy, effectively maintaining scalability with respect to memory requirements.

\subsection{Summary}
\label{sec:summary_code}
The complete MOSAIC algorithm executes the processes described above in a loop. Figure~\ref{fig:approach} illustrates the algorithmic pipeline with each of the components. MOSAIC computes embeddings from batches of state-action-reward (SAR) data collected under the current policy, and these embeddings evolve over time as the policy improves. Knowledge reuse is governed by a linear combination of task-specific masks selected using similarity (computed from embeddings) and performance heuristics, with beta parameters re-initialized at each communication event and then fine-tuned to reflect downstream utility to the current task. While not part of this study, Appendix~\ref{sec:mask_composition_ll} provides a formalization of how masks can be linearly combined and how beta parameters can be initialized to extend MOSAIC to a fully-fledged lifelong reinforcement learning setting \cite{ben2022lifelong,xie2022lifelong}.

Algorithm~\ref{alg:mosaic-trainer} provides an outline of the overall process. Pseudo-code for how the forward pass is computed is provided in Appendix~\ref{sec:implementation_details} Algorithm~\ref{alg:mosaic-forwardpass}. MOSAIC makes use of parallelized processes to achieve asynchronicity between learning and sharing knowledge. These parallel processes are described in Appendix~\ref{sec:implementation_details} Algorithms~\ref{alg:mosaic-update}, \ref{alg:mosaic-comm}, and \ref{alg:mosaic-server}, which handle the updating of the mask and linear combination parameters on every communication event and manage the communication client/server, respectively. Queries and masks are shared around the system via multi-processing queues \(Q_{\text{emb}}\) and \(Q_{\text{mask}}\). Appendix~\ref{sec:implementation_details} Algorithm~\ref{alg:mosaic-wdm} shows the computation of the Wasserstein task embeddings. The Python code of the complete algorithm to reproduce the results is provided at \url{https://github.com/DMIU-ShELL/MOSAIC}.
\begin{algorithm}
\caption{Agent Training Loop in MOSAIC}
\label{alg:mosaic-trainer}
\begin{algorithmic}[1]
\Require Assigned task \(\tau \in \mathcal{T}\), shared backbone \(\Phi\)
\Require Communication event interval \(\Delta_{\text{comm}}\), embedding interval \(\Delta_{\text{embed}}\)
\Require Replay buffer \(\mathcal{D}_\tau\), rollout length \(z\), total steps \(\Omega\), cosine similarity threshold \(\theta = 0.5\), \(N\gets128\)
\State Initialize mask \(\phi_\tau\), embedding \(v_\tau \gets \mathbf{0}\), return estimate \(r \gets 0\), step counter \(t \gets 0\)
\State Initialize peer mask set \(P_0 = \emptyset\), and linear combination parameters \({\beta} \in \mathbb{R}^{1 + |P_0|}\)
\State Launch \textbf{parallel threads}:
\Statex \hspace{1em} \textsc{ReplacePeerMasks}($Q_{\text{mask}}$) \hfill \Comment{Receives and applies mask updates Alg.~\ref{alg:mosaic-update}}
\Statex \hspace{1em} \textsc{CommunicationModule}($Q_{\text{emb}}, Q_{\text{mask}}$) \hfill \Comment{Handles queries and peer responses Alg.~\ref{alg:mosaic-comm}}
\While{\(t < \Omega\)}
    \State Roll out policy \(\pi_\tau = \pi_{\Phi \odot g(\phi_\tau^\text{lc})}\) for \(z\) steps\Comment{Forward pass Alg.~\ref{alg:mosaic-forwardpass}}
    \State Store transitions in \(\mathcal{D}_\tau\); update iteration return estimate \(r\)
    \State Update \(\phi_\tau\) using policy gradient on loss \(\mathcal{L}(\pi_\tau)\) \Comment{Via Eq.~\ref{eq:linearcombination}}
    \State \(t \gets t + z\)
    \If{\(t \bmod \Delta_{\text{embed}} = 0\) \textbf{and} \(|\mathcal{D}_\tau| \ge N\)}
        \State Sample \(N\) samples from \(\mathcal{D}_\tau\) and compute task embedding \(v_\tau \gets \psi(\mu_\tau)\)\Comment{Alg.~\ref{alg:mosaic-wdm}}
    \EndIf
    \If{\(t \bmod \Delta_{\text{comm}} = 0\)}
        \State Send \texttt{TEQ} for \((v_\tau, r)\) to \textsc{CommunicationModule} via \(Q_{\text{emb}}\) and acquire set of peer masks \(P_{c+1}=\{\phi_1...\phi_K\}\) in \textsc{CommunicationModule}
        \State Update model with \(P_{c+1}\) for forward pass via \textsc{ReplacePeerMasks} through \(Q_\text{mask}\)
    \EndIf
    \If{\(t=\Omega\)}
        \State Enter idle mode to keep \textsc{CommunicationModule} active
    \EndIf
\EndWhile
\end{algorithmic}
\end{algorithm}


