\section{Implementation Details}
\label{sec:implementation_details}
Algorithm~\ref{alg:mosaic-forwardpass} describes how the forward pass is computed using a weighted linear combination of the current task mask, peer masks, and the backbone network. Algorithm~\ref{alg:mosaic-server} presents an alternative communication strategy in MOSAIC, where agents perform selection on the server side by returning only the most relevant masks from their knowledge base to querying agents. This alternative approach improves scalability and communication efficiency without changing the way MOSAIC works. This alternative approach is especially useful in the lifelong learning scenario where each agent encounters multiple tasks. By reducing the exchange of irrelevant information, this server-side selection mechanism enables MOSAIC to adapt effectively to lifelong learning, where agents would be expected to learn multiple task-masks. Rather than share all information of all the available knowledge, peer MOSAIC agents would perform selection locally for the querying agents and send the appropriate mask(s). The lifelong learning adaptation of MOSAIC is discussed in Section~\ref{sec:mask_composition_ll}.
\begin{algorithm}[ht]
\caption{Forward pass using masks for network layer \(l\)}
\label{alg:mosaic-forwardpass}
\begin{algorithmic}[1]
\Require Masks \(\phi_\tau\), peer mask set \(P=\{\phi_k\}_{k=1}^{|P|}\), parameters \(\beta_\tau\), \(\{\beta_k\}_{k=1}^{|P|}\), backbone \(\Phi\)
\Procedure{ForwardPass}{\textbf{x}}
    \If{\(|P| = 0\)} \Comment{no peer masks available}
        \State Set \(\phi_\tau^\text{lc}\gets\phi_\tau\)
    \Else
        \State \(\phi_\tau^\text{lc}\gets g\left(\beta_\tau\phi_\tau+\sum_{k\in P}\beta_k\phi_k\right)\) \Comment{Eq.~\ref{eq:linearcombination}}
    \EndIf
    \State \(\pi_\tau \gets \pi_{\Phi\odot\phi_\tau^\text{lc}}\)\Comment{Modulate backbone with LC mask to get policy}
    \State \(y \gets \pi_\tau\cdot \textbf{x}\)\Comment{Compute output from policy}
    \State \Return \(y\)
\EndProcedure
\end{algorithmic}
\end{algorithm}
\begin{algorithm}[ht]
\caption{Updating set of peer masks and resetting linear combination parameters}
\label{alg:mosaic-update}
\begin{algorithmic}[1]
\Require latest iteration return \(r\)
\Procedure{ReplacePeerMasks}{$Q_{\text{mask}}$}
    \While{running}
        \State Wait for set of new peer masks \(P_{c+1}=\{\phi^\text{new}_1,\dots,\phi^\text{new}_K\}\) from \(Q_\text{mask}\)
        \State Update \(\phi_\tau \gets \beta_\tau \phi_\tau + \sum_{k \in P_{c}} \beta_k \phi_k\)\Comment{Consolidation step}
        \State Cache consolidated mask for forward pass
        \State Update \(\beta_\tau \gets 0.5 + 0.5r\), \(\beta_k\gets\frac{0.5(1-r)}{|P_{c+1}|} \quad \forall k \in P_{c+1}\)
        \State \(P_c \gets P_{c+1}\)
    \EndWhile
\EndProcedure
\end{algorithmic}
\end{algorithm}
\begin{algorithm}[ht]
\caption{{MOSAIC Communication Module}}
\label{alg:mosaic-comm}
\begin{algorithmic}[1]
\Require Agent's IP/Port \(\texttt{addr}_i\), Communication graph \(\mathcal{G}=\{\mathcal{I},\mathcal{E}\}\), where \(\mathcal{E} = \{(i, j) \mid i, j \in \mathcal{I},\ i \ne j\}\)
\Procedure{CommunicationModule}{$Q_{\text{emb}}, Q_{\text{mask}}$}
    \State Initialize \textbf{parallel process} \textsc{CommunicationServer(\(Q_{\text{mask}}\))}
    \While{running}
        \State Wait for query \((v_i, r_i, \texttt{addr}_i)\) from \(Q_{\text{emb}}\)
        \State Send query to known peers
        \State Wait for set of peer \texttt{QR}s \(\{(v_j, r_j, \text{mask\_id}_j, \texttt{addr}_j)\}\) from \textsc{CommunicationServer}
        \State Select peers \(P \gets \{j\ |\ \mathbb{I}_{\text{align}} \text{ and } \mathbb{I}_\text{perf}\}\)
        \State Send mask request (\texttt{MR}) to selected peers \(P\)
        \State Wait for peer masks from \textsc{CommunicationServer} and send to model via \(Q_{\text{mask}}\)
    \EndWhile
\EndProcedure
\end{algorithmic}
\end{algorithm}
\begin{algorithm}[ht]
\caption{{Communication server}}
\label{alg:mosaic-server}
\begin{algorithmic}[1]
\Require World size \(W\), Agent's IP/Port \(\texttt{addr}_i\)
\Procedure{CommunicationServer}{$Q_{\text{mask}}$}
    \State Bind TCP socket to \((\texttt{addr}_i)\)
    \State Listen for connections with backlog size \(W\)
    \While{running}
        \State Accept incoming connection \((\texttt{conn}, \texttt{remote\_addr})\)
        \State Receive message from connection
        \If{message is an \texttt{TEQ}}
            \If{Server-side selection}
                \State Select mask(s) and respond with \texttt{MTR} to \texttt{remote\_addr}
            \Else
                \State Respond to \texttt{remote\_addr} with embedding and performance (\texttt{QR})
            \EndIf
        \ElsIf{message is an \texttt{QR}}
            \State Store \texttt{QR} \((v_j,r_j,\text{mask\_id},\texttt{addr}_j)\) in set of query responses
        \ElsIf{message is an \texttt{MR}}
            \State Fetch corresponding mask for mask id and respond to \texttt{remote\_addr} with \texttt{MTR}
        \ElsIf{message is an \texttt{MTR}}
            \State Add mask to set of acquired peer masks
        \EndIf
    \EndWhile
\EndProcedure
\end{algorithmic}
\end{algorithm}
\begin{algorithm}[ht]
\caption{Wasserstein Embedding Computation}
\label{alg:mosaic-wdm}
\begin{algorithmic}[1]
\Procedure{ComputeEmbedding}{$\mathcal{D}$}
    \State Compute embedding \(v_\tau^{\text{new}} \gets \psi(\mathcal{D})\) \Comment{via Eq.~\ref{eq:embedding_mapping}}
    \State \(v_\tau \gets \frac{1}{2}(v_\tau + v_\tau^{\text{new}})\) \Comment{Moving average update}
    \State \textbf{return \(v_\tau\)}
\EndProcedure
\end{algorithmic}
\end{algorithm}
